#include <stdlib.h>
#include <string.h>

// Structure to represent a traffic flow
typedef struct TrafficFlow {
    int FlowID;
    char Direction;
    unsigned long PacketCount;
} TrafficFlow;

// Function to initialize the array of traffic flows
void initTrafficFlows(TrafficFlow **flows, int num_flows) {
    // Allocate memory for the array of flows
    *flows = (TrafficFlow *)malloc(num_flows * sizeof(TrafficFlow));
    if (*flows == NULL) {
        // Handle out-of-memory condition
        printf("Error: unable to allocate memory for traffic flows\n");
        exit(1);
    }

    // Initialize the packet count for each flow to zero
    for (int i = 0; i < num_flows; i++) {
        (*flows)[i].PacketCount = 0;
    }
}

// Function to add a new traffic flow based on a unique identifier
void addTrafficFlow(TrafficFlow **flows, int num_flows, int FlowID, char Direction) {
    // Check if the flow ID is valid
    if (FlowID < 0 || FlowID >= num_flows) {
        printf("Error: invalid flow ID\n");
        return;
    }

    // Allocate memory for the new flow
    TrafficFlow *new_flow = (TrafficFlow *)malloc(sizeof(TrafficFlow));
    if (new_flow == NULL) {
        // Handle out-of-memory condition
        printf("Error: unable to allocate memory for new traffic flow\n");
        return;
    }

    // Initialize the new flow
    new_flow->FlowID = FlowID;
    new_flow->Direction = Direction;
    new_flow->PacketCount = 0;

    // Add the new flow to the array of flows
    (*flows)[FlowID] = *new_flow;
}

// Function to query the total packet count across all flows
unsigned long getTotalPacketCount(TrafficFlow **flows, int num_flows) {
    unsigned long total_packets = 0;

    // Iterate over each flow and add its packet count to the total
    for (int i = 0; i < num_flows; i++) {
        total_packets += (*flows)[i].PacketCount;
    }

    return total_packets;
}

// Function to free the memory allocated for the array of traffic flows
void freeTrafficFlows(TrafficFlow **flows, int num_flows) {
    // Free the memory allocated for each flow
    for (int i = 0; i < num_flows; i++) {
        free((*flows)[i]);
    }

    // Free the memory allocated for the array of flows
    free(*flows);
}
```
