// Function to dynamically allocate memory for and initialize two arrays: one for 'long' offset values and one for 'int' keys
void init_arrays(Record **records, long *offsets, int *keys, int num_records) {
    // Allocate memory for the record array
    records = (Record **)malloc(num_records * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for record array\n");
        return;
    }

    // Initialize each record's key field to a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            return;
        }
        records[i]->key = rand() % 100 + 1; // Random value within the specified range
    }

    // Allocate memory for the offset array
    offsets = (long *)malloc(num_records * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize each offset value to 0
    for (int i = 0; i < num_records; i++) {
        offsets[i] = 0;
    }

    // Allocate memory for the key array
    keys = (int *)malloc(num_records * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for key array\n");
        return;
    }

    // Initialize each key value to 0
    for (int i = 0; i < num_records; i++) {
        keys[i] = 0;
    }
}

// Function to free memory allocated by init_arrays()
void free_arrays(Record **records, long *offsets, int *keys) {
    // Free the record array
    for (int i = 0; i < num_records; i++) {
        if (records[i]) {
            free(records[i]);
        }
    }
    free(records);

    // Free the offset array
    free(offsets);

    // Free the key array
    free(keys);
}
