#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

void process_log(char* input_file, char* output_file, char* criteria, int compress) {
    // Open the input file and read its contents into a buffer
    FILE* fp = fopen(input_file, "r");
    if (fp == NULL) {
        printf("Error: unable to open input file\n");
        return;
    }
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    rewind(fp);
    char* buffer = (char*)malloc(file_size + 1);
    if (buffer == NULL) {
        printf("Error: unable to allocate memory for input file\n");
        fclose(fp);
        return;
    }
    size_t bytes_read = fread(buffer, 1, file_size, fp);
    buffer[bytes_read] = '\0';
    fclose(fp);

    // Extract relevant events from the input buffer based on user-defined criteria
    char* event_start = strstr(buffer, "EVENT:");
    while (event_start != NULL) {
        // Check if the current event meets the specified criteria
        if (meets_criteria(event_start, criteria)) {
            // Output the event to the summary file
            FILE* fp = fopen(output_file, "a");
            if (fp == NULL) {
                printf("Error: unable to open output file\n");
                return;
            }
            fprintf(fp, "%s", event_start);
            fclose(fp);
        }
        // Move on to the next event
        event_start = strstr(event_start + 1, "EVENT:");
    }

    // Compress the output file if necessary
    if (compress) {
        FILE* fp = fopen(output_file, "r+b");
        if (fp == NULL) {
            printf("Error: unable to open output file\n");
            return;
        }
        gzFile gzfp = gzdopen(fileno(fp), "wb");
        if (gzfp == NULL) {
            printf("Error: unable to compress output file\n");
            fclose(fp);
            return;
        }
        char* buffer = (char*)malloc(file_size + 1);
        if (buffer == NULL) {
            printf("Error: unable to allocate memory for compressed output file\n");
            gzclose(gzfp);
            fclose(fp);
            return;
        }
        size_t bytes_written = gzwrite(gzfp, buffer, file_size);
        free(buffer);
        gzclose(gzfp);
        fclose(fp);
    }
}

int meets_criteria(char* event, char* criteria) {
    // Check if the current event meets the specified criteria
    return strstr(event, criteria) != NULL;
}
