int dnsResolution(const char* hostname, u_char** ipAddress) {
    // Initialize variables
    int errorCode = ERROR_SUCCESS;
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    // Perform DNS resolution
    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        errorCode = ERROR_DNS_RESOLUTION_FAILED;
        goto cleanup;
    }

    // Allocate memory for the IP address
    *ipAddress = (u_char*)malloc(sizeof(struct in_addr));
    if (*ipAddress == NULL) {
        errorCode = ERROR_MEMORY_ALLOCATION_FAILED;
        goto cleanup;
    }

    // Copy the IP address to the output parameter
    memcpy(*ipAddress, res->ai_addr, sizeof(struct in_addr));

    // Log the successful resolution
    logMessage(LOG_LEVEL_INFO, "DNS resolution succeeded for hostname %s", hostname);

cleanup:
    // Free the memory allocated for the DNS response
