typedef struct {
    char* message;
    time_t timestamp;
} LogMessage;

// Define a queue to store logged messages
Queue<LogMessage> log_queue;

// Define a function to log a message to the error log
void log_error(const char* format, ...) {
    // Check if logging is enabled and the condition for logging is met
    if (log_enabled && condition) {
        // Create a new LogMessage structure
        LogMessage msg;

        // Get the current time as a timestamp
        time_t now = time(NULL);

        // Format the message using snprintf and va_list
        vsnprintf(msg.message, sizeof(msg.message), format, args);

        // Add the LogMessage to the log queue
        log_queue.push(msg);
    }
}

// Define a function to flush the log queue to the error log
void flush_log() {
    // Check if logging is enabled and there are messages in the queue
    if (log_enabled && !log_queue.empty()) {
        // Iterate over the messages in the queue
        for (LogMessage msg : log_queue) {
            // Print the message to the error log
            fprintf(stderr, "%s\n", msg.message);
        }

        // Clear the log queue
        log_queue.clear();
    }
}

// Define a function to bypass logging under certain conditions
void set_log_enabled(bool enabled) {
    log_enabled = enabled;
}
