    } else if (strcmp(cipher_name, "ECB") == 0) {
        return EVP_des_ecb();
    } else if (strcmp(cipher_name, "EDE") == 0) {
        return EVP_des_ede();
    } else if (strcmp(cipher_name, "EDE3") == 0) {
        return EVP_des_ede3();
    } else if (strcmp(cipher_name, "CFB") == 0) {
        return EVP_des_cfb();
    } else {
        return NULL;
    }
}

bool verify_access_token(const char* json_string) {
    json_object *json = json_tokener_parse(json_string);
    if (!json) {
        return false;
    }

    const char* access_token = json_object_get_string(json, "access_token");
    if (!access_token) {
        return false;
    }

    int expires_in = json_object_get_int(json, "expires_in");
    if (expires_in <= 0) {
        return false;
    }

    const char* token_type = json_object_get_string(json, "token_type");
    if (!token_type || strcmp(token_type, "Bearer") != 0) {
        return false;
    }

    const char* refresh_token = json_object_get_string(json, "refresh_token");
    if (refresh_token && strlen(refresh_token) > 0) {
        return true;
    }

    return false;
}
