            case "Dragon":
                return "Use Dragon-type moves and attack with high Speed stat";
            default:
                return "";
        }
    }

    public static String getPokemonReport(Pokemon pokemon) {
        // Use a caching mechanism to handle repeated lookups of the same Pokemon data
        if (WEAKNESS_MAP.containsKey(pokemon.getName())) {
            return WEAKNESS_MAP.get(pokemon.getName());
        } else {
            String weaknesses = getWeaknesses(pokemon);
            String strengths = getStrengths(pokemon);
            String possibleStrategies = getPossibleStrategies(pokemon);
            WEAKNESS_MAP.put(pokemon.getName(), weaknesses + "\n" + strengths + "\n" + possibleStrategies);
            return WEAKNESS_MAP.get(pokemon.getName());
        }
    }
