#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Custom struct to store information about each cipher and hash function
typedef struct {
    const char* name;
    void (*func_ptr)(void);
    int config_param;
} cipher_info;

// Function to retrieve a list of available cryptographic hash functions and block ciphers
cipher_info* get_available_ciphers(const char** platforms, size_t num_platforms) {
    // Initialize the linked list of cipher_info structs
    cipher_info* head = NULL;
    cipher_info* current = NULL;

    // Iterate over each platform in the list
    for (size_t i = 0; i < num_platforms; ++i) {
        const char* platform = platforms[i];

        // Get a list of available hash functions and block ciphers for this platform
        STACK_OF(EVP_CIPHER)* cipher_stack = EVP_get_cipherbyname();
        STACK_OF(EVP_MD)* md_stack = EVP_get_digestbyname();

        // Iterate over each hash function and block cipher in the list
        for (size_t j = 0; j < sk_EVP_CIPHER_num(cipher_stack); ++j) {
            const EVP_CIPHER* cipher = sk_EVP_CIPHER_value(cipher_stack, j);
            const EVP_MD* md = sk_EVP_MD_value(md_stack, j);

            // Check if the hash function or block cipher is compatible with this platform
            if (is_compatible(platform, cipher) || is_compatible(platform, md)) {
                // Create a new cipher_info struct and add it to the linked list
                cipher_info* new_cipher = malloc(sizeof(cipher_info));
                new_cipher->name = EVP_CIPHER_get_name(cipher);
                new_cipher->func_ptr = EVP_CIPHER_get_impl(cipher);
                new_cipher->config_param = EVP_CIPHER_get_key_length(cipher);
                if (current == NULL) {
                    head = current = new_cipher;
                } else {
                    current->next = new_cipher;
                    current = new_cipher;
                }
            }
        }
    }

    // Return the linked list of cipher_info structs
    return head;
}

// Function to check if a hash function or block cipher is compatible with a specific platform
int is_compatible(const char* platform, const EVP_CIPHER* cipher) {
    // Check if the platform supports the cipher's algorithm
    if (EVP_CIPHER_is_a(cipher, platform)) {
        return 1;
    }

    // Check if the platform supports the cipher's key size
    int key_size = EVP_CIPHER_get_key_length(cipher);
    if (key_size > 0 && strcmp(platform, "aes") == 0) {
        return 1;
    }

    // Check if the platform supports authenticated encryption
    if (strcmp(platform, "auth") == 0) {
        return EVP_CIPHER_get_flags(cipher) & EVP_CIPH_FLAG_AEAD_CIPHER;
    }

    // Check if the platform supports key management
    if (strcmp(platform, "key") == 0) {
        return EVP_CIPHER_get_flags(cipher) & EVP_CIPH_FLAG_KEY_FUNCTIONS;
    }

    // Check if the platform supports compression
    if (strcmp(platform, "comp") == 0) {
        return EVP_CIPHER_get_flags(cipher) & EVP_CIPH_FLAG_COMPRESS;
    }

    // If none of the above conditions are met, the cipher is not compatible with this platform
    return 0;
}

// Function to handle dynamic memory allocation and deallocation safely
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        ERR_load_crypto_strings();
        ERR_error_string(ERR_get_error(), "safe_malloc");
    }
    return ptr;
}

// Function to handle dynamic memory allocation and deallocation safely
void safe_free(void* ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}
```
This code defines a function `get_available_ciphers` that takes an array of platform names as input, and returns a linked list of custom `cipher_info` structs containing information about each available cipher and hash function. The function uses OpenSSL's `EVP_CIPHER` and `EVP_MD` functions to retrieve a list of available cryptographic algorithms for each platform, and checks if the algorithm is compatible with the platform using the `is_compatible` function. If the algorithm is compatible, it creates a new `cipher_info` struct and adds it to the linked list. The function also handles dynamic memory allocation and deallocation safely using the `safe_malloc` and `safe_free` functions.

The `cipher_info` struct contains the name of the hash function or block cipher, a function pointer to its implementation, and any required configuration parameters. The function returns the linked list of `cipher_info` structs, which can be used by the caller to retrieve information about each available cipher and hash function.

The `is_compatible` function checks if a hash function or block cipher is compatible with a specific platform using several conditions:

* Check if the platform supports the cipher's algorithm using `EVP_CIPHER_is_a`.
* Check if the platform supports the cipher's key size using `EVP_CIPHER_get_key_length` and comparing it to a specific value for a given platform.
* Check if the platform supports authenticated encryption using `EVP_CIPHER_get_flags` and checking if the flag `EVP_CIPH_FLAG_AEAD_CIPHER` is set.
* Check if the platform supports key management using `EVP_CIPHER_get_flags` and checking if the flag `EVP_CIPH_FLAG_KEY_FUNCTIONS` is set.
* Check if the platform supports compression using `EVP_CIPHER_get_flags` and checking if the flag `EVP_CIPH_FLAG_COMPRESS` is set.

The function returns 1 if any of these conditions are met, or 0 otherwise.

The `safe_malloc` and `safe_free` functions handle dynamic memory allocation and deallocation safely by using OpenSSL's error handling functions to print an error message in case of failure, and by freeing the allocated memory using `free`.']

