#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Function to read a file in manageable chunks and update the hash using EVP_CIPHER_CTX
EVP_CIPHER_CTX *readFileAndUpdateHash(const char *filePath, const char *commandLineOption) {
    // Open the file for reading
    int fd = open(filePath, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return NULL;
    }

    // Get the size of the file
    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("Error getting file size");
        close(fd);
        return NULL;
    }

    // Allocate memory for the hash object
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        perror("Error allocating memory for hash object");
        close(fd);
        return NULL;
    }

    // Initialize the hash object with the appropriate algorithm and key
    if (!EVP_CipherInit_ex(ctx, EVP_get_digestbyname(commandLineOption), NULL, NULL, NULL)) {
        perror("Error initializing hash object");
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return NULL;
    }

    // Read the file in manageable chunks and update the hash
    char buffer[4096];
    ssize_t bytesRead;
    while ((bytesRead = read(fd, buffer, sizeof(buffer))) > 0) {
        if (!EVP_CipherUpdate(ctx, buffer, bytesRead)) {
            perror("Error updating hash");
            EVP_CIPHER_CTX_free(ctx);
            close(fd);
            return NULL;
        }
    }

    // Handle potential interruptions gracefully by checking for partial hashes
    if (bytesRead == -1) {
        perror("Error reading file");
        EVP_CIPHER_CTX_free(ctx);
        close(fd);
        return NULL;
    }

    // Close the file and return the cipher object
    close(fd);
    return ctx;
}
