#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

struct circular_buffer {
    size_t capacity;
    size_t read_index;
    size_t write_index;
    sem_t *read_sem;
    sem_t *write_sem;
    void **data;
};

void init_circular_buffer(struct circular_buffer *cb, size_t capacity) {
    cb->capacity = capacity;
    cb->read_index = 0;
    cb->write_index = 0;
    cb->read_sem = sem_open("read_sem", O_CREAT | O_EXCL, 0644, 1);
    cb->write_sem = sem_open("write_sem", O_CREAT | O_EXCL, 0644, 1);
    cb->data = malloc(sizeof(void *) * capacity);
}

void destroy_circular_buffer(struct circular_buffer *cb) {
    free(cb->data);
    sem_close(cb->read_sem);
    sem_close(cb->write_sem);
}

void write_to_circular_buffer(struct circular_buffer *cb, void *data) {
    sem_wait(cb->write_sem);
    cb->data[cb->write_index] = data;
    cb->write_index = (cb->write_index + 1) % cb->capacity;
    sem_post(cb->read_sem);
}

void *read_from_circular_buffer(struct circular_buffer *cb) {
    void *data = NULL;
    sem_wait(cb->read_sem);
    data = cb->data[cb->read_index];
    cb->read_index = (cb->read_index + 1) % cb->capacity;
    sem_post(cb->write_sem);
    return data;
}
