using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;

public static IDataReader ExecuteQuery(SqlConnection connection, List<string> tables, List<string> columns, Dictionary<string, object> filters)
{
    // Check if the input parameters are valid
    if (connection == null || tables == null || columns == null || filters == null)
        throw new ArgumentNullException("Invalid input parameters");

    // Create a new SQL command
    SqlCommand command = connection.CreateCommand();

    // Set the command text to an empty string
    command.CommandText = "";

    // Build the SELECT clause
    StringBuilder selectClause = new StringBuilder();
    selectClause.Append("SELECT ");
    foreach (string column in columns)
    {
        selectClause.Append(column + ",");
    }
    selectClause.Remove(selectClause.Length - 1, 1);

    // Build the FROM clause
    StringBuilder fromClause = new StringBuilder();
    foreach (string table in tables)
    {
        fromClause.Append("JOIN " + table + " ON ");
        fromClause.Append(table + ".ID = ");
        fromClause.Append(table + "_ID");
        fromClause.Append(" AND ");
    }
    fromClause.Remove(fromClause.Length - 4, 4);

    // Build the WHERE clause
    StringBuilder whereClause = new StringBuilder();
    foreach (KeyValuePair<string, object> filter in filters)
    {
        if (filter.Value != null)
        {
            whereClause.Append(filter.Key + " = @" + filter.Key);
            whereClause.Append(" AND ");
        }
    }
    whereClause.Remove(whereClause.Length - 5, 5);

    // Build the query
    command.CommandText = selectClause.ToString() + " FROM " + fromClause.ToString() + " WHERE " + whereClause.ToString();

    // Add parameters for each filter value
    foreach (KeyValuePair<string, object> filter in filters)
    {
        if (filter.Value != null)
        {
            command.Parameters.AddWithValue("@" + filter.Key, filter.Value);
        }
    }

    // Execute the query and return the result set
    return command.ExecuteReader();
}
```
This method takes a connection to a SQL database, a list of tables to join, a list of columns to select, and a dictionary of filter criteria as input parameters. It constructs a parameterized SQL query based on these inputs, handles potential nulls and empty lists gracefully, and returns an IDataReader for the result set. The method optimizes query performance by minimizing the number of joins and avoiding unnecessary columns.

Here's how you can use this method:
