// Function to manage user profiles
async function updateUserProfile(req, res) {
  // Get the unique user ID from the request parameters
  const userId = req.params.userId;

  // Check if the user is authorized to make changes to their profile
  if (!isAuthorized(userId)) {
    return res.status(403).json({ message: "Forbidden" });
  }

  // Update or delete the user profile based on the request method
  switch (req.method) {
    case "PUT":
      // Get the updated profile data from the request body
      const updatedProfile = req.body;

      // Validate the updated profile data
      if (!validateProfile(updatedProfile)) {
        return res.status(400).json({ message: "Invalid profile data" });
      }

      // Update the user profile in the database
      const result = await updateUserProfileInDatabase(userId, updatedProfile);

      // Log the change to the audit log
      logAuditEvent("UPDATE_USER_PROFILE", { userId, updatedProfile });

      return res.status(200).json({ message: "Profile updated successfully" });
    case "DELETE":
      // Delete the user profile from the database
      const result = await deleteUserProfileFromDatabase(userId);

      // Log the change to the audit log
      logAuditEvent("DELETE_USER_PROFILE", { userId });

      return res.status(204).json({ message: "Profile deleted successfully" });
    default:
      return res.status(405).json({ message: "Method not allowed" });
  }
}
