function handleUserRequest($_REQUEST) {
    // Validate input data
    $validation = validateInput($_REQUEST);
    if ($validation['status'] === 'error') {
        return json_encode(['message' => 'error', 'errors' => $validation['errors']]);
    }

    // Check for duplicate emails
    if (isset($_REQUEST['email']) && !isDuplicateEmail($_REQUEST['email'])) {
        return json_encode(['message' => 'error', 'errors' => ['email' => 'duplicate email']]);
    }

    // Save data to database
    $saveResult = saveData($_REQUEST);
    if ($saveResult === false) {
        return json_encode(['message' => 'error', 'errors' => ['database' => 'failed to save data']]);
    }

    // Get user account data
    $userAccount = getUserAccount($_REQUEST['id']);
    if (!$userAccount) {
        return json_encode(['message' => 'error', 'errors' => ['account' => 'not found']]);
    }

    // Handle sub-action (delete)
    if (isset($_REQUEST['sub_action']) && $_REQUEST['sub_action'] === 'delete') {
        $deleteResult = deleteUserAccount($userAccount);
        if ($deleteResult === false) {
            return json_encode(['message' => 'error', 'errors' => ['account' => 'failed to delete account']]);
        }
    }

    // Log changes made to user accounts
    logChanges($_REQUEST['id'], $_REQUEST['sub_action']);

    // Return success message
    return json_encode(['message' => 'success']);
}
```
