import java.io.BufferedReader;
import java.io.FileReader;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class DuplicateTransactionDetector {
    public static void main(String[] args) throws Exception {
        // Read the CSV file
        BufferedReader reader = new BufferedReader(new FileReader("transactions.csv"));
        String line;
        Map<Long, List<Double>> transactionMap = new HashMap<>();
        long startTime = System.currentTimeMillis();
        while ((line = reader.readLine()) != null) {
            // Parse the transaction data from the CSV file
            String[] transactionData = line.split(",");
            Long transactionId = Long.parseLong(transactionData[0]);
            Double amount = Double.parseDouble(transactionData[1]);

            // Check if the transaction ID already exists in the map
            if (transactionMap.containsKey(transactionId)) {
                // If it does, add the amount to the list of duplicate occurrences
                List<Double> duplicates = transactionMap.get(transactionId);
                duplicates.add(amount);
            } else {
                // If it doesn't, create a new entry in the map with the amount as the only value
                List<Double> duplicates = new ArrayList<>();
                duplicates.add(amount);
                transactionMap.put(transactionId, duplicates);
            }

            // Log the processing time for each batch of 10,000 transactions
            if (transactionMap.size() % 10000 == 0) {
                long endTime = System.currentTimeMillis();
                long processingTime = endTime - startTime;
                System.out.println("Processed " + transactionMap.size() + " transactions in " + processingTime + " milliseconds");
            }
        }

        // Print the results of the duplicate detection
        for (Long transactionId : transactionMap.keySet()) {
            List<Double> duplicates = transactionMap.get(transactionId);
            System.out.println("Transaction ID: " + transactionId);
            System.out.println("Duplicate occurrences: " + duplicates);
        }
    }
}
```
This code uses a `HashMap` to store the transaction IDs and their corresponding amounts, and a `List` to track duplicate occurrences for each transaction ID. It reads the CSV file line by line, parsing the transaction data from each line and adding it to the map if it doesn't already exist. If the transaction ID already exists in the map, it adds the amount to the list of duplicate occurrences. The code also logs the processing time for each batch of 10,000 transactions using `System.currentTimeMillis()`. Finally, it prints the results of the duplicate detection, including the transaction IDs and their corresponding duplicate occurrences.']

