function updateUserProfile($userId, $preferences, $notifications) {
  // Connect to database
  $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');

  // Prepare statement for updating user profile
  $stmt = $db->prepare("UPDATE users SET preferences = :preferences, notifications = :notifications WHERE id = :userId");

  // Bind parameters to statement
  $stmt->bindParam(':preferences', $preferences);
  $stmt->bindParam(':notifications', $notifications);
  $stmt->bindParam(':userId', $userId);

  // Execute statement and check for errors
  if ($stmt->execute()) {
    // Log changes to audit table
