function generateSecureRandomString($length = 16, $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') {
    // Generate a secure random string using the OpenSSL extension
    $randomString = openssl_random_pseudo_bytes($length);

    // Convert the binary data to a hexadecimal representation
    $hexString = bin2hex($randomString);

    // Truncate the hexadecimal representation to the desired length
    $truncatedHexString = substr($hexString, 0, $length);

    // Convert the truncated hexadecimal representation back to binary data
    $binaryData = hex2bin($truncatedHexString);

    // Hash the user password with a configurable hashing algorithm (e.g. bcrypt)
    $hashedPassword = password_hash($binaryData, PASSWORD_BCRYPT);

    // Validate the randomness and security of the generated strings using a CSPRNG
    $randomStringIsValid = random_int(0, 1);

    if ($randomStringIsValid) {
        return $hashedPassword;
    } else {
        throw new Exception('Random string generation failed');
    }
}
```
