def generate_pem_certificate(oauth_request):
    # Retrieve private key and certificate from OAuth request
    private_key = oauth_request.get("private_key")
    certificate = oauth_request.get("certificate")

    # Combine private key and certificate into a single PEM file
    pem_file = f"{private_key}\n{certificate}"

    # Create graph in graph database
