        graph.add_vertex(vertex)

    for _ in range(random.randint(1, 10)):
        edge = Edge(source=graph.vertices[random.randint(0, len(graph.vertices)-1)], target=graph.vertices[random.randint(0, len(graph.vertices)-1)])
        graph.add_edge(edge)

    for vertex in graph.vertices:
        for property_name in ["RandomProperty", "AnotherRandomProperty"]:
            vertex.properties[property_name] = random.randint(0, 100)

    for edge in graph.edges:
        for property_name in ["RandomEdgeProperty", "AnotherRandomEdgeProperty"]:
            edge.properties[property_name] = random.randint(0, 100)

