struct StateNode {
    int state;
    struct StateNode* next;
};

struct FSA {
    // ...
};

struct StateList {
    struct StateNode* head;
    struct StateNode* tail;
};

struct StateList* processStates(struct StateList* currentStateList, int* states, int numStates, struct FSA* fsa, int lastState) {
    if (currentStateList == NULL || states == NULL || fsa == NULL) {
        return NULL;
    }

    // Create a new state list by processing the states in reverse order
    struct StateList* newStateList = malloc(sizeof(struct StateList));
    if (newStateList == NULL) {
        return NULL;
    }
    newStateList->head = NULL;
    newStateList->tail = NULL;

    for (int i = numStates - 1; i >= 0; i--) {
        struct StateNode* newStateNode = malloc(sizeof(struct StateNode));
        if (newStateNode == NULL) {
            free(newStateList);
            return NULL;
        }
        newStateNode->state = states[i];
        newStateNode->next = NULL;

        // Update the next pointer of the last state in the current state list to point to the head of the newly created state list
        if (currentStateList->tail != NULL) {
            currentStateList->tail->next = newStateNode;
        } else {
            currentStateList->head = newStateNode;
        }
        currentStateList->tail = newStateNode;
    }

    // Update the next pointer of the last state in the newly created state list to point to the head of the current state list
    if (newStateList->tail != NULL) {
        newStateList->tail->next = currentStateList->head;
    } else {
        newStateList->head = currentStateList->head;
    }
    currentStateList->tail = newStateList->tail;

    return newStateList;
}
