['```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace RandomValueGenerator
{
    public class RandomValueGenerator
    {
        private List<Range> ranges = new List<Range>();

        public void AddRange(int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value cannot be greater than maximum value.");

            ranges.Add(new Range(min, max));
        }

        public float GenerateFloatValue()
        {
            return (float)(ranges[0].Max - ranges[0].Min) * Random.NextDouble() + ranges[0].Min;
        }

        public int GenerateIntValue()
        {
            return (int)(ranges[0].Max - ranges[0].Min) * Random.Next(ranges[0].Min, ranges[0].Max);
        }

        public void ShiftRangeByOffset(int offset)
        {
            foreach (var range in ranges)
            {
                range.Min += offset;
                range.Max += offset;
            }
        }

        public void ScaleRangeByFactor(float factor)
        {
            foreach (var range in ranges)
            {
                range.Min *= factor;
                range.Max *= factor;
            }
        }

        public void MergeRanges(int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value cannot be greater than maximum value.");

            var mergedRange = new Range(min, max);
            ranges.RemoveAll(range => range.OverlapsWith(mergedRange));
            ranges.Add(mergedRange);
        }

        public override string ToString()
        {
            return "Active Ranges: " + String.Join(", ", ranges.Select(range => $"{range.Min} - {range.Max}"));
        }

        public void SerializeToJson(string json)
        {
            var serializer = new JsonSerializer();
            using (var writer = new StringWriter())
            {
                serializer.Serialize(writer, ranges);
                json = writer.ToString();
            }
        }

        public void DeserializeFromJson(string json)
        {
            var deserializer = new JsonSerializer();
            using (var reader = new StringReader(json))
            {
                ranges = deserializer.Deserialize<List<Range>>(reader);
            }
        }

        public float CalculateMean()
        {
            var sum = 0f;
            foreach (var range in ranges)
            {
                sum += range.Min + range.Max;
            }
            return sum / ranges.Count;
        }

        public float CalculateStandardDeviation()
        {
            var mean = CalculateMean();
            var variance = 0f;
            foreach (var range in ranges)
            {
                variance += Math.Pow(range.Min + range.Max - mean, 2);
            }
            return (float)Math.Sqrt(variance / ranges.Count);
        }

        public int FindSmallestValue()
        {
            var smallest = Int32.MaxValue;
            foreach (var range in ranges)
            {
                if (range.Min < smallest)
                    smallest = range.Min;
            }
            return smallest;
        }

        public int FindLargestValue()
        {
            var largest = Int32.MinValue;
            foreach (var range in ranges)
            {
                if (range.Max > largest)
                    largest = range.Max;
            }
            return largest;
        }

        private class Range
        {
            public int Min { get; set; }
            public int Max { get; set; }

            public Range(int min, int max)
            {
                this.Min = min;
                this.Max = max;
            }

            public bool OverlapsWith(Range other)
            {
                return !(this.Min > other.Max || this.Max < other.Min);
            }
        }
    }
}
```
This code defines a `RandomValueGenerator` class that manages multiple ranges of values simultaneously. Each range is defined by a minimum and maximum value, both inclusive. The class provides methods to generate random float and integer values within these ranges, as well as methods to shift the entire range by a specified offset and scale all values within the range by a given factor. Additionally, the class includes methods to merge two overlapping ranges into a single range, handle invalid ranges gracefully, and calculate the mean and standard deviation of all values generated within the ranges.

The `AddRange` method is used to add a new range to the list of managed ranges. The `GenerateFloatValue` and `GenerateIntValue` methods are used to generate random float and integer values within the first range in the list, respectively. The `ShiftRangeByOffset` method shifts the entire range by a specified offset, while the `ScaleRangeByFactor` method scales all values within the range by a given factor.

The `MergeRanges` method is used to merge two overlapping ranges into a single range. The `ToString` method is overridden to display the active ranges and their current settings. The `SerializeToJson` and `DeserializeFromJson` methods are used to serialize and deserialize the class state to/from JSON, respectively.

