#define LOG_FILE "log.txt"
#define MAX_LINE_LENGTH 1024
#define MAX_LOG_SIZE (1 << 20) // 1 MB

void logError(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        return;
    }
    fprintf(fp, "%s\n", msg);
    fclose(fp);
}

int main() {
    FILE *file = fopen("input.txt", "r");
    if (file == NULL) {
        logError("File not found or unreadable");
        return 1;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        // Split the line into tokens using space as delimiter
        char *token = strtok(line, " ");
        int numTokens = 0;
        float sum = 0.0;
        while (token != NULL) {
            numTokens++;
            sum += atof(token);
            token = strtok(NULL, " ");
        }

        // Calculate the average of the last three fields
        int avg = 0;
        if (numTokens >= 3) {
            avg = (sum / numTokens) * 100;
        }

        // Print the line in a comma-separated format, with the average at the end
        printf("%s,%d\n", line, avg);
    }

    fclose(file);
    return 0;
}
```
