char* modify_filename(const char* filename) {
    // Extract the last three characters of the filename
    const char* last_three = &filename[strlen(filename) - 3];

    // Calculate the number of digits to append to the new extension
    int num_digits = 0;
    for (int i = 0; i < 3; i++) {
        if (isdigit(last_three[i])) {
            num_digits++;
        } else {
            break;
        }
    }

    // Ensure the new extension is exactly 8 characters long, including the period and the digits
    int new_extension_len = 5 + num_digits;
    if (new_extension_len > 8) {
        new_extension_len = 8;
    }

    // Truncate the calculated number of digits to 5 if necessary
    if (num_digits > 5) {
        num_digits = 5;
    }

    // Validate that the filename does not exceed a total length of 256 characters after modification
    int new_filename_len = strlen(filename) + new_extension_len - num_digits;
    if (new_filename_len > 256) {
        return NULL;
    }

    // Construct the new filename using sprintf and strcat
    char* new_filename = malloc(new_filename_len + 1);
    snprintf(new_filename, new_filename_len + 1, "%s.%05d", filename, num_digits);

    return new_filename;
}
