// Function to initialize AES-256-CBC cipher with given password
EVP_CIPHER_CTX* init_aes_cbc(const char* password, int iv_length) {
    // Check if password is empty
    if (password == NULL || strlen(password) == 0) {
        return NULL;
    }

    // Derive key and IV from password
    unsigned char key[32];
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(key, &sha256);

    // Ensure IV length is at least 16 bytes for CBC mode
    if (iv_length < 16) {
        iv_length = 16;
    }

    // Allocate memory for cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return NULL;
    }

    // Initialize AES-256-CBC cipher with derived key and IV
    int ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set IV length to user-specified value
    ret = EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_IVLEN, iv_length, NULL);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Return initialized cipher context
    return ctx;
}

// Function to clean up AES-256-CBC cipher and free allocated resources
void cleanup_aes_cbc(EVP_CIPHER_CTX* ctx) {
    if (ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
```
