import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.HashMap;
import java.util.Map;

public class SerializationHelper {
    private static final Map<String, Class<?>> registeredClasses = new HashMap<>();

    public static <T> T deserialize(byte[] data) throws IOException, ClassNotFoundException {
        ObjectInputStream ois = null;
        try {
            ois = new ObjectInputStream(new ByteArrayInputStream(data));
            return (T) ois.readObject();
        } catch (ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize object: " + e.getMessage());
        } finally {
            if (ois != null) {
                try {
                    ois.close();
                } catch (IOException ex) {
                    // ignore
                }
            }
        }
    }

    public static void registerClass(String className, Class<?> clazz) {
        registeredClasses.put(className, clazz);
    }

    public static Class<?> getRegisteredClass(String className) {
        return registeredClasses.get(className);
    }
}
```
