function generateRandomGraph() {
  // Generate random vertices using Math.random()
  const numVertices = 10;
  const vertices = [];
  for (let i = 0; i < numVertices; i++) {
    vertices.push({
      id: `v${i}`,
      label: `Vertex ${i}`
    });
  }

  // Generate random edges using Math.random()
  const numEdges = 20;
  const edges = [];
  for (let i = 0; i < numEdges; i++) {
    const source = vertices[Math.floor(Math.random() * numVertices)];
    const target = vertices[Math.floor(Math.random() * numVertices)];
    edges.push({
      id: `e${i}`,
      label: `Edge ${i}`,
      source,
      target
    });
  }

  // Set random properties on the vertices and edges using Math.random()
  for (const vertex of vertices) {
    const propName = `prop${Math.floor(Math.random() * 10)}`;
    const propValue = Math.floor(Math.random() * 10);
    vertex[propName] = propValue;
  }

  for (const edge of edges) {
    const propName = `prop${Math.floor(Math.random() * 10)}`;
    const propValue = Math.floor(Math.random() * 10);
    edge[propName] = propValue;
  }

  // Output the updated graph structure to the browser
  console.log(vertices, edges);
}
