#define ERROR_NEGATIVE_EXPIRES_IN 4
#define ERROR_UNKNOWN_MODE 5
#define ERROR_UNKNOWN_FIELD 6
#define ERROR_PARSING_FAILED 7

// Define the library's configuration options
struct config {
    int mode; // The encryption mode (ECB, EDE, EDE3, CFB)
    int block_size; // The block size for the encryption algorithm
    int key_size; // The key size for the encryption algorithm
};

// Define the library's state
struct state {
    struct config config; // The current configuration of the library
    unsigned char *key; // The encryption key
    unsigned char *iv; // The initialization vector (IV) for CFB mode
};

// Initialize the library with a given configuration
int init(struct config *config, unsigned char *key, unsigned char *iv) {
    if (!config || !key || !iv) {
        return ERROR_UNKNOWN_MODE;
    }

    // Set the current configuration of the library
    struct state *state = malloc(sizeof(struct state));
    state->config = *config;
    state->key = key;
    state->iv = iv;

    return 0;
}

// Encrypt data using the specified encryption mode and key
int encrypt(unsigned char *data, int length, unsigned char *encrypted_data) {
    if (!data || !length || !encrypted_data) {
        return ERROR_UNKNOWN_MODE;
    }

    // Select the appropriate encryption function based on the mode
    switch (state->config.mode) {
        case MODE_ECB:
            DES_ecb_encrypt(data, encrypted_data, state->key, state->block_size);
            break;
        case MODE_EDE:
            DES_ede_encrypt(data, encrypted_data, state->key, state->block_size);
            break;
        case MODE_EDE3:
            DES_ede3_encrypt(data, encrypted_data, state->key, state->block_size);
            break;
        case MODE_CFB:
            DES_cfb_encrypt(data, encrypted_data, state->key, state->iv, state->block_size);
            break;
        default:
            return ERROR_UNKNOWN_MODE;
    }

    return 0;
}

// Decrypt data using the specified encryption mode and key
int decrypt(unsigned char *data, int length, unsigned char *decrypted_data) {
    if (!data || !length || !decrypted_data) {
        return ERROR_UNKNOWN_MODE;
    }

    // Select the appropriate decryption function based on the mode
    switch (state->config.mode) {
        case MODE_ECB:
            DES_ecb_decrypt(data, decrypted_data, state->key, state->block_size);
            break;
        case MODE_EDE:
            DES_ede_decrypt(data, decrypted_data, state->key, state->block_size);
            break;
        case MODE_EDE3:
            DES_ede3_decrypt(data, decrypted_data, state->key, state->block_size);
            break;
        case MODE_CFB:
            DES_cfb_decrypt(data, decrypted_data, state->key, state->iv, state->block_size);
            break;
        default:
            return ERROR_UNKNOWN_MODE;
    }

    return 0;
}

// Validate an OAuth2 access token response by parsing a JSON string and ensuring the presence of required fields
int validate_token(char *json) {
    if (!json) {
        return ERROR_PARSING_FAILED;
    }

    // Parse the JSON string into a json-c object
    json_object *root = json_tokener_parse(json);
    if (!root) {
        return ERROR_PARSING_FAILED;
    }

    // Check that all required fields are present and have valid values
    json_object *access_token = json_object_object_get(root, "access_token");
    if (!access_token) {
        return ERROR_MISSING_ACCESS_TOKEN;
    }
    int expires_in = json_object_get_int(json_object_object_get(root, EXPIRES_IN_FIELD));
    if (expires_in < 0) {
        return ERROR_NEGATIVE_EXPIRES_IN;
    }
    const char *token_type = json_object_get_string(json_object_object_get(root, "token_type"));
    if (!token_type || strcmp(token_type, TOKEN_TYPE) != 0) {
        return ERROR_INVALID_TOKEN_TYPE;
    }
    json_object *refresh_token = json_object_object_get(root, REFRESH_TOKEN_FIELD);
    if (refresh_token && !json_object_is_type(refresh_token, json_type_null)) {
        return ERROR_UNKNOWN_FIELD;
    }

    // Free the json-c object and return success
    json_object_put(root);
    return 0;
}
```
