```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    float value;
    char status;
} record;

// Define the function to initialize and allocate memory for the arrays
void init_arrays(long* offset_arr, int* key_arr, float* data_arr, int num_records) {
    // Allocate memory for the arrays
    offset_arr = (long*)malloc(num_records * sizeof(long));
    key_arr = (int*)malloc(num_records * sizeof(int));
    data_arr = (float*)malloc(num_records * sizeof(float));

    // Initialize the arrays with random values within specified ranges
    for (int i = 0; i < num_records; i++) {
        offset_arr[i] = rand() % 1000;
        key_arr[i] = rand() % 1000;
        data_arr[i] = (float)rand() / RAND_MAX * 100.0f;
    }

    // Calculate the sum of all float values and ensure it does not exceed the given limit
    float total_sum = 0.0f;
    for (int i = 0; i < num_records; i++) {
        total_sum += data_arr[i];
        if (total_sum > LIMIT) {
            // If the sum exceeds the limit, reduce the value of the last record by a random amount
            int reduction = rand() % 100;
            data_arr[i] -= reduction / 100.0f;
        }
    }

    // Track the total memory usage of all allocated structures and ensure that memory is freed upon function exit
    long total_memory = num_records * sizeof(long) + num_records * sizeof(int) + num_records * sizeof(float);
    printf("Total memory usage: %ld bytes\n", total_memory);
    free(offset_arr);
    free(key_arr);
    free(data_arr);
}

// Define the function to handle concurrent access to shared resources safely and provide a mechanism to serialize access to these resources to prevent race conditions
void safe_access(long* offset_arr, int* key_arr, float* data_arr) {
    // Use a mutex to protect the shared resources from concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Perform the operation on the shared resources
    for (int i = 0; i < num_records; i++) {
        offset_arr[i]++;
        key_arr[i]++;
        data_arr[i] += 1.0f;
    }

    // Unlock the mutex to allow other threads to access the shared resources
    pthread_mutex_unlock(&mutex);
}
