// Define the function to compute MD5 hashes in parallel
void compute_md5(char **strings, int num_strings) {
    // Allocate memory for the MD5 hashes
    unsigned char *hashes = (unsigned char *)malloc(num_strings * 16);
    if (!hashes) {
        printf("Error: Failed to allocate memory for MD5 hashes\n");
        exit(1);
    }

    // Initialize the MD5 context
    MD5_CTX ctx;
    MD5_Init(&ctx);

    // Compute the MD5 hashes in parallel
    #pragma omp parallel for schedule(dynamic)
    for (int i = 0; i < num_strings; i++) {
        MD5_Update(&ctx, strings[i], strlen(strings[i]));
        MD5_Final(hashes + i * 16, &ctx);
    }

    // Free the memory for the MD5 hashes
    free(hashes);
}

// Define the function to detect and report duplicate MD5 hash values
void detect_duplicates(unsigned char **hashes, int num_hashes) {
    // Allocate memory for the duplicate list
    unsigned char *duplicates = (unsigned char *)malloc(num_hashes * 16);
    if (!duplicates) {
        printf("Error: Failed to allocate memory for duplicate list\n");
        exit(1);
    }

    // Initialize the duplicate list
    memset(duplicates, 0, num_hashes * 16);

    // Iterate over the hashes and check for duplicates
    for (int i = 0; i < num_hashes; i++) {
        unsigned char *current_hash = hashes[i];
        for (int j = i + 1; j < num_hashes; j++) {
            unsigned char *other_hash = hashes[j];
            if (memcmp(current_hash, other_hash, 16) == 0) {
                duplicates[i] = 1;
                break;
            }
        }
    }

    // Print the duplicate list
    printf("Duplicate MD5 hashes:\n");
    for (int i = 0; i < num_hashes; i++) {
        if (duplicates[i]) {
            unsigned char *current_hash = hashes[i];
            printf("%d: %s\n", i, current_hash);
        }
    }

    // Free the memory for the duplicate list
    free(duplicates);
}

int main() {
