    int num_records = 1000;

    // Initialize the arrays for the offset, key, and data values
    long *offset_arr;
    int *key_arr;
    float *data_arr;
    init_arrays(num_records, &offset_arr, &key_arr, &data_arr);

    // Compute the MD5 hashes for a batch of strings in parallel
    char **strings = (char **)malloc(num_records * sizeof(char *));
    if (!strings) {
        printf("Error: Failed to allocate memory for string array\n");
        exit(1);
    }
    for (int i = 0; i < num_records; i++) {
        strings[i] = malloc(16 * sizeof(char));
        if (!strings[i]) {
            printf("Error: Failed to allocate memory for string %d\n", i);
            exit(1);
        }
    }
    compute_md5(strings, num_records);

    // Detect and report duplicate MD5 hash values
    unsigned char **hashes = (unsigned char **)malloc(num_records * sizeof(unsigned char *));
    if (!hashes) {
        printf("Error: Failed to allocate memory for hash array\n");
        exit(1);
    }
    for (int i = 0; i < num_records; i++) {
        hashes[i] = malloc(16 * sizeof(unsigned char));
        if (!hashes[i]) {
            printf("Error: Failed to allocate memory for hash %d\n", i);
            exit(1);
        }
    }
    compute_md5(strings, num_records);
    detect_duplicates(hashes, num_records);

    // Free the memory for the arrays and strings
    free(offset_arr);
    free(key_arr);
    free(data_arr);
    for (int i = 0; i < num_records; i++) {
        free(strings[i]);
        free(hashes[i]);
    }
    free(strings);
    free(hashes);

    return 0;
}
