    entry *entries = (entry *)malloc(num_entries * sizeof(entry));
    for (int i = 0; i < num_entries; i++) {
        entries[i].integer = integers[i % num_integers];
        entries[i].double_value = doubles[i % num_doubles];
        entries[i].active = flags[i % num_flags];
