    free(integers);
    free(flags);
    free(entries);

    // Process sequences in parallel using a configurable smoothing filter
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, process_sequence, &entries[i]);
    }
    for (int i = 0; i < 10; i++) {
