    } else if (algorithm == 'e') {
        // Exponential smoothing
        double alpha = 2.0 / (window_size + 1);
        for (int i = 0; i < window_size; i++) {
            entry->value += alpha * (entry->weight - entry->value) / (double)window_size;
        }
    }

    // Return the processed sequence
    return entry;
}
