    if (!seq->entries) {
        fprintf(stderr, "Failed to allocate memory for sequence entries\n");
        exit(1);
    }

    // Initialize the sequence metadata
    seq->num_entries = 0;
    seq->total_memory = BUFFER_SIZE * sizeof(entry_t);
}

// Define a function to add an entry to a sequence
void add_entry(sequence_t *seq, short int value, double weight) {
    // Check if the buffer is full and needs to be reallocated
    if (seq->num_entries == BUFFER_SIZE) {
        seq->total_memory += BUFFER_SIZE * sizeof(entry_t);
        seq->entries = (entry_t *)realloc(seq->entries, seq->total_memory);
        if (!seq->entries) {
            fprintf(stderr, "Failed to reallocate memory for sequence entries\n");
            exit(1);
        }
    }

    // Add the new entry to the sequence
    seq->entries[seq->num_entries].value = value;
    seq->entries[seq->num_entries].weight = weight;
    seq->entries[seq->num_entries].active = true;
    seq->num_entries++;
}

// Define a function to process a sequence in parallel
void process_sequence(sequence_t *seq) {
    // Initialize the smoothing filter with the window size
    int window_size = WINDOW_SIZE;

    // Apply the smoothing filter to each entry in the sequence
    for (int i = 0; i < seq->num_entries; i++) {
