    fclose(input);

    return sequence_number;
}

// Define a function to apply a smoothing filter to a numerical sequence
void smooth_sequence(sequence_t *seq, int window_size) {
    // Check if the sequence is too large for efficient processing
    handle_large_input(seq);

    // Process the sequence in parallel using the smoothing filter
    process_sequence(seq);
}

// Define a function to generate a string representation of a filtered numerical sequence
char *filtered_sequence_string(sequence_t *seq, int window_size) {
    // Check if the sequence is too large for efficient processing
    handle_large_input(seq);

    // Apply the smoothing filter to the sequence using the specified window size
    smooth_sequence(seq, window_size);

    // Allocate memory for the filtered string representation
    char *filtered_string = (char *)malloc(BUFFER_SIZE * sizeof(char));
    if (!filtered_string) {
        fprintf(stderr, "Failed to allocate memory for filtered sequence string\n");
        exit(1);
    }

    // Initialize the filtered string representation with the header
    sprintf(filtered_string, "%d", seq->num_entries);

    // Iterate over each entry in the sequence and append it to the filtered string
    for (int i = 0; i < seq->num_entries; i++) {
        char *entry_string = (char *)malloc(BUFFER_SIZE * sizeof(char));
        if (!entry_string) {
            fprintf(stderr, "Failed to allocate memory for filtered sequence entry string\n");
            exit(1);
        }
        sprintf(entry_string, "%d %f", seq->entries[i].value, seq->entries[i].weight);
        strcat(filtered_string, entry_string);
    }

    // Release the memory allocated for the filtered string representation
    free(filtered_string);

    return filtered_string;
}
