#include <mutex>
#include <condition_variable>
#include <thread>

struct OctreeNode {
  std::vector<int> records;
  std::vector<OctreeNode*> childNodes;
};

void initializeOctreeWithRecords(const int featureSize, const int numLeafNodes, const int dataCapacity) {
  // Dynamically allocate memory for the octree and its nodes
  OctreeNode* root = new OctreeNode();
  std::vector<OctreeNode*> leafNodes;
  for (int i = 0; i < numLeafNodes; ++i) {
    leafNodes.push_back(new OctreeNode());
  }

  // Initialize the records in each node with random values within the specified range
  std::random_device rd;
  std::mt19937 gen(rd());
  std::uniform_int_distribution<int> distribution(0, dataCapacity);
  for (auto& leafNode : leafNodes) {
    for (int i = 0; i < featureSize; ++i) {
      leafNode->records.push_back(distribution(gen));
    }
  }

  // Set the child nodes of each non-leaf node to point to its corresponding leaf node
  for (auto& node : leafNodes) {
    int index = std::distance(&leafNodes[0], &node);
    root->childNodes.push_back(node);
    if (index < numLeafNodes - 1) {
      root->childNodes.push_back(leafNodes[index + 1]);
    } else {
      root->childNodes.push_back(leafNodes[0]);
    }
  }

  // Track the total memory usage of all allocated structures
  std::mutex mtx;
  std::condition_variable cv;
  std::thread t([&]() {
    while (true) {
      std::unique_lock<std::mutex> lock(mtx);
      cv.wait(lock, [&]() { return root->childNodes.size() == numLeafNodes; });
      int totalMemoryUsage = 0;
      for (auto& node : leafNodes) {
        totalMemoryUsage += sizeof(OctreeNode) + node->records.capacity() * sizeof(int);
      }
      std::cout << "Total memory usage: " << totalMemoryUsage << " bytes" << std::endl;
    }
  });
  t.detach();

  // Handle concurrent access to shared resources safely
  std::mutex mtx2;
  std::condition_variable cv2;
  std::thread t2([&]() {
    while (true) {
      std::unique_lock<std::mutex> lock(mtx2);
      cv2.wait(lock, [&]() { return root->childNodes.size() == numLeafNodes; });
      for (auto& node : leafNodes) {
        for (int i = 0; i < featureSize; ++i) {
          std::cout << "Record: " << node->records[i] << std::endl;
        }
      }
    }
  });
  t2.detach();

  // Free memory upon function exit
  ~initializeOctreeWithRecords() {
    for (auto& node : leafNodes) {
      delete node;
    }
    delete root;
  }
}
