['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>
#include <math.h>

// Define the maximum number of transactions to process per second
#define MAX_TRANSACTIONS 1000000

// Define the age threshold for filtering transactions (in seconds)
#define AGE_THRESHOLD 5

// Define the count threshold for filtering transactions (in seconds)
#define COUNT_THRESHOLD 3

// Define the weighted sum threshold for filtering transactions (in units of the transaction weight)
#define WEIGHTED_SUM_THRESHOLD 1000

// Define the predefined threshold for triggering alerts (in seconds)
#define ALERT_THRESHOLD 2

// Define the logging file path
#define LOGGING_FILE "/var/log/transaction-processing.log"

// Define the metrics file path
#define METRICS_FILE "/var/metrics/transaction-processing.txt"

// Define the semaphore for synchronizing access to the transaction queue
sem_t *queue_sem;

// Define the mutex for protecting the transaction queue and metrics
pthread_mutex_t *queue_mutex;

// Define the condition variable for signaling when a new transaction is available
pthread_cond_t *new_transaction_cv;

// Define the transaction queue
struct transaction_queue {
    int head;
    int tail;
    struct transaction transactions[MAX_TRANSACTIONS];
};

// Define the transaction structure
struct transaction {
    long id;
    double weighted_sum;
    time_t age;
    int count;
};

// Define the metrics structure
struct metrics {
    long total_transactions;
    double average_transaction_age;
    long highest_weighted_sum;
};

// Initialize the transaction queue and metrics
void init() {
    // Create the semaphore for synchronizing access to the transaction queue
    if (sem_init(queue_sem, 0, MAX_TRANSACTIONS) == -1) {
        perror("Error creating semaphore");
        exit(EXIT_FAILURE);
    }

    // Create the mutex for protecting the transaction queue and metrics
    if (pthread_mutex_init(queue_mutex, NULL) == -1) {
        perror("Error creating mutex");
        exit(EXIT_FAILURE);
    }

    // Initialize the condition variable for signaling when a new transaction is available
    if (pthread_cond_init(new_transaction_cv, NULL) == -1) {
        perror("Error creating condition variable");
        exit(EXIT_FAILURE);
    }

    // Initialize the transaction queue and metrics
    struct transaction_queue *queue = malloc(sizeof(struct transaction_queue));
    memset(queue, 0, sizeof(struct transaction_queue));
    struct metrics *metrics = malloc(sizeof(struct metrics));
    memset(metrics, 0, sizeof(struct metrics));
}

// Add a new transaction to the queue and signal any waiting threads
void add_transaction(long id, double weighted_sum, time_t age, int count) {
    // Acquire the semaphore for synchronizing access to the transaction queue
    if (sem_wait(queue_sem) == -1) {
        perror("Error waiting on semaphore");
        exit(EXIT_FAILURE);
    }

    // Lock the mutex for protecting the transaction queue and metrics
    if (pthread_mutex_lock(queue_mutex) == -1) {
        perror("Error locking mutex");
        exit(EXIT_FAILURE);
    }

    // Add the new transaction to the queue
    struct transaction *transaction = malloc(sizeof(struct transaction));
    memset(transaction, 0, sizeof(struct transaction));
    transaction->id = id;
    transaction->weighted_sum = weighted_sum;
    transaction->age = age;
    transaction->count = count;
    queue->tail = (queue->tail + 1) % MAX_TRANSACTIONS;
    queue->transactions[queue->tail] = *transaction;

    // Update the metrics
    metrics->total_transactions++;
    metrics->average_transaction_age += age;
    if (weighted_sum > metrics->highest_weighted_sum) {
        metrics->highest_weighted_sum = weighted_sum;
    }

    // Signal any waiting threads that a new transaction is available
    pthread_cond_signal(new_transaction_cv);

    // Release the mutex for protecting the transaction queue and metrics
    if (pthread_mutex_unlock(queue_mutex) == -1) {
        perror("Error unlocking mutex");
        exit(EXIT_FAILURE);
    }

    // Release the semaphore for synchronizing access to the transaction queue
    if (sem_post(queue_sem) == -1) {
        perror("Error posting to semaphore");
        exit(EXIT_FAILURE);
    }
}

// Filter transactions based on the given criteria and return the highest weighted sum
long filter_transactions() {
    // Acquire the semaphore for synchronizing access to the transaction queue
    if (sem_wait(queue_sem) == -1) {
        perror("Error waiting on semaphore");
        exit(EXIT_FAILURE);
    }

    // Lock the mutex for protecting the transaction queue and metrics
    if (pthread_mutex_lock(queue_mutex) == -1) {
        perror("Error locking mutex");
        exit(EXIT_FAILURE);
    }

    // Filter transactions based on the given criteria
    long highest_weighted_sum = 0;
    for (int i = queue->head; i != queue->tail; i = (i + 1) % MAX_TRANSACTIONS) {
        struct transaction *transaction = &queue->transactions[i];
        if (transaction->age > AGE_THRESHOLD || transaction->count > COUNT_THRESHOLD || transaction->weighted_sum > WEIGHTED_SUM_THRESHOLD) {
            continue;
        } else {
            highest_weighted_sum = fmax(highest_weighted_sum, transaction->weighted_sum);
        }
    }

    // Update the metrics
    metrics->total_transactions -= queue->tail - queue->head;
    metrics->average_transaction_age /= (queue->tail - queue->head);

    // Release the mutex for protecting the transaction queue and metrics
    if (pthread_mutex_unlock(queue_mutex) == -1) {
        perror("Error unlocking mutex");
        exit(EXIT_FAILURE);
    }

    // Release the semaphore for synchronizing access to the transaction queue
    if (sem_post(queue_sem) == -1) {
        perror("Error posting to semaphore");
        exit(EXIT_FAILURE);
    }

    return highest_weighted_sum;
}

// Update the metrics and log any filtered transactions
void update_metrics() {
    // Acquire the semaphore for synchronizing access to the transaction queue
    if (sem_wait(queue_sem) == -1) {
        perror("Error waiting on semaphore");
        exit(EXIT_FAILURE);
    }

    // Lock the mutex for protecting the transaction queue and metrics
    if (pthread_mutex_lock(queue_mutex) == -1) {
        perror("Error locking mutex");
        exit(EXIT_FAILURE);
    }

    // Update the metrics
    metrics->total_transactions -= queue->tail - queue->head;
    metrics->average_transaction_age /= (queue->tail - queue->head);

    // Log any filtered transactions
    for (int i = queue->head; i != queue->tail; i = (i + 1) % MAX_TRANSACTIONS) {
        struct transaction *transaction = &queue->transactions[i];
        if (transaction->age > AGE_THRESHOLD || transaction->count > COUNT_THRESHOLD || transaction->weighted_sum > WEIGHTED_SUM_THRESHOLD) {
            char log_message[256];
            snprintf(log_message, sizeof(log_message), "Filtered transaction: id=%ld, weighted_sum=%f, age=%d, count=%d", transaction->id, transaction->weighted_sum, transaction->age, transaction->count);
            write_to_file(LOGGING_FILE, log_message);
        }
    }

    // Release the mutex for protecting the transaction queue and metrics
    if (pthread_mutex_unlock(queue_mutex) == -1) {
        perror("Error unlocking mutex");
        exit(EXIT_FAILURE);
    }

    // Release the semaphore for synchronizing access to the transaction queue
    if (sem_post(queue_sem) == -1) {
        perror("Error posting to semaphore");
        exit(EXIT_FAILURE);
    }
}

// Write a message to a file
void write_to_file(const char *filename, const char *message) {
    // Open the file for appending
    int fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    // Write the message to the file
    ssize_t bytes_written = write(fd, message, strlen(message));
    if (bytes_written == -1) {
        perror("Error writing to file");
        exit(EXIT_FAILURE);
    }

    // Close the file
    close(fd);
}

// Gracefully shut down the function and flush any pending transactions
void shutdown() {
    // Acquire the semaphore for synchronizing access to the transaction queue
    if (sem_wait(queue_sem) == -1) {
        perror("Error waiting on semaphore");
        exit(EXIT_FAILURE);
    }

    // Lock the mutex for protecting the transaction queue and metrics
    if (pthread_mutex_lock(queue_mutex) == -1) {
        perror("Error locking mutex");
        exit(EXIT_FAILURE);
    }

    // Flush any pending transactions
    while (queue->head != queue->tail) {
        struct transaction *transaction = &queue->transactions[queue->head];
        write_to_file(LOGGING_FILE, "Flushed transaction: id=%ld, weighted_sum=%f, age=%d, count=%d", transaction->id, transaction->weighted_sum, transaction->age, transaction->count);
        queue->head = (queue->head + 1) % MAX_TRANSACTIONS;
    }

    // Update the metrics
    metrics->total_transactions = 0;
    metrics->average_transaction_age = 0;
    metrics->highest_weighted_sum = 0;

    // Release the mutex for protecting the transaction queue and metrics
    if (pthread_mutex_unlock(queue_mutex) == -1) {
        perror("Error unlocking mutex");
        exit(EXIT_FAILURE);
    }

    // Release the semaphore for synchronizing access to the transaction queue
    if (sem_post(queue_sem) == -1) {
        perror("Error posting to semaphore");
        exit(EXIT_FAILURE);
    }
}

// Monitor the function's performance and trigger alerts as necessary
void monitor() {
    // Acquire the semaphore for synchronizing access to the transaction queue
    if (sem_wait(queue_sem) == -1) {
        perror("Error waiting on semaphore");
        exit(EXIT_FAILURE);
    }

    // Lock the mutex for protecting the transaction queue and metrics
    if (pthread_mutex_lock(queue_mutex) == -1) {
        perror("Error locking mutex");
        exit(EXIT_FAILURE);
    }

    // Monitor the function's performance
    double cpu_usage = 0;
    long memory_consumption = 0;
    long transaction_processing_rate = 0;
    for (int i = queue->head; i != queue->tail; i = (i + 1) % MAX_TRANSACTIONS) {
        struct transaction *transaction = &queue->transactions[i];
        cpu_usage += transaction->weighted_sum / metrics->total_transactions;
        memory_consumption += transaction->age * sizeof(struct transaction);
        transaction_processing_rate++;
    }

    // Trigger alerts as necessary
    if (cpu_usage > 0.8) {
        write_to_file(LOGGING_FILE, "CPU usage exceeded threshold: %f", cpu_usage);
    }
    if (memory_consumption > 100 * 1024 * 1024) {
        write_to_file(LOGGING_FILE, "Memory consumption exceeded threshold: %ld MB", memory_consumption / (1024 * 1024));
    }
    if (transaction_processing_rate > MAX_TRANSACTIONS / 2) {
        write_to_file(LOGGING_FILE, "Transaction processing rate exceeded threshold: %ld transactions/second", transaction_processing_rate);
    }

    // Release the mutex for protecting the transaction queue and metrics
    if (pthread_mutex_unlock(queue_mutex) == -1) {
        perror("Error unlocking mutex");
        exit(EXIT_FAILURE);
    }

    // Release the semaphore for synchronizing access to the transaction queue
    if (sem_post(queue_sem) == -1) {
        perror("Error posting to semaphore");
        exit(EXIT_FAILURE);
    }
}
