public class LoadMoSTStateFromFile {
    private static final Logger LOGGER = Logger.getLogger(LoadMoSTStateFromFile.class.getName());

    public static MoSTState loadMoSTStateFromFile(String filePath) throws IOException {
        FileInputStream inputStream = new FileInputStream(filePath);
        ObjectInputStream objectInputStream = new ObjectInputStream(inputStream);

        try {
            // Read the first byte to determine if the file contains a compatible object
            int firstByte = objectInputStream.read();
            if (firstByte == -1) {
                return null;
            }

            // Create an instance of the MoSTState class and deserialize it from the input stream
            MoSTState state = new MoSTState();
            objectInputStream.readFully(state);

            // Close the ObjectInputStream to prevent resource leaks
            objectInputStream.close();

            return state;
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "Error reading file", e);
            return null;
        } finally {
            if (objectInputStream != null) {
                try {
                    objectInputStream.close();
                } catch (IOException e) {
                    LOGGER.log(Level.WARNING, "Error closing ObjectInputStream", e);
                }
            }
        }
    }
}
