// Define a function to compute the SHA-256 hash of a file path in parallel
void compute_sha256(char *file_path) {
    // Open the file for reading
    FILE *fp = fopen(file_path, "r");
    if (!fp) {
        printf("Error: Failed to open file %s\n", file_path);
        return;
    }

    // Allocate memory for the buffer
    char *buffer = (char *)malloc(1024 * sizeof(char));
    if (!buffer) {
        printf("Error: Failed to allocate memory for buffer\n");
        fclose(fp);
        return;
    }

    // Initialize the SHA-256 context
    SHA256_CTX ctx;
    SHA256_Init(&ctx);

    // Read the file in chunks and update the hash
    while (!feof(fp)) {
        size_t bytes_read = fread(buffer, 1, 1024 * sizeof(char), fp);
        if (bytes_read > 0) {
            SHA256_Update(&ctx, buffer, bytes_read);
        }
    }

    // Finalize the hash and print it to stdout
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Final(hash, &ctx);
    printf("Hash of %s: ", file_path);
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        printf("%02x", hash[i]);
    }
    printf("\n");

    // Clean up resources
    free(buffer);
    fclose(fp);
}

// Define a function to process a batch of file paths in parallel
void process_file_paths(char **file_paths, int num_file_paths) {
    // Create a pool of worker threads to compute the SHA-256 hashes
    pthread_t *threads = (pthread_t *)malloc(num_file_paths * sizeof(pthread_t));
    if (!threads) {
        printf("Error: Failed to allocate memory for threads\n");
        return;
    }

    // Initialize the worker threads
    for (int i = 0; i < num_file_paths; i++) {
        pthread_create(&threads[i], NULL, compute_sha256, file_paths[i]);
    }

    // Wait for all worker threads to complete
    for (int i = 0; i < num_file_paths; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up resources
    free(threads);
}

// Define a function to detect and report duplicate SHA-256 hash values
void detect_duplicates(char **file_paths, int num_file_paths) {
    // Create a set of unique SHA-256 hashes
    unsigned char *hashes = (unsigned char *)malloc(num_file_paths * sizeof(unsigned char));
    if (!hashes) {
        printf("Error: Failed to allocate memory for hashes\n");
        return;
    }

    // Initialize the set of unique SHA-256 hashes
    for (int i = 0; i < num_file_paths; i++) {
        unsigned char *hash = compute_sha256(file_paths[i]);
        if (!hash) {
            printf("Error: Failed to compute SHA-256 hash of %s\n", file_paths[i]);
            continue;
        }
        hashes[i] = *hash;
    }

    // Detect duplicate SHA-256 hash values
    for (int i = 0; i < num_file_paths - 1; i++) {
        for (int j = i + 1; j < num_file_paths; j++) {
            if (hashes[i] == hashes[j]) {
                printf("Duplicate SHA-256 hash value found: %s and %s\n", file_paths[i], file_paths[j]);
            }
        }
    }

    // Clean up resources
    free(hashes);
}

int main() {
    // Initialize the arrays containing 'double' precision numbers, 'unsigned int' IDs, and 'char' labels
    init_arrays(100, 50, 26);

    // Process a batch of file paths in parallel
    char *file_paths[] = {"path/to/file1", "path/to/file2", "path/to/file3"};
    process_file_paths(file_paths, 3);

    // Detect and report duplicate SHA-256 hash values
    detect_duplicates(file_paths, 3);

    return 0;
}
