#include <pthread.h>

// Define the structure for NetworkDevice
typedef struct {
    int DeviceID;
    int PortCount;
    float BandwidthUsage;
} NetworkDevice;

// Define a hash table to store the devices
static pthread_mutex_t device_table_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t device_table_cv = PTHREAD_COND_INITIALIZER;
static NetworkDevice* device_table = NULL;

// Function to initialize the device table
void init_device_table() {
    // Allocate memory for the hash table
    device_table = (NetworkDevice*)malloc(sizeof(NetworkDevice) * 10);
    if (!device_table) {
        perror("Failed to allocate memory for device table");
        exit(EXIT_FAILURE);
    }

    // Initialize the hash table with empty slots
    for (int i = 0; i < 10; i++) {
        device_table[i].DeviceID = -1;
        device_table[i].PortCount = 0;
        device_table[i].BandwidthUsage = 0.0f;
    }
}

// Function to add a new device to the table
void add_device(int DeviceID, int PortCount) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&device_table_lock);

    // Check if the device ID is already in use
    for (int i = 0; i < 10; i++) {
        if (device_table[i].DeviceID == DeviceID) {
            pthread_mutex_unlock(&device_table_lock);
            return;
        }
    }

    // Find an empty slot in the hash table
    int index = -1;
    for (int i = 0; i < 10; i++) {
        if (device_table[i].DeviceID == -1) {
            index = i;
            break;
        }
    }

    // If no empty slot is found, increase the size of the hash table
    if (index == -1) {
        NetworkDevice* new_table = (NetworkDevice*)realloc(device_table, sizeof(NetworkDevice) * 20);
        if (!new_table) {
            perror("Failed to reallocate memory for device table");
            exit(EXIT_FAILURE);
        }
        device_table = new_table;
        index = 10;
    }

    // Add the new device to the hash table
    device_table[index].DeviceID = DeviceID;
    device_table[index].PortCount = PortCount;
    device_table[index].BandwidthUsage = 0.0f;

    // Release the lock on the hash table
    pthread_mutex_unlock(&device_table_lock);
}

// Function to update the bandwidth usage for a device
void update_bandwidth_usage(int DeviceID, float BandwidthUsage) {
    // Acquire the lock on the hash table
    pthread_mutex_lock(&device_table_lock);

    // Find the device in the hash table
    int index = -1;
    for (int i = 0; i < 10; i++) {
        if (device_table[i].DeviceID == DeviceID) {
            index = i;
            break;
        }
    }

    // If the device is not found, return
    if (index == -1) {
        pthread_mutex_unlock(&device_table_lock);
        return;
    }

    // Update the bandwidth usage for the device
    device_table[index].BandwidthUsage = BandwidthUsage;

    // Release the lock on the hash table
    pthread_mutex_unlock(&device_table_lock);
}

// Function to query the total bandwidth usage across all devices
float get_total_bandwidth_usage() {
    float total_usage = 0.0f;

    // Acquire the lock on the hash table
    pthread_mutex_lock(&device_table_lock);

    // Iterate over all devices in the hash table and calculate the total usage
    for (int i = 0; i < 10; i++) {
        if (device_table[i].DeviceID != -1) {
            total_usage += device_table[i].BandwidthUsage;
        }
    }

    // Release the lock on the hash table
    pthread_mutex_unlock(&device_table_lock);

    return total_usage;
}

// Function to free the memory allocated for the device table
void free_device_table() {
