// Function to read a list of floating-point numbers from standard input
float* read_numbers(int *num_read) {
  // Allocate memory for the array
  float *arr = malloc(100 * sizeof(float));
  if (arr == NULL) {
    fprintf(stderr, "Error: Failed to allocate memory for array\n");
    return NULL;
  }

  // Read numbers from standard input and validate them
  int i = 0;
  while (i < 100 && scanf("%f", &arr[i]) == 1) {
    if (!(arr[i] >= -100.0 && arr[i] <= 100.0)) {
      fprintf(stderr, "Error: Number out of range\n");
      break;
    }
    i++;
  }

  // If the array is empty, print an appropriate message and return NULL
  if (i == 0) {
    printf("No numbers were read\n");
    free(arr);
    return NULL;
  }

  // Calculate mean, median, and standard deviation of the numbers in the array
  float sum = 0.0;
  for (int j = 0; j < i; j++) {
    sum += arr[j];
  }
  float mean = sum / i;
  float median = 0.0;
  if (i % 2 == 0) {
    median = (arr[i/2] + arr[(i/2) - 1]) / 2.0;
  } else {
    median = arr[i/2];
  }
  float stddev = 0.0;
  for (int j = 0; j < i; j++) {
    stddev += pow(arr[j] - mean, 2);
  }
  stddev /= i - 1;
  stddev = sqrt(stddev);

  // Print the results
  printf("Mean: %f\n", mean);
  printf("Median: %f\n", median);
  printf("Standard deviation: %f\n", stddev);

  *num_read = i;
  return arr;
}
