using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public static async Task<string> ModifyKickstartConfigAsync(string encryptedMessage, Dictionary<string, string> parameters)
{
    // Validate input parameters
    if (encryptedMessage == null || parameters == null)
        throw new ArgumentNullException();

    // Decrypt the message using Triple DES encryption with a provided key and initialization vector (IV)
    byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage);
    byte[] decryptedBytes = await DecryptAsync(encryptedBytes, parameters["key"], parameters["iv"]);

    // Modify the Kickstart configuration file by replacing the specified placeholders with their corresponding values
    string configFilePath = parameters["configFilePath"];
    string modifiedConfig = ReplacePlaceholders(decryptedBytes, parameters);

    // Generate an encrypted password using a secure random number generator and store it in the file
    byte[] passwordBytes = await GeneratePasswordAsync();
    string password = Convert.ToBase64String(passwordBytes);
    modifiedConfig += $"\npassword = {password}";

    // Write the modified configuration to disk asynchronously
    using (FileStream fs = new FileStream(configFilePath, FileMode.Create))
    {
        await fs.WriteAsync(Encoding.UTF8.GetBytes(modifiedConfig));
    }

    return configFilePath;
}

private static async Task<byte[]> DecryptAsync(byte[] encryptedBytes, string key, string iv)
{
    using (TripleDES des = TripleDES.Create())
    {
        des.Key = Encoding.UTF8.GetBytes(key);
        des.IV = Encoding.UTF8.GetBytes(iv);
        return await des.DecryptAsync(encryptedBytes);
    }
}

private static async Task<byte[]> GeneratePasswordAsync()
{
    using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
    {
        byte[] passwordBytes = new byte[32];
        await rng.GetNonZeroBytesAsync(passwordBytes);
        return passwordBytes;
    }
}

private static string ReplacePlaceholders(byte[] decryptedBytes, Dictionary<string, string> parameters)
{
    string configFileContent = Encoding.UTF8.GetString(decryptedBytes);
    foreach (var parameter in parameters)
    {
        configFileContent = configFileContent.Replace($"{{{parameter.Key}}}", parameter.Value);
    }
    return configFileContent;
}
