Here is the Python function that calculates both MD5 and SHA-256 hashes of large files given their paths, supporting parallel processing for efficient hashing:
```python
import os
import hashlib
from concurrent.futures import ThreadPoolExecutor

def calculate_hashes(file_paths, base_dir=None):
    """
    Calculates both MD5 and SHA-256 hashes of large files given their paths, supporting parallel processing for efficient hashing.

    Args:
        file_paths (list[str]): List of file paths to calculate the hashes for.
        base_dir (str, optional): Base directory to resolve relative file paths against. Defaults to None.

    Returns:
        dict: Dictionary containing the hexdigests of the MD5 and SHA-256 hashes for each file path.
    """
    # Initialize a dictionary to store the hashes
    hashes = {}

    # Create a thread pool executor with a fixed number of threads based on the number of CPU cores
    with ThreadPoolExecutor(max_workers=os.cpu_count()) as executor:
        # Iterate over the file paths and calculate the hashes in parallel using the thread pool executor
        for file_path in file_paths:
            if base_dir is not None:
                file_path = os.path.join(base_dir, file_path)
            with open(file_path, 'rb') as f:
                # Read the file in chunks and compute the hashes using the hashlib library
                for chunk in iter(lambda: f.read(1024), b''):
                    md5 = hashlib.md5()
                    sha256 = hashlib.sha256()
                    md5.update(chunk)
                    sha256.update(chunk)
                    # Store the hashes in the dictionary
                    hashes[file_path] = {
                        'md5': md5.hexdigest(),
                        'sha256': sha256.hexdigest()
                    }

    return hashes
