```csharp
using System;
using System.Security.Cryptography;
using System.Text;

public static string Decrypt(string encryptedMessage, string key, string iv)
{
    // Convert the Base64-encoded message to bytes
    byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage);

    // Create a new TripleDESCryptoServiceProvider object with the provided key and IV
    using (TripleDESCryptoServiceProvider csp = new TripleDESCryptoServiceProvider())
    {
        // Set the key and IV on the csp object
        csp.Key = Encoding.UTF8.GetBytes(key);
        csp.IV = Encoding.UTF8.GetBytes(iv);

        // Create a new MemoryStream to hold the decrypted data
        using (MemoryStream ms = new MemoryStream())
        {
            // Decrypt the encrypted bytes and write them to the memory stream
            using (CryptoStream cs = new CryptoStream(ms, csp.CreateDecryptor(), CryptoStreamMode.Write))
            {
                cs.Write(encryptedBytes, 0, encryptedBytes.Length);
                cs.FlushFinalBlock();
            }

            // Return the decrypted data as a string
            return Encoding.UTF8.GetString(ms.ToArray());
        }
    }
}
