            logger.error(f'Error calculating hash for {file_path}: File not found or insufficient memory')

    # Return hashes and logging summary
    return {'hashes': file_hashes, 'logging_summary': logger.get_log_summary()}

def calculate_hash(file_path):
    """
    Calculates the MD5 and SHA-256 hashes of a file using the `hashlib` library.

    Args:
        file_path (str): Path to the file to be hashed.

    Returns:
        dict: Dictionary containing the hexdigests of the hashes.
    """
    # Initialize variables
    md5 = hashlib.md5()
    sha256 = hashlib.sha256()
    chunk_size = 1024 * 1024  # 1 MB

    # Open file and calculate hashes in chunks
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            md5.update(data)
            sha256.update(data)

    # Return hashes
    return {'md5': md5.hexdigest(), 'sha256': sha256.hexdigest()}
