using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace DynamicValueManager
{
    public class DynamicValueManager
    {
        private List<Range> _ranges = new List<Range>();

        public void AddRange(float min, float max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

            var range = new Range(min, max);
            _ranges.Add(range);
        }

        public void RemoveRange(float min, float max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

            var range = new Range(min, max);
            _ranges.Remove(range);
        }

        public void ShiftRange(float offset)
        {
            foreach (var range in _ranges)
            {
                range.Min += offset;
                range.Max += offset;
            }
        }

        public void ScaleRange(float factor)
        {
            foreach (var range in _ranges)
            {
                range.Min *= factor;
                range.Max *= factor;
            }
        }

        public void MergeRanges(float min, float max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

            var range = new Range(min, max);
            _ranges.Add(range);
        }

        public void GenerateRandomFloatValue()
        {
            foreach (var range in _ranges)
            {
                float randomValue = range.Min + (float)(range.Max - range.Min) * new Random().NextDouble();
                Console.WriteLine($"Generated value: {randomValue}");
            }
        }

        public void GenerateRandomIntegerValue()
        {
            foreach (var range in _ranges)
            {
                int randomValue = new Random().Next(range.Min, range.Max + 1);
                Console.WriteLine($"Generated value: {randomValue}");
            }
        }

        public void SerializeToJson()
        {
            // Implement serialization logic here
        }

        public void DeserializeFromJson(string json)
        {
            // Implement deserialization logic here
        }

        public float CalculateMean()
        {
            var sum = 0f;
            foreach (var range in _ranges)
            {
                sum += range.Min + range.Max;
            }
            return sum / (_ranges.Count * 2);
        }

        public float CalculateStandardDeviation()
        {
            var mean = CalculateMean();
            var variance = 0f;
            foreach (var range in _ranges)
            {
                variance += Math.Pow(range.Min + range.Max - mean, 2);
            }
            return (float)Math.Sqrt(variance / (_ranges.Count * 2));
        }

        public int FindSmallestValue()
        {
            var smallest = int.MaxValue;
            foreach (var range in _ranges)
            {
                if (range.Min < smallest)
                    smallest = range.Min;
            }
            return smallest;
        }

        public int FindLargestValue()
        {
            var largest = int.MinValue;
            foreach (var range in _ranges)
            {
                if (range.Max > largest)
                    largest = range.Max;
            }
            return largest;
        }

        public void LogRandomValues()
        {
            // Implement logging logic here
        }

        public override string ToString()
        {
            var sb = new StringBuilder();
            foreach (var range in _ranges)
            {
                sb.AppendLine($"Range: [{range.Min}, {range.Max}]");
            }
            return sb.ToString();
        }
    }

    public class Range
    {
        public float Min { get; set; }
        public float Max { get; set; }

        public Range(float min, float max)
        {
            Min = min;
            Max = max;
        }
    }
}
