#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <locale.h>

// Define a structure to represent a resource bundle item
typedef struct {
    char *key;
    char *value;
} ResourceBundleItem;

// Define a structure to represent the resource bundle
typedef struct {
    ResourceBundleItem **items;
    size_t numItems;
    size_t capacity;
} ResourceBundle;

// Function to load a resource bundle from a file
int loadResourceBundle(const char *filePath, const char *locale) {
    // Open the file for reading
    FILE *file = fopen(filePath, "r");
    if (file == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Create a new resource bundle with an initial capacity of 10 items
    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (bundle == NULL) {
        fclose(file);
        perror("Error allocating memory for resource bundle");
        return -1;
    }
    bundle->items = malloc(10 * sizeof(ResourceBundleItem *));
    if (bundle->items == NULL) {
        free(bundle);
        fclose(file);
        perror("Error allocating memory for resource bundle items");
        return -1;
    }
    bundle->numItems = 0;
    bundle->capacity = 10;

    // Read the file line by line and parse each non-comment line
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Trim leading and trailing whitespace from the line
        char *trimmedLine = trimWhitespace(line);

        // Ignore empty lines and comments
        if (strlen(trimmedLine) == 0 || trimmedLine[0] == '#') {
            continue;
        }

        // Parse the key-value pair from the line
        char *key = strtok(trimmedLine, "=");
        char *value = strtok(NULL, "=");

        // Add the item to the resource bundle if it is unique
        if (isUniqueItem(bundle, key)) {
            addItemToBundle(bundle, key, value);
        }
    }

    // Close the file and free the line buffer
    fclose(file);
    free(line);

    // Return the number of items in the resource bundle
    return bundle->numItems;
}

// Function to trim leading and trailing whitespace from a string
char *trimWhitespace(char *str) {
    size_t len = strlen(str);
    size_t start = 0;
    while (isspace(str[start])) {
        start++;
    }
    size_t end = len - 1;
    while (isspace(str[end]) && end >= start) {
        end--;
    }
    if (start > 0 || end < len - 1) {
        str[start] = '\0';
        return &str[start];
    } else {
        return str;
    }
}

// Function to check if an item is unique in the resource bundle
bool isUniqueItem(ResourceBundle *bundle, const char *key) {
    for (size_t i = 0; i < bundle->numItems; i++) {
        if (strcasecmp(bundle->items[i]->key, key) == 0) {
            return false;
        }
    }
    return true;
}

// Function to add an item to the resource bundle
void addItemToBundle(ResourceBundle *bundle, const char *key, const char *value) {
    // Check if the capacity of the bundle needs to be increased
    if (bundle->numItems == bundle->capacity) {
        ResourceBundleItem **newItems = realloc(bundle->items, 2 * bundle->capacity * sizeof(ResourceBundleItem *));
        if (newItems == NULL) {
            perror("Error reallocating memory for resource bundle items");
            return;
        }
        bundle->items = newItems;
        bundle->capacity *= 2;
    }

    // Create a new item and add it to the bundle
    ResourceBundleItem *item = malloc(sizeof(ResourceBundleItem));
    if (item == NULL) {
        perror("Error allocating memory for resource bundle item");
        return;
    }
    item->key = strdup(key);
    item->value = strdup(value);
    bundle->items[bundle->numItems++] = item;
}

// Function to free the memory allocated for a resource bundle
void freeResourceBundle(ResourceBundle *bundle) {
    // Free each item in the bundle
    for (size_t i = 0; i < bundle->numItems; i++) {
        free(bundle->items[i]->key);
        free(bundle->items[i]->value);
        free(bundle->items[i]);
    }

    // Free the array of items and the bundle structure itself
    free(bundle->items);
    free(bundle);
}
