#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/md5.h>

typedef struct {
    int key;
    float data;
    char status;
} record;

void generate_data(char* filename, int limit) {
    // Allocate memory for arrays of long, int, and float values
    long* offset_array = (long*)malloc(sizeof(long) * 10);
    int* key_array = (int*)malloc(sizeof(int) * 10);
    float* data_array = (float*)malloc(sizeof(float) * 10);

    // Allocate memory for an array of record structures
    record* records = (record*)malloc(sizeof(record) * 10);

    // Initialize arrays with random values
    srand(time(NULL));
    for (int i = 0; i < 10; i++) {
        offset_array[i] = rand() % limit;
        key_array[i] = rand() % limit;
        data_array[i] = (float)rand() / RAND_MAX * limit;
    }

    // Initialize records with random values
    for (int i = 0; i < 10; i++) {
        records[i].key = key_array[i];
        records[i].data = data_array[i];
        records[i].status = 'A';
    }

    // Compute MD5 hashes in parallel
    #pragma omp parallel for schedule(dynamic)
    for (int i = 0; i < 10; i++) {
        char* md5_hash = (char*)malloc(32);
        MD5((unsigned char*)&records[i], sizeof(record), md5_hash);
        records[i].md5_hash = md5_hash;
    }

    // Detect and report duplicate MD5 hash values
    for (int i = 0; i < 10; i++) {
        for (int j = i + 1; j < 10; j++) {
            if (strcmp(records[i].md5_hash, records[j].md5_hash) == 0) {
                printf("Duplicate MD5 hash value found: %s\n", records[i].md5_hash);
            }
        }
    }

    // Release memory
    free(offset_array);
    free(key_array);
    free(data_array);
    free(records);
}

void modify_filename(char* filename, int digits, char* filetype) {
    // Get the original filename and extension
    char* orig_filename = strtok(filename, ".");
    char* orig_extension = strtok(NULL, "\0");

    // Create a new filename with the specified number of digits and file type
    int len = strlen(orig_filename) + strlen(filetype) + digits;
    char* new_filename = (char*)malloc(len);
    sprintf(new_filename, "%s%0*d.%s", orig_filename, digits, 1, filetype);

    // Free the original filename and extension
    free(orig_filename);
    free(orig_extension);

    return new_filename;
}
