#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure to store the data
typedef struct {
    long offset;
    int key;
    char* string;
} Data;

// Function to read and process input from standard input
void readInput(Data** data, size_t* num_data) {
    // Initialize the arrays for storing the data
    *data = (Data*)malloc(sizeof(Data) * 10);
    *num_data = 0;

    // Read and process input from standard input
    while (fscanf(stdin, "%ld %d %s", &(*data)[*num_data].offset, &(*data)[*num_data].key, (*data)[*num_data].string) == 3) {
        // Increment the number of data points
        *num_data += 1;
    }
}

// Function to find and print the largest integer with its corresponding string
void findLargestInteger(Data** data, size_t num_data) {
    long largest_offset = -1;
    int largest_key = -1;
    char* largest_string = NULL;

    // Iterate over the data and find the largest integer
    for (size_t i = 0; i < num_data; i++) {
        if ((*data)[i].offset > largest_offset) {
            largest_offset = (*data)[i].offset;
            largest_key = (*data)[i].key;
            largest_string = (*data)[i].string;
        }
    }

    // Print the largest integer with its corresponding string
    printf("Largest integer: %ld\n", largest_offset);
    printf("Corresponding string: %s\n", largest_string);
}

// Function to manage memory allocation and deallocation for the data arrays
void manageMemory(Data** data, size_t* num_data) {
    // Free any existing memory allocated for the data arrays
    free(*data);

    // Reallocate memory for the data arrays based on the new number of data points
    *data = (Data*)realloc(*data, sizeof(Data) * (*num_data));
}

// Function to handle errors in reading and processing input from standard input
void handleErrors() {
    // Handle any errors that may occur during reading and processing input from standard input
    perror("Error reading or processing input");
}

int main() {
    Data* data = NULL;
    size_t num_data = 0;

    // Read and process input from standard input
    readInput(&data, &num_data);

    // Find and print the largest integer with its corresponding string
    findLargestInteger(&data, num_data);

    // Manage memory allocation and deallocation for the data arrays
    manageMemory(&data, &num_data);

    return 0;
}
