#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

// Configuration module
#define CONFIG_FILE "config.txt"
#define MAX_INPUT_SIZE 1024

typedef struct {
    int max_int;
    char *max_str;
    float max_float;
} MaxData;

void processInput(MaxData *data) {
    // Initialize variables
    data->max_int = INT_MIN;
    data->max_str = NULL;
    data->max_float = -FLT_MAX;

    // Read configuration file
    FILE *configFile = fopen(CONFIG_FILE, "r");
    if (configFile == NULL) {
        printf("Error: unable to open config file\n");
        return;
    }

    char line[MAX_INPUT_SIZE];
    while (fgets(line, MAX_INPUT_SIZE, configFile)) {
        // Parse input line
        int num = 0;
        char *str = NULL;
        float flt = 0.0f;
        sscanf(line, "%d %s %f", &num, str, &flt);

        // Update maximum values
        if (num > data->max_int) {
            data->max_int = num;
            data->max_str = strdup(str);
            data->max_float = flt;
        }
    }

    fclose(configFile);
}

void printMaxData(MaxData *data) {
    printf("Maximum integer: %d\n", data->max_int);
    printf("Maximum string: %s\n", data->max_str);
    printf("Maximum float: %f\n", data->max_float);
}

int main() {
    MaxData *data = malloc(sizeof(MaxData));
    if (data == NULL) {
        printf("Error: unable to allocate memory for maximum data\n");
        return 1;
    }

    processInput(data);
    printMaxData(data);

    free(data->max_str);
    free(data);

    return 0;
}
