} Record;

// Function to allocate memory for an array of pointers to records
void allocateRecords(Record** records, int numRecords) {
    // Allocate memory for the array of pointers
    *records = (Record*)malloc(numRecords * sizeof(Record*));
    if (*records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        return;
    }

    // Initialize each record's fields to random values within specified ranges
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        (*records)[i] = malloc(sizeof(Record));
        if ((*records)[i] == NULL) {
            printf("Error: Failed to allocate memory for record %d\n", i);
            return;
        }
        (*records)[i]->offset = rand() % 1000000;
        (*records)[i]->weight = (float)(rand() % 100) / 10.0f;
    }
}

// Function to free memory for an array of pointers to records
void freeRecords(Record** records, int numRecords) {
    // Free each record's fields and the array of pointers
    for (int i = 0; i < numRecords; i++) {
        if ((*records)[i] != NULL) {
            free((*records)[i]);
        }
    }
    free(*records);
}
