            return;
        }
        record->offset = rand() % 1000;
        record->weight = (float)(rand() % 1000) / 100.0f;
        records[i] = record;
    }

    // Periodically validate and repair corrupted entries in the list
    for (int i = 0; i < num_records; i++) {
        if (records[i]->offset < 0 || records[i]->weight < 0) {
            printf("Error: Corrupted record found at index %d\n", i);
