// Function to handle caching of frequently accessed records in memory
void cache_records(List* list) {
    // Iterate over all records in the list
    for (int i = 0; i < list->size; i++) {
        Record* record = &list->data[i];
        // Check if the record is already cached
        if (!record->cached) {
            // If not, cache it by adding it to a linked list of cached records
            record->next = list->cached_records;
            list->cached_records = record;
            record->cached = true;
        }
    }
}

// Function to handle eviction of unused records from the cache
void evict_unused_records(List* list) {
    // Iterate over all cached records in the list
    for (Record* record = list->cached_records; record != NULL; record = record->next) {
        // Check if the record is not used anymore
        if (!record->used) {
            // If so, remove it from the cache by removing it from the linked list of cached records
            Record* previous = record->previous;
            Record* next = record->next;
            if (previous != NULL) {
                previous->next = next;
            } else {
                list->cached_records = next;
            }
            if (next != NULL) {
                next->previous = previous;
            }
        }
    }
}

