void generate_records(char* filename, int num_records, int max_float_value) {
    // Allocate memory for the arrays
    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    float* data = malloc(num_records * sizeof(float));
    record* records = malloc(num_records * sizeof(record));

    // Initialize the arrays with random values
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 1000000;
        keys[i] = rand() % 1000000;
        data[i] = (float)rand() / RAND_MAX * max_float_value;
        records[i].key = keys[i];
        records[i].data = data[i];
        records[i].status = 'A';
    }

    // Compute the MD5 hashes in parallel
    #pragma omp parallel for schedule(dynamic)
    for (int i = 0; i < num_records; i++) {
        char* str = malloc(1024);
        sprintf(str, "%d %f", keys[i], data[i]);
        records[i].md5 = MD5(str, strlen(str), NULL);
    }

    // Detect and report duplicate MD5 hashes
    int num_duplicates = 0;
    for (int i = 0; i < num_records - 1; i++) {
        for (int j = i + 1; j < num_records; j++) {
            if (strcmp(records[i].md5, records[j].md5) == 0) {
                num_duplicates++;
            }
        }
    }

    // Release memory and return the list of duplicates
    free(offsets);
    free(keys);
    free(data);
    free(records);
    return num_duplicates;
}

// Modify the filename to include a number of digits and a file type
void modify_filename(char* filename, int num_digits) {
    char* new_filename = malloc(strlen(filename) + 10);
    sprintf(new_filename, "%s.%d", filename, num_digits);
    strcat(new_filename, ".txt");
    return new_filename;
}
