// Define the hash calculation function
void calculate_hash(const char *filepath, int level) {
    // Open the file for reading
    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        log(LOG_LEVEL_ERROR, "Failed to open file %s: %s", filepath, strerror(errno));
        return;
    }

    // Create a hash object for the specified algorithm
    hashlib_t *hash = hashlib_new(level);
    if (hash == NULL) {
        log(LOG_LEVEL_ERROR, "Failed to create hash object: %s", strerror(errno));
        fclose(fp);
        return;
    }

    // Read the file in chunks and update the hash
    char buffer[4096];
    size_t bytes_read = 0;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
        hashlib_update(hash, buffer, bytes_read);
    }

    // Close the file and get the final hash value
    fclose(fp);
    char *hash_value = hashlib_finalize(hash);
    if (hash_value == NULL) {
        log(LOG_LEVEL_ERROR, "Failed to calculate hash: %s", strerror(errno));
        return;
    }

    // Print the hash value to stdout
    printf("%s\n", hash_value);

    // Free the hash object and hash value
    free(hash_value);
    hashlib_free(hash);
}

