        free(schema_string);
        return false;
    }

    // Validate the JSON object against the schema
    json_t *errors = json_validate(json_object, schema_string);
    if (errors != NULL) {
        log(LOG_LEVEL_ERROR, "JSON validation failed: %s", errors);
        free(schema_string);
        return false;
    }

    // Free the JSON object and schema string
    json_decref(json_object);
    free(schema_string);

    // Return true if the JSON is valid, false otherwise
    return true;
}
