The Python function for calculating MD5 and SHA-256 hashes of large files can be implemented as follows:
```python
import os
import hashlib
import threading

# Define the chunk size for reading files in parallel
CHUNK_SIZE = 1024 * 1024

# Define the number of threads to use for calculating hashes
NUM_THREADS = 8

# Define a class for managing file access and hashing
class FileHasher:
    def __init__(self, filepath):
        self.filepath = filepath
        self.hashlib = hashlib.new(filepath)
        self.lock = threading.Lock()

    # Read a chunk of the file and update the hash object
    def read_chunk(self, offset, size):
        with open(self.filepath, "rb") as fp:
            fp.seek(offset)
            data = fp.read(size)
            self.hashlib.update(data)

    # Calculate the hash of the entire file
    def calculate_hash(self):
        with open(self.filepath, "rb") as fp:
            size = os.fstat(fp.fileno()).st_size
            chunks = (size + CHUNK_SIZE - 1) // CHUNK_SIZE
            threads = []
            for i in range(NUM_THREADS):
                thread = threading.Thread(target=self.read_chunk, args=(i * chunks // NUM_THREADS, (i + 1) * chunks // NUM_THREADS))
                threads.append(thread)
            for thread in threads:
                thread.start()
            for thread in threads:
                thread.join()
        return self.hashlib.hexdigest()
