// Custom data structures and functions for managing memory pools and logging
struct MemoryPool {
    void* pool;
    size_t size;
};

void initMemoryPool(struct MemoryPool* pool, size_t size) {
    pool->pool = malloc(size);
    if (pool->pool == NULL) {
        printf("Error: Failed to allocate memory for memory pool\n");
        exit(1);
    }
    pool->size = size;
}

void freeMemoryPool(struct MemoryPool* pool) {
    free(pool->pool);
}

void logMemoryUsage() {
    printf("Total memory usage: %lu bytes\n", getTotalMemoryUsage());
}

// Custom data structures and functions for managing records
struct Record {
    int id;
    char status;
    float measurement;
    struct LogEntry* log_entry;
};

void initRecord(struct Record* record, int id) {
    record->id = id;
    record->status = 'I';
    record->measurement = 0.0f;
    record->log_entry = NULL;
}

void freeRecord(struct Record* record) {
    if (record->log_entry != NULL) {
        freeLogEntry(record->log_entry);
    }
    free(record);
}

struct LogEntry {
    long offset;
    int key;
    struct Record* record;
};

