    log_entry->offset = offset;
    log_entry->key = key;
    log_entry->record = NULL;
}

void freeLogEntry(struct LogEntry* log_entry) {
    if (log_entry->record != NULL) {
        freeRecord(log_entry->record);
    }
    free(log_entry);
}

// Custom data structures and functions for managing concurrent access to shared resources
struct SharedResource {
    pthread_mutex_t mutex;
    struct MemoryPool* memory_pool;
    struct Record* records[];
};

void initSharedResource(struct SharedResource* resource) {
    pthread_mutex_init(&resource->mutex, NULL);
    initMemoryPool(&resource->memory_pool, 1024 * 1024); // 1 MB
}

void freeSharedResource(struct SharedResource* resource) {
    pthread_mutex_destroy(&resource->mutex);
    freeMemoryPool(&resource->memory_pool);
}

void acquireLock(pthread_mutex_t* mutex) {
    int ret = pthread_mutex_lock(mutex);
    if (ret != 0) {
        printf("Error: Failed to acquire lock\n");
        exit(1);
    }
}

void releaseLock(pthread_mutex_t* mutex) {
    int ret = pthread_mutex_unlock(mutex);
    if (ret != 0) {
        printf("Error: Failed to release lock\n");
        exit(1);
    }
}

