    acquireLock(&manager->resource.mutex);
    if (record->id != id) {
        printf("Error: Record ID mismatch\n");
        exit(1);
    }
    updateRecord(record, id);
    releaseLock(&manager->resource.mutex);
}

void deleteRecordInSharedResource(struct Record* record) {
    acquireLock(&manager->resource.mutex);
    if (record->id == -1) {
        printf("Error: Record is not initialized\n");
        exit(1);
    }
    deleteRecord(record);
    manager->resource.records[record->id] = NULL;
    releaseLock(&manager->resource.mutex);
}

