struct SharedLogEntryManager {
    struct SharedResource* resource;
};

void initSharedLogEntryManager(struct SharedLogEntryManager* manager) {
    initSharedResource(&manager->resource);
}

void freeSharedLogEntryManager(struct SharedLogEntryManager* manager) {
    freeSharedResource(&manager->resource);
}

struct LogEntry* createLogEntryInSharedResource(long offset, int key) {
    struct LogEntry* log_entry = NULL;
    acquireLock(&manager->resource.mutex);
    if (manager->resource.memory_pool.size < sizeof(struct LogEntry)) {
        printf("Error: Memory pool is full\n");
        exit(1);
    }
    log_entry = createLogEntry(offset, key);
    manager->resource.log_entries[log_entry->key] = log_entry;
    releaseLock(&manager->resource.mutex);
    return log_entry;
}

void updateLogEntryInSharedResource(struct LogEntry* log_entry, long offset, int key) {
    acquireLock(&manager->resource.mutex);
    if (log_entry->key != key) {
        printf("Error: Log entry key mismatch\n");
        exit(1);
    }
    updateLogEntry(log_entry, offset, key);
    releaseLock(&manager->resource.mutex);
}

void deleteLogEntryInSharedResource(struct LogEntry* log_entry) {
    acquireLock(&manager->resource.mutex);
    if (log_entry->key == -1) {
        printf("Error: Log entry is not initialized\n");
        exit(1);
    }
    deleteLogEntry(log_entry);
    manager->resource.log_entries[log_entry->key] = NULL;
    releaseLock(&manager->resource.mutex);
}

