// Define the function to allocate and initialize memory for the arrays
void allocate_memory(int num_records, int offset_range, int key_range, float precision_range) {
    // Allocate memory for the offset array
    long *offset_array = (long *)je_malloc(num_records * sizeof(long));
    if (!offset_array) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Allocate memory for the key array
    int *key_array = (int *)je_malloc(num_records * sizeof(int));
    if (!key_array) {
        printf("Error: Failed to allocate memory for key array\n");
        je_free(offset_array);
        return;
    }

    // Allocate memory for the precision array
    float *precision_array = (float *)je_malloc(num_records * sizeof(float));
    if (!precision_array) {
        printf("Error: Failed to allocate memory for precision array\n");
        je_free(offset_array);
        je_free(key_array);
        return;
    }

    // Allocate memory for the record structures
    record *records = (record *)je_malloc(num_records * sizeof(record));
    if (!records) {
        printf("Error: Failed to allocate memory for record structures\n");
        je_free(offset_array);
        je_free(key_array);
        je_free(precision_array);
        return;
    }

    // Initialize the offset array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = rand() % offset_range + 1;
    }

    // Initialize the key array with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        key_array[i] = rand() % key_range + 1;
    }

    // Initialize the precision array with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        precision_array[i] = rand() % precision_range + 1.0f;
    }

    // Initialize the record structures with the random values
    for (int i = 0; i < num_records; i++) {
        records[i].integer_field = key_array[i];
        records[i].timestamp = time(NULL);
        records[i].precision = precision_array[i];
    }

    // Track the total memory usage of all allocated structures
    long total_memory_usage = num_records * sizeof(long) + num_records * sizeof(int) + num_records * sizeof(float) + num_records * sizeof(record);
    printf("Total memory usage: %ld bytes\n", total_memory_usage);

    // Free the memory allocated for the arrays and the record structures upon function exit
    je_free(offset_array);
    je_free(key_array);
    je_free(precision_array);
    je_free(records);
}

