using namespace std;

namespace RandomGenerator {
    static mt19937 random_engine;

    class Record {
        int value;
        long* offset;

    public:
        Record(int v, long* o) : value(v), offset(o) {}

        int getValue() const { return value; }
        long* getOffset() const { return offset; }
    };

    class RandomGenerator {
    public:
        RandomGenerator() { random_engine.seed(time(0)); }
        ~RandomGenerator() = default;

        int generateRandomNumber(int min, int max) {
            uniform_int_distribution<int> distribution(min, max);
            return distribution(random_engine);
        }
    };
}

int manageMemoryAndRandomize(int n, int m, int k) {
    if (n <= 0 || m <= 0 || k <= 0) {
        // Handle edge case where any of the input parameters is zero or negative
        return -1;
    }

    long* offsets = new long[n];
    Record* records = new Record[k];

    if (offsets == nullptr || records == nullptr) {
        // Handle allocation failure
        delete[] offsets;
        delete[] records;
        return -1;
    }

    for (int i = 0; i < n; ++i) {
        offsets[i] = i * sizeof(long);
    }

    for (int i = 0; i < k; ++i) {
        int random_value = RandomGenerator::generateRandomNumber(0, 1000);
        long* offset = &offsets[random_value];
        records[i] = Record(random_value, offset);
    }

    delete[] offsets;
    delete[] records;
    return 0;
}
