void resize_buffer(circular_buffer_t* buffer, int new_size) {
    if (new_size < MIN_BUFFER_SIZE || new_size > MAX_BUFFER_SIZE) {
        return;
    }
    buffer->capacity = new_size;
    buffer->data = realloc(buffer->data, buffer->capacity);
}

