    // Check if the input parameters are valid
    if (directoryPath == NULL || templateFileName == NULL || dataSourceFileName == NULL) {
        return 1;
    }

    // Open the data source file and check for errors
    FILE* dataSourceFile = fopen(dataSourceFileName, "r");
    if (dataSourceFile == NULL) {
        printf("Error opening data source file: %s\n", strerror(errno));
        return 1;
    }

    // Open the template file and check for errors
    FILE* templateFile = fopen(templateFileName, "r");
    if (templateFile == NULL) {
        printf("Error opening template file: %s\n", strerror(errno));
        return 1;
    }

    // Create a buffer to store the contents of the data source file
    char* dataSourceBuffer = malloc(sizeof(char) * 1024);
    if (dataSourceBuffer == NULL) {
        printf("Error allocating memory for data source buffer\n");
        return 1;
    }

    // Create a buffer to store the contents of the template file
    char* templateBuffer = malloc(sizeof(char) * 1024);
    if (templateBuffer == NULL) {
        printf("Error allocating memory for template buffer\n");
        return 1;
    }

    // Read the contents of the data source file into a buffer
    size_t dataSourceFileSize = fread(dataSourceBuffer, sizeof(char), 1024, dataSourceFile);
    if (ferror(dataSourceFile)) {
        printf("Error reading from data source file: %s\n", strerror(errno));
        return 1;
    }

    // Read the contents of the template file into a buffer
    size_t templateFileSize = fread(templateBuffer, sizeof(char), 1024, templateFile);
    if (ferror(templateFile)) {
        printf("Error reading from template file: %s\n", strerror(errno));
        return 1;
    }

    // Close the data source and template files
    fclose(dataSourceFile);
    fclose(templateFile);

    // Create a buffer to store the contents of the generated file
    char* generatedFileBuffer = malloc(sizeof(char) * 1024);
    if (generatedFileBuffer == NULL) {
        printf("Error allocating memory for generated file buffer\n");
        return 1;
    }

    // Iterate over each entry in the data source file
    int entryIndex = 0;
    while (entryIndex < dataSourceFileSize) {
        // Extract the current entry from the data source buffer
        char* currentEntry = &dataSourceBuffer[entryIndex];

        // Replace placeholders in the template with the current entry
        int placeholderIndex = 0;
        while (placeholderIndex < templateFileSize) {
            if (templateBuffer[placeholderIndex] == '%') {
                char* placeholderStart = &templateBuffer[placeholderIndex + 1];
                char* placeholderEnd = strchr(placeholderStart, '%');
                int placeholderLength = placeholderEnd - placeholderStart;

                // Replace the placeholder with the current entry
                memcpy(&generatedFileBuffer[placeholderIndex], currentEntry, placeholderLength);
                generatedFileBuffer[placeholderIndex + placeholderLength] = '\0';

                // Update the index to skip over the replaced placeholder
                placeholderIndex += (placeholderLength + 1);
            } else {
                // Move to the next character in the template buffer
                ++placeholderIndex;
            }
        }

        // Create a filename for the generated file based on the output format and entry index
        char* fileName = NULL;
        if (outputFormat == OUTPUT_JSON) {
            fileName = malloc(sizeof(char) * 1024);
            sprintf(fileName, "%s/%d.json", directoryPath, entryIndex);
        } else if (outputFormat == OUTPUT_CSV) {
            fileName = malloc(sizeof(char) * 1024);
            sprintf(fileName, "%s/%d.csv", directoryPath, entryIndex);
        }

        // Open the generated file and check for errors
        FILE* generatedFile = fopen(fileName, "w");
        if (generatedFile == NULL) {
            printf("Error opening generated file: %s\n", strerror(errno));
            return 1;
        }

        // Write the contents of the generated file buffer to the file
        size_t bytesWritten = fwrite(generatedFileBuffer, sizeof(char), 1024, generatedFile);
        if (ferror(generatedFile)) {
            printf("Error writing to generated file: %s\n", strerror(errno));
            return 1;
        }

        // Close the generated file and check for errors
        fclose(generatedFile);
        if (ferror(generatedFile)) {
            printf("Error closing generated file: %s\n", strerror(errno));
            return 1;
        }

        // Increment the entry index
        ++entryIndex;
    }

    // Free the buffers and close the files
    free(dataSourceBuffer);
    free(templateBuffer);
    free(generatedFileBuffer);
    fclose(dataSourceFile);
    fclose(templateFile);

    // Return 0 if successful, else 1
    return 0;
}
