#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <limits.h>
#include <math.h>
#include <time.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <libxml/parser.h>
#include <libxml/tree.h>
#include <libxml/xpath.h>
#include <libxml/xpathInternals.h>
#include <json-c/json.h>

// Define the structure for a user profile
typedef struct {
    char *username;
    int age;
    bool active;
    double account_balance;
} UserProfile;

// Define the structure for an activity
typedef struct {
    char *type;
    double timestamp;
} Activity;

// Define the structure for a session
typedef struct {
    LinkedList *activities;
    bool valid;
} Session;

// Define the structure for a histogram of user descriptions
typedef struct {
    int *histogram;
    int size;
} UserDescriptionHistogram;

// Function to parse an XML document and construct a user profile
int parse_xml(const char *filename, UserProfile *profile) {
    // Initialize the parser and context
    xmlParserCtxtPtr ctxt = xmlNewParserCtxt();
    if (ctxt == NULL) {
        fprintf(stderr, "Failed to create XML parser context\n");
        return 1;
    }

    // Parse the XML document
    xmlDocPtr doc = xmlCtxtReadFile(ctxt, filename, NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "Failed to parse XML document\n");
        return 1;
    }

    // Get the root element of the document
    xmlNodePtr root = xmlDocGetRootElement(doc);
    if (root == NULL) {
        fprintf(stderr, "Failed to get root element of XML document\n");
        return 1;
    }

    // Find the user name and age elements in the document
    xmlNodePtr username_node = xmlXPathNodeEval(root, "//user/name", NULL);
    if (username_node == NULL) {
        fprintf(stderr, "Failed to find user name element\n");
        return 1;
    }
    profile->username = (char *)xmlNodeGetContent(username_node);

    xmlNodePtr age_node = xmlXPathNodeEval(root, "//user/age", NULL);
    if (age_node == NULL) {
        fprintf(stderr, "Failed to find user age element\n");
        return 1;
    }
    profile->age = atoi((char *)xmlNodeGetContent(age_node));

    // Find the active status and account balance elements in the document
    xmlNodePtr active_node = xmlXPathNodeEval(root, "//user/active", NULL);
    if (active_node == NULL) {
        fprintf(stderr, "Failed to find user active element\n");
        return 1;
    }
    profile->active = atoi((char *)xmlNodeGetContent(active_node));

    xmlNodePtr account_balance_node = xmlXPathNodeEval(root, "//user/account_balance", NULL);
    if (account_balance_node == NULL) {
        fprintf(stderr, "Failed to find user account balance element\n");
        return 1;
    }
    profile->account_balance = atof((char *)xmlNodeGetContent(account_balance_node));

    // Clean up the parser and context
    xmlFreeDoc(doc);
    xmlFreeParserCtxt(ctxt);

    return 0;
}

// Function to construct a session structure for a user profile
Session *construct_session(UserProfile *profile) {
    Session *session = malloc(sizeof(Session));
    if (session == NULL) {
        fprintf(stderr, "Failed to allocate memory for session\n");
        return NULL;
    }

    // Initialize the linked list of activities
    LinkedList *activities = create_linked_list();
    if (activities == NULL) {
        fprintf(stderr, "Failed to create linked list of activities\n");
        free(session);
        return NULL;
    }
    session->activities = activities;

    // Initialize the validity flag
    session->valid = true;

    return session;
}

// Function to populate a user profile structure with random values
void populate_profile(UserProfile *profile) {
    srand(time(NULL));

    // Generate a random username
    char *username = malloc(10);
    if (username == NULL) {
        fprintf(stderr, "Failed to allocate memory for username\n");
        return;
    }
    for (int i = 0; i < 10; i++) {
        int c = rand() % 26 + 'a';
        *(username + i) = c;
    }
    profile->username = username;

    // Generate a random age between 18 and 90
    profile->age = (rand() % 72) + 18;

    // Generate a random active status
    profile->active = rand() % 2;

    // Generate a random account balance between 0 and 1000
    profile->account_balance = (double)(rand() % 1000) / 100.0;
}

// Function to populate an activity structure with random values
void populate_activity(Activity *activity) {
    srand(time(NULL));

    // Generate a random type
    char *type = malloc(10);
    if (type == NULL) {
        fprintf(stderr, "Failed to allocate memory for activity type\n");
        return;
    }
    for (int i = 0; i < 10; i++) {
        int c = rand() % 26 + 'a';
        *(type + i) = c;
    }
    activity->type = type;

    // Generate a random timestamp between 0 and 1000
    activity->timestamp = (double)(rand() % 1000) / 100.0;
}

// Function to populate a session structure with random values
void populate_session(Session *session) {
    // Populate the linked list of activities with random values
    LinkedListNode *node = session->activities->head;
    while (node != NULL) {
        Activity *activity = node->data;
        populate_activity(activity);
        node = node->next;
    }
}

// Function to track total memory usage and release it upon function exit
void track_memory_usage() {
    // Get the current memory usage
    size_t memory_usage = get_total_memory_usage();

    // Print a message indicating the memory usage
    printf("Total memory usage: %lu bytes\n", memory_usage);

    // Release any excess memory
    release_excess_memory(memory_usage);
}

// Function to get the total memory usage in bytes
size_t get_total_memory_usage() {
    // Get the current memory usage
    size_t memory_usage = 0;
    struct sysinfo info;
    if (sysinfo(&info) == 0) {
        memory_usage = info.totalram * info.mem_unit;
    }

    return memory_usage;
}

// Function to release any excess memory
void release_excess_memory(size_t memory_usage) {
    // Get the maximum allowed memory usage
    size_t max_memory_usage = 1024 * 1024 * 1024; // 1 GB

    // Release any excess memory if necessary
    if (memory_usage > max_memory_usage) {
        printf("Releasing excess memory...\n");
        free(NULL);
    }
}

// Function to serialize a user profile structure
void serialize_profile(UserProfile *profile, FILE *file) {
    // Serialize the username
    fprintf(file, "\"username\": \"%s\",", profile->username);

    // Serialize the age
    fprintf(file, "\"age\": %d,", profile->age);

    // Serialize the active status
    fprintf(file, "\"active\": %d,", profile->active);

    // Serialize the account balance
    fprintf(file, "\"account_balance\": %.2f", profile->account_balance);
}

// Function to serialize a session structure
void serialize_session(Session *session, FILE *file) {
    // Serialize the validity flag
    fprintf(file, "\"valid\": %d,", session->valid);

    // Serialize the linked list of activities
    LinkedListNode *node = session->activities->head;
    while (node != NULL) {
        Activity *activity = node->data;
        serialize_activity(activity, file);
        node = node->next;
    }
}

// Function to serialize an activity structure
void serialize_activity(Activity *activity, FILE *file) {
    // Serialize the type
    fprintf(file, "\"type\": \"%s\",", activity->type);

    // Serialize the timestamp
    fprintf(file, "\"timestamp\": %.2f", activity->timestamp);
}

// Function to deserialize a user profile structure from JSON
void deserialize_profile(UserProfile *profile, json_object *json) {
    // Deserialize the username
    json_object_object_get_ex(json, "username", &profile->username);

    // Deserialize the age
    json_object_object_get_ex(json, "age", &profile->age);

    // Deserialize the active status
    json_object_object_get_ex(json, "active", &profile->active);

    // Deserialize the account balance
    json_object_object_get_ex(json, "account_balance", &profile->account_balance);
}

// Function to deserialize a session structure from JSON
void deserialize_session(Session *session, json_object *json) {
    // Deserialize the validity flag
    json_object_object_get_ex(json, "valid", &session->valid);

    // Deserialize the linked list of activities
    LinkedListNode *node = session->activities->head;
    while (node != NULL) {
        Activity *activity = node->data;
        deserialize_activity(activity, json);
        node = node->next;
    }
}

// Function to deserialize an activity structure from JSON
void deserialize_activity(Activity *activity, json_object *json) {
    // Deserialize the type
    json_object_object_get_ex(json, "type", &activity->type);

    // Deserialize the timestamp
    json_object_object_get_ex(json, "timestamp", &activity->timestamp);
}

// Function to convert a collection of XML documents into JSON format
int xml_to_json(const char *directory_path, const char *output_file, size_t max_memory_usage) {
    // Initialize the histogram for user descriptions
    UserDescriptionHistogram histogram = {NULL, 0};

    // Open the output file
    FILE *output_file = fopen(output_file, "w");
    if (output_file == NULL) {
        fprintf(stderr, "Failed to open output file\n");
        return 1;
    }

    // Iterate over the XML documents in the directory
    DIR *directory = opendir(directory_path);
    if (directory == NULL) {
        fprintf(stderr, "Failed to open directory\n");
        return 1;
    }
    struct dirent *entry;
    while ((entry = readdir(directory)) != NULL) {
        // Skip any non-XML files
        if (strcmp(entry->d_name + strlen(entry->d_name) - 4, ".xml") != 0) {
            continue;
        }

        // Parse the XML document and construct a user profile structure
        UserProfile profile = {NULL, 0, false, 0.0};
        if (parse_xml(entry->d_name, &profile) != 0) {
            fprintf(stderr, "Failed to parse XML document\n");
            return 1;
        }

        // Populate the user profile structure with random values
        populate_profile(&profile);

        // Construct a session structure for the user profile
        Session *session = construct_session(&profile);
        if (session == NULL) {
            fprintf(stderr, "Failed to allocate memory for session\n");
            return 1;
        }

        // Populate the session structure with random values
        populate_session(session);

        // Serialize the user profile and session structures to JSON
        json_object *json = json_object_new();
        serialize_profile(&profile, json);
        serialize_session(session, json);

        // Add the JSON object to the histogram of user descriptions
        add_to_histogram(&histogram, profile.username);

        // Write the JSON object to the output file
