        histogram->size++;
        histogram->histogram = realloc(histogram->histogram, sizeof(int) * histogram->size);
        if (histogram->histogram == NULL) {
            fprintf(stderr, "Failed to allocate memory for histogram\n");
            return;
        }
    }
    histogram->histogram[index]++;
}
