    int page_count;
    Page* pages;
} Document;

typedef struct Page {
    char* text_content;
    int font_size;
    bool highlight;
} Page;

typedef struct Section {
    Document* document;
    char* section_title;
    double estimated_reading_time;
} Section;

// Define the function to convert images to PDF format
int convert_images_to_pdf(Document** documents, int num_documents, int max_estimated_reading_time) {
    // Initialize variables for memory tracking and serialization
    size_t total_memory = 0;
    Document* current_document = NULL;
    Section* current_section = NULL;
    bool is_serializing = false;

    // Loop through each document in the collection
    for (int i = 0; i < num_documents; i++) {
        // Get the current document and its page count
        Document* document = documents[i];
        int page_count = document->page_count;

        // Initialize a new section for this document
        Section* section = malloc(sizeof(Section));
        section->document = document;
        section->section_title = NULL;
        section->estimated_reading_time = 0;

        // Loop through each page in the current document
        for (int j = 0; j < page_count; j++) {
            // Get the current page and its text content
            Page* page = &(document->pages[j]);
            char* text_content = page->text_content;

            // Compute the estimated reading time for this page
            double estimated_reading_time = (double)strlen(text_content) / 200.0;

            // Add the estimated reading time to the section's total
            section->estimated_reading_time += estimated_reading_time;

            // Check if the total estimated reading time exceeds the limit
            if (section->estimated_reading_time > max_estimated_reading_time) {
                // If so, serialize the current section and reset its estimated reading time
                is_serializing = true;
                serialize_section(current_section);
                current_section->estimated_reading_time = 0;
            }

            // Add the page to the current section's linked list of pages
            Page* new_page = malloc(sizeof(Page));
            new_page->text_content = text_content;
            new_page->font_size = page->font_size;
            new_page->highlight = page->highlight;
            section->pages = realloc(section->pages, sizeof(Page*) * (j + 1));
            section->pages[j] = new_page;
        }

        // If the current section's estimated reading time exceeds the limit, serialize it
        if (is_serializing) {
            serialize_section(current_section);
            current_section->estimated_reading_time = 0;
        }

        // Add the current section to the list of sections
        total_memory += sizeof(Section);
        Section** new_sections = realloc(sections, sizeof(Section*) * (i + 1));
        new_sections[i] = section;
        sections = new_sections;
    }

    // Serialize the final section if necessary
    if (is_serializing) {
        serialize_section(current_section);
    }

    // Free any memory that was allocated during the function call
    for (int i = 0; i < num_documents; i++) {
        free(documents[i]);
    }
    free(documents);
    for (int i = 0; i < total_memory; i++) {
        free(sections[i]);
    }
    free(sections);

    // Return 0 if successful, else 1
    return 0;
}

// Define the function to serialize a section
void serialize_section(Section* section) {
    // Write the section's title and estimated reading time to a file
    FILE* file = fopen("sections.txt", "a");
    fprintf(file, "%s\t%f\n", section->section_title, section->estimated_reading_time);
    fclose(file);
}
