// Function to add an event to a session
void add_event(Session *session, time_t timestamp, int event_id, int user_id, char *payload) {
    // Create a new event structure
    Event *new_event = malloc(sizeof(Event));
    new_event->timestamp = timestamp;
    new_event->event_id = event_id;
    new_event->user_id = user_id;
    new_event->payload = payload;

    // Add the event to the session's linked list of events
    if (session->events == NULL) {
        session->events = new_event;
    } else {
        Event *current_event = session->events;
        while (current_event->next != NULL) {
            current_event = current_event->next;
        }
        current_event->next = new_event;
    }

    // Update the total duration of the session
    session->total_duration += timestamp - session->events->timestamp;
}

// Function to compute the duration of a session
double compute_session_duration(Session *session) {
    return session->total_duration;
}

// Function to add a session to the histogram
void add_session_to_histogram(Histogram *histogram, Session *session) {
    // Compute the duration of the session
    double duration = compute_session_duration(session);

    // Add the duration to the histogram
    if (histogram->size == 0) {
        histogram->histogram[0] = duration;
        histogram->size++;
    } else {
        int i = 0;
        while (i < histogram->size && histogram->histogram[i] < duration) {
            i++;
        }
        if (i == histogram->size) {
            histogram->histogram[histogram->size++] = duration;
        } else {
            for (int j = histogram->size - 1; j >= i; j--) {
                histogram->histogram[j + 1] = histogram->histogram[j];
            }
            histogram->histogram[i] = duration;
            histogram->size++;
        }
    }
}

// Function to detect and report sessions with identical IDs
void detect_and_report_duplicate_sessions(Session *session) {
    // Check if the session ID is already in the histogram
    int i = 0;
    while (i < histogram->size && strcmp(histogram->histogram[i]->session_id, session->session_id) != 0) {
        i++;
    }
    if (i == histogram->size) {
        // Add the session to the histogram
        add_session_to_histogram(histogram, session);
    } else {
