    Histogram histogram = {NULL, 0};

    // Open the log file for reading
    FILE *log_file_ptr = fopen(log_file, "r");
    if (log_file_ptr == NULL) {
        printf("Error: Could not open log file %s\n", log_file);
        return 1;
    }

    // Read the log file line by line
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, log_file_ptr)) != -1) {
        // Parse the log entry from the line
        char *timestamp_str = strtok(line, ",");
        int timestamp = atoi(timestamp_str);
        char *user_id_str = strtok(NULL, ",");
        int user_id = atoi(user_id_str);
        char *service_name_str = strtok(NULL, ",");
        char *event_type_str = strtok(NULL, ",");
        char *payload_str = strtok(NULL, "\n");
        int event_id = generate_event_id();

        // Create a new session structure if necessary
        Session *session = NULL;
        if (histogram.size == 0) {
            session = malloc(sizeof(Session));
            session->session_id = generate_session_id();
            session->events = NULL;
            session->total_duration = 0;
        } else {
            // Check if the session ID is already in the histogram
            int i = 0;
            while (i < histogram.size && strcmp(histogram.histogram[i]->session_id, session->session_id) != 0) {
                i++;
            }
            if (i == histogram.size) {
                // Create a new session structure
                session = malloc(sizeof(Session));
                session->session_id = generate_session_id();
                session->events = NULL;
                session->total_duration = 0;
            } else {
                // Reuse the existing session structure
                session = histogram.histogram[i];
            }
        }

        // Add the event to the session's linked list of events
        add_event(session, timestamp, event_id, user_id, payload_str);

        // Update the total duration of the session
        session->total_duration += timestamp - session->events->timestamp;

        // Add the session to the histogram
        add_session_to_histogram(&histogram, session);

        // Detect and report duplicate session IDs
        detect_and_report_duplicate_sessions(session);
    }

    // Close the log file
    fclose(log_file_ptr);

    return 0;
}
