#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#include <cstdlib>
#include <ctime>

using namespace std;

struct Record {
  int values[N]; // N is the feature size
};

struct Node {
  vector<Record> records;
  atomic<int> num_records;
  mutex mtx;
  condition_variable cv;
};

class Octree {
 public:
  Octree(int feature_size, int leaf_nodes, int data_capacity) :
      feature_size_(feature_size),
      leaf_nodes_(leaf_nodes),
      data_capacity_(data_capacity) {}

  void initialize() {
    // Dynamically allocate memory for the octree and its prefix leafs.
    nodes_.resize(leaf_nodes_);
    for (int i = 0; i < leaf_nodes_; ++i) {
      nodes_[i].records.resize(data_capacity_);
    }

    // Initialize the records in each node with random values within a specified range.
    srand(time(nullptr));
    for (int i = 0; i < leaf_nodes_; ++i) {
      for (int j = 0; j < data_capacity_; ++j) {
        nodes_[i].records[j].values[0] = rand() % MAX_VALUE;
      }
    }

    // Initialize the total memory usage of all allocated structures.
    total_memory_usage_ = leaf_nodes_ * data_capacity_ * sizeof(Record);
  }

  void insert(const Record& record) {
    // Find the node that the record belongs to and increment its num_records.
    int node_id = get_node_id(record);
    nodes_[node_id].num_records++;

    // If the node is full, resize it by doubling its capacity.
    if (nodes_[node_id].num_records == data_capacity_) {
      resize_node(node_id);
    }

    // Insert the record into the node.
    nodes_[node_id].records.push_back(record);
  }

  void retrieve(const Record& record, vector<Record>& results) {
    // Find the node that the record belongs to and retrieve its records.
    int node_id = get_node_id(record);
    for (int i = 0; i < nodes_[node_id].num_records; ++i) {
      if (nodes_[node_id].records[i] == record) {
        results.push_back(nodes_[node_id].records[i]);
      }
    }
  }

 private:
  int get_node_id(const Record& record) {
    // Calculate the hash value of the record and use it to determine which node it belongs to.
    int hash = 0;
    for (int i = 0; i < feature_size_; ++i) {
      hash += record.values[i];
    }
    return hash % leaf_nodes_;
  }

  void resize_node(int node_id) {
    // Double the capacity of the node and copy its records to a new array.
    int old_capacity = nodes_[node_id].records.size();
    int new_capacity = old_capacity * 2;
    vector<Record> new_records(new_capacity);
    for (int i = 0; i < old_capacity; ++i) {
      new_records[i] = nodes_[node_id].records[i];
    }
    nodes_[node_id].records = move(new_records);
  }

  int feature_size_;
  int leaf_nodes_;
  int data_capacity_;
  vector<Node> nodes_;
  atomic<int> total_memory_usage_;
};
```
This code defines a class `Octree` that implements an advanced octree data structure with dynamic resizing and concurrent access safety. The constructor takes three parameters: the feature size, the number of leaf nodes, and the data capacity. It initializes the octree by dynamically allocating memory for the prefix leafs and data arrays, and initializing each node's records with random values within a specified range.

The `initialize` function is used to initialize the octree when it is first created. It dynamically allocates memory for the octree and its prefix leafs, and initializes each node's records with random values within a specified range.

The `insert` function is used to insert a record into the octree. It finds the node that the record belongs to and increments its num_records. If the node is full, it resizes it by doubling its capacity. Finally, it inserts the record into the node.

The `retrieve` function is used to retrieve records from the octree. It finds the node that the record belongs to and retrieves its records.

This code also includes a mechanism for tracking the total memory usage of all allocated structures and ensuring that memory is freed upon function exit. Additionally, it supports dynamic resizing of the octree when the number of records exceeds the current capacity. The `Octree` class also integrates an external library for memory management to optimize performance and reduce memory fragmentation.

