#define MIN_HASH_LEN 16
#define MAX_HASH_LEN 32
#define DEFAULT_DNS_SERVERS "8.8.8.8,8.8.4.4"
#define DNS_TIMEOUT 5000 // 5 seconds
#define RETRY_DELAY 1000 // 1 second
#define MAX_RETRY_COUNT 3
#define MEMORY_LIMIT 2097152 // 2 MB
#define CACHE_SIZE 100000
#define COMPRESSION_ALGORITHM "gzip"
#define COMPRESSION_LEVEL 6

typedef struct {
    char *hostname;
    u_char ip[4];
    size_t hash_len;
    unsigned char hash[MAX_HASH_LEN];
} record_t;

typedef struct {
    record_t **records;
    size_t count;
    size_t capacity;
} records_t;

void resolve_and_hash_files(const char *hostname, const char *directory, records_t *records) {
    // Initialize DNS servers and timeout
    struct addrinfo hints = {
        .ai_family = AF_INET,
        .ai_socktype = SOCK_DGRAM,
        .ai_flags = AI_ADDRCONFIG | AI_V4MAPPED
    };
    char *dns_servers = getenv("DNS_SERVERS");
    if (dns_servers == NULL) {
        dns_servers = DEFAULT_DNS_SERVERS;
    }
    struct addrinfo *result, *rp;
    int s;
    if ((s = getaddrinfo(dns_servers, NULL, &hints, &result)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(s));
        return;
    }
    struct timeval timeout = {
        .tv_sec = DNS_TIMEOUT / 1000,
        .tv_usec = (DNS_TIMEOUT % 1000) * 1000
    };
    // Initialize file list and hashes
    DIR *dir;
    struct dirent *entry;
    char *filepath;
    size_t filesize;
    unsigned char *hash;
    if ((dir = opendir(directory)) == NULL) {
        fprintf(stderr, "opendir: %s\n", strerror(errno));
        return;
    }
    while ((entry = readdir(dir)) != NULL) {
        filepath = malloc(strlen(directory) + strlen(entry->d_name) + 2);
        if (filepath == NULL) {
            fprintf(stderr, "malloc: %s\n", strerror(errno));
            return;
        }
        sprintf(filepath, "%s/%s", directory, entry->d_name);
        filesize = get_filesize(filepath);
        if (filesize > MAX_FILE_SIZE) {
            continue;
        }
        hash = malloc(MIN_HASH_LEN + filesize);
        if (hash == NULL) {
            fprintf(stderr, "malloc: %s\n", strerror(errno));
            return;
        }
        // Perform DNS resolution and calculate hash for each file
        int i = 0;
        while (i < MAX_RETRY_COUNT && !resolve_and_hash(hostname, filepath, filesize, hash)) {
            usleep(RETRY_DELAY * 1000);
            i++;
        }
        if (i == MAX_RETRY_COUNT) {
            fprintf(stderr, "Failed to resolve and hash %s\n", filepath);
            continue;
        }
        // Add record to records list
        record_t *record = malloc(sizeof(record_t));
        if (record == NULL) {
            fprintf(stderr, "malloc: %s\n", strerror(errno));
            return;
        }
        record->hostname = hostname;
        memcpy(record->ip, &result->ai_addr.sin_addr, 4);
        record->hash_len = hash_len;
        memcpy(record->hash, hash, hash_len);
        records->records[records->count++] = record;
    }
    closedir(dir);
}

bool resolve_and_hash(const char *hostname, const char *filepath, size_t filesize, unsigned char *hash) {
    // Initialize socket and DNS request
    int sockfd;
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) == -1) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        return false;
    }
    struct sockaddr_in server;
    memset(&server, 0, sizeof(server));
    server.sin_family = AF_INET;
    server.sin_port = htons(53);
    if (inet_pton(AF_INET, hostname, &server.sin_addr) <= 0) {
        fprintf(stderr, "inet_pton: %s\n", strerror(errno));
        return false;
    }
    char *request = malloc(strlen(hostname) + 12);
    if (request == NULL) {
        fprintf(stderr, "malloc: %s\n", strerror(errno));
        return false;
    }
    sprintf(request, "%s\0", hostname);
    // Send DNS request and receive response
    struct timeval timeout = {
        .tv_sec = DNS_TIMEOUT / 1000,
        .tv_usec = (DNS_TIMEOUT % 1000) * 1000
    };
    setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout));
    if (sendto(sockfd, request, strlen(request), 0, (struct sockaddr *)&server, sizeof(server)) == -1) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
        return false;
    }
    char response[512];
    struct iovec iov = {
        .iov_base = response,
        .iov_len = sizeof(response)
    };
    struct msghdr msg = {
        .msg_name = &server,
        .msg_namelen = sizeof(server),
        .msg_iov = &iov,
        .msg_iovlen = 1
    };
    ssize_t n;
    if ((n = recvmsg(sockfd, &msg, 0)) == -1) {
        fprintf(stderr, "recvmsg: %s\n", strerror(errno));
        return false;
    }
    // Parse DNS response and calculate hash for file
    char *ptr = response;
    ptr += 2; // Skip ID and flags
    int qdcount = ntohs(*((uint16_t *)ptr));
    ptr += 4; // Skip QDCOUNT, ANCOUNT, NSCOUNT, ARCOUNT
    while (qdcount-- > 0) {
        ptr += 10; // Skip name
        uint16_t type = ntohs(*((uint16_t *)ptr));
        ptr += 2; // Skip type
        uint16_t class = ntohs(*((uint16_t *)ptr));
        ptr += 2; // Skip class
    }
    int ancount = ntohs(*((uint16_t *)ptr));
    while (ancount-- > 0) {
        ptr += 10; // Skip name
        uint16_t type = ntohs(*((uint16_t *)ptr));
        ptr += 2; // Skip type
        uint16_t class = ntohs(*((uint16_t *)ptr));
        ptr += 2; // Skip class
        uint32_t ttl = ntohl(*((uint32_t *)ptr));
        ptr += 4; // Skip TTL
        uint16_t rdlength = ntohs(*((uint16_t *)ptr));
        ptr += 2; // Skip RDLENGTH
        if (type == 1) { // A record
            memcpy(hash, ptr, MIN_HASH_LEN);
            return true;
        } else {
            ptr += rdlength; // Skip data
        }
    }
    return false;
}

size_t get_filesize(const char *filepath) {
    struct stat st;
    if (stat(filepath, &st) == -1) {
        fprintf(stderr, "stat: %s\n", strerror(errno));
        return 0;
    }
    return st.st_size;
}

void free_records(records_t *records) {
    for (int i = 0; i < records->count; i++) {
        record_t *record = records->records[i];
        free(record->hostname);
        free(record->ip);
        free(record->hash);
        free(record);
    }
    free(records->records);
}

void cache_records(records_t *records) {
