// Function to calculate MD5 hash of a file
void calculate_md5_hash(const char *filepath) {
    // Open the file for reading in binary mode
    int fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        printf("Error: Failed to open file %s with error code %d\n", filepath, errno);
        return;
    }

    // Initialize the MD5 hash object
    md5_state_t state;
    md5_init(&state);

    // Read the file in chunks and update the MD5 hash
    char buffer[4096];
    ssize_t bytes_read = 0;
    while ((bytes_read = read(fd, buffer, sizeof(buffer))) > 0) {
        md5_update(&state, (const unsigned char *)buffer, bytes_read);
    }

    // Close the file and free the memory allocated for the MD5 hash object
    close(fd);
    md5_finalize(&state);

    // Print the MD5 hash to standard output
    printf("MD5 hash of %s: ", filepath);
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", state.digest[i]);
    }
    printf("\n");
}

