void calculate_sha256_hash(const char *filepath) {
    // Open the file for reading in binary mode
    int fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        printf("Error: Failed to open file %s with error code %d\n", filepath, errno);
        return;
    }

    // Initialize the SHA-256 hash object
    sha256_state_t state;
    sha256_init(&state);

    // Read the file in chunks and update the SHA-256 hash
    char buffer[4096];
    ssize_t bytes_read = 0;
    while ((bytes_read = read(fd, buffer, sizeof(buffer))) > 0) {
        sha256_update(&state, (const unsigned char *)buffer, bytes_read);
    }

    // Close the file and free the memory allocated for the SHA-256 hash object
    close(fd);
    sha256_finalize(&state);

    // Print the SHA-256 hash to standard output
    printf("SHA-256 hash of %s: ", filepath);
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        printf("%02x", state.digest[i]);
    }
    printf("\n");
}

// Function to collect data from a stream and save it to an array
void collect_data_from_stream(const char *filepath) {
    // Open the file for reading in binary mode
    int fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        printf("Error: Failed to open file %s with error code %d\n", filepath, errno);
        return;
    }

    // Initialize the array for storing the data
    char *data = malloc(sizeof(char));
    if (!data) {
        printf("Error: Failed to allocate memory for data array\n");
        close(fd);
        return;
    }

    // Read the file in chunks and store the data in the array
    char buffer[4096];
    ssize_t bytes_read = 0;
    while ((bytes_read = read(fd, buffer, sizeof(buffer))) > 0) {
        for (int i = 0; i < bytes_read; i++) {
            data = realloc(data, (sizeof(char) * (i + 1)));
            if (!data) {
                printf("Error: Failed to allocate memory for data array\n");
                close(fd);
                return;
            }
            data[i] = buffer[i];
        }
    }

    // Close the file and free the memory allocated for the array
    close(fd);
    free(data);
}
