        return false;
    }
    int fd = open(schema, O_RDONLY);
    if (fd == -1) {
        printf("Error: Failed to open file %s for reading\n", schema);
        json_parser_free(parser);
        return false;
    }
    char *buffer = malloc(4096);
    ssize_t bytes_read = read(fd, buffer, 4096);
