// Define the function to calculate both MD5 and SHA-256 hashes of a file given its path
void calculate_hashes(const char *filepath) {
    // Open the file for reading
    int fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        printf("Error: Failed to open file %s for reading\n", filepath);
        return;
    }

    // Initialize the hash objects and read the file in chunks
    unsigned char md5[MD5_DIGEST_LENGTH];
    unsigned char sha256[SHA256_DIGEST_LENGTH];
    EVP_MD *md = EVP_get_digestbyname("md5");
    EVP_MD *sha256_md = EVP_get_digestbyname("sha256");
    if (!md || !sha256_md) {
        printf("Error: Failed to initialize the hash objects\n");
        close(fd);
        return;
    }
    unsigned char buffer[4096];
    ssize_t bytes_read = read(fd, buffer, 4096);
    while (bytes_read > 0) {
        // Calculate the MD5 and SHA-256 hashes of the chunk
        EVP_DigestUpdate(md, buffer, bytes_read);
        EVP_DigestUpdate(sha256_md, buffer, bytes_read);

        // Read the next chunk
        bytes_read = read(fd, buffer, 4096);
    }

    // Close the file and free the memory allocated for the hash objects
    close(fd);
    EVP_MD_CTX_free(md);
    EVP_MD_CTX_free(sha256_md);

    // Print the MD5 and SHA-256 hashes to the console
    printf("MD5: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", md5[i]);
    }
    printf("\n");
    printf("SHA-256: ");
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        printf("%02x", sha256[i]);
    }
    printf("\n");
}

