// Define the function to validate a JSON string against a predefined schema
bool validate_json(const char *json, const char *schema) {
    // Initialize the JSON parser and schema validator
    json_parser_t *parser = json_parser_new();
    if (!parser) {
        printf("Error: Failed to initialize the JSON parser\n");
        return false;
    }
    json_validator_t *validator = json_validator_new(schema);
    if (!validator) {
        printf("Error: Failed to initialize the JSON schema validator\n");
        json_parser_free(parser);
        return false;
    }

    // Parse the JSON string and validate it against the predefined schema
