    if (!json_parse(parser, json, &error)) {
        printf("Error: Failed to parse the JSON string (%s)\n", error.text);
        json_validator_free(validator);
        json_parser_free(parser);
        return false;
    }
    if (!json_validate(validator, parser->root)) {
        printf("Error: Failed to validate the JSON string against the predefined schema\n");
        json_validator_free(validator);
        json_parser_free(parser);
        return false;
    }

    // Free the resources allocated by the JSON parser and schema validator
    json_validator_free(validator);
    json_parser_free(parser);

    // Return true if the JSON string is valid, false otherwise
    return true;
}

// Define the function to calculate both MD5 and SHA-256 hashes of large files given their paths
void calculate_hashes(const char *file_path) {
    // Open the file for reading
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        printf("Error: Failed to open the input file\n");
        return;
    }

    // Initialize the hash objects and buffer for reading chunks of data from the file
    hashlib_md5_t *md5 = hashlib_md5_new();
    hashlib_sha256_t *sha256 = hashlib_sha256_new();
    uint8_t buffer[4096];

    // Read chunks of data from the file and update the hash objects
    while (!feof(file)) {
        size_t bytes_read = fread(buffer, 1, sizeof(buffer), file);
        if (bytes_read > 0) {
            hashlib_md5_update(md5, buffer, bytes_read);
            hashlib_sha256_update(sha256, buffer, bytes_read);
        }
    }

    // Calculate the MD5 and SHA-256 hashes of the file data
    uint8_t md5_hash[16];
    uint8_t sha256_hash[32];
    hashlib_md5_final(md5, md5_hash);
    hashlib_sha256_final(sha256, sha256_hash);

    // Print the MD5 and SHA-256 hashes to the console
    printf("MD5 hash: %s\n", hashlib_md5_hexdigest(md5));
    printf("SHA-256 hash: %s\n", hashlib_sha256_hexdigest(sha256));

    // Free the resources allocated by the hash objects and close the file
    hashlib_md5_free(md5);
    hashlib_sha256_free(sha256);
    fclose(file);
}

// Define the function to collect data from a stream and save it to an array
void collect_data(const char *stream, int size) {
    // Initialize the array for storing the collected data
    uint8_t *array = (uint8_t *)malloc(size);
    if (!array) {
        printf("Error: Failed to allocate memory for the collected data\n");
        return;
    }

    // Read chunks of data from the stream and store them in the array
    int offset = 0;
    while (offset < size) {
        int bytes_read = fread(array + offset, 1, sizeof(uint8_t), stream);
        if (bytes_read > 0) {
            offset += bytes_read;
        } else {
            break;
        }
    }

    // Print the collected data to the console
    printf("Collected data: ");
    for (int i = 0; i < size; i++) {
        printf("%d ", array[i]);
    }
    printf("\n");

    // Free the memory allocated for the array and close the stream
    free(array);
}
