// Define the maximum number of active ranges
#define MAX_RANGES 10

// Define the structure to store the range information
typedef struct {
    float min;
    float max;
} Range;

// Define the structure to store the dynamic value manager state
typedef struct {
    int num_ranges;
    Range ranges[MAX_RANGES];
    json_object *json_state;
} DynamicValueManagerState;

// Initialize the dynamic value manager state
void init_dynamic_value_manager(DynamicValueManagerState *state) {
    // Set the number of active ranges to 0
    state->num_ranges = 0;

    // Initialize the JSON state object
    state->json_state = json_object_new();
}

// Add a new range to the dynamic value manager
void add_range(DynamicValueManagerState *state, float min, float max) {
    // Check if there is space for another range
    if (state->num_ranges >= MAX_RANGES) {
        printf("Error: maximum number of ranges exceeded\n");
        return;
    }

    // Add the new range to the state
    state->ranges[state->num_ranges].min = min;
    state->ranges[state->num_ranges].max = max;
    state->num_ranges++;
}

// Remove a range from the dynamic value manager
void remove_range(DynamicValueManagerState *state, int index) {
    // Check if the index is valid
    if (index < 0 || index >= state->num_ranges) {
        printf("Error: invalid range index\n");
        return;
    }

    // Remove the range from the state
    for (int i = index; i < state->num_ranges - 1; i++) {
        state->ranges[i] = state->ranges[i + 1];
    }
    state->num_ranges--;
}

// Generate a random float value within the specified range
float generate_random_float(DynamicValueManagerState *state, int index) {
    // Check if the index is valid
    if (index < 0 || index >= state->num_ranges) {
        printf("Error: invalid range index\n");
        return NAN;
    }

    // Generate a random float value within the specified range
    float min = state->ranges[index].min;
    float max = state->ranges[index].max;
    return (float)rand() / RAND_MAX * (max - min) + min;
}

// Generate a random integer value within the specified range
int generate_random_integer(DynamicValueManagerState *state, int index) {
    // Check if the index is valid
    if (index < 0 || index >= state->num_ranges) {
        printf("Error: invalid range index\n");
        return NAN;
    }

    // Generate a random integer value within the specified range
    int min = state->ranges[index].min;
    int max = state->ranges[index].max;
    return rand() % (max - min + 1) + min;
}

// Serialize the current state of the ranges to JSON
void serialize_state(DynamicValueManagerState *state, json_object *json_state) {
    // Clear any existing data in the JSON object
    json_object_put(json_state);

    // Add the number of active ranges to the JSON object
    json_object_object_add(json_state, "num_ranges", json_object_new_int(state->num_ranges));

    // Add each range to the JSON object
    for (int i = 0; i < state->num_ranges; i++) {
        json_object *range_json = json_object_new_object();
        json_object_object_add(range_json, "min", json_object_new_double(state->ranges[i].min));
        json_object_object_add(range_json, "max", json_object_new_double(state->ranges[i].max));
        json_object_array_add(json_state, range_json);
    }
}

// Deserialize the JSON state back into the class state
void deserialize_state(DynamicValueManagerState *state, json_object *json_state) {
    // Clear any existing data in the class state
    state->num_ranges = 0;

    // Get the number of active ranges from the JSON object
    int num_ranges = json_object_get_int(json_object_object_get(json_state, "num_ranges"));

    // Add each range to the class state
    for (int i = 0; i < num_ranges; i++) {
        json_object *range_json = json_object_array_get_idx(json_state, i);
        float min = json_object_get_double(json_object_object_get(range_json, "min"));
        float max = json_object_get_double(json_object_object_get(range_json, "max"));
        add_range(state, min, max);
    }
}

// Calculate the mean and standard deviation of all values generated within the ranges
void calculate_statistics(DynamicValueManagerState *state) {
    // Initialize the sum and count to 0
    double sum = 0;
    int count = 0;

    // Iterate over each range and add its values to the sum and count
    for (int i = 0; i < state->num_ranges; i++) {
        float min = state->ranges[i].min;
        float max = state->ranges[i].max;
        int num_values = max - min + 1;
        sum += (double)num_values * (min + max) / 2.0;
        count += num_values;
    }

    // Calculate the mean and standard deviation
    double mean = sum / count;
    double variance = 0;
    for (int i = 0; i < state->num_ranges; i++) {
        float min = state->ranges[i].min;
        float max = state->ranges[i].max;
        int num_values = max - min + 1;
        variance += (double)num_values * pow((min + max) / 2.0 - mean, 2);
    }
    variance /= count;
    double standard_deviation = sqrt(variance);

    // Print the statistics to the console
    printf("Mean: %f\n", mean);
    printf("Standard Deviation: %f\n", standard_deviation);
}

// Find the smallest and largest values across all ranges
void find_min_max(DynamicValueManagerState *state) {
    // Initialize the minimum and maximum to infinity
    float min = INFINITY;
    float max = -INFINITY;

    // Iterate over each range and update the minimum and maximum values
    for (int i = 0; i < state->num_ranges; i++) {
        float range_min = state->ranges[i].min;
        float range_max = state->ranges[i].max;
        if (range_min < min) {
            min = range_min;
        }
        if (range_max > max) {
            max = range_max;
        }
    }

    // Print the smallest and largest values to the console
    printf("Smallest value: %f\n", min);
    printf("Largest value: %f\n", max);
}

// Log a message for future analysis and debugging purposes
void log_message(DynamicValueManagerState *state, char *message) {
    // Add the message to the JSON state object
    json_object *json_message = json_object_new_string(message);
    json_object_array_add(state->json_state, json_message);
}
