    modular_design_index = 0;

    // Create a semaphore for synchronizing access to shared resources
    sem_t *semaphore = sem_open("crc_indication_semaphore", O_CREAT, 0644, 1);

    // Loop over the input parameters and populate the list of CRC indication PDUs
    for (int i = 0; i < N; i++) {
        // Acquire the semaphore to synchronize access to shared resources
        sem_wait(semaphore);

        // Allocate a new structure from the memory pool
        crc_indication_pdu_t *new_pdu = (crc_indication_pdu_t *)memory_pool + memory_pool_index;
        memory_pool_index += sizeof(crc_indication_pdu_t);

