        new_pdu->id = i;
        new_pdu->seq_num = i + 1;
        new_pdu->priority = i % 3;
        new_pdu->pdu.rx_ue_information_tag = (NFAPI_RX_UE_INFORMATION_TAG)malloc(sizeof(nfapi_rx_ue_information_t));
        new_pdu->pdu.rx_ue_information_tag->rnti = i + 1;

        // Set a randomly set CRCFLAG in the CRC_INDICATION_REL8_TAG
        new_pdu->pdu.crc_indication_rel8_tag = (NFAPI_CRC_INDICATION_REL8_TAG)malloc(sizeof(nfapi_crc_indication_rel8_t));
        new_pdu->pdu.crc_indication_rel8_tag->crc_flag = rand() % 2;

