        new_pdu->pdu.timestamp = (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;

        // Release the semaphore to allow other threads to access shared resources
        sem_post(semaphore);

        // Log any failures during population process
        if (new_pdu->pdu.rx_ue_information_tag == NULL || new_pdu->pdu.crc_indication_rel8_tag == NULL) {
            log_failure("Failed to allocate memory for CRC indication PDU");
        }
    }

    // Close the semaphore and free any unused memory in the memory pool
    sem_close(semaphore);
    memory_pool_index = 0;
}

