#include <nlohmann/json.hpp>

using namespace std;
using json = nlohmann::json;

// Define regular expressions for matching book names
const regex BOOK_NAMES_REGEX("\\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\\b");
const regex BOOK_NAMES_REGEX_IGNORE_PUNCTUATION("\\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\\b(?![^\\s])");

// Define a mutex to ensure thread safety when accessing shared resources
mutex mtx;

// Define a map to store the detected book counts
map<string, int> book_counts;

// Define a logging mechanism to record the detection process
void log(const string& message) {
  cout << "[" << chrono::system_clock::now().time_since_epoch().count() << "] " << message << endl;
}

// Define a memory allocation strategy to handle large texts without excessive memory usage or performance degradation
void* allocate(size_t size) {
  void* ptr = malloc(size);
  if (ptr == nullptr) {
    throw runtime_error("Failed to allocate memory");
  }
  return ptr;
}

// Define a serialization mechanism to serialize the detected book counts to JSON format
string serialize() {
  json j;
  for (const auto& [book, count] : book_counts) {
    j[book] = count;
  }
  return j.dump();
}

// Define a deserialization mechanism to deserialize the detected book counts from JSON format
void deserialize(const string& json_string) {
  try {
    json j = json::parse(json_string);
    for (const auto& [book, count] : j.items()) {
      book_counts[book] = count;
    }
  } catch (const exception& e) {
    log("Failed to deserialize JSON string: " + json_string);
  }
}

// Define an incremental algorithm for statistical calculations
void calculate_statistics(const string& text) {
  // Initialize variables for mean and standard deviation
  double sum = 0;
  int count = 0;
  double mean = 0;
  double variance = 0;

  // Iterate over the words in the text
  for (const auto& word : split(text, " ")) {
    // Check if the word is a book name
    smatch match;
    if (regex_search(word, match, BOOK_NAMES_REGEX_IGNORE_PUNCTUATION)) {
      // Increment the count of the book
      book_counts[match.str()]++;

      // Update the sum and count for calculating mean and standard deviation
      sum += match.str().length();
      count++;
    }
  }

  // Calculate the mean and standard deviation
  if (count > 0) {
    mean = sum / count;
    variance = pow(sum, 2) / count - pow(mean, 2);
  }
}

// Define a method to find the most frequently mentioned books and their respective counts
void find_most_frequent_books() {
  // Initialize a map to store the most frequent books and their counts
  map<string, int> most_frequent_books;

  // Iterate over the book counts
  for (const auto& [book, count] : book_counts) {
    // Check if the book is already in the map of most frequent books
    if (most_frequent_books.find(book) == most_frequent_books.end()) {
      // Add the book to the map with a count of 1
      most_frequent_books[book] = 1;
    } else {
      // Increment the count of the book in the map
      most_frequent_books[book]++;
    }
  }

  // Sort the map by value (count) in descending order
  for (const auto& [book, count] : most_frequent_books) {
    log("Most frequent book: " + book + ", count: " + to_string(count));
  }
}

// Define a method to process a given text string and extract the names of books from the Bible's Old Testament that are mentioned within it
void process_text(const string& text) {
  // Clear the book counts map
  book_counts.clear();

  // Calculate the statistics for the text
  calculate_statistics(text);

  // Find the most frequent books and their respective counts
  find_most_frequent_books();
}

