void process_file(const string& filename) {
  // Open the file in read mode
  ifstream file(filename);
  if (!file.is_open()) {
    throw runtime_error("Failed to open file: " + filename);
  }

  // Read the contents of the file into a string
  string text;
  file >> noskipws >> text;

  // Process the text
  process_text(text);
}

