#include <pthread.h>

// Define the structure for a network connection record
typedef struct {
    int conn_id;
    char client_ip[16];
    int port;
    int state;
    time_t last_activity;
} CONN_RECORD;

// Define the function to populate the collection of network connection records
void populate_conn_records(int N, int seed, int time_window) {
    // Initialize the array of connection records
    CONN_RECORD *conn_records = (CONN_RECORD *)malloc(sizeof(CONN_RECORD) * N);
    if (!conn_records) {
        printf("Error: Failed to allocate memory for connection records\n");
        return;
    }

    // Initialize the seed value for random number generation
    srand(seed);

    // Populate the array of connection records with random values
    for (int i = 0; i < N; i++) {
        conn_records[i].conn_id = rand();
        inet_ntop(AF_INET, &(rand() % 256), conn_records[i].client_ip, sizeof(conn_records[i].client_ip));
        conn_records[i].port = rand() % 1000;
        conn_records[i].state = (rand() % 2) ? OPEN : CLOSED;
        conn_records[i].last_activity = time(NULL);
    }

    // Sort the array of connection records by last activity
    qsort(conn_records, N, sizeof(CONN_RECORD), compare_conn_records);

    // Determine the most recently active connection among a set of clients
    int most_recently_active = 0;
    for (int i = 1; i < N; i++) {
        if (conn_records[i].last_activity > conn_records[most_recently_active].last_activity) {
            most_recently_active = i;
        }
    }

    // Print the details of the most recently active connection
    printf("Most recently active connection:\n");
    printf("Connection ID: %d\n", conn_records[most_recently_active].conn_id);
    printf("Client IP: %s\n", conn_records[most_recently_active].client_ip);
    printf("Port: %d\n", conn_records[most_recently_active].port);
    printf("State: %s\n", (conn_records[most_recently_active].state == OPEN) ? "Open" : "Closed");
    printf("Last activity: %s\n", ctime(&(conn_records[most_recently_active].last_activity)));

    // Clean up memory allocation for the array of connection records
    free(conn_records);
}

// Define the function to compare two connection records based on last activity
int compare_conn_records(const void *a, const void *b) {
    return ((CONN_RECORD *)a)->last_activity - ((CONN_RECORD *)b)->last_activity;
}

// Define the function to handle errors during memory allocation and deallocation
void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}
