// Define the structure for holding the CRC indication data
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T crc_indication;
} CrcIndicationData;

// Define the array of CRC indication data structures
static CrcIndicationData *crc_indications = NULL;

// Define the maximum number of records that can be stored in the array
#define MAX_RECORDS 1000

// Define a mutex for synchronizing access to the array
static pthread_mutex_t crc_indication_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the CRC indication data structure
void initCrcIndicationData(CrcIndicationData *data) {
    // Set the RX UE information tag and RNTI
    data->crc_indication.rx_ue_information_tag = 0;
    data->crc_indication.rnti = 0;

    // Set a random value for the CRC indication REL8 tag
    data->crc_indication.crc_indication_rel8_tag = rand();
}

// Function to add a new element to the array
void addCrcIndication(NFAPI_CRC_INDICATION_PDU_T *crc_indication) {
    // Acquire the mutex for synchronizing access to the array
    pthread_mutex_lock(&crc_indication_mutex);

    // Check if the array is full
    if (crc_indications == NULL || crc_indications->size >= MAX_RECORDS) {
        // If the array is full, allocate a new one with double the size
        CrcIndicationData *new_array = realloc(crc_indications, 2 * MAX_RECORDS);
        if (new_array == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&crc_indication_mutex);
            return;
        }
        crc_indications = new_array;
    }

    // Initialize the new element with a random value for the CRC indication REL8 tag
    initCrcIndicationData(&crc_indications[crc_indications->size]);
    crc_indications->size++;

    // Copy the input data to the new element
    memcpy(&crc_indications[crc_indications->size - 1].crc_indication, crc_indication, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Release the mutex for synchronizing access to the array
    pthread_mutex_unlock(&crc_indication_mutex);
}

// Function to remove an element from the array
void removeCrcIndication(int index) {
    // Acquire the mutex for synchronizing access to the array
    pthread_mutex_lock(&crc_indication_mutex);

    // Check if the input index is valid
    if (index < 0 || index >= crc_indications->size) {
        // If the input index is invalid, release the mutex and return
        pthread_mutex_unlock(&crc_indication_mutex);
        return;
    }

    // Shift all elements after the input index to the left by one position
    for (int i = index + 1; i < crc_indications->size; i++) {
        memcpy(&crc_indications[i - 1], &crc_indications[i], sizeof(CrcIndicationData));
    }

    // Decrement the size of the array by one
    crc_indications->size--;

    // Release the mutex for synchronizing access to the array
    pthread_mutex_unlock(&crc_indication_mutex);
}

// Function to get an element from the array
CrcIndicationData *getCrcIndication(int index) {
    // Acquire the mutex for synchronizing access to the array
    pthread_mutex_lock(&crc_indication_mutex);

    // Check if the input index is valid
    if (index < 0 || index >= crc_indications->size) {
        // If the input index is invalid, release the mutex and return NULL
        pthread_mutex_unlock(&crc_indication_mutex);
        return NULL;
    }

    // Return a pointer to the element at the input index
    CrcIndicationData *data = &crc_indications[index];

    // Release the mutex for synchronizing access to the array
    pthread_mutex_unlock(&crc_indication_mutex);

    return data;
}
