    // Compute the lengths of each product description and store them in a histogram
    int *histogram = (int *)malloc(num_products * sizeof(int));
    if (!histogram) {
        printf("Error: Failed to allocate memory for histogram\n");
        return;
    }
    for (int i = 0; i < num_products; i++) {
        histogram[i] = strlen(product_descriptions[i]);
    }

    // Detect and report products with identical descriptions
    int duplicate_count = 0;
    for (int i = 0; i < num_products - 1; i++) {
        if (strcmp(product_descriptions[i], product_descriptions[i + 1]) == 0) {
            duplicate_count++;
        }
    }
    printf("Number of duplicate products: %d\n", duplicate_count);

    // Release memory for histogram
    free(histogram);
}
