use std::sync::Arc;
use std::thread;
use std::time::Instant;

struct CrcIndicationPdu {
    rx_ue_information_tag: u32,
    rnti: u64,
    crc_indication_rel8_tag: u16,
    timestamp: Instant,
}

impl CrcIndicationPdu {
    fn new(rx_ue_information_tag: u32, rnti: u64, crc_indication_rel8_tag: u16) -> Self {
        let timestamp = Instant::now();
        Self {
            rx_ue_information_tag,
            rnti,
            crc_indication_rel8_tag,
            timestamp,
        }
    }
}

struct CrcIndicationPduPool {
    pool: Vec<Arc<CrcIndicationPdu>>,
}

impl CrcIndicationPduPool {
    fn new(size: usize) -> Self {
        let mut pool = Vec::with_capacity(size);
        for _ in 0..size {
            pool.push(Arc::new(CrcIndicationPdu::new(0, 0, 0)));
        }
        Self { pool }
    }

    fn allocate(&mut self) -> Arc<CrcIndicationPdu> {
        if let Some(pdu) = self.pool.pop() {
            pdu
        } else {
            Arc::new(CrcIndicationPdu::new(0, 0, 0))
        }
    }

    fn deallocate(&mut self, pdu: Arc<CrcIndicationPdu>) {
        self.pool.push(pdu);
    }
}

struct CrcIndicationManager {
    pool: CrcIndicationPduPool,
    sequence_number: u32,
    priority_levels: [u8; 4],
}

impl CrcIndicationManager {
    fn new(size: usize) -> Self {
        let mut priority_levels = [0; 4];
        for i in 0..priority_levels.len() {
            priority_levels[i] = i as u8;
        }
        Self {
            pool: CrcIndicationPduPool::new(size),
            sequence_number: 0,
            priority_levels,
        }
    }

    fn allocate(&mut self) -> Arc<CrcIndicationPdu> {
        let pdu = self.pool.allocate();
        pdu.sequence_number = self.sequence_number;
        self.sequence_number += 1;
        pdu
    }

    fn deallocate(&mut self, pdu: Arc<CrcIndicationPdu>) {
        self.pool.deallocate(pdu);
    }
}

fn main() {
    let mut manager = CrcIndicationManager::new(1000);
    let mut rx_ue_information_tag: u32 = 0;
    let mut rnti: u64 = 0;
    let mut crc_indication_rel8_tag: u16 = 0;
    let mut timestamp: Instant = Instant::now();

    loop {
        // Read input parameters from command line arguments
        rx_ue_information_tag = 0;
        rnti = 0;
        crc_indication_rel8_tag = 0;
        timestamp = Instant::now();

        // Allocate a new CRC indication PDU from the pool
        let pdu = manager.allocate();

        // Populate the PDU with input parameters
        pdu.rx_ue_information_tag = rx_ue_information_tag;
        pdu.rnti = rnti;
        pdu.crc_indication_rel8_tag = crc_indication_rel8_tag;
        pdu.timestamp = timestamp;

        // Add the PDU to the list of CRC indications
        manager.add(pdu);
    }
}
