// Define the structure for a user session record
typedef struct {
    int session_id;
    char* login_name;
    time_t last_accessed;
    time_t expiration_time;
    bool is_active;
} SESSION_RECORD;

// Define the function to populate the user session records
void populate_session_records(int N, int seed, int grace_period) {
    // Initialize the array of session records
    SESSION_RECORD* records = (SESSION_RECORD*)malloc(N * sizeof(SESSION_RECORD));

    // Generate random numbers for each record
    srand(seed);
    for (int i = 0; i < N; i++) {
        records[i].session_id = rand();
        records[i].login_name = "user";
        records[i].last_accessed = time(NULL) - grace_period;
        records[i].expiration_time = time(NULL) + (rand() % 3600);
        records[i].is_active = true;
    }

    // Sort the array by session ID in ascending order
    qsort(records, N, sizeof(SESSION_RECORD), compare_session_ids);

    // Initialize the mutex for thread-safe operations
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Populate the session records in parallel using threads
    int num_threads = 4; // Adjust this value based on available CPU cores
    pthread_t* threads = (pthread_t*)malloc(num_threads * sizeof(pthread_t));
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, populate_session_records_helper, records);
    }

    // Wait for all threads to complete and destroy the mutex
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
    pthread_mutex_destroy(&mutex);

    // Free the memory allocated for the session records
    free(records);
}

// Define a helper function to populate the session records in parallel using threads
void* populate_session_records_helper(void* arg) {
    SESSION_RECORD* records = (SESSION_RECORD*)arg;
    int num_records = N / 4; // Adjust this value based on available CPU cores
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        records[i].last_accessed = time(NULL) - grace_period;
        records[i].expiration_time = time(NULL) + (rand() % 3600);
    }
    pthread_mutex_unlock(&mutex);
}

