    int state;
    time_t last_activity;
} conn_record_t;

// Define the collection of network connection records
conn_record_t *records = NULL;
int num_records = 0;
pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to populate the collection of network connection records
void populate_records(int N, int seed, time_t window) {
    // Initialize the collection of records with the given number of elements
    num_records = N;
    records = (conn_record_t *)malloc(sizeof(conn_record_t) * num_records);

    // Generate random numbers for each record's ID, IP address, and port number
    srand(seed);
    for (int i = 0; i < num_records; i++) {
        records[i].id = rand() % 10000;
        records[i].ip[0] = '1';
        records[i].ip[1] = '.';
        records[i].ip[2] = '2';
        records[i].ip[3] = '.';
        records[i].ip[4] = '3';
        records[i].ip[5] = '.';
        records[i].ip[6] = '4';
        records[i].port = rand() % 10000;
    }

    // Set the initial state of each record to closed
    for (int i = 0; i < num_records; i++) {
        records[i].state = CLOSED;
    }

    // Set the last activity time for each record to the current time
    time_t now = time(NULL);
    for (int i = 0; i < num_records; i++) {
        records[i].last_activity = now;
    }
}

// Function to update the state of a network connection record
void update_record(int id, int state) {
    // Lock the record mutex to prevent concurrent access
    pthread_mutex_lock(&record_lock);

    // Find the record with the given ID and update its state
    for (int i = 0; i < num_records; i++) {
        if (records[i].id == id) {
            records[i].state = state;
            break;
        }
    }

    // Unlock the record mutex and return
    pthread_mutex_unlock(&record_lock);
}

// Function to retrieve the most recently active connection among a set of clients
conn_record_t *get_active_connection(int num_clients, int *client_ids) {
    // Lock the record mutex to prevent concurrent access
    pthread_mutex_lock(&record_lock);

    // Find the most recently active connection among the given clients
    conn_record_t *active_connection = NULL;
    time_t last_activity = 0;
    for (int i = 0; i < num_clients; i++) {
        int client_id = client_ids[i];
        for (int j = 0; j < num_records; j++) {
            if (records[j].id == client_id) {
                time_t current_activity = records[j].last_activity;
                if (current_activity > last_activity) {
                    active_connection = &records[j];
                    last_activity = current_activity;
                }
            }
        }
    }

    // Unlock the record mutex and return the most recently active connection
    pthread_mutex_unlock(&record_lock);
    return active_connection;
}
