int readNASMessagesFromFile(const char* filename, NFCellCtrlMsgType** nasMessages) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Read the number of messages in the file
    int numMessages = 0;
    if (fscanf(fp, "%d", &numMessages) != 1) {
        fclose(fp);
        perror("Error reading number of messages");
        return -1;
    }

    // Allocate memory for the array of NAS messages
    *nasMessages = (NFCellCtrlMsgType*)malloc(sizeof(NFCellCtrlMsgType) * numMessages);
    if (*nasMessages == NULL) {
        fclose(fp);
        perror("Error allocating memory");
        return -1;
    }

    // Read the messages from the file and populate the array
    for (int i = 0; i < numMessages; i++) {
        NFCellCtrlMsgType* msg = &(*nasMessages)[i];
        if (fscanf(fp, "%d %hhd %s", &msg->UE_ID, &msg->RRC_Cause, msg->NAS_Message) != 3) {
            fclose(fp);
            perror("Error reading message");
            return -1;
        }
    }

    // Close the file
    fclose(fp);

    // Validate the integrity of the NAS messages using a checksum algorithm
    for (int i = 0; i < numMessages; i++) {
        NFCellCtrlMsgType* msg = &(*nasMessages)[i];
        uint32_t checksum = calculateChecksum(msg->NAS_Message);
        if (checksum != msg->RRC_Cause) {
            perror("Error validating NAS message");
            return -1;
        }
    }

    // Return the array of NAS messages
    return numMessages;
}

// Function to calculate the checksum of a NAS message
uint32_t calculateChecksum(const char* nasMessage) {
    uint32_t checksum = 0;
    for (int i = 0; i < strlen(nasMessage); i++) {
        checksum += nasMessage[i];
    }
    return checksum;
}
