// Define the structure for storing NAS messages
typedef struct {
    uint32_t UE_ID;
    uint8_t RRC_Cause;
    char* NAS_Message;
} NFCellCtrlMsgType;

// Define the cache size and eviction policy
#define CACHE_SIZE 1000
#define EVICTION_POLICY LRU

// Define the function to populate the array of NAS messages
void populateNASMessages(char* filepath) {
    // Open the file for reading
    FILE* fp = fopen(filepath, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filepath);
        return;
    }

    // Allocate memory for the array of NAS messages
    NFCellCtrlMsgType* nas_messages = malloc(sizeof(NFCellCtrlMsgType) * CACHE_SIZE);
    if (nas_messages == NULL) {
        printf("Error: unable to allocate memory for NAS messages\n");
        fclose(fp);
        return;
    }

    // Read the file line by line and populate the array of NAS messages
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Parse the line into UE ID, RRC cause, and NAS message
        char* token = strtok(line, ",");
        uint32_t UE_ID = atoi(token);
        token = strtok(NULL, ",");
        uint8_t RRC_Cause = atoi(token);
        token = strtok(NULL, ",");
        char* NAS_Message = token;

        // Add the NAS message to the cache
        addNASMessageToCache(UE_ID, RRC_Cause, NAS_Message);
    }

    // Close the file and free memory
    fclose(fp);
    free(line);
}

// Define the function to add a NAS message to the cache
void addNASMessageToCache(uint32_t UE_ID, uint8_t RRC_Cause, char* NAS_Message) {
    // Check if the cache is full and evict an entry if necessary
    if (cache_size == CACHE_SIZE) {
        evictNASMessageFromCache();
    }

    // Add the new NAS message to the cache
    NFCellCtrlMsgType* nas_message = malloc(sizeof(NFCellCtrlMsgType));
    nas_message->UE_ID = UE_ID;
    nas_message->RRC_Cause = RRC_Cause;
    nas_message->NAS_Message = NAS_Message;
    cache[cache_size++] = nas_message;
}

// Define the function to evict a NAS message from the cache
void evictNASMessageFromCache() {
    // Find the least recently used entry in the cache
    int lru_index = 0;
    for (int i = 1; i < cache_size; i++) {
        if (cache[i]->last_accessed < cache[lru_index]->last_accessed) {
            lru_index = i;
        }
    }

    // Remove the least recently used entry from the cache
    free(cache[lru_index]);
    cache[lru_index] = NULL;
}

// Define the function to validate the integrity of a NAS message using a checksum algorithm
void validateNASMessage(NFCellCtrlMsgType* nas_message) {
    // Calculate the MD5 hash of the NAS message
    char* hash = calculateMD5Hash(nas_message->NAS_Message);

    // Compare the calculated hash with the expected hash
    if (strcmp(hash, nas_message->hash) != 0) {
        printf("Error: invalid NAS message detected\n");
    }
}

// Define the function to calculate the MD5 hash of a string using OpenSSL
char* calculateMD5Hash(char* str) {
    // Allocate memory for the hash
    char* hash = malloc(16);
    if (hash == NULL) {
        printf("Error: unable to allocate memory for hash\n");
        return NULL;
    }

    // Calculate the MD5 hash of the string
    MD5_CTX ctx;
    MD5Init(&ctx);
    MD5Update(&ctx, str, strlen(str));
    MD5Final(hash, &ctx);

    return hash;
}
