        products[j].price = rand() % 100;
        products[j].quantity = rand() % 50;
    }

    // Compute the lengths of the product descriptions and store them in a histogram
    int *histogram = (int *)malloc(num_records * sizeof(int));
    if (!histogram) {
        printf("Error: Failed to allocate memory for histogram\n");
        free(ue_context);
        free(products);
        return;
    }
    for (i = 0; i < num_records; i++) {
        histogram[i] = strlen(products[i].product_name);
    }

    // Detect and report products with identical descriptions
    int duplicate_count = 0;
    for (i = 0; i < num_records - 1; i++) {
        for (j = i + 1; j < num_records; j++) {
            if (strcmp(products[i].product_name, products[j].product_name) == 0) {
                duplicate_count++;
            }
        }
    }
    printf("Number of duplicate products: %d\n", duplicate_count);

    // Release the memory allocated for the UE context collection and product information structures
    free(ue_context);
    free(products);
    free(histogram);
}
