                continue;
            }
        }
    }

    // Update the metrics and return the maximum weighted sum and corresponding transaction ID
    double max_weighted_sum = 0;
    int max_transaction_id = -1;
    for (int i = 0; i < M - filtered_events; ++i) {
        NetworkEvent* event = &events[i];
        if (event->type == 1 || event->type == 2) {
            // Update the metrics and return the maximum weighted sum and corresponding transaction ID
            double weighted_sum = 0;
            for (int j = 0; j < 5; ++j) {
                weighted_sum += event->metrics[j];
            }
            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
                max_transaction_id = i;
            }
        } else if (event->type == 3 || event->type == 4) {
            // Update the metrics and return the maximum weighted sum and corresponding transaction ID
            double weighted_sum = 0;
            for (int j = 0; j < 5; ++j) {
                weighted_sum += event->metrics[j];
            }
            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
                max_transaction_id = i;
            }
        } else if (event->type == 5 || event->type == 6) {
            // Update the metrics and return the maximum weighted sum and corresponding transaction ID
            double weighted_sum = 0;
            for (int j = 0; j < 5; ++j) {
                weighted_sum += event->metrics[j];
            }
            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
                max_transaction_id = i;
            }
        }
    }

    // Free the memory allocated for the list of network events
