#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <stdbool.h>

// Define the structure for CRC indication PDUs
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to construct and populate an array of CRC indication PDUs
NFAPI_CRC_INDICATION_PDU_T* construct_crc_indication_pdu_array(int N, int seed) {
    // Allocate memory for the array of CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (!crc_indication_pdu_array) {
        // Log an error message and return NULL if memory allocation fails
        printf("Error: Failed to allocate memory for CRC indication PDU array\n");
        return NULL;
    }

    // Initialize the timestamp mechanism
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Populate the array of CRC indication PDUs with random values
    for (int i = 0; i < N; i++) {
        crc_indication_pdu_array[i].rx_ue_information_tag = rand_r(&seed) % 65536;
        crc_indication_pdu_array[i].rnti = rand_r(&seed) % 4294967296;
        crc_indication_pdu_array[i].crc_indication_rel8_tag = rand_r(&seed) % 256;
        crc_indication_pdu_array[i].crcflag = (rand_r(&seed) % 2 == 0);
    }

    // Log the processing time for each CRC indication
    clock_gettime(CLOCK_MONOTONIC, &end);
    printf("Processing time: %.3f ms\n", (double)(end.tv_sec - start.tv_sec) * 1000 + (double)(end.tv_nsec - start.tv_nsec) / 1e6);

    // Return the array of CRC indication PDUs
    return crc_indication_pdu_array;
}
