// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *crc_indication_list = NULL;
size_t crc_indication_list_size = 0;
pthread_mutex_t crc_indication_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
void create_and_populate_crc_indication_list(size_t num_elements) {
    // Lock the mutex to ensure thread safety when accessing the list
    pthread_mutex_lock(&crc_indication_list_lock);

    // Check if the list is already allocated and has enough space for the new elements
    if (crc_indication_list == NULL || crc_indication_list_size < num_elements) {
        // If the list is not allocated or does not have enough space, allocate a new one with double the size of the previous one
        size_t new_list_size = (crc_indication_list == NULL) ? 0 : crc_indication_list_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(crc_indication_list, new_list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list == NULL) {
            // If the allocation fails, log an error and return
            printf("Error: Failed to allocate memory for crc_indication_list\n");
            pthread_mutex_unlock(&crc_indication_list_lock);
            return;
        }
        crc_indication_list = new_list;
        crc_indication_list_size = new_list_size;
    }

    // Populate the list with random values for RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
    srand(time(NULL));
    for (size_t i = 0; i < num_elements; i++) {
        crc_indication_list[i].rx_ue_information_tag = rand() % 10000;
        crc_indication_list[i].rnti = rand() % 1000000000;
        crc_indication_list[i].crc_indication_rel8_tag = rand() % 256;
    }

    // Unlock the mutex to release thread safety
    pthread_mutex_unlock(&crc_indication_list_lock);
}

// Function to log performance metrics for the create_and_populate_crc_indication_list function
void log_performance_metrics(size_t num_elements) {
    // Calculate the time taken to populate the list
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    create_and_populate_crc_indication_list(num_elements);
    clock_gettime(CLOCK_MONOTONIC, &end);
    double time_taken = (double)(end.tv_sec - start.tv_sec) + (double)(end.tv_nsec - start.tv_nsec) / 1000000000;

    // Log the performance metrics to the logging framework
    printf("Performance Metrics: create_and_populate_crc_indication_list()\n");
    printf("\tTime taken: %f seconds\n", time_taken);
    printf("\tMemory usage: %lu bytes\n", sizeof(NFAPI_CRC_INDICATION_PDU_T) * crc_indication_list_size);
}
