// Define the structure for a connection request
typedef struct {
    int client_id;
    time_t timestamp;
    bool is_active;
} ConnectionRequest;

// Define the pool of connection requests
ConnectionRequest* pool = NULL;
size_t pool_size = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new connection request to the pool
void add_connection_request(int client_id, time_t timestamp) {
    // Lock the pool mutex to prevent concurrent access
    pthread_mutex_lock(&pool_lock);

    // Check if the pool needs to be resized
    if (pool_size == 0 || pool_size == pool->capacity) {
        // Resize the pool by a factor of 2
        pool = realloc(pool, pool_size * 2 * sizeof(ConnectionRequest));
        if (pool == NULL) {
            printf("Error: Failed to resize connection request pool\n");
            return;
        }
    }

    // Add the new connection request to the pool
    pool[pool_size].client_id = client_id;
    pool[pool_size].timestamp = timestamp;
    pool[pool_size].is_active = true;
    pool_size++;

    // Unlock the pool mutex
    pthread_mutex_unlock(&pool_lock);
}

// Function to remove a connection request from the pool
void remove_connection_request(int client_id) {
    // Lock the pool mutex to prevent concurrent access
    pthread_mutex_lock(&pool_lock);

    // Find the index of the connection request to be removed
    size_t i;
    for (i = 0; i < pool_size; i++) {
        if (pool[i].client_id == client_id) {
            break;
        }
    }

    // Check if the connection request was found
    if (i == pool_size) {
        printf("Error: Connection request not found\n");
        return;
    }

    // Remove the connection request from the pool
    pool[i].is_active = false;

    // Unlock the pool mutex
    pthread_mutex_unlock(&pool_lock);
}

// Function to process a connection request
void process_connection_request(int client_id) {
    // Lock the pool mutex to prevent concurrent access
    pthread_mutex_lock(&pool_lock);

    // Find the index of the connection request to be processed
    size_t i;
    for (i = 0; i < pool_size; i++) {
        if (pool[i].client_id == client_id) {
            break;
        }
    }

    // Check if the connection request was found
    if (i == pool_size) {
        printf("Error: Connection request not found\n");
        return;
    }

    // Process the connection request
    // ...

    // Unlock the pool mutex
    pthread_mutex_unlock(&pool_lock);
}

// Function to handle incoming connection requests
void handle_connection_requests() {
    // Lock the pool mutex to prevent concurrent access
    pthread_mutex_lock(&pool_lock);

    // Check if there are any active connection requests in the pool
    size_t i;
    for (i = 0; i < pool_size; i++) {
        if (pool[i].is_active) {
            break;
        }
    }

    // If there are no active connection requests, unlock the pool mutex and return
    if (i == pool_size) {
        pthread_mutex_unlock(&pool_lock);
        return;
    }

    // Process the next active connection request in the pool
    process_connection_request(pool[i].client_id);

    // Remove the processed connection request from the pool
    remove_connection_request(pool[i].client_id);

    // Unlock the pool mutex
    pthread_mutex_unlock(&pool_lock);
}

// Function to handle incoming connection requests with backpressure
void handle_connection_requests_with_backpressure() {
    // Lock the pool mutex to prevent concurrent access
    pthread_mutex_lock(&pool_lock);

    // Check if there are any active connection requests in the pool
    size_t i;
    for (i = 0; i < pool_size; i++) {
        if (pool[i].is_active) {
            break;
        }
    }

    // If there are no active connection requests, unlock the pool mutex and return
    if (i == pool_size) {
        pthread_mutex_unlock(&pool_lock);
        return;
    }

    // Process the next active connection request in the pool
    process_connection_request(pool[i].client_id);

    // Remove the processed connection request from the pool
    remove_connection_request(pool[i].client_id);

    // Check if there are any other active connection requests in the pool
    for (size_t j = i + 1; j < pool_size; j++) {
        if (pool[j].is_active) {
            break;
        }
    }

    // If there are no other active connection requests, unlock the pool mutex and return
    if (j == pool_size) {
        pthread_mutex_unlock(&pool_lock);
        return;
    }

    // Handle excessive incoming requests by blocking until a connection request is processed
    while (pool[j].is_active) {
        pthread_cond_wait(&pool_cond, &pool_lock);
    }

    // Process the next active connection request in the pool
    process_connection_request(pool[j].client_id);

    // Remove the processed connection request from the pool
    remove_connection_request(pool[j].client_id);

    // Unlock the pool mutex
    pthread_mutex_unlock(&pool_lock);
}

// Function to monitor key performance indicators
void monitor_performance() {
    // Lock the pool mutex to prevent concurrent access
    pthread_mutex_lock(&pool_lock);

    // Calculate the average queue length
    size_t total_queue_length = 0;
    for (size_t i = 0; i < pool_size; i++) {
