void create_and_populate_linked_list(int num_structures) {
    // Initialize the linked list
    LINKED_LIST list = {NULL, NULL};

    // Create the structures and populate them with random data
    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        structure->rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        structure->rnti = rand() % 10000;
        structure->crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
