    pthread_mutex_lock(&mutex);

    // Optimize resource management to minimize memory overhead
    NFAPI_CRC_INDICATION_PDU_T *current = list.head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    // Dynamically adjust allocation strategy based on available system resources
    if (list.head == NULL) {
        list.head = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list.tail = list.head;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *new_structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list.tail->next = new_structure;
        list.tail = new_structure;
    }

    pthread_mutex_unlock(&mutex);
}
