    // Initialize the random number generator with a fixed seed value
    srand(seed);

    // Allocate memory for the collection of user sessions
    UserSession* sessions = (UserSession*)malloc(N * sizeof(UserSession));

    // Populate the collection of user sessions
    for (int i = 0; i < N; i++) {
        // Generate a random session ID and authentication token
