        for (int j = 0; j < 5; j++) {
            // Generate a random event ID and type
            int event_id = rand() % 100 + 1;
            char event_type[10];
            sprintf(event_type, "event-%d", event_id);

            // Create a new session event with the generated values
            SessionEvent event;
            event.id = event_id;
            strcpy(event.type, event_type);
            event.timestamp = time(NULL);
            sprintf(event.attributes, "priority=%d", rand() % 10 + 1);

            // Add the new session event to the list of events for the current user session
            events[j] = event;
        }

        // Create a new user session with the generated values and add it to the collection
        UserSession session;
        session.session_id = session_id;
        session.profile = profile;
        strcpy(session.authentication_token, authentication_token);
        session.last_activity_timestamp = time(NULL);
        session.events = events;
        sessions[i] = session;
    }

    // Free the memory allocated for the collection of user sessions
    free(sessions);
}

// Define the function to generate a random string with a given length
char* generate_random_string(int length) {
    char* str = (char*)malloc((length + 1) * sizeof(char));
    for (int i = 0; i < length; i++) {
        int r = rand() % 26 + 97;
        str[i] = (char)r;
    }
    str[length] = '\0';
    return str;
}
