} UE_CONTEXT_INFO_RECORD;

// Define the collection of UE context information records
typedef struct {
    UE_CONTEXT_INFO_RECORD *records;
    int num_records;
    pthread_mutex_t mutex;
} UE_CONTEXT_COLLECTION;

// Initialize the UE context collection with a given number of records
void init_ue_context_collection(UE_CONTEXT_COLLECTION *collection, int num_records) {
    // Allocate memory for the records
    collection->records = (UE_CONTEXT_INFO_RECORD *)malloc(num_records * sizeof(UE_CONTEXT_INFO_RECORD));
    if (!collection->records) {
        printf("Error: Failed to allocate memory for UE context information records\n");
        return;
    }

    // Initialize the number of records and mutex
    collection->num_records = num_records;
    pthread_mutex_init(&collection->mutex, NULL);
}

// Populate the UE context collection with input parameters for the number of records, seed value for random number generation, and priority threshold
void populate_ue_context_collection(UE_CONTEXT_COLLECTION *collection, int num_records, int seed, int priority_threshold) {
    // Lock the mutex to ensure thread safety when accessing and modifying shared resources
    pthread_mutex_lock(&collection->mutex);

    // Generate random UE identifiers for each record
    srand(seed);
    for (int i = 0; i < num_records; i++) {
        collection->records[i].ue_id = rand();
    }

    // Set the serving cell information and mobility status for each record
    for (int i = 0; i < num_records; i++) {
        strcpy(collection->records[i].serving_cell, "Cell XYZ");
        collection->records[i].mobility_status = 1;
    }

    // Set the priority level for each record based on the input priority threshold
    for (int i = 0; i < num_records; i++) {
        if (collection->records[i].priority_level >= priority_threshold) {
            collection->records[i].validity_flag = true;
        } else {
            collection->records[i].validity_flag = false;
        }
    }

    // Update the last update time for each record
    for (int i = 0; i < num_records; i++) {
        collection->records[i].last_update_time = time(NULL);
    }

    // Unlock the mutex to release shared resources
    pthread_mutex_unlock(&collection->mutex);
}

// Free the memory allocated for the UE context information records
void free_ue_context_collection(UE_CONTEXT_COLLECTION *collection) {
    // Lock the mutex to ensure thread safety when accessing and modifying shared resources
    pthread_mutex_lock(&collection->mutex);

    // Free the memory allocated for the records
    free(collection->records);

    // Reset the number of records and mutex
    collection->num_records = 0;
    pthread_mutex_destroy(&collection->mutex);

    // Unlock the mutex to release shared resources
    pthread_mutex_unlock(&collection->mutex);
}
