    char *network_type; // Type of network (e.g., Wi-Fi, cellular)
    bool connected; // Connection status (true if connected, false otherwise)
    int quality_score; // Quality score for the connection (0-100)
    uint32_t flags; // Flags indicating current state of the connection
    time_t last_update; // Timestamp representing the last update time of the connection
} DEVICE_CONN_RECORD;

// Define a collection of network device connection records
typedef struct {
    DEVICE_CONN_RECORD *records; // Array of DEVICE_CONN_RECORD structures
    size_t num_records; // Number of records in the collection
} DEVICE_CONN_COLLECTION;

// Define a callback function for updating the quality threshold dynamically
typedef int (*QUALITY_THRESHOLD_UPDATE_CB)(int);

// Function to populate a collection of network device connection records
void populate_device_conn_collection(DEVICE_CONN_COLLECTION *collection, size_t N, uint32_t seed, int quality_threshold, bool enable_logging, QUALITY_THRESHOLD_UPDATE_CB update_cb) {
    // Initialize the collection with the given number of records
    collection->num_records = N;
    collection->records = (DEVICE_CONN_RECORD *)malloc(sizeof(DEVICE_CONN_RECORD) * N);
    if (!collection->records) {
        // Handle memory allocation failure
        printf("Error: Failed to allocate memory for device connection records\n");
        return;
    }

    // Initialize the records with random values and set the quality threshold
    srand(seed);
    for (size_t i = 0; i < N; ++i) {
        collection->records[i].id = rand();
        collection->records[i].network_type = "Wi-Fi"; // TODO: Replace with actual network type
        collection->records[i].connected = (rand() % 2 == 0);
        collection->records[i].quality_score = rand() % 100;
        collection->records[i].flags = 0;
        collection->records[i].last_update = time(NULL);
    }

    // Update the quality threshold dynamically using the provided callback function
    if (update_cb) {
        int new_threshold = update_cb(quality_threshold);
        if (new_threshold >= 0) {
            quality_threshold = new_threshold;
        }
    }

    // Filter the records based on the quality threshold and logging configuration
    size_t filtered_count = 0;
    for (size_t i = 0; i < N; ++i) {
        if (collection->records[i].quality_score >= quality_threshold) {
            collection->records[filtered_count++] = collection->records[i];
        } else if (enable_logging) {
            // Log the record as filtered out due to low quality score
            printf("Filtered out device connection with ID %u and quality score %d\n", collection->records[i].id, collection->records[i].quality_score);
        }
    }

    // Update the number of records in the filtered collection
    collection->num_records = filtered_count;
}

// Function to free the memory allocated for a collection of network device connection records
void free_device_conn_collection(DEVICE_CONN_COLLECTION *collection) {
    if (collection && collection->records) {
        free(collection->records);
    }
}
