#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>

// Define the structure for UE context information records
typedef struct {
    long ue_id; // Unique UE identifier
    int serving_cell; // Serving cell information
    bool mobility_status; // Mobility status of the UE
    time_t last_update_time; // Timestamp representing the last update time
} UE_CONTEXT_INFO_RECORD;

// Define the structure for the hash table
typedef struct {
    int size; // Size of the hash table
    int capacity; // Capacity of the hash table
    int load_factor; // Load factor of the hash table
    UE_CONTEXT_INFO_RECORD **records; // Array of records in the hash table
} HASH_TABLE;

// Define the structure for the logging mechanism
typedef struct {
    FILE *log_file; // File pointer for the log file
    int log_level; // Log level (e.g., error, warning, info)
} LOGGING;

// Define the function to populate the UE context information records
void populate_ue_context(int M, int seed, HASH_TABLE *hash_table, LOGGING *logging) {
    // Initialize the hash table with a default size and capacity
    hash_table->size = 10;
    hash_table->capacity = 20;
    hash_table->load_factor = 0.75;
    hash_table->records = (UE_CONTEXT_INFO_RECORD **)malloc(sizeof(UE_CONTEXT_INFO_RECORD *) * hash_table->capacity);

    // Initialize the logging mechanism with a default log level and file name
    logging->log_level = 1;
    logging->log_file = fopen("ue_context.log", "w");

    // Populate the UE context information records based on input parameters
    for (int i = 0; i < M; i++) {
        // Generate a random UE identifier and serving cell information
        long ue_id = rand() % seed + 1;
        int serving_cell = rand() % seed + 1;

        // Create a new record in the hash table
        UE_CONTEXT_INFO_RECORD *record = (UE_CONTEXT_INFO_RECORD *)malloc(sizeof(UE_CONTEXT_INFO_RECORD));
        record->ue_id = ue_id;
        record->serving_cell = serving_cell;
        record->mobility_status = false;
        record->last_update_time = time(NULL);

        // Insert the new record into the hash table
        int index = (ue_id % hash_table->capacity) + 1;
        if (hash_table->records[index] != NULL) {
            // Collision resolution through chaining
            UE_CONTEXT_INFO_RECORD *temp = hash_table->records[index];
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = record;
        } else {
            // Insert the new record into the hash table
            hash_table->records[index] = record;
        }
    }
}

// Define the function to find and print the largest integer along with its corresponding string
void find_largest_integer(HASH_TABLE *hash_table, LOGGING *logging) {
    // Initialize the largest integer and its corresponding string
    long largest_ue_id = 0;
    char *largest_string = NULL;

    // Iterate through the hash table records
    for (int i = 1; i <= hash_table->capacity; i++) {
        UE_CONTEXT_INFO_RECORD *record = hash_table->records[i];
        while (record != NULL) {
            // Check if the current record has a larger UE identifier than the previous largest one
            if (record->ue_id > largest_ue_id) {
                largest_ue_id = record->ue_id;
                largest_string = record->serving_cell;
            }
            record = record->next;
        }
    }

    // Print the largest integer along with its corresponding string
    printf("Largest UE identifier: %ld\n", largest_ue_id);
    printf("Corresponding serving cell: %s\n", largest_string);
}

// Define the function to insert a new UE context record into the hash table
void insert_ue_context(long ue_id, int serving_cell, HASH_TABLE *hash_table, LOGGING *logging) {
    // Check if the hash table needs to be resized
    if (hash_table->size == hash_table->capacity) {
        resize_hash_table(hash_table);
    }

    // Create a new record in the hash table
    UE_CONTEXT_INFO_RECORD *record = (UE_CONTEXT_INFO_RECORD *)malloc(sizeof(UE_CONTEXT_INFO_RECORD));
    record->ue_id = ue_id;
    record->serving_cell = serving_cell;
    record->mobility_status = false;
    record->last_update_time = time(NULL);

    // Insert the new record into the hash table
    int index = (ue_id % hash_table->capacity) + 1;
    if (hash_table->records[index] != NULL) {
        // Collision resolution through chaining
        UE_CONTEXT_INFO_RECORD *temp = hash_table->records[index];
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = record;
    } else {
        // Insert the new record into the hash table
        hash_table->records[index] = record;
    }
}

// Define the function to delete a UE context record from the hash table
void delete_ue_context(long ue_id, HASH_TABLE *hash_table, LOGGING *logging) {
    // Check if the hash table needs to be resized
    if (hash_table->size == hash_table->capacity / 2) {
        resize_hash_table(hash_table);
    }

    // Find the record in the hash table
    int index = (ue_id % hash_table->capacity) + 1;
    UE_CONTEXT_INFO_RECORD *record = hash_table->records[index];
    while (record != NULL && record->ue_id != ue_id) {
        record = record->next;
    }

    // Check if the record was found in the hash table
    if (record == NULL) {
        logging->log_level = 2;
        fprintf(logging->log_file, "UE context record with UE identifier %ld not found\n", ue_id);
        return;
    }

    // Delete the record from the hash table
    if (record == hash_table->records[index]) {
        hash_table->records[index] = record->next;
    } else {
        UE_CONTEXT_INFO_RECORD *temp = hash_table->records[index];
        while (temp->next != NULL && temp->next->ue_id != ue_id) {
            temp = temp->next;
        }
        if (temp->next == NULL) {
            logging->log_level = 2;
            fprintf(logging->log_file, "UE context record with UE identifier %ld not found\n", ue_id);
            return;
        } else {
            temp->next = temp->next->next;
        }
    }
}

// Define the function to resize the hash table
void resize_hash_table(HASH_TABLE *hash_table) {
    // Create a new hash table with twice the capacity of the current one
    HASH_TABLE *new_hash_table = (HASH_TABLE *)malloc(sizeof(HASH_TABLE));
    new_hash_table->size = 0;
    new_hash_table->capacity = hash_table->capacity * 2;
    new_hash_table->load_factor = 0.75;
    new_hash_table->records = (UE_CONTEXT_INFO_RECORD **)malloc(sizeof(UE_CONTEXT_INFO_RECORD *) * new_hash_table->capacity);

    // Iterate through the records in the current hash table
    for (int i = 1; i <= hash_table->capacity; i++) {
        UE_CONTEXT_INFO_RECORD *record = hash_table->records[i];
        while (record != NULL) {
            // Insert the record into the new hash table
            int index = (record->ue_id % new_hash_table->capacity) + 1;
            if (new_hash_table->records[index] != NULL) {
                // Collision resolution through chaining
                UE_CONTEXT_INFO_RECORD *temp = new_hash_table->records[index];
                while (temp->next != NULL) {
                    temp = temp->next;
                }
                temp->next = record;
            } else {
                // Insert the record into the new hash table
                new_hash_table->records[index] = record;
            }
            record = record->next;
        }
    }

    // Free the memory of the current hash table and assign the new one to it
    free(hash_table->records);
    hash_table->records = new_hash_table->records;
    hash_table->capacity = new_hash_table->capacity;
}

// Define the function to export the UE context records to a persistent storage solution
void export_ue_context(HASH_TABLE *hash_table, LOGGING *logging) {
    // Open a file for writing in append mode
    FILE *file = fopen("ue_context.txt", "a");

    // Iterate through the records in the hash table
    for (int i = 1; i <= hash_table->capacity; i++) {
        UE_CONTEXT_INFO_RECORD *record = hash_table->records[i];
        while (record != NULL) {
            // Write the record to the file
            fprintf(file, "%ld,%d,%s\n", record->ue_id, record->serving_cell, record->mobility_status ? "true" : "false");
            record = record->next;
        }
    }

    // Close the file
    fclose(file);
}
