    uint32_t id; // Unique identifier for the device
    char *network_type; // Type of network (e.g., Wi-Fi, cellular)
    bool connected; // Connection status (true if connected, false otherwise)
    int quality_score; // Quality score for the connection (0-100)
    uint32_t flags; // Flags indicating current state of the connection
    time_t last_update; // Timestamp representing the last update time of the connection
} DEVICE_CONN_RECORD;

// Define the collection of network device connection records
DEVICE_CONN_RECORD *device_conn_records = NULL;
size_t num_devices = 0; // Number of devices in the collection

// Function to populate the collection of network device connection records
void populate_device_conn_records(uint32_t N, uint32_t seed, int quality_threshold, bool enable_logging) {
    // Initialize the collection if necessary
    if (device_conn_records == NULL) {
        device_conn_records = malloc(sizeof(DEVICE_CONN_RECORD) * N);
        num_devices = N;
    }

    // Generate random numbers for the quality scores and flags
    srand(seed);
    int quality_scores[N];
    bool flags[N];
    for (int i = 0; i < N; i++) {
        quality_scores[i] = rand() % 100 + 1; // Generate a random quality score between 1 and 100
        flags[i] = (rand() % 2) ? true : false; // Generate a random flag value (true or false)
    }

    // Populate the collection with the generated quality scores and flags
    for (int i = 0; i < N; i++) {
        device_conn_records[i].id = i + 1;
        device_conn_records[i].network_type = "Wi-Fi"; // Set the network type to Wi-Fi
        device_conn_records[i].connected = true; // Set the connection status to connected
        device_conn_records[i].quality_score = quality_scores[i];
        device_conn_records[i].flags = flags[i] ? 1 : 0;
        device_conn_records[i].last_update = time(NULL); // Set the last update time to the current time
    }

    // Filter out connections with a quality score less than the specified threshold
    for (int i = 0; i < N; i++) {
        if (device_conn_records[i].quality_score < quality_threshold) {
            device_conn_records[i].connected = false; // Set the connection status to disconnected
        }
    }

    // Log any failures during population process
    if (!enable_logging) {
        return;
    }
    for (int i = 0; i < N; i++) {
        if (device_conn_records[i].quality_score < quality_threshold) {
            printf("Connection %d has a quality score of %d, which is less than the specified threshold of %d\n", device_conn_records[i].id, device_conn_records[i].quality_score, quality_threshold);
        }
    }
}

// Function to add a new network device connection record to the collection
void add_device_conn_record(uint32_t id, char *network_type, bool connected, int quality_score, uint32_t flags) {
    // Check if the collection is full
    if (num_devices == 0) {
        return;
    }

    // Find an empty slot in the collection
    for (int i = 0; i < num_devices; i++) {
        if (device_conn_records[i].id == 0) {
            device_conn_records[i].id = id;
            device_conn_records[i].network_type = network_type;
            device_conn_records[i].connected = connected;
            device_conn_records[i].quality_score = quality_score;
            device_conn_records[i].flags = flags;
            device_conn_records[i].last_update = time(NULL);
            break;
        }
    }
}

// Function to remove a network device connection record from the collection
void remove_device_conn_record(uint32_t id) {
    // Check if the collection is empty
    if (num_devices == 0) {
        return;
    }

    // Find the index of the specified device in the collection
    int i = -1;
    for (int j = 0; j < num_devices; j++) {
        if (device_conn_records[j].id == id) {
            i = j;
            break;
        }
    }

    // Check if the device was found in the collection
    if (i == -1) {
        return;
    }

    // Remove the device from the collection by shifting all subsequent devices back one index
    for (int j = i; j < num_devices - 1; j++) {
        device_conn_records[j] = device_conn_records[j + 1];
    }
    num_devices--;
}

