        event->metrics = malloc(sizeof(double) * 10);
        if (!event->metrics) {
            printf("Error: Failed to allocate memory for metrics\n");
            return;
        }
        for (int j = 0; j < 10; j++) {
            event->metrics[j] = rand() % 100;
        }

        // Add the network event to the list
        pthread_mutex_lock(&event_list_lock);
        if (event_list_size >= max_size) {
            // Truncate the oldest events or reallocate the list if necessary
            if (event_list_size > MAX_EVENT_LIST_SIZE * REALLOCATION_THRESHOLD) {
                truncate_events(event_list, event_list_size);
            } else {
                reallocate_events(event_list, event_list_size);
            }
        }
        event_list[event_list_size++] = event;
        pthread_mutex_unlock(&event_list_lock);
    }
}

// Truncate the oldest events in the list
void truncate_events(network_event_t* events, int size) {
    // Calculate the number of events to truncate
    int num_to_truncate = size - MAX_EVENT_LIST_SIZE;

    // Truncate the oldest events
    for (int i = 0; i < num_to_truncate; i++) {
        free(events[i].source_id);
        free(events[i].metrics);
        events[i] = NULL;
    }
}

// Reallocate the list of network events
void reallocate_events(network_event_t* events, int size) {
    // Calculate the new size of the list
    int new_size = size * 2;

    // Allocate memory for the new list
    network_event_t* new_events = malloc(sizeof(network_event_t) * new_size);
    if (!new_events) {
        printf("Error: Failed to allocate memory for new events\n");
        return;
    }

    // Copy the existing events to the new list
    for (int i = 0; i < size; i++) {
        new_events[i] = events[i];
    }

    // Free the old list of events
    free(events);

    // Update the list of network events
    events = new_events;
}

// Calculate the MD5 hash of a file located at `file_path` using the specified `chunk_size` for reading the file in segments
void calculate_md5(char* file_path, int chunk_size) {
    // Open the file for reading
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        printf("Error: Failed to open file %s\n", file_path);
        return;
    }

    // Initialize the MD5 context
    MD5_CTX ctx;
    MD5Init(&ctx);

    // Read the file in segments and update the MD5 hash
    char buffer[chunk_size];
    while (fread(buffer, 1, chunk_size, file) > 0) {
        MD5Update(&ctx, buffer, chunk_size);
    }

    // Close the file
    fclose(file);

    // Calculate the final MD5 hash
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5Final(digest, &ctx);

    // Print the hexdigest of the MD5 hash
    printf("MD5 hash: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", digest[i]);
    }
    printf("\n");
}

// Update the user's password in a database connected via `db_connection`
