// Function to manage a dynamic list of LTE cell information structures
void manage_cells(LTE_CELL_INFO_T **cells, int num_cells) {
    // Validate the input parameters
    if (cells == NULL || num_cells <= 0) {
        return;
    }

    // Allocate memory for the cells in the memory pool
    LTE_CELL_INFO_T *new_cells = malloc(num_cells * sizeof(LTE_CELL_INFO_T));
    if (new_cells == NULL) {
        return;
    }

    // Copy the input cells to the new memory pool
    memcpy(new_cells, cells, num_cells * sizeof(LTE_CELL_INFO_T));

    // Deallocate the old memory pool if necessary
    if (memory_pool != NULL) {
        free(memory_pool);
    }

    // Update the memory pool with the new cells
    memory_pool = new_cells;

    // Recalculate and update the RSRP values for each cell
    for (int i = 0; i < num_cells; i++) {
        LTE_CELL_INFO_T *cell = &memory_pool[i];
        cell->rsrp = calculate_rsrp(cell);
    }
