bool process_file(const char* filename) {
    // Open the file in binary mode
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return false;
    }

    // Calculate the MD5 hash of the file
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);

    // Read the file in chunks to manage memory usage and ensure robustness against incomplete reads or file interruptions
    size_t chunk_size = 1024 * 1024; // 1 MB
    char* buffer = malloc(chunk_size);
    if (buffer == NULL) {
        printf("Error: unable to allocate memory for buffer\n");
        fclose(fp);
        return false;
    }

    size_t bytes_read = 0;
    while ((bytes_read = fread(buffer, 1, chunk_size, fp)) > 0) {
        MD5_Update(&ctx, buffer, bytes_read);
    }

    // Verify that the file was read successfully
    if (ferror(fp)) {
        printf("Error: unable to read from file %s\n", filename);
        fclose(fp);
        free(buffer);
        return false;
    }

    // Close the file
    fclose(fp);

    // Calculate the MD5 hash of the entire file
    MD5_Final(md5_hash, &ctx);

    // Print a progress indicator every 10% of the file's processing
    size_t total_bytes = ftell(fp);
    size_t processed_bytes = 0;
    while (processed_bytes < total_bytes) {
        printf("Processing file %s: %.1f%% complete\n", filename, (float)processed_bytes / total_bytes * 100.0);
        fflush(stdout);
        processed_bytes += chunk_size;
    }

    // Free the buffer
    free(buffer);

    // Return the MD5 hash and a boolean indicating whether the file was processed successfully
    return true;
}
