    NFAPI_CRC_INDICATION_PDU_INFO_T *tail;
} NFAPI_CRC_INDICATION_PDU_LIST_T;

// Define a function to create and populate a list of CRC indication PDUs
NFAPI_CRC_INDICATION_PDU_LIST_T* createAndPopulateCrcIndicationPduList(int numStructures, int seed) {
    // Allocate memory for the linked list
    NFAPI_CRC_INDICATION_PDU_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST_T));
    if (!list) {
        printf("Error: Failed to allocate memory for CRC indication PDU list\n");
        return NULL;
    }

    // Initialize the linked list
    list->head = NULL;
    list->tail = NULL;

    // Loop through each structure and populate it with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < numStructures; i++) {
        // Allocate memory for the current structure
        NFAPI_CRC_INDICATION_PDU_INFO_T *current = malloc(STRUCTURE_SIZE);
        if (!current) {
            printf("Error: Failed to allocate memory for CRC indication PDU %d\n", i + 1);
            return NULL;
        }

        // Set the RX_UE_INFORMATION_TAG and RNTI values randomly based on the seed
        current->pdu.rxUeInformationTag = rand_range(seed, INT_MIN, INT_MAX);
        current->pdu.rnti = rand_range(seed, 0, UINT16_MAX);

        // Set the CRC_INDICATION_REL8_TAG value randomly based on the seed
        current->crcFlag = (rand_range(seed, 0, 1) == 0) ? false : true;

        // Add the current structure to the linked list
        if (!list->head) {
            list->head = current;
            list->tail = current;
        } else {
            list->tail->next = current;
            list->tail = current;
        }
    }

    return list;
}

// Define a function to handle dynamic resizing of the linked list
void resizeCrcIndicationPduList(NFAPI_CRC_INDICATION_PDU_LIST_T *list, int numStructures) {
    // Check if the number of structures exceeds the maximum limit
    if (numStructures > MAX_STRUCTURES) {
        printf("Error: Number of CRC indication PDUs exceeds maximum limit\n");
        return;
    }

    // Loop through each structure and validate that the RX_UE_INFORMATION_TAG and RNTI values are within acceptable ranges
    for (int i = 0; i < numStructures; i++) {
        NFAPI_CRC_INDICATION_PDU_INFO_T *current = list->head;
        while (current) {
            if (!isValidRxUeInformationTag(current->pdu.rxUeInformationTag)) {
                printf("Error: Invalid RX_UE_INFORMATION_TAG value %d\n", current->pdu.rxUeInformationTag);
                return;
            } else if (!isValidRnti(current->pdu.rnti)) {
                printf("Error: Invalid RNTI value %u\n", current->pdu.rnti);
                return;
            }
            current = current->next;
        }
    }

    // Resize the linked list to match the number of structures
    NFAPI_CRC_INDICATION_PDU_INFO_T *current = list->head;
    while (current) {
        if (i == numStructures) {
