        stats[i].destination_account_id = rand() % 1000;
        stats[i].transaction_amount = records[i].transaction_amount;
        stats[i].priority_level = rand() % 100;
    }

    // Find the largest transaction amount and its corresponding activity type
    double largest_transaction_amount = -1.0;
    char* largest_activity_type = NULL;
    for (int i = 0; i < N; ++i) {
        if (stats[i].transaction_amount > largest_transaction_amount) {
            largest_transaction_amount = stats[i].transaction_amount;
            largest_activity_type = records[i].activity_type;
        }
    }

    // Print the largest transaction amount and its corresponding activity type
    printf("Largest transaction amount: %f\n", largest_transaction_amount);
