        printf("Error: Failed to allocate memory for the metric pool\n");
        free(cell_info_pool);
        return;
    }

    // Initialize the cell information structures and metrics structures
    for (int i = 0; i < num_cells; i++) {
        cell_info[i].CELL_ID = -1;
        cell_info[i].PCI = -1;
