                continue;
            }
            cell_info[i].RSRP = rsrp;
        }
    }

    // Periodically revalidate the cell information due to potential changes in network settings or configuration
    for (int i = 0; i < num_cells; i++) {
        if (cell_info[i].CELL_ID != -1 && cell_info[i].PCI != -1) {
