    for (int i = 0; i < num_cells; i++) {
        if (cell_info[i].CELL_ID != -1 && cell_info[i].PCI != -1) {
            // Handle high-throughput scenarios by using a memory pool for the cell information structures and metrics structures
            LTE_CELL_INFO_T* cell_info_pool = (LTE_CELL_INFO_T*)malloc(sizeof(LTE_CELL_INFO_T) * num_cells);
