        fprintf(output_file_ptr, "%d,%d,%f,%d,%s\n", record->product_id, record->stock_quantity, record->price, record->supplier_id, record->geographical_origin);
        fprintf(output_file_ptr, "%d,%d,%f,%d\n", statistics->product_id, statistics->total_sales_volume, statistics->average_price, statistics->priority_level);
