void init_nfapi_crc_indication_pdus(nfapi_crc_indication_pdu_t **pdus, size_t num_pdus) {
    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    *pdus = (nfapi_crc_indication_pdu_t *)malloc(num_pdus * sizeof(nfapi_crc_indication_pdu_t));

    // Initialize each structure in the array with default values
    for (size_t i = 0; i < num_pdus; i++) {
        (*pdus)[i].rx_ue_information_tag = 0;
        (*pdus)[i].rnti = 0;
        (*pdus)[i].crc_indication_rel8_tag = 0;
        (*pdus)[i].crcflag = 0;
    }
}

// Define a function to populate an NFAPI_CRC_INDICATION_PDU_T structure with data from an external data source
void populate_nfapi_crc_indication_pdu(nfapi_crc_indication_pdu_t *pdu, uint16_t rx_ue_information_tag, uint16_t rnti) {
    // Set the RX_UE_INFORMATION_TAG and RNTI values in the structure
    pdu->rx_ue_information_tag = rx_ue_information_tag;
    pdu->rnti = rnti;

    // Calculate the CRC flag based on a configurable threshold value
    uint8_t crcflag = 0;
    if (crcflag_threshold > 0) {
        crcflag = 1;
