    // Set the CRC_INDICATION_REL8_TAG and CRCFLAG values in the structure
    pdu->crc_indication_rel8_tag = 0;
    pdu->crcflag = crcflag;
}

// Define a function to handle concurrent access to the NFAPI_CRC_INDICATION_PDU_T structures from multiple threads
void handle_concurrent_access(nfapi_crc_indication_pdu_t **pdus, size_t num_pdus) {
    // Use a mutex to synchronize access to the array of NFAPI_CRC_INDICATION_PDU_T structures
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Populate each structure in the array with data from an external data source
    for (size_t i = 0; i < num_pdus; i++) {
