            }
        }

        // Update the set of metrics and return the maximum weighted sum and the corresponding transaction ID
        int max_weighted_sum = 0;
        int max_transaction_id = -1;
        for (int i = 0; i < num_filtered_transactions; i++) {
            // Calculate the weighted sum of the metrics for each filtered transaction
            int weighted_sum = 0;
            for (int j = 0; j < M; j++) {
                weighted_sum += cell_info[i].metrics[j].value * cell_info[i].metrics[j].quality_level;
            }
            // Update the maximum weighted sum and corresponding transaction ID if necessary
            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
                max_transaction_id = i;
            }
        }

        return max_weighted_sum, max_transaction_id;
    }
}
