void init_cache(cache_t *cache, size_t capacity) {
    cache->entries = (cache_entry_t *)malloc(sizeof(cache_entry_t) * capacity);
    cache->capacity = capacity;
    cache->count = 0;
}

// Add a new session to the cache
void add_session(cache_t *cache, const char *sid) {
    // Check if the cache is full
    if (cache->count == cache->capacity) {
        // Remove the oldest session if necessary
        if (cache->entries[0].state != DISCONNECTED) {
            remove_session(cache, cache->entries[0].sid);
        }
    }

    // Add the new session to the end of the array
    cache->entries[cache->count].sid = sid;
    cache->entries[cache->count].start_time = time(NULL);
    cache->entries[cache->count].last_activity = cache->entries[cache->count].start_time;
    cache->entries[cache->count].state = CONNECTED;
    cache->count++;
}

// Update the last activity timestamp for a session
void update_session(cache_t *cache, const char *sid) {
    // Find the index of the session in the array
    size_t i;
    for (i = 0; i < cache->count; i++) {
        if (strcmp(cache->entries[i].sid, sid) == 0) {
            break;
        }
    }

    // Update the last activity timestamp
    cache->entries[i].last_activity = time(NULL);
}

// Remove an expired session from the cache
void remove_session(cache_t *cache, const char *sid) {
    // Find the index of the session in the array
    size_t i;
    for (i = 0; i < cache->count; i++) {
        if (strcmp(cache->entries[i].sid, sid) == 0) {
            break;
        }
    }

    // Remove the session from the array
    memmove(&cache->entries[i], &cache->entries[i + 1], sizeof(cache_entry_t) * (cache->count - i));
    cache->count--;
}

// Check if a session is expired based on the idle timeout threshold
int is_expired(cache_t *cache, const char *sid) {
    // Find the index of the session in the array
    size_t i;
    for (i = 0; i < cache->count; i++) {
        if (strcmp(cache->entries[i].sid, sid) == 0) {
            break;
        }
    }

    // Check if the session is expired based on the idle timeout threshold
    return time(NULL) - cache->entries[i].last_activity > IDLE_TIMEOUT;
}

// Remove all expired sessions from the cache
void remove_expired_sessions(cache_t *cache) {
    // Iterate over the array and remove any expired sessions
    size_t i = 0;
    while (i < cache->count) {
        if (is_expired(cache, cache->entries[i].sid)) {
            remove_session(cache, cache->entries[i].sid);
        } else {
            i++;
        }
    }
}

