    for (int i = 0; i < num_products; i++) {
        PRODUCT_DESCRIPTION *product = &(products[i]);

        // Compute length of product description
        int length = strlen(product->description);

        // Increment histogram counter for product description length
        DESCRIPTION_HISTOGRAM *histogram = (DESCRIPTION_HISTOGRAM *)malloc(100 * sizeof(DESCRIPTION_HISTOGRAM));
        histogram[length].count++;

        // Check if product description length is already in the histogram
        bool found = false;
        for (int j = 0; j < 100; j++) {
            if (histogram[j].length == length) {
