// Define data structures for managing memory usage and serialization
typedef struct {
    void* memoryBlock;
    size_t memorySize;
} MEMORY_BLOCK;

typedef struct {
    MEMORY_BLOCK* memoryBlocks;
    int numMemoryBlocks;
} MEMORY_MANAGER;

// Define data structures for tracking histograms and detecting duplicate client descriptions
typedef struct {
    int* histogram;
    int numClients;
