    // Initialize random number generator with seed value
    srand(seed);

    // Allocate memory for network element configurations
    NetworkElementConfig* configs = (NetworkElementConfig*)malloc(N * sizeof(NetworkElementConfig));
    if (!configs) {
        printf("Error: Failed to allocate memory for network element configurations\n");
        return;
    }

    // Populate network element configurations with random values
    for (int i = 0; i < N; i++) {
