    for (int i = 0; i < N; i++) {
        packets[i].source_ip_address = generateRandomIPAddress();
        packets[i].source_port_number = rand() % 65536;
        packets[i].destination_ip_address = generateRandomIPAddress();
        packets[i].destination_port_number = rand() % 65536;
        packets[i].protocol_type = generateRandomProtocolType();
        packets[i].payload_checksum = calculatePayloadChecksum(packets[i].source_ip_address, packets[i].source_port_number, packets[i].destination_ip_address, packets[i].destination_port_number);
    }

    // Print network packet structures
    for (int i = 0; i < N; i++) {
        printf("Network packet %d:\n", i + 1);
        printf("\tSource IP address: %s\n", packets[i].source_ip_address);
        printf("\tSource port number: %d\n", packets[i].source_port_number);
        printf("\tDestination IP address: %s\n", packets[i].destination_ip_address);
        printf("\tDestination port number: %d\n", packets[i].destination_port_number);
        printf("\tProtocol type: %s\n", packets[i].protocol_type);
        printf("\tPayload checksum: %lu\n", packets[i].payload_checksum);
    }

    // Deallocate memory for network element configurations and network packet structures
    free(configs);
    free(packets);
}

