} NetworkElementConfig;

// Define a dynamic array to store the network element configurations
NetworkElementConfig* configs = NULL;
int num_configs = 0;

// Function to populate the network element configurations based on input parameters
void populateConfigurations(int N, int seed) {
    // Initialize the random number generator with a seed value
    srand(seed);

    // Allocate memory for the dynamic array of network element configurations
    configs = (NetworkElementConfig*)malloc(N * sizeof(NetworkElementConfig));
    if (!configs) {
        printf("Error: Failed to allocate memory for network element configurations\n");
        return;
    }

