    for (int i = 0; i < N; i++) {
        configs[i].id = rand() % 10000;
        sprintf(configs[i].ip, "192.168.%d.%d", rand() % 256, rand() % 256);
        configs[i].port = rand() % 65536;
        configs[i].connected = (rand() % 2) ? true : false;
    }

    // Print the largest integer and its corresponding string
    int max_id = -1;
    char* max_string = NULL;
    for (int i = 0; i < N; i++) {
        if (configs[i].id > max_id) {
            max_id = configs[i].id;
            max_string = configs[i].ip;
        }
    }
    printf("Largest integer: %d\n", max_id);
    printf("Corresponding string: %s\n", max_string);

    // Initialize and manage the 'long', 'int', and 'char' arrays and their respective records
    long* long_array = (long*)malloc(N * sizeof(long));
    int* int_array = (int*)malloc(N * sizeof(int));
    char* char_array = (char*)malloc(N * 16);
    if (!long_array || !int_array || !char_array) {
        printf("Error: Failed to allocate memory for arrays\n");
        return;
    }
    for (int i = 0; i < N; i++) {
        long_array[i] = configs[i].id;
        int_array[i] = configs[i].port;
        strcpy(char_array + i * 16, configs[i].ip);
    }
    free(configs);
}

// Function to find and print the largest integer along with its corresponding string
void findLargestInteger() {
    int max_id = -1;
    char* max_string = NULL;
    for (int i = 0; i < num_configs; i++) {
        if (configs[i].id > max_id) {
            max_id = configs[i].id;
            max_string = configs[i].ip;
        }
    }
    printf("Largest integer: %d\n", max_id);
    printf("Corresponding string: %s\n", max_string);
}

// Function to initialize and manage the 'long', 'int', and 'char' arrays and their respective records
void initArrays() {
    long* long_array = (long*)malloc(num_configs * sizeof(long));
    int* int_array = (int*)malloc(num_configs * sizeof(int));
    char* char_array = (char*)malloc(num_configs * 16);
    if (!long_array || !int_array || !char_array) {
        printf("Error: Failed to allocate memory for arrays\n");
        return;
    }
    for (int i = 0; i < num_configs; i++) {
        long_array[i] = configs[i].id;
        int_array[i] = configs[i].port;
        strcpy(char_array + i * 16, configs[i].ip);
    }
}

// Function to manage the memory allocation and deallocation of the 'long', 'int', and 'char' arrays and their respective records
void manageMemory() {
    free(configs);
    free(long_array);
    free(int_array);
    free(char_array);
}
