// Define the structure for network configurations
typedef struct {
    int id;
    char *ip_address;
    int port;
    bool connected;
} NetworkConfig;

// Define a collection of network configurations
static NetworkConfig *configs = NULL;

// Define a mutex to protect the configuration collection from concurrent updates
static pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

// Define a function to validate a network configuration
bool validate_config(NetworkConfig *config) {
    // Check if the IP address is valid
    if (!inet_pton(AF_INET, config->ip_address, NULL)) {
        printf("Invalid IP address: %s\n", config->ip_address);
        return false;
    }

    // Check if the port number is non-negative
    if (config->port < 0) {
        printf("Invalid port number: %d\n", config->port);
        return false;
    }

    // Check if the connection status is valid
    if (config->connected != true && config->connected != false) {
        printf("Invalid connection status: %s\n", config->connected ? "true" : "false");
        return false;
    }

    return true;
}

// Define a function to populate the configuration collection from an external JSON file
void populate_configs(const char *filepath) {
    // Open the JSON file and check if it exists
    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        printf("Failed to open JSON file: %s\n", strerror(errno));
        return;
    }

    // Parse the JSON data and check for errors
    json_object *root = json_loadf(fp, 0, &error);
    if (root == NULL) {
        printf("Failed to parse JSON file: %s\n", error.text);
        fclose(fp);
        return;
    }

    // Iterate over the JSON data and populate the configuration collection
    json_object_foreach(root, key, value) {
        NetworkConfig *config = malloc(sizeof(NetworkConfig));
        config->id = atoi(key);
        config->ip_address = strdup(json_string_value(json_object_get(value, "ip_address")));
        config->port = atoi(json_string_value(json_object_get(value, "port")));
        config->connected = json_boolean_value(json_object_get(value, "connected"));

        // Validate the configuration and add it to the collection if valid
        if (validate_config(config)) {
            pthread_mutex_lock(&config_lock);
            configs = realloc(configs, sizeof(NetworkConfig) * (num_configs + 1));
            configs[num_configs++] = config;
            pthread_mutex_unlock(&config_lock);
        } else {
            free(config);
        }
    }

    // Close the JSON file and release resources
    fclose(fp);
    json_object_put(root);
}

// Define a function to add a new network configuration to the collection
void add_config(NetworkConfig *config) {
    pthread_mutex_lock(&config_lock);
    configs = realloc(configs, sizeof(NetworkConfig) * (num_configs + 1));
    configs[num_configs++] = config;
    pthread_mutex_unlock(&config_lock);
}

// Define a function to remove a network configuration from the collection
void remove_config(int id) {
    pthread_mutex_lock(&config_lock);
    for (int i = 0; i < num_configs; i++) {
        if (configs[i]->id == id) {
            free(configs[i]);
            configs[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&config_lock);
}

// Define a function to update the connection status of a network configuration
void update_connection_status(int id, bool connected) {
    pthread_mutex_lock(&config_lock);
    for (int i = 0; i < num_configs; i++) {
        if (configs[i]->id == id) {
            configs[i]->connected = connected;
            break;
        }
    }
    pthread_mutex_unlock(&config_lock);
}

// Define a function to retrieve the network configuration with the given ID
NetworkConfig *get_config(int id) {
    NetworkConfig *config = NULL;
    pthread_mutex_lock(&config_lock);
    for (int i = 0; i < num_configs; i++) {
        if (configs[i]->id == id) {
            config = configs[i];
            break;
        }
    }
    pthread_mutex_unlock(&config_lock);
    return config;
}

// Define a function to retrieve all network configurations
NetworkConfig **get_all_configs() {
    NetworkConfig **configs = malloc(sizeof(NetworkConfig *) * num_configs);
    pthread_mutex_lock(&config_lock);
    for (int i = 0; i < num_configs; i++) {
        configs[i] = configs[i];
    }
    pthread_mutex_unlock(&config_lock);
    return configs;
}

// Define a function to release the memory allocated for the configuration collection
void free_configs() {
    pthread_mutex_lock(&config_lock);
    for (int i = 0; i < num_configs; i++) {
        if (configs[i] != NULL) {
            free(configs[i]);
        }
    }
    free(configs);
    pthread_mutex_unlock(&config_lock);
}
