    pthread_mutex_unlock(&mempool_mutex);
    printf("Error: Failed to allocate memory for CRC indication PDUs\n");
    return NULL;
  }

  // Update the memory pool statistics
  mempool->used += num_elements;
  if (mempool->peak < mempool->used) {
    mempool->peak = mempool->used;
  }

