// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(size_t n) {
    // Check if the number of structures exceeds available memory
    if (n > SIZE_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Error: Number of structures exceeds available memory\n");
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for CRC indication PDU\n");
        return NULL;
    }

    // Initialize the structures with unique values
    for (size_t i = 0; i < n; i++) {
        pdu[i].RX_UE_INFORMATION_TAG = i + 1;
        pdu[i].RNTI = rand() % 65536;
        pdu[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    // Verify the integrity of the allocated memory before returning
    for (size_t i = 0; i < n; i++) {
        if (pdu[i].RX_UE_INFORMATION_TAG != i + 1 || pdu[i].RNTI == 0 || pdu[i].CRC_INDICATION_REL8_TAG == 0) {
            fprintf(stderr, "Error: Memory integrity check failed\n");
            free(pdu);
            return NULL;
        }
    }

    // Ensure that all operations are thread-safe when used in a multi-threaded environment
    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T* result = pdu;
    pthread_mutex_unlock(&mutex);

    return result;
}
