// Define the maximum number of socket handles that can be allocated
#define MAX_SOCKETS 1024

// Define the minimum and maximum values for the SOCKET_ID, REMOTE_IP_ADDRESS, and LOCAL_PORT_NUMBER
#define MIN_SOCKET_ID 0
#define MAX_SOCKET_ID 65535
#define MIN_REMOTE_IP_ADDRESS "192.168.1.1"
#define MAX_REMOTE_IP_ADDRESS "255.255.255.255"
#define MIN_LOCAL_PORT_NUMBER 1024
#define MAX_LOCAL_PORT_NUMBER 65535

// Define the structure to hold information about each socket handle
typedef struct {
    uint16_t socket_id;
    char remote_ip_address[16];
    uint16_t local_port_number;
} SocketHandle;

// Define an array to store all the allocated socket handles
SocketHandle socket_handles[MAX_SOCKETS];

// Define a function to allocate a new socket handle and return its index
int allocate_socket_handle(uint16_t *socket_id, char *remote_ip_address, uint16_t local_port_number) {
    // Check if there is space for a new socket handle in the array
    if (num_allocated_sockets >= MAX_SOCKETS) {
        return -1;
    }

    // Allocate a new socket handle and initialize its fields
    int index = num_allocated_sockets++;
    socket_handles[index].socket_id = *socket_id;
    strcpy(socket_handles[index].remote_ip_address, remote_ip_address);
    socket_handles[index].local_port_number = local_port_number;

    // Create a new socket and bind it to the specified address and port number
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    inet_pton(AF_INET, remote_ip_address, &addr.sin_addr);
    addr.sin_port = htons(local_port_number);
    if (bind(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        return -1;
    }

    // Return the index of the newly allocated socket handle
    return index;
}

// Define a function to deallocate a socket handle and release its resources
void deallocate_socket_handle(int index) {
    // Check if the specified index is valid
    if (index < 0 || index >= num_allocated_sockets) {
        return;
    }

    // Close the socket and free its resources
    close(socket_handles[index].sock);
    memset(&socket_handles[index], 0, sizeof(SocketHandle));
}

