    *phy_test_config = malloc(num_cells * sizeof(LTE_PHY_TEST_CONFIG_PDU_T));
    if (*phy_test_config == NULL) {
        // Handle memory allocation failure
        return;
    }

    // Initialize the structures with default values
    for (int i = 0; i < num_cells; i++) {
        (*phy_test_config)[i].physical_layer_configuration_tag = 1;
        (*phy_test_config)[i].channel_bandwidth = 20;
        (*phy_test_config)[i].subcarrier_spacing = 15;
        (*phy_test_config)[i].tx_power_level = 1.0f; // Initialized to a default value but can be dynamically adjusted based on real-time environmental factors
    }
}
```
