#include <stdio.h>

// Define the maximum length of the password in bytes
#define MAX_PASSWORD_LEN 32

// Define the minimum and maximum lengths of the IV in bytes
#define MIN_IV_LEN 16
#define MAX_IV_LEN 32

// Define the number of iterations for key derivation
#define KEY_DERIVATION_ITERATIONS 10000

// Define the length of the SHA-256 hash in bytes
#define HASH_LENGTH 32

// Define the length of the derived key in bytes
#define DERIVED_KEY_LEN 32

// Define the length of the initialization vector in bytes
#define IV_LEN 16

// Define the maximum length of the password in characters
#define MAX_PASSWORD_CHARS 64

// Define the maximum length of the initialization vector in characters
#define MAX_IV_CHARS 32

// Define the character set for generating the IV
#define IV_CHARSET "0123456789abcdef"

// Define the function to generate a random initialization vector
void generate_iv(unsigned char *iv, size_t iv_len) {
  // Generate a random initialization vector of the specified length
  for (size_t i = 0; i < iv_len; ++i) {
    iv[i] = IV_CHARSET[rand() % strlen(IV_CHARSET)];
  }
}

// Define the function to derive a key from a password
void derive_key(const unsigned char *password, size_t password_len, unsigned char *derived_key) {
  // Derive a 32-byte key from the first N bytes of the SHA-256 hash of the password
  SHA256_CTX ctx;
  SHA256_Init(&ctx);
  SHA256_Update(&ctx, password, password_len);
  SHA256_Final(derived_key, &ctx);
}

// Define the function to initialize an AES-256-CBC cipher using a given password and IV
void init_cipher(const unsigned char *password, size_t password_len, const unsigned char *iv, size_t iv_len) {
  // Check if the password is empty
  if (password_len == 0) {
    printf("Error: Password cannot be empty\n");
    return;
  }

  // Check if the IV length is valid
  if (iv_len < MIN_IV_LEN || iv_len > MAX_IV_LEN) {
    printf("Error: Invalid IV length\n");
    return;
  }

  // Derive a 32-byte key from the first N bytes of the SHA-256 hash of the password
  unsigned char derived_key[DERIVED_KEY_LEN];
  derive_key(password, password_len, derived_key);

  // Initialize an AES-256-CBC cipher using the derived key and IV
  EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
  EVP_EncryptInit(ctx, EVP_aes_256_cbc(), derived_key, iv);
}

// Define the function to clean up an AES-256-CBC cipher
void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
  // Disable the cipher and release any allocated resources
  EVP_CIPHER_CTX_free(ctx);
}

// Define the function to encrypt data using an AES-256-CBC cipher
void encrypt(const unsigned char *data, size_t data_len, const unsigned char *password, size_t password_len, const unsigned char *iv, size_t iv_len) {
  // Initialize the cipher using the given password and IV
  init_cipher(password, password_len, iv, iv_len);

  // Encrypt the data using the initialized cipher
  EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
  EVP_EncryptInit(ctx, EVP_aes_256_cbc(), derived_key, iv);
  EVP_EncryptUpdate(ctx, NULL, &data_len, data, data_len);

  // Clean up the cipher and release any allocated resources
  cleanup_cipher(ctx);
}

// Define the function to decrypt data using an AES-256-CBC cipher
void decrypt(const unsigned char *data, size_t data_len, const unsigned char *password, size_t password_len, const unsigned char *iv, size_t iv_len) {
  // Initialize the cipher using the given password and IV
  init_cipher(password, password_len, iv, iv_len);

  // Decrypt the data using the initialized cipher
  EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
  EVP_DecryptInit(ctx, EVP_aes_256_cbc(), derived_key, iv);
  EVP_DecryptUpdate(ctx, NULL, &data_len, data, data_len);

  // Clean up the cipher and release any allocated resources
  cleanup_cipher(ctx);
}
