// Define the structure for storing node information
typedef struct {
    int node_id;
    char* fqdn;
    double latency;
} NODE_INFO_T;

// Define a memory pool for allocating and deallocating nodes
static void* node_pool = NULL;
static size_t node_pool_size = 0;

// Function to manage the dynamic list of nodes
void manage_nodes(NODE_INFO_T** nodes, int num_nodes) {
    // Validate the input parameters
    if (nodes == NULL || num_nodes <= 0) {
        return;
    }

    // Allocate memory for the node pool if necessary
    if (node_pool == NULL) {
        node_pool = malloc(sizeof(NODE_INFO_T) * num_nodes);
        node_pool_size = num_nodes;
    } else if (num_nodes > node_pool_size) {
        // Reallocate the memory pool to accommodate more nodes
        void* new_pool = realloc(node_pool, sizeof(NODE_INFO_T) * num_nodes);
        if (new_pool == NULL) {
            return;
        }
        node_pool = new_pool;
        node_pool_size = num_nodes;
    }

    // Initialize the nodes in the pool
    for (int i = 0; i < num_nodes; i++) {
        NODE_INFO_T* node = &((NODE_INFO_T*)node_pool)[i];
        node->node_id = -1;
        node->fqdn = NULL;
        node->latency = 0.0;
    }

    // Update the nodes in the pool with the latest information
    for (int i = 0; i < num_nodes; i++) {
        NODE_INFO_T* node = &((NODE_INFO_T*)node_pool)[i];
        if (node->node_id == -1) {
            continue;
        }
        // Update the FQDN and latency values asynchronously
        char* new_fqdn = nodes[i]->fqdn;
        double new_latency = nodes[i]->latency;
        if (new_fqdn != NULL && strcmp(node->fqdn, new_fqdn) != 0) {
            free(node->fqdn);
            node->fqdn = strdup(new_fqdn);
        }
        if (new_latency != node->latency) {
            node->latency = new_latency;
        }
    }

    // Log any discrepancies or anomalies during management operations
    for (int i = 0; i < num_nodes; i++) {
        NODE_INFO_T* node = &((NODE_INFO_T*)node_pool)[i];
        if (node->node_id == -1) {
            continue;
        }
        // Log any discrepancies or anomalies during management operations
        if (node->fqdn == NULL || node->latency <= 0.0) {
            printf("Node %d has invalid FQDN or latency value\n", node->node_id);
        }
    }
}

// Function to deallocate the memory pool
void free_nodes() {
    if (node_pool != NULL) {
        free(node_pool);
        node_pool = NULL;
        node_pool_size = 0;
    }
}
