MAC_FRAME_T* init_mac_frames(size_t num_frames, int signal_strength_range) {
    // Allocate memory for the array of MAC frames
    MAC_FRAME_T* mac_frames = (MAC_FRAME_T*)malloc(num_frames * sizeof(MAC_FRAME_T));
    if (!mac_frames) {
        fprintf(stderr, "Error: Failed to allocate memory for MAC frames\n");
        return NULL;
    }

    // Initialize the MAC header and preamble for each frame
    for (size_t i = 0; i < num_frames; i++) {
        mac_frames[i].header.init();
        mac_frames[i].preamble.init();
    }

    // Generate random SNR values within the specified range for each frame
    srand(time(NULL));
    for (size_t i = 0; i < num_frames; i++) {
        int snr = rand() % signal_strength_range + 1;
        mac_frames[i].signal_info.set_snr(snr);
    }

    // Validate the integrity of the populated frames
    for (size_t i = 0; i < num_frames; i++) {
        if (!mac_frames[i].header.is_valid() || !mac_frames[i].preamble.is_valid()) {
            fprintf(stderr, "Error: Invalid MAC frame at index %zu\n", i);
            free(mac_frames);
            return NULL;
        }
    }

    return mac_frames;
}
