// Define the function to initialize and populate the array of TRANSMISSION_RECORD structures
void init_transmission_records(TRANSMISSION_RECORD** records, int num_records, float snr, int modulation_scheme) {
    // Allocate memory for the array of TRANSMISSION_RECORD structures
    *records = (TRANSMISSION_RECORD*)malloc(num_records * sizeof(TRANSMISSION_RECORD));
    if (*records == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize the TRANSMISSION_HEADER field for each record
    for (int i = 0; i < num_records; i++) {
        (*records)[i].header.sequence_number = i + 1;
        (*records)[i].header.timestamp = i * 1000;
    }

    // Initialize the ENCODING_PARAMETERS field for each record based on the specified SNR and modulation scheme
    for (int i = 0; i < num_records; i++) {
        (*records)[i].parameters.snr = snr;
        (*records)[i].parameters.modulation_scheme = modulation_scheme;
    }

    // Calculate the bit error rate (BER) for each record based on simulated channel noise
    for (int i = 0; i < num_records; i++) {
        (*records)[i].status.ber = calculate_ber(snr, modulation_scheme);
    }
}

// Define the function to validate the integrity of the transmitted records after initialization
void validate_transmission_records(TRANSMISSION_RECORD* records, int num_records) {
    // Check if any record has a bit error rate (BER) greater than 1%
    for (int i = 0; i < num_records; i++) {
        if ((*records)[i].status.ber > 0.01) {
            printf("Error: Bit error rate (BER) exceeds 1%%\n");
            return;
        }
    }
}

// Define the function to calculate the bit error rate (BER) based on simulated channel noise
float calculate_ber(float snr, int modulation_scheme) {
    // Calculate the signal power based on the SNR and modulation scheme
    float signal_power = powf(10, snr / 10);

    // Calculate the noise power based on the SNR and modulation scheme
    float noise_power = signal_power * (1 - signal_power) / (2 * signal_power);

    // Calculate the bit error rate (BER) based on the simulated channel noise
    float ber = sqrtf(noise_power / signal_power);

    return ber;
}
