void populateNfapiCrcIndications(int N, int randomize_crcflag) {
    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (crc_indications == NULL) {
        handle_error("Failed to allocate memory for crc_indications");
        return;
    }

    // Initialize each structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < N; i++) {
        crc_indications[i].rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        crc_indications[i].rnti = i + 1; // Start with RNTI value of 1
        if (randomize_crcflag) {
            crc_indications[i].crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
            crc_indications[i].crc_indication_rel8.crcFlag = rand() % 2; // Generate a random CRCFLAG value between 0 and 1
        } else {
            crc_indications[i].crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
            crc_indications[i].crc_indication_rel8.crcFlag = 0; // Set CRCFLAG to a constant value of 0
        }
    }

    // Validate each CRC_INDICATION_REL8_TAG and ensure all RNTI values are unique within the array
    for (int i = 0; i < N; i++) {
        if (crc_indications[i].crc_indication_rel8.tag != CRC_INDICATION_REL8_TAG) {
            handle_error("Invalid CRCFLAG value for RNTI %d", crc_indications[i].rnti);
