// Define the function to manage the dynamic list of cellular radio measurement records
void manageMeasurementRecords(int timeThreshold, int CI, int RSSI) {
    // Initialize a dynamically allocated array of MeasurementRecord structures
    MeasurementRecord* measurementRecords = (MeasurementRecord*)malloc(sizeof(MeasurementRecord) * 10);
    if (!measurementRecords) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Add new records to the list
    for (int i = 0; i < 10; i++) {
        measurementRecords[i].timestamp = time(NULL);
        measurementRecords[i].CI = CI;
        measurementRecords[i].RSSI = RSSI;
    }

    // Remove outdated records based on the configurable time threshold
    for (int i = 0; i < 10; i++) {
        if (measurementRecords[i].timestamp < time(NULL) - timeThreshold) {
            measurementRecords[i] = measurementRecords[9 - i];
        }
    }

    // Calculate the average RSSI for a specified cell identity within a given time window
    int sumRSSI = 0;
    int count = 0;
    for (int i = 0; i < 10; i++) {
        if (measurementRecords[i].CI == CI) {
            sumRSSI += measurementRecords[i].RSSI;
            count++;
        }
    }
    float averageRSSI = sumRSSI / count;

    // Initialize a dynamically allocated array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* nfapiCrcIndicationPdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10);
    if (!nfapiCrcIndicationPdus) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Populate the NFAPI_CRC_INDICATION_PDU_T structures with valid data
    for (int i = 0; i < 10; i++) {
        nfapiCrcIndicationPdus[i].RX_UE_INFORMATION_TAG = measurementRecords[i].CI;
        nfapiCrcIndicationPdus[i].RNTI = rand(); // Randomly generate a CRCFLAG
        nfapiCrcIndicationPdus[i].CRC_INDICATION_REL8_TAG = averageRSSI;
    }

    // Free the dynamically allocated arrays of MeasurementRecord and NFAPI_CRC_INDICATION_PDU_T structures
    free(measurementRecords);
    free(nfapiCrcIndicationPdus);
}
