    NFAPI_CRC_INDICATION_PDU_T* crcIndicationPdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numRecords * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crcIndicationPdus) {
        printf("Error: Failed to allocate memory for CRC indication PDUs\n");
        return;
