    for (int i = 0; i < numRecords; i++) {
        crcIndicationPdus[i].RX_UE_INFORMATION_TAG = records[i].ci;
        crcIndicationPdus[i].RNTI = records[i].rssi;
        crcIndicationPdus[i].CRC_INDICATION_REL8_TAG = rand() % 1000; // Generate a random CRCFLAG value for each record
    }

    // Implement an efficient mechanism to calculate the average RSSI for a specified cell identity within a given time window
    int avgRssi = 0;
    int numRecordsInWindow = 0;
    time_t startTime = records[0].timestamp - (time_t)(10 * 60); // Start time is 10 minutes ago
    for (int i = 0; i < numRecords; i++) {
        if (records[i].timestamp >= startTime) {
            avgRssi += records[i].rssi;
            numRecordsInWindow++;
        } else {
            break;
        }
    }
    if (numRecordsInWindow > 0) {
        avgRssi /= numRecordsInWindow;
    }

    // Free the memory allocated for the CRC indication PDUs
