// Define the structure to hold the LTE PHY context information
typedef struct {
    int ci; // Cell identity (CI)
    int frequency_band; // Frequency band
    int num_downlink_channels; // Number of downlink channels
    int* downlink_channels; // Vector of downlink channels
} LTEPHYCONTEXT;

// Function to initialize and configure the dynamic array of LTE PHY contexts
void init_ltephycontext(LTEPHYCONTEXT** ltephycontext, int num_cells) {
    // Allocate memory for the dynamic array of LTE PHY contexts
    *ltephycontext = (LTEPHYCONTEXT*)malloc(num_cells * sizeof(LTEPHYCONTEXT));
    if (*ltephycontext == NULL) {
        printf("Error: Failed to allocate memory for the dynamic array of LTE PHY contexts\n");
        return;
    }

    // Initialize each entry in the dynamic array with a valid cell identity (CI), frequency band, and vector of downlink channels
    for (int i = 0; i < num_cells; i++) {
        (*ltephycontext)[i].ci = i + 1;
        (*ltephycontext)[i].frequency_band = 2400; // Default frequency band is 2400 MHz
        (*ltephycontext)[i].num_downlink_channels = 36; // Default number of downlink channels is 36
        (*ltephycontext)[i].downlink_channels = (int*)malloc(36 * sizeof(int));
        if ((*ltephycontext)[i].downlink_channels == NULL) {
            printf("Error: Failed to allocate memory for the vector of downlink channels\n");
            return;
        }
        // Initialize each entry in the vector with a unique downlink channel number
        for (int j = 0; j < 36; j++) {
            (*ltephycontext)[i].downlink_channels[j] = i * 36 + j + 1;
        }
    }
}

// Function to add a new channel to the dynamic array of LTE PHY contexts
void add_channel(LTEPHYCONTEXT** ltephycontext, int cell_id, int channel) {
    // Check if the cell ID is valid and the channel is unique
    for (int i = 0; i < (*ltephycontext)[cell_id].num_downlink_channels; i++) {
        if ((*ltephycontext)[cell_id].downlink_channels[i] == channel) {
            printf("Error: The channel is already in use\n");
            return;
        }
    }

    // Add the new channel to the vector of downlink channels
    (*ltephycontext)[cell_id].num_downlink_channels++;
    (*ltephycontext)[cell_id].downlink_channels = (int*)realloc((*ltephycontext)[cell_id].downlink_channels, (*ltephycontext)[cell_id].num_downlink_channels * sizeof(int));
    if ((*ltephycontext)[cell_id].downlink_channels == NULL) {
        printf("Error: Failed to allocate memory for the vector of downlink channels\n");
        return;
    }
    (*ltephycontext)[cell_id].downlink_channels[(*ltephycontext)[cell_id].num_downlink_channels - 1] = channel;
}

// Function to remove a channel from the dynamic array of LTE PHY contexts
void remove_channel(LTEPHYCONTEXT** ltephycontext, int cell_id, int channel) {
    // Check if the cell ID and channel are valid
    if (cell_id < 0 || cell_id >= (*ltephycontext)[cell_id].num_downlink_channels) {
        printf("Error: The cell ID is invalid\n");
        return;
    }
    for (int i = 0; i < (*ltephycontext)[cell_id].num_downlink_channels; i++) {
        if ((*ltephycontext)[cell_id].downlink_channels[i] == channel) {
            // Remove the channel from the vector of downlink channels
            for (int j = i; j < (*ltephycontext)[cell_id].num_downlink_channels - 1; j++) {
                (*ltephycontext)[cell_id].downlink_channels[j] = (*ltephycontext)[cell_id].downlink_channels[j + 1];
            }
            (*ltephycontext)[cell_id].num_downlink_channels--;
            break;
        }
    }
}
```
