    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Read each line of the file and print its contents in a comma-separated format
    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        // Split the line into tokens using whitespace as a delimiter
        char **tokens = strtok(line, " ");

        // Print each token in the line, separated by commas
        for (int i = 0; tokens[i] != NULL; i++) {
            printf("%s", tokens[i]);

            if (i < 2) {
                printf(",");
            } else {
                int average = atoi(tokens[i - 1]) + atoi(tokens[i]) / 2;
                printf(",%d", average);
            }
        }

        // Free the memory allocated for the line
        free(line);
    }

    // Close the file
    fclose(file);
}

