        for (int j = contexts[i]->num_channels - 2; j < contexts[i]->num_channels; j++) {
            sum += contexts[i]->channels[j].frequency;
        }
        contexts[i]->metadata = sum / 2;
    }

    // Free allocated memory for the array of LTEPHYCONTEXT structures and close the file
    free(contexts);
    fclose(file);
