// Structure to represent a channel
typedef struct Channel {
    int frequency;
    int bandwidth;
} Channel;

// Structure to represent an LTE PHY context
typedef struct LTEPHYContext {
    int ci; // Cell identity
    int frequency_band;
    Channel *channels; // Linked list of downlink channels
} LTEPHYContext;

// Function to initialize a new LTE PHY context
LTEPHYContext* init_ltephycontext(int ci, int frequency_band) {
    LTEPHYContext *ctx = malloc(sizeof(LTEPHYContext));
    if (!ctx) {
        fprintf(stderr, "Error: Failed to allocate memory for LTE PHY context\n");
        return NULL;
    }
    ctx->ci = ci;
    ctx->frequency_band = frequency_band;
    ctx->channels = NULL;
    return ctx;
}

// Function to add a new channel to an LTE PHY context
int add_channel(LTEPHYContext *ctx, int frequency, int bandwidth) {
    Channel *new_channel = malloc(sizeof(Channel));
    if (!new_channel) {
        fprintf(stderr, "Error: Failed to allocate memory for new channel\n");
        return -1;
    }
    new_channel->frequency = frequency;
    new_channel->bandwidth = bandwidth;
    new_channel->next = ctx->channels;
    ctx->channels = new_channel;
    return 0;
}

// Function to remove a channel from an LTE PHY context
int remove_channel(LTEPHYContext *ctx, int frequency) {
    Channel *prev = NULL;
    Channel *curr = ctx->channels;
    while (curr != NULL && curr->frequency != frequency) {
        prev = curr;
        curr = curr->next;
    }
    if (curr == NULL) {
        fprintf(stderr, "Error: Could not find channel with frequency %d\n", frequency);
        return -1;
    }
    if (prev != NULL) {
        prev->next = curr->next;
    } else {
        ctx->channels = curr->next;
    }
    free(curr);
    return 0;
}

