// Define the function to parse and index a document
void parse_and_index_document(Document *doc) {
    // Initialize the term frequency map
    size_t term_frequency_map[256] = {};

    // Iterate over each line in the document
    for (size_t i = 0; i < doc->num_lines; i++) {
        wchar_t *line = doc->lines[i];

        // Skip comments and whitespace-only lines
        if (iswspace(line[0]) || line[0] == L'#') continue;

        // Tokenize the line into terms
