        wchar_t **terms = tokenize_line(line, &num_terms);

        // Iterate over each term in the line
        for (size_t j = 0; j < num_terms; j++) {
            wchar_t *term = terms[j];

            // Increment the frequency of the term in the map
            if (term_frequency_map[term]) {
                term_frequency_map[term]++;
            } else {
                term_frequency_map[term] = 1;
            }
        }
    }

    // Create a new term for each unique term in the map
    size_t num_terms = 0;
    Term *terms = malloc(sizeof(Term) * (256));
    for (size_t i = 0; i < 256; i++) {
        if (term_frequency_map[i]) {
            terms[num_terms].term = i;
            terms[num_terms].frequency = term_frequency_map[i];
            num_terms++;
        }
    }

    // Create a new document for the indexed terms
    Document *indexed_doc = malloc(sizeof(Document));
    indexed_doc->filename = doc->filename;
    indexed_doc->file_descriptor = doc->file_descriptor;
    indexed_doc->file_size = doc->file_size;
    indexed_doc->lines = terms;
    indexed_doc->num_lines = num_terms;

    // Return the indexed document
    return indexed_doc;
}

// Define the function to tokenize a line into terms
wchar_t **tokenize_line(wchar_t *line, size_t *num_terms) {
    wchar_t **terms = malloc(sizeof(wchar_t *) * 16);
    size_t num_tokens = 0;

    // Iterate over each token in the line
    for (size_t i = 0; i < wcslen(line); i++) {
        if (iswspace(line[i])) continue;

        // Tokenize the line into terms
        size_t j = i;
        while (!iswspace(line[j]) && line[j] != L'\0') j++;
        wchar_t *term = malloc(sizeof(wchar_t) * (j - i + 1));
        wcscpy(term, &line[i]);
        terms[num_tokens++] = term;

        // Skip the rest of the line if it is a comment
        if (line[j] == L'#') break;
    }

    *num_terms = num_tokens;
    return terms;
}

// Define the function to build an inverted index from a set of documents
InvertedIndex *build_inverted_index(Document **docs, size_t num_docs) {
    // Initialize the inverted index
    InvertedIndex *index = malloc(sizeof(InvertedIndex));
    index->num_terms = 0;
    index->num_documents = num_docs;
