    for (int i = 0; i < N; i++) {
        crcIndications[i].RX_UE_INFORMATION_TAG = 1;
        crcIndications[i].RNTI = i + 1;
    }

    // Set the CRC_INDICATION_REL8_TAG field for each structure based on user input
    if (useRandomCRCFlag) {
