    ENCODING_PARAMETERS parameters;
    RECEPTION_STATUS status;
} TRANSMISSION_RECORD;

// Define the function to initialize and populate a dynamically allocated array of TRANSMISSION_RECORD structures
void init_transmission_records(TRANSMISSION_RECORD **records, int num_records) {
    // Allocate memory for the array of records
    *records = (TRANSMISSION_RECORD *)malloc(num_records * sizeof(TRANSMISSION_RECORD));
    if (*records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for transmission records\n");
        return;
    }

    // Initialize the header and parameters fields of each record
    for (int i = 0; i < num_records; i++) {
        (*records)[i].header.valid = false;
        (*records)[i].parameters.encoding_scheme = -1;
        (*records)[i].parameters.modulation_index = -1;
        (*records)[i].status.ber = -1;
    }

    // Calculate the BER for each record based on simulated channel noise
    for (int i = 0; i < num_records; i++) {
        double snr = (*records)[i].parameters.snr;
        double ber = calculate_ber(snr);
        (*records)[i].status.ber = ber;
    }
}

// Define the function to validate the integrity of transmission records against predefined quality metrics
void validate_transmission_records(TRANSMISSION_RECORD *records, int num_records) {
    // Check that each record has a valid header and parameters field
    for (int i = 0; i < num_records; i++) {
        if (!records[i].header.valid || records[i].parameters.encoding_scheme == -1 || records[i].parameters.modulation_index == -1) {
            fprintf(stderr, "Error: Transmission record %d has an invalid header or parameters field\n", i);
            return;
        }
    }

    // Check that the BER for each record is within a predefined range
    for (int i = 0; i < num_records; i++) {
        double ber = records[i].status.ber;
        if (ber < 0 || ber > 1) {
            fprintf(stderr, "Error: Transmission record %d has an invalid BER value\n", i);
            return;
        }
    }
}

// Define the function to calculate the bit error rate (BER) based on simulated channel noise
double calculate_ber(double snr) {
    // Calculate the signal power and noise power based on the SNR
    double signal_power = pow(10, snr / 10);
    double noise_power = signal_power / (2 * log(2));

    // Calculate the BER based on the ratio of signal power to noise power
    double ber = signal_power / noise_power;

    return ber;
}
