    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct node *next;
} NODE_T;

// Define the hash map data structure for managing UE configurations
typedef struct {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    bool crcflag;
    struct node *next;
} HASH_MAP_T;

// Define the function for initializing and populating an array of NFAPI_CRC_INDICATION_PDU_T structures
void init_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, uint16_t rx_ue_information_tag, uint16_t rnti, bool crcflag) {
