// Define the function for reading UE-specific parameters from an external configuration file
void read_ue_config(char *filename, HASH_MAP_T **hash_map) {
    // Open the configuration file in read mode
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("Error opening configuration file");
        exit(1);
    }

    // Read the contents of the configuration file into a buffer
    char *buffer = malloc(sizeof(char) * 4096);
    read(fd, buffer, 4096);

    // Close the configuration file
    close(fd);

    // Parse the contents of the buffer and populate the hash map with UE configurations
    char *token = strtok(buffer, "\n");
    while (token != NULL) {
        // Extract the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG from the token
        uint16_t rx_ue_information_tag = atoi(strtok(token, ","));
        uint16_t rnti = atoi(strtok(NULL, ","));
        bool crcflag = atoi(strtok(NULL, ","));

        // Add the UE configuration to the hash map
        HASH_MAP_T *new_node = malloc(sizeof(HASH_MAP_T));
        new_node->rx_ue_information_tag = rx_ue_information_tag;
        new_node->rnti = rnti;
        new_node->crcflag = crcflag;
        new_node->next = NULL;

        // Check if the hash map is empty, and if so, set the head node to the new node
        if (*hash_map == NULL) {
            *hash_map = new_node;
        } else {
            // Otherwise, add the new node to the end of the linked list
            HASH_MAP_T *current_node = *hash_map;
            while (current_node->next != NULL) {
                current_node = current_node->next;
            }
            current_node->next = new_node;
        }

        // Move on to the next token
        token = strtok(NULL, "\n");
    }
}

