    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    *pdu_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_ues);

    // Initialize and populate each structure in the array with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (uint16_t i = 0; i < num_ues; i++) {
