    NODE_T *current_node = head;

    // Iterate through the hash map and check for cyclic dependencies
    while (current_node != NULL) {
        HASH_MAP_T *next_node = current_node->next;
        if (current_node->rx_ue_information_tag == next_node->rx_ue_information_tag &&
