// Thread-safe file access functions
int read_config_file(char *filename, char **buffer) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    struct stat st;
    if (fstat(fd, &st) < 0) {
        perror("fstat");
        close(fd);
        return -1;
    }

    *buffer = malloc(st.st_size + 1);
    if (*buffer == NULL) {
        perror("malloc");
        close(fd);
        return -1;
    }

    ssize_t nread = read(fd, *buffer, st.st_size);
    if (nread < 0) {
        perror("read");
        free(*buffer);
        close(fd);
        return -1;
    }

    (*buffer)[nread] = '\0';
    close(fd);
    return nread;
}

int write_config_file(char *filename, char *buffer) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    ssize_t nwritten = write(fd, buffer, strlen(buffer));
    if (nwritten < 0) {
        perror("write");
        close(fd);
        return -1;
    }

    close(fd);
    return nwritten;
}

// Memory pool management functions
void *memory_pool = NULL;
size_t memory_pool_size = 0;

void init_memory_pool() {
    memory_pool = malloc(MEMORY_POOL_SIZE);
    if (memory_pool == NULL) {
        perror("malloc");
        exit(1);
    }
    memory_pool_size = MEMORY_POOL_SIZE;
}

void *allocate_memory(size_t size) {
    void *ptr = NULL;
    if (size > memory_pool_size) {
        ptr = malloc(size);
        if (ptr == NULL) {
            perror("malloc");
            return NULL;
        }
    } else {
        ptr = memory_pool;
        memory_pool += size;
        memory_pool_size -= size;
    }
    return ptr;
}

void free_memory(void *ptr) {
    if (ptr != NULL && ptr < memory_pool + MEMORY_POOL_SIZE) {
        memory_pool -= (char *)ptr - (char *)memory_pool;
        memory_pool_size += (char *)ptr - (char *)memory_pool;
    } else {
        free(ptr);
    }
}

// Error handling functions
void handle_error(const char *msg) {
    perror(msg);
    exit(1);
}

int handle_file_access_error(const char *filename, int errno) {
    if (errno == EAGAIN || errno == EWOULDBLOCK) {
        usleep(RETRY_DELAY_MS * 1000);
        return -1;
    } else {
        handle_error("File access error");
    }
}

