    static int ue_index = 0;
    return ue_index++;
}

void distribute_ues(NFAPI_CRC_INDICATION_PDU_T *pdu, int num_ues) {
    int next_ue_index = get_next_ue_index();
    for (int i = 0; i < num_ues; i++) {
        pdu[i].rx_ue_information.ue_index = next_ue_index++;
    }
}

