// Function to add an element to the list
void add_element(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&list_mutex);

    // Check if the RNTI is already in the list
    for (size_t i = 0; i < list->count; i++) {
        if (list->list[i].RNTI == element->RNTI) {
            // If it is, do not add the element and return
            pthread_mutex_unlock(&list_mutex);
            return;
