import java.security.SecureRandom;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class AESCipher {
    private static final Logger logger = LogManager.getLogger(AESCipher.class);

    // Constants for key derivation and IV generation
    private static final int KEY_BYTES = 32;
    private static final int IV_MIN_LENGTH = 16;
    private static final int IV_MAX_LENGTH = 32;

    // Instance variables for the cipher and key
    private Cipher cipher;
    private SecretKeySpec secretKey;

    public AESCipher(String password, int ivLength) throws Exception {
        // Validate input parameters
        if (password == null || password.isEmpty()) {
            throw new IllegalArgumentException("Password cannot be empty");
        }
        if (ivLength < IV_MIN_LENGTH || ivLength > IV_MAX_LENGTH) {
            throw new IllegalArgumentException("Invalid IV length: " + ivLength);
        }

        // Generate a secure random IV
        byte[] iv = new byte[ivLength];
        SecureRandom random = new SecureRandom();
        random.nextBytes(iv);

        // Derive the key from the password using SHA-256 hash
        byte[] key = new byte[KEY_BYTES];
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] passwordHash = digest.digest(password.getBytes());
        System.arraycopy(passwordHash, 0, key, 0, Math.min(KEY_BYTES, passwordHash.length));

        // Create the cipher instance and set the IV
        cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        secretKey = new SecretKeySpec(key, "AES");
        IvParameterSpec ivSpec = new IvParameterSpec(iv);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, ivSpec);
    }

    public byte[] encrypt(byte[] plaintext) throws Exception {
        // Encrypt the plaintext using the cipher instance
        return cipher.doFinal(plaintext);
    }

    public byte[] decrypt(byte[] ciphertext) throws Exception {
        // Decrypt the ciphertext using the cipher instance
        return cipher.doFinal(ciphertext);
    }

    public void startService() {
        // Start the service with a random delay between starts
        int delay = new SecureRandom().nextInt(10) + 1;
        logger.info("Starting service with delay: " + delay);
        try {
            Thread.sleep(delay * 1000L);
        } catch (InterruptedException e) {
            // Handle interruption
        }
    }

    public void stopService() {
        // Send a message to the messaging system when the service is deactivated
        logger.info("Deactivating service");
        // Disable the cipher and release resources
        cipher = null;
        secretKey = null;
    }
}
