// Define the structure for cell information
typedef struct {
    int cell_id;
    int pci;
    int rsrp;
} LTE_CELL_INFO_T;

// Define the list of cells
LTE_CELL_INFO_T *cells = NULL;

// Define the size of the list
int num_cells = 0;

// Define the mutex for protecting the list
pthread_mutex_t cell_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the semaphore for signaling when a new cell is added or removed
semaphore_t cell_list_semaphore = SEMAPHORE_INITIALIZER;

// Function to add a new cell to the list
void add_cell(int cell_id, int pci, int rsrp) {
    // Lock the mutex to protect the list
    pthread_mutex_lock(&cell_list_mutex);

    // Check if the list is full
    if (num_cells == MAX_CELLS) {
        // If the list is full, resize it by 50%
        num_cells = num_cells * 1.5;
        cells = realloc(cells, sizeof(LTE_CELL_INFO_T) * num_cells);
    }

    // Add the new cell to the list
    cells[num_cells].cell_id = cell_id;
    cells[num_cells].pci = pci;
    cells[num_cells].rsrp = rsrp;
    num_cells++;

    // Unlock the mutex
    pthread_mutex_unlock(&cell_list_mutex);

    // Signal the semaphore to wake up any waiting threads
    semaphore_signal(&cell_list_semaphore);
}

// Function to remove a cell from the list
void remove_cell(int cell_id) {
    // Lock the mutex to protect the list
    pthread_mutex_lock(&cell_list_mutex);

    // Find the index of the cell to be removed
    int i = 0;
    while (i < num_cells && cells[i].cell_id != cell_id) {
        i++;
    }

    // If the cell is found, remove it from the list
    if (i < num_cells) {
        for (int j = i; j < num_cells - 1; j++) {
            cells[j] = cells[j + 1];
        }
        num_cells--;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&cell_list_mutex);

    // Signal the semaphore to wake up any waiting threads
    semaphore_signal(&cell_list_semaphore);
}

// Function to update the RSRP value of a cell in the list
void update_rsrp(int cell_id, int rsrp) {
    // Lock the mutex to protect the list
    pthread_mutex_lock(&cell_list_mutex);

    // Find the index of the cell to be updated
    int i = 0;
    while (i < num_cells && cells[i].cell_id != cell_id) {
        i++;
    }

    // If the cell is found, update its RSRP value
    if (i < num_cells) {
        cells[i].rsrp = rsrp;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&cell_list_mutex);
}

// Function to retrieve a cell from the list by its ID
LTE_CELL_INFO_T *get_cell(int cell_id) {
    // Lock the mutex to protect the list
    pthread_mutex_lock(&cell_list_mutex);

    // Find the index of the cell to be retrieved
    int i = 0;
    while (i < num_cells && cells[i].cell_id != cell_id) {
        i++;
    }

    // If the cell is found, return its pointer
    if (i < num_cells) {
        LTE_CELL_INFO_T *cell = &cells[i];
        pthread_mutex_unlock(&cell_list_mutex);
        return cell;
    } else {
        // If the cell is not found, return NULL
        pthread_mutex_unlock(&cell_list_mutex);
        return NULL;
    }
}

// Function to validate the integrity of the cell information
void validate_cells() {
    // Lock the mutex to protect the list
    pthread_mutex_lock(&cell_list_mutex);

    // Iterate over all cells and validate their RSRP values
    for (int i = 0; i < num_cells; i++) {
        if (cells[i].rsrp < MIN_RSRP || cells[i].rsrp > MAX_RSRP) {
            // If the RSRP value is out of range, log an error
            printf("Error: Invalid RSRP value for cell %d\n", cells[i].cell_id);
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&cell_list_mutex);
}

// Function to log discrepancies or anomalies in the cell information
void log_discrepancies() {
    // Lock the mutex to protect the list
    pthread_mutex_lock(&cell_list_mutex);

    // Iterate over all cells and log any discrepancies or anomalies
    for (int i = 0; i < num_cells; i++) {
        if (cells[i].rsrp < MIN_RSRP || cells[i].rsrp > MAX_RSRP) {
            // If the RSRP value is out of range, log an error
            printf("Error: Invalid RSRP value for cell %d\n", cells[i].cell_id);
        } else if (cells[i].pci < MIN_PCI || cells[i].pci > MAX_PCI) {
            // If the PCI value is out of range, log a warning
            printf("Warning: Invalid PCI value for cell %d\n", cells[i].cell_id);
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&cell_list_mutex);
}
