void init_ue_context_collection(int num_records, int seed) {
    // Allocate memory for the UE context collection
    UE_CONTEXT_INFO_RECORD *ue_context_collection = (UE_CONTEXT_INFO_RECORD *)malloc(num_records * sizeof(UE_CONTEXT_INFO_RECORD));
    if (!ue_context_collection) {
