        ue_context_record->num_products++;
    }
}

// Define a function to compute the total value of unsold products and update the UE context collection
void update_unsold_products(UE_CONTEXT_INFO_RECORD *ue_context_collection, int num_records) {
    // Iterate over each UE context record in the collection
    for (int i = 0; i < num_records; i++) {
        // Compute the total value of unsold products for the current UE context record
        double total_value = 0.0;
        for (int j = 0; j < ue_context_collection[i].num_products; j++) {
            total_value += ue_context_collection[i].product_description[j].price * ue_context_collection[i].product_description[j].quantity;
        }

