// Define the INTERFACE_CONFIG structure
typedef struct {
    int id;
    char ip[16];
    unsigned short flags;
    time_t last_update;
} INTERFACE_CONFIG;

// Define a collection of interface configurations
INTERFACE_CONFIG *configs = NULL;
size_t config_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void populate_configs(int n, int seed) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Allocate memory for the interface configurations
    configs = (INTERFACE_CONFIG *)malloc(n * sizeof(INTERFACE_CONFIG));
    if (!configs) {
        printf("Failed to allocate memory for interface configurations\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Populate the interface configurations with random values
    srand(seed);
    for (int i = 0; i < n; ++i) {
        configs[i].id = i + 1;
        snprintf(configs[i].ip, sizeof(configs[i].ip), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        configs[i].flags = (rand() % 3) + 1;
        configs[i].last_update = time(NULL);
    }

    // Update the number of interface configurations
    config_count = n;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

void update_config(int id, char *ip, unsigned short flags) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Find the interface configuration with the given ID
    int i;
    for (i = 0; i < config_count; ++i) {
        if (configs[i].id == id) {
            break;
        }
    }

    // Update the IP address and flags of the interface configuration
    if (i < config_count) {
        strcpy(configs[i].ip, ip);
        configs[i].flags = flags;
        configs[i].last_update = time(NULL);
    } else {
        printf("Failed to find interface configuration with ID %d\n", id);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

void free_configs() {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Free the memory allocated for the interface configurations
    if (configs) {
        free(configs);
        configs = NULL;
    }

    // Update the number of interface configurations
    config_count = 0;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}
