// Define a collection of interface configurations
INTERFACE_CONFIG *interface_configs = NULL;

// Define the number of interfaces to populate
int num_interfaces = 0;

// Define the seed value for random number generation
unsigned int seed = 0;

// Define the mutex for protecting shared resources
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to populate the collection of interface configurations
void populate_interface_configs(int n, unsigned int s) {
    // Validate input parameters
    if (n <= 0 || s == 0) {
        return;
    }

    // Initialize the number of interfaces and seed value
    num_interfaces = n;
    seed = s;

    // Allocate memory for the collection of interface configurations
    interface_configs = (INTERFACE_CONFIG *)malloc(num_interfaces * sizeof(INTERFACE_CONFIG));
    if (!interface_configs) {
        return;
    }

    // Populate the collection of interface configurations with random values
    for (int i = 0; i < num_interfaces; i++) {
        INTERFACE_CONFIG *config = &interface_configs[i];
        config->id = i + 1;
        srand(seed);
        config->ip_address[0] = rand() % 256;
        config->ip_address[1] = rand() % 256;
        config->ip_address[2] = rand() % 256;
        config->ip_address[3] = rand() % 256;
        config->flags = rand() % 0xFFFF;
        config->last_update = time(NULL);
    }
}

// Function to update the interface configurations with new values
void update_interface_configs(int id, char *ip_address, unsigned short flags) {
    // Validate input parameters
    if (id <= 0 || ip_address == NULL || flags == 0) {
        return;
    }

    // Acquire the mutex for protecting shared resources
    pthread_mutex_lock(&mutex);

    // Update the interface configuration with new values
    INTERFACE_CONFIG *config = &interface_configs[id - 1];
    strcpy(config->ip_address, ip_address);
    config->flags = flags;
    config->last_update = time(NULL);

    // Release the mutex for protecting shared resources
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve the interface configurations
void get_interface_configs(int *n, INTERFACE_CONFIG **configs) {
    // Validate input parameters
    if (n == NULL || configs == NULL) {
        return;
    }

    // Acquire the mutex for protecting shared resources
    pthread_mutex_lock(&mutex);

    // Retrieve the number of interfaces and the collection of interface configurations
    *n = num_interfaces;
    *configs = interface_configs;

    // Release the mutex for protecting shared resources
    pthread_mutex_unlock(&mutex);
}
