// Define the structure for session information
typedef struct {
    int id;
    bool authenticated;
    time_t expiration;
    char *resources[10]; // Maximum number of resources per session is 10
} SESSION_INFO;

// Define the collection of sessions
SESSION_INFO *sessions = NULL;

// Define the mutex for protecting concurrent access to the sessions
pthread_mutex_t sessions_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to populate the session information based on input parameters
int populate_sessions(int n, int seed) {
    // Check if the input value for N is valid
    if (n <= 0) {
        printf("Invalid input value for N\n");
        return -1;
    }

    // Allocate memory for the sessions
    sessions = malloc(sizeof(SESSION_INFO) * n);
    if (!sessions) {
        printf("Failed to allocate memory for sessions\n");
        return -1;
    }

    // Initialize the session information
    for (int i = 0; i < n; i++) {
        sessions[i].id = i + 1;
        sessions[i].authenticated = false;
        sessions[i].expiration = time(NULL) + seed * 60; // Set the expiration time to the current time plus the seed value multiplied by 60 seconds
        for (int j = 0; j < 10; j++) {
            sessions[i].resources[j] = NULL;
        }
    }

    return 0;
}

// Function to update the session information based on input parameters
int update_session(int id, bool authenticated, char *resources[]) {
    // Check if the input value for ID is valid
    if (id <= 0 || id > n) {
        printf("Invalid input value for ID\n");
        return -1;
    }

    // Lock the mutex to protect concurrent access to the sessions
    pthread_mutex_lock(&sessions_mutex);

    // Update the session information
    SESSION_INFO *session = &sessions[id - 1];
    session->authenticated = authenticated;
    for (int i = 0; i < 10; i++) {
        if (resources[i]) {
            strcpy(session->resources[i], resources[i]);
        } else {
            break;
        }
    }

    // Unlock the mutex to allow other threads to access the sessions
    pthread_mutex_unlock(&sessions_mutex);

    return 0;
}

// Function to clean up inactive sessions automatically
void cleanup_inactive_sessions() {
    // Lock the mutex to protect concurrent access to the sessions
    pthread_mutex_lock(&sessions_mutex);

    // Iterate over the sessions and remove any that have expired
    for (int i = 0; i < n; i++) {
        if (time(NULL) > sessions[i].expiration) {
            free(sessions[i].resources);
            memmove(&sessions[i], &sessions[i + 1], sizeof(SESSION_INFO) * (n - i - 1));
            n--;
        }
    }

    // Unlock the mutex to allow other threads to access the sessions
    pthread_mutex_unlock(&sessions_mutex);
}
