// Define function to initialize and configure dynamic array of LTE PHY contexts
void init_ltephycontext(LTEPHYCONTEXT **ltephycontext, int num_elements) {
    // Allocate memory for the dynamic array
    *ltephycontext = (LTEPHYCONTEXT *)malloc(num_elements * sizeof(LTEPHYCONTEXT));

    // Initialize each element in the dynamic array with default values
    for (int i = 0; i < num_elements; i++) {
        (*ltephycontext)[i].ci = -1;
        (*ltephycontext)[i].frequency_band = -1;
        (*ltephycontext)[i].num_downlink_channels = 0;
    }
}

// Define function to add new channels to the dynamic array of LTE PHY contexts
void add_channel(LTEPHYCONTEXT **ltephycontext, int num_elements, int channel) {
    // Check if the channel is already in the dynamic array
    for (int i = 0; i < num_elements; i++) {
        if ((*ltephycontext)[i].num_downlink_channels == channel) {
            return; // Channel already exists, do nothing
        }
    }

    // Add the new channel to the dynamic array
    for (int i = 0; i < num_elements; i++) {
        if ((*ltephycontext)[i].num_downlink_channels == -1) {
            (*ltephycontext)[i].num_downlink_channels++;
            (*ltephycontext)[i].downlink_channels[(*ltephycontext)[i].num_downlink_channels - 1] = channel;
            return; // Channel added successfully
        }
    }
}

