        // Add the new channel to the LTE PHY context
        ltephycontext->num_downlink_channels++;
        ltephycontext->downlink_channels[ltephycontext->num_downlink_channels - 1] = downlink_channel;
    }
}

// Define the function to read a potentially large text file line by line, dynamically allocating memory for each line
void read_file(char *filename) {
    // Open the file in read mode
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Define a buffer for reading lines from the file
    char line[1024];

    // Read each line of the file and dynamically allocate memory for it
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Remove any trailing newline characters
        int len = strlen(line);
        if (line[len - 1] == '\n') {
            line[len - 1] = '\0';
        }

        // Split the line into comma-separated values
        char *values[10];
        int num_values = 0;
        char *token = strtok(line, ",");
        while (token != NULL) {
            values[num_values++] = token;
            token = strtok(NULL, ",");
        }

        // Check if the line has the correct number of values
        if (num_values < 3) {
            printf("Error: invalid number of values in line %s\n", line);
            continue;
        }

        // Convert the values to integers and add them to the LTE PHY context
        int ci = atoi(values[0]);
        int frequency_band = atoi(values[1]);
        int downlink_channel = atoi(values[2]);
        add_channel(&ltephycontext, ci, frequency_band, downlink_channel);
    }

    // Close the file
    fclose(fp);
}

