    printf("%d,%d,", ltephycontext->ci, ltephycontext->frequency_band);
    for (int i = 0; i < ltephycontext->num_downlink_channels; i++) {
        if (i > 0) {
            printf(",");
        }
        printf("%d", ltephycontext->downlink_channels[i]);
    }
    printf("\n");
}

// Define the function to calculate the average of the last two fields in a LTE PHY context
void calculate_average(LTEPHYCONTEXT *ltephycontext) {
    if (ltephycontext->num_downlink_channels < 2) {
        return;
    }
    int sum = ltephycontext->downlink_channels[ltephycontext->num_downlink_channels - 1] + ltephycontext->downlink_channels[ltephycontext->num_downlink_channels - 2];
    float average = (float)sum / 2.0;
    printf("%d,%f\n", ltephycontext->ci, average);
}

// Define the main function to demonstrate the use of the functions defined above
