    read_file("example.txt");

    // Print the contents of the LTE PHY context in a comma-separated format
    print_ltephycontext(ltephycontext);

    // Calculate the average of the last two fields in the LTE PHY context
    calculate_average(ltephycontext);

    // Free the memory allocated for the dynamic array of LTE PHY contexts
    free(ltephycontext);

    return 0;
}
