// Define the structure for a network device connection record
typedef struct {
    int id; // unique identifier for the device
    char *network_type; // type of network (e.g., Wi-Fi, cellular)
    char *connection_status; // current status of the connection (e.g., connected, disconnected)
    float quality_score; // signal strength or other metric for connection quality
    int flags; // flags indicating the current state of the connection
    time_t last_update; // timestamp representing the last update time of the connection
} DEVICE_CONN_RECORD;

// Define a linked list data structure to store the network device connection records
typedef struct {
    DEVICE_CONN_RECORD *head;
    DEVICE_CONN_RECORD *tail;
} DEVICE_CONN_LIST;

// Function to initialize and populate the network device connection list
void init_device_conn_list(int N, int seed, float quality_threshold, bool enable_logging) {
    // Initialize the linked list data structure
    DEVICE_CONN_LIST *list = malloc(sizeof(DEVICE_CONN_LIST));
    list->head = NULL;
    list->tail = NULL;

    // Generate random numbers for each connection record
    srand(seed);
    int i;
    for (i = 0; i < N; i++) {
        DEVICE_CONN_RECORD *record = malloc(sizeof(DEVICE_CONN_RECORD));
        record->id = i + 1;
        record->network_type = "Wi-Fi"; // default network type
        record->connection_status = "connected"; // default connection status
        record->quality_score = (float)rand() / RAND_MAX * 100; // random quality score between 0 and 100
        record->flags = 0; // no flags set by default
        record->last_update = time(NULL); // current timestamp

        // Add the new connection record to the linked list
        if (list->head == NULL) {
            list->head = record;
            list->tail = record;
        } else {
            list->tail->next = record;
            list->tail = record;
        }
    }

    // Filter out connections with a quality score below the threshold
    DEVICE_CONN_RECORD *current = list->head;
    while (current != NULL) {
        if (current->quality_score < quality_threshold) {
            DEVICE_CONN_RECORD *next = current->next;
            free(current);
            current = next;
        } else {
            current = current->next;
        }
    }

    // Log any failures during population process
    if (enable_logging) {
        printf("Populating network device connection list...\n");
        for (i = 0; i < N; i++) {
            DEVICE_CONN_RECORD *record = list->head;
            while (record != NULL) {
                if (record->quality_score < quality_threshold) {
                    printf("Connection %d: Quality score below threshold (%f)\n", record->id, record->quality_score);
                }
                record = record->next;
            }
        }
    }
}

// Function to update the quality threshold based on external network conditions
void update_quality_threshold(float new_threshold) {
    // Update the quality threshold in the linked list data structure
    DEVICE_CONN_RECORD *current = list->head;
    while (current != NULL) {
        if (current->quality_score < new_threshold) {
            current->flags |= 1 << 0; // set flag for connection with low quality score
        } else {
            current->flags &= ~(1 << 0); // clear flag for connection with high quality score
        }
        current = current->next;
    }
}

// Function to handle concurrent modifications safely and efficiently
void modify_device_conn_list(int id, char *network_type, char *connection_status, float quality_score) {
    // Find the connection record with the specified ID
    DEVICE_CONN_RECORD *record = list->head;
    while (record != NULL && record->id != id) {
        record = record->next;
    }

    // Update the connection record if found
    if (record != NULL) {
        record->network_type = network_type;
        record->connection_status = connection_status;
        record->quality_score = quality_score;
        record->last_update = time(NULL);
    } else {
        // Add a new connection record if not found
        DEVICE_CONN_RECORD *new_record = malloc(sizeof(DEVICE_CONN_RECORD));
        new_record->id = id;
        new_record->network_type = network_type;
        new_record->connection_status = connection_status;
        new_record->quality_score = quality_score;
        new_record->last_update = time(NULL);

        // Add the new connection record to the linked list
        if (list->head == NULL) {
            list->head = new_record;
            list->tail = new_record;
        } else {
            list->tail->next = new_record;
            list->tail = new_record;
        }
    }
}

// Function to handle memory allocation and deallocation efficiently
void free_device_conn_list() {
    DEVICE_CONN_RECORD *current = list->head;
    while (current != NULL) {
        DEVICE_CONN_RECORD *next = current->next;
        free(current);
        current = next;
    }
}
