}

// Function to add a new channel to the dynamic array of LTEPHYCONTEXT structures
void add_channel(ltephycontext **array, int num_elements, int ci, int frequency_band) {
    // Check if the array is full
    if (num_elements == 0) {
        printf("Error: Array is full\n");
        return;
    }

    // Find the first empty slot in the array
    int i = 0;
    while ((*array)[i].ci != -1) {
        i++;
