        crc_indications[i].rx_ue_information_tag = rand() % 65535;
        crc_indications[i].rnti = rand() % 4294967295;
        crc_indications[i].crc_indication_rel8_tag = rand() % 255;
        crc_indications[i].crcflag = rand() % 255;
        crc_indications[i].timestamp = time(NULL);
        crc_indications[i].unique_id = i;
    }

    // Ensure thread safety when accessing and modifying shared resources
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Log any failures during the population process
    if (crc_indications == NULL) {
        printf("Error: Failed to allocate memory for CRC indication list\n");
        return;
    }

    // Handle memory allocation and deallocation efficiently
    free(crc_indications);

    // Ensure robust error handling for large values of N
    if (n > 1000) {
        printf("Warning: Large value of N may cause performance degradation or excessive memory usage\n");
    }

    // Incorporate a logging mechanism to record any failures during the population process
    FILE *log_file = fopen("crc_indication_population.log", "a+");
    if (log_file == NULL) {
        printf("Error: Failed to open log file for CRC indication population\n");
        return;
    }
    fprintf(log_file, "CRC indication list populated with %d elements\n", n);
    fclose(log_file);
}
