// Function to populate the collection of packets based on input parameters
int populate_packets(int N, unsigned long seed, size_t packet_size, char payload_type, time_t timestamp_granularity) {
    // Validate input parameters
    if (N < 0 || seed <= 0 || packet_size <= 0 || timestamp_granularity <= 0) {
        return -1;
    }

    // Allocate memory for the packets
    packets = malloc(sizeof(Packet) * N);
    if (packets == NULL) {
        return -2;
    }

    // Initialize the mutex and set the number of packets to 0
    pthread_mutex_init(&mutex, NULL);
    num_packets = 0;

    // Generate random numbers for the sequence numbers and timestamps
    srand(seed);
    for (int i = 0; i < N; ++i) {
        packets[i].sequence_number = rand();
        packets[i].timestamp = time(NULL);
    }

    // Set the packet size and payload type
    for (int i = 0; i < N; ++i) {
        packets[i].packet_length = packet_size;
        switch (payload_type) {
            case 'A':
                packets[i].payload_data = "Hello, world!";
                break;
            case 'B':
                packets[i].payload_data = "Goodbye, cruel world...";
                break;
            default:
                packets[i].payload_data = NULL;
        }
    }

    // Increment the number of packets and return success
    num_packets += N;
    return 0;
}

// Function to add a new packet to the collection
int add_packet(Packet *packet) {
    // Validate input parameters
    if (packet == NULL) {
        return -1;
    }

    // Acquire the mutex and check if the collection is full
    pthread_mutex_lock(&mutex);
    if (num_packets >= MAX_PACKETS) {
        pthread_mutex_unlock(&mutex);
        return -2;
    }

    // Add the packet to the collection and increment the number of packets
    packets[num_packets++] = *packet;
    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to remove a packet from the collection
int remove_packet(Packet *packet) {
    // Validate input parameters
    if (packet == NULL) {
        return -1;
    }

    // Acquire the mutex and check if the collection is empty
    pthread_mutex_lock(&mutex);
    if (num_packets <= 0) {
        pthread_mutex_unlock(&mutex);
        return -2;
    }

    // Find the packet in the collection and remove it
    for (int i = 0; i < num_packets; ++i) {
        if (packets[i].sequence_number == packet->sequence_number && packets[i].timestamp == packet->timestamp) {
            memmove(&packets[i], &packets[i + 1], sizeof(Packet) * (num_packets - i - 1));
            --num_packets;
            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }

    // If the packet is not found, return an error
    pthread_mutex_unlock(&mutex);
    return -3;
}

// Function to get a packet from the collection by sequence number and timestamp
Packet *get_packet(int sequence_number, time_t timestamp) {
    // Validate input parameters
    if (sequence_number <= 0 || timestamp <= 0) {
        return NULL;
    }

    // Acquire the mutex and check if the collection is empty
    pthread_mutex_lock(&mutex);
    if (num_packets <= 0) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Find the packet in the collection and return it
    for (int i = 0; i < num_packets; ++i) {
        if (packets[i].sequence_number == sequence_number && packets[i].timestamp == timestamp) {
            pthread_mutex_unlock(&mutex);
            return &packets[i];
        }
    }

    // If the packet is not found, return an error
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Function to get all packets from the collection
Packet **get_all_packets() {
    // Acquire the mutex and check if the collection is empty
    pthread_mutex_lock(&mutex);
    if (num_packets <= 0) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Allocate memory for the packets and copy them into an array
    Packet **packets = malloc(sizeof(Packet *) * num_packets);
    memcpy(packets, this->packets, sizeof(Packet) * num_packets);

    // Release the mutex and return the array of packets
    pthread_mutex_unlock(&mutex);
    return packets;
}

// Function to clear all packets from the collection
void clear_packets() {
    // Acquire the mutex and set the number of packets to 0
    pthread_mutex_lock(&mutex);
    num_packets = 0;
    pthread_mutex_unlock(&mutex);
}
