#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>

// Define the structure to hold connection metadata
typedef struct {
    int fd; // file descriptor for the socket
    char *peer_addr; // peer address as a string
    int state; // current state of the connection (e.g., ESTABLISHED, CLOSED)
    time_t last_activity; // timestamp of the last activity on this connection
} conn_metadata_t;

// Define the pool structure to hold the connections
typedef struct {
    int size; // current size of the pool
    int capacity; // maximum capacity of the pool
    conn_metadata_t *connections; // array of connections
} connection_pool_t;

// Initialize a new connection pool with the given initial size
connection_pool_t* init_connection_pool(int initial_size) {
    connection_pool_t *pool = (connection_pool_t*) malloc(sizeof(connection_pool_t));
    if (!pool) {
        perror("Failed to allocate memory for the connection pool");
        return NULL;
    }

    // Initialize the pool size and capacity
    pool->size = initial_size;
    pool->capacity = initial_size;

    // Allocate memory for the connections array
    pool->connections = (conn_metadata_t*) malloc(sizeof(conn_metadata_t) * initial_size);
    if (!pool->connections) {
        perror("Failed to allocate memory for the connections array");
        free(pool);
        return NULL;
    }

    // Initialize each connection in the pool with default values
    for (int i = 0; i < initial_size; i++) {
        pool->connections[i].fd = -1;
        pool->connections[i].peer_addr = NULL;
        pool->connections[i].state = CLOSED;
        pool->connections[i].last_activity = 0;
    }

    return pool;
}

// Add a new connection to the pool, growing the pool if necessary
int add_connection(connection_pool_t *pool, int fd) {
    // Check if the pool is full and needs to be grown
    if (pool->size == pool->capacity) {
        // Double the capacity of the pool
        pool->capacity *= 2;

        // Reallocate memory for the connections array
        conn_metadata_t *new_connections = (conn_metadata_t*) realloc(pool->connections, sizeof(conn_metadata_t) * pool->capacity);
        if (!new_connections) {
            perror("Failed to grow the connection pool");
            return -1;
        }

        // Update the connections array and size
        pool->connections = new_connections;
        pool->size++;
    }

    // Initialize the new connection with default values
    pool->connections[pool->size].fd = fd;
    pool->connections[pool->size].peer_addr = NULL;
    pool->connections[pool->size].state = CLOSED;
    pool->connections[pool->size].last_activity = 0;

    return 0;
}

// Remove a connection from the pool, shrinking the pool if necessary
int remove_connection(connection_pool_t *pool, int fd) {
    // Find the index of the connection to be removed
    int i;
    for (i = 0; i < pool->size; i++) {
        if (pool->connections[i].fd == fd) {
            break;
        }
    }

    // Check if the connection was found
    if (i == pool->size) {
        printf("Connection not found in the pool\n");
        return -1;
    }

    // Remove the connection from the pool by shifting all subsequent connections back one index
    for (int j = i + 1; j < pool->size; j++) {
        pool->connections[j - 1] = pool->connections[j];
    }

    // Decrement the size of the pool and reallocate memory if necessary
    pool->size--;
    if (pool->size == pool->capacity / 2) {
        pool->capacity /= 2;

        conn_metadata_t *new_connections = (conn_metadata_t*) realloc(pool->connections, sizeof(conn_metadata_t) * pool->capacity);
        if (!new_connections) {
            perror("Failed to shrink the connection pool");
            return -1;
        }

        pool->connections = new_connections;
    }

    return 0;
}

// Update the metadata of a connection in the pool
int update_connection(connection_pool_t *pool, int fd, char *peer_addr, int state) {
    // Find the index of the connection to be updated
    int i;
    for (i = 0; i < pool->size; i++) {
        if (pool->connections[i].fd == fd) {
            break;
        }
    }

    // Check if the connection was found
    if (i == pool->size) {
        printf("Connection not found in the pool\n");
        return -1;
    }

    // Update the metadata of the connection
    pool->connections[i].peer_addr = peer_addr;
    pool->connections[i].state = state;
    pool->connections[i].last_activity = time(NULL);

    return 0;
}

// Reap expired connections based on the inactivity timeout
int reap_expired_connections(connection_pool_t *pool, int inactivity_timeout) {
    // Iterate over all connections and check if they are expired
    for (int i = 0; i < pool->size; i++) {
        // Check if the connection is expired based on the inactivity timeout
        if (time(NULL) - pool->connections[i].last_activity > inactivity_timeout) {
            // Remove the expired connection from the pool
            remove_connection(pool, pool->connections[i].fd);
        }
    }

    return 0;
}

// Buffer incoming TCP packets and handle missing data gracefully
int buffer_packet(connection_pool_t *pool, int fd, char *data, int len) {
    // Find the connection associated with the file descriptor
    int i;
    for (i = 0; i < pool->size; i++) {
        if (pool->connections[i].fd == fd) {
            break;
        }
    }

    // Check if the connection was found
    if (i == pool->size) {
        printf("Connection not found in the pool\n");
        return -1;
    }

    // Update the last activity timestamp of the connection
    pool->connections[i].last_activity = time(NULL);

    // Handle missing data gracefully by buffering the packet and waiting for more data to arrive
    if (pool->connections[i].state == WAITING) {
        // Buffer the incoming packet
        pool->connections[i].buffer = realloc(pool->connections[i].buffer, pool->connections[i].buffer_len + len);
        memcpy(pool->connections[i].buffer + pool->connections[i].buffer_len, data, len);
        pool->connections[i].buffer_len += len;

        // Check if the buffer is complete and finalize the connection object
        if (pool->connections[i].buffer_len == pool->connections[i].expected_len) {
            pool->connections[i].state = FINALIZED;

            // Handle the finalized connection object
            handle_finalized_connection(pool, i);
        }
    } else {
        // Handle the incoming packet as a complete connection object
        handle_complete_connection(pool, fd, data, len);
    }

    return 0;
}

// Handle a finalized connection object by updating its metadata and invoking any necessary callbacks
int handle_finalized_connection(connection_pool_t *pool, int i) {
    // Update the metadata of the finalized connection
    pool->connections[i].state = FINALIZED;
    pool->connections[i].last_activity = time(NULL);

    // Invoke any necessary callbacks for the finalized connection
    if (pool->callbacks) {
        for (int j = 0; j < pool->num_callbacks; j++) {
            if (pool->callbacks[j].fd == pool->connections[i].fd) {
                pool->callbacks[j].callback(pool->connections[i].fd, pool->connections[i].buffer, pool->connections[i].buffer_len);
                break;
            }
        }
    }

    return 0;
}

// Handle a complete connection object by updating its metadata and invoking any necessary callbacks
int handle_complete_connection(connection_pool_t *pool, int fd, char *data, int len) {
    // Update the metadata of the complete connection
    pool->connections[i].state = COMPLETE;
    pool->connections[i].last_activity = time(NULL);

    // Invoke any necessary callbacks for the complete connection
    if (pool->callbacks) {
        for (int j = 0; j < pool->num_callbacks; j++) {
            if (pool->callbacks[j].fd == pool->connections[i].fd) {
                pool->callbacks[j].callback(pool->connections[i].fd, data, len);
                break;
            }
        }
    }

    return 0;
