        initial_size = 10;
    }
    sessions = malloc(sizeof(Session) * initial_size);
    for (int i = 0; i < initial_size; i++) {
        sessions[i].user_id = -1;
        sessions[i].authenticated = false;
        sessions[i].last_activity = time(NULL);
        sessions[i].config_params = NULL;
    }
