    for (i = 0; i < session_pool_size; i++) {
        if (sessions[i].user_id == user_id) {
            break;
        }
    }
    // If the session is found, update its last activity timestamp
    if (i < session_pool_size) {
        sessions[i].last_activity = time(NULL);
    }
