        if (mac_frames[i].schedule_id <= 0 || mac_frames[i].phy_layer_status < 0) {
            printf("Error: Invalid values in MAC frame %d\n", i);
            return;
        }
    }

    // Populate the collection of scheduled tasks with the MAC frames
    TASK_RECORD *task_records = (TASK_RECORD *)malloc(M * sizeof(TASK_RECORD));
    if (!task_records) {
        printf("Error: Failed to allocate memory for the collection of scheduled tasks\n");
        return;
