// Define the data structure for a sensor reading
typedef struct {
    int type;
    time_t timestamp;
    char* identifier;
    unsigned long quality_flags;
} SensorReading;

// Define the list of sensor readings
typedef struct {
    SensorReading* readings;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} SensorReadingList;

// Initialize a new list with the given maximum size and seed value for random number generation
void init_list(SensorReadingList* list, size_t max_size, unsigned int seed) {
    list->readings = (SensorReading*)malloc(max_size * sizeof(SensorReading));
    list->capacity = max_size;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new sensor reading to the list
void add_reading(SensorReadingList* list, int type, time_t timestamp, char* identifier, unsigned long quality_flags) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&list->mutex);

    // Check if the list has reached its maximum size and truncate the oldest readings if necessary
    if (list->count == list->capacity) {
        // Truncate the oldest reading
        SensorReading* old_reading = &list->readings[0];
        free(old_reading);
        memmove(&list->readings[0], &list->readings[1], (list->count - 1) * sizeof(SensorReading));
        list->count--;
    }

    // Add the new reading to the end of the list
    SensorReading* new_reading = &list->readings[list->count];
    new_reading->type = type;
    new_reading->timestamp = timestamp;
    new_reading->identifier = identifier;
    new_reading->quality_flags = quality_flags;
    list->count++;

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&list->mutex);
}

// Remove a sensor reading from the list by its index
void remove_reading(SensorReadingList* list, size_t index) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&list->mutex);

    // Check if the index is valid and remove the reading
    if (index < list->count) {
        SensorReading* old_reading = &list->readings[index];
        free(old_reading);
        memmove(&list->readings[index], &list->readings[index + 1], (list->count - index - 1) * sizeof(SensorReading));
        list->count--;
    }

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&list->mutex);
}

// Get a sensor reading from the list by its index
SensorReading* get_reading(SensorReadingList* list, size_t index) {
    // Lock the mutex before accessing the list
    pthread_mutex_lock(&list->mutex);

    // Check if the index is valid and return the reading
    if (index < list->count) {
        SensorReading* reading = &list->readings[index];
        pthread_mutex_unlock(&list->mutex);
        return reading;
    } else {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }
}

// Get the number of sensor readings in the list
size_t get_count(SensorReadingList* list) {
    // Lock the mutex before accessing the list
    pthread_mutex_lock(&list->mutex);

    // Return the number of readings
    size_t count = list->count;

    // Unlock the mutex after accessing the list
    pthread_mutex_unlock(&list->mutex);

    return count;
}

// Free the memory allocated for the list
void free_list(SensorReadingList* list) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&list->mutex);

    // Free the memory allocated for the readings
    free(list->readings);
    list->readings = NULL;
    list->capacity = 0;
    list->count = 0;

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&list->mutex);
