// Define the condition variable for signaling when an element is added or removed from the array
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Define the function to add a new element to the array
void add_element(NFAPI_CRC_INDICATION_PDU_T *element) {
    // Acquire the mutex for synchronizing access to the array
    pthread_mutex_lock(&mutex);

    // Check if the array is full and needs to be resized
    if (array_size == 10000) {
        // Resize the array by doubling its size
        array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array_size * 2));
        // Update the new size of the array
        array_size *= 2;
    }

    // Add the new element to the end of the array
    array[array_size++] = *element;

    // Signal any waiting threads that an element has been added
    pthread_cond_signal(&cond);

    // Release the mutex for synchronizing access to the array
    pthread_mutex_unlock(&mutex);
}

// Define the function to remove an element from the array by its index
void remove_element(uint32_t index) {
    // Acquire the mutex for synchronizing access to the array
    pthread_mutex_lock(&mutex);

    // Check if the index is valid and within the bounds of the array
    if (index < 0 || index >= array_size) {
        printf("Invalid index: %d\n", index);
        return;
    }

    // Remove the element from the array by shifting all elements after it to the left
    for (uint32_t i = index + 1; i < array_size; i++) {
        array[i - 1] = array[i];
    }

    // Decrement the size of the array
    array_size--;

