    public class RandomValueGenerator
    {
        private List<Range> ranges = new List<Range>();

        public void AddRange(int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

            ranges.Add(new Range(min, max));
        }

        public void RemoveRange(int index)
        {
            if (index < 0 || index >= ranges.Count)
                throw new ArgumentOutOfRangeException("Index must be within the range of valid indices.");

            ranges.RemoveAt(index);
        }

        public void ShiftRanges(int offset)
        {
            foreach (var range in ranges)
            {
                range.Min += offset;
                range.Max += offset;
            }
        }

        public void ScaleRanges(float factor)
        {
            if (factor <= 0)
                throw new ArgumentException("Factor must be greater than zero.");

            foreach (var range in ranges)
            {
                range.Min *= factor;
                range.Max *= factor;
            }
        }

        public void MergeRanges(int index1, int index2)
        {
            if (index1 < 0 || index1 >= ranges.Count)
                throw new ArgumentOutOfRangeException("Index1 must be within the range of valid indices.");

            if (index2 < 0 || index2 >= ranges.Count)
                throw new ArgumentOutOfRangeException("Index2 must be within the range of valid indices.");

            var range1 = ranges[index1];
            var range2 = ranges[index2];

            if (!range1.Overlaps(range2))
                return;

            ranges.RemoveAt(index2);
            ranges.Add(new Range(Math.Min(range1.Min, range2.Min), Math.Max(range1.Max, range2.Max)));
        }

        public float GenerateFloatValue()
        {
            if (ranges.Count == 0)
                throw new InvalidOperationException("No ranges have been defined.");

            var random = new Random();
            var totalWeight = ranges.Sum(range => range.Max - range.Min + 1);
            var weightedIndex = random.Next(totalWeight);
            var currentWeight = 0;

            foreach (var range in ranges)
            {
                if (weightedIndex >= currentWeight && weightedIndex <= currentWeight + range.Max - range.Min + 1)
                    return range.Min + random.Next(range.Max - range.Min + 1);

                currentWeight += range.Max - range.Min + 1;
            }

            throw new InvalidOperationException("Failed to generate a value within the defined ranges.");
        }

        public int GenerateIntegerValue()
        {
            return (int)GenerateFloatValue();
        }

        public void Serialize(string jsonString)
        {
            var serializer = new JsonSerializer();
            using (var writer = new StringWriter())
            {
                serializer.Serialize(writer, ranges);
                jsonString = writer.ToString();
            }
        }

        public void Deserialize(string jsonString)
        {
            var deserializer = new JsonSerializer();
            using (var reader = new StringReader(jsonString))
            {
                ranges = deserializer.Deserialize<List<Range>>(reader);
            }
        }

        public float CalculateMean()
        {
            var sum = 0f;
            foreach (var range in ranges)
            {
                sum += range.Min + range.Max;
            }

            return sum / (ranges.Count * 2);
        }

        public float CalculateStandardDeviation()
        {
            var mean = CalculateMean();
            var squaredDifferences = ranges.Select(range => Math.Pow((range.Min + range.Max) - mean, 2));
            return (float)Math.Sqrt(squaredDifferences.Sum() / (ranges.Count * 2 - 1));
        }

        public int FindSmallestValue()
        {
            var smallest = int.MaxValue;
            foreach (var range in ranges)
            {
                if (range.Min < smallest)
                    smallest = range.Min;
            }

            return smallest;
        }

        public int FindLargestValue()
        {
            var largest = int.MinValue;
            foreach (var range in ranges)
            {
                if (range.Max > largest)
                    largest = range.Max;
            }

            return largest;
        }

        public float GenerateWeightedFloatValue(float[] weights)
        {
            if (weights == null || weights.Length != ranges.Count)
                throw new ArgumentException("Weights must be a non-null array of length equal to the number of ranges.");

            var random = new Random();
            var totalWeight = weights.Sum();
            var weightedIndex = random.Next(totalWeight);
            var currentWeight = 0;

            foreach (var range in ranges)
            {
                if (weightedIndex >= currentWeight && weightedIndex <= currentWeight + weights[range])
                    return range.Min + random.Next(range.Max - range.Min + 1);

                currentWeight += weights[range];
            }

            throw new InvalidOperationException("Failed to generate a value within the defined ranges.");
        }

        public int GenerateWeightedIntegerValue(float[] weights)
        {
            return (int)GenerateWeightedFloatValue(weights);
        }

        public void ValidateValues(float[] constraints)
        {
            if (constraints == null || constraints.Length != ranges.Count * 2)
                throw new ArgumentException("Constraints must be a non-null array of length equal to twice the number of ranges.");

            foreach (var range in ranges)
            {
                for (int i = 0; i < 2; i++)
                {
                    if (constraints[range.Index * 2 + i] > constraints[range.Index * 2 + i + 1])
                        throw new ArgumentException("Constraints must be in ascending order.");
                }
            }
        }

        public void LogOperation(string operation, params object[] args)
        {
            // Implement logging mechanism here
        }

        public string ExportData()
        {
            // Implement data export mechanism here
        }
    }

    public class Range
    {
        public int Min { get; set; }
        public int Max { get; set; }

        public Range(int min, int max)
        {
            Min = min;
            Max = max;
        }

        public bool Overlaps(Range other)
        {
            return !(Min > other.Max || Max < other.Min);
        }
    }
}
