record_t** get_user_data(int num_records) {
    // Allocate memory for the arrays of offsets and keys
    long* offset_array = malloc(num_records * sizeof(long));
    int* key_array = malloc(num_records * sizeof(int));

    // Initialize the arrays with random integers within a specified range
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = rand() % 1000;
        key_array[i] = rand() % 1000;
