#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the structure for UE context information record
typedef struct {
    int ue_id;
    char serving_cell[10];
    int mobility_status;
    time_t last_update_time;
} UE_CONTEXT_INFO_RECORD;

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to manage the dynamic collection of UE context information records
void populate_ue_context(int num_records, int seed, bool degraded) {
    // Initialize the random number generator with the given seed value
    srand(seed);

    // Create a mutex for thread-safe operations
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the UE context information records
    UE_CONTEXT_INFO_RECORD *records = (UE_CONTEXT_INFO_RECORD *)malloc(num_records * sizeof(UE_CONTEXT_INFO_RECORD));

    // Initialize the records with default values
    for (int i = 0; i < num_records; i++) {
        records[i].ue_id = i + 1;
        strcpy(records[i].serving_cell, "Serving Cell");
        records[i].mobility_status = 0;
        records[i].last_update_time = time(NULL);
    }

    // Populate the records with random values if not in degraded mode
    if (!degraded) {
        for (int i = 0; i < num_records; i++) {
            records[i].ue_id = rand() % 100 + 1;
            strcpy(records[i].serving_cell, "Serving Cell");
            records[i].mobility_status = rand() % 2;
            records[i].last_update_time = time(NULL);
        }
    }

    // Create a list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_records * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the list with default values
    for (int i = 0; i < num_records; i++) {
        crc_indication_pdu_list[i].rx_ue_information_tag = rand() % 100 + 1;
        crc_indication_pdu_list[i].rnti = rand() % 100 + 1;
        crc_indication_pdu_list[i].crc_indication_rel8_tag = rand() % 2;
    }

    // Populate the list with random values if not in degraded mode
    if (!degraded) {
        for (int i = 0; i < num_records; i++) {
            crc_indication_pdu_list[i].rx_ue_information_tag = rand() % 100 + 1;
            crc_indication_pdu_list[i].rnti = rand() % 100 + 1;
            crc_indication_pdu_list[i].crc_indication_rel8_tag = rand() % 2;
        }
    }

    // Find the largest integer in the list and print its corresponding string
    int largest_integer = -1;
    char *largest_string = NULL;
    for (int i = 0; i < num_records; i++) {
        if (crc_indication_pdu_list[i].rx_ue_information_tag > largest_integer) {
            largest_integer = crc_indication_pdu_list[i].rx_ue_information_tag;
            largest_string = records[i].serving_cell;
        }
    }
    printf("Largest integer: %d\n", largest_integer);
    printf("Corresponding string: %s\n", largest_string);

    // Initialize and manage the long, int, and char arrays and their respective records
    long *long_array = (long *)malloc(num_records * sizeof(long));
    int *int_array = (int *)malloc(num_records * sizeof(int));
    char *char_array = (char *)malloc(num_records * sizeof(char));
    for (int i = 0; i < num_records; i++) {
        long_array[i] = records[i].ue_id;
        int_array[i] = records[i].mobility_status;
        char_array[i] = records[i].serving_cell[0];
    }

    // Print the contents of the arrays and their respective records
    printf("Long array: ");
    for (int i = 0; i < num_records; i++) {
        printf("%ld ", long_array[i]);
    }
    printf("\n");
    printf("Int array: ");
    for (int i = 0; i < num_records; i++) {
        printf("%d ", int_array[i]);
    }
    printf("\n");
    printf("Char array: ");
    for (int i = 0; i < num_records; i++) {
        printf("%c ", char_array[i]);
    }
    printf("\n");

    // Clean up the memory allocated for the UE context information records and the list of NFAPI_CRC_INDICATION_PDU_T structures
    free(records);
    free(crc_indication_pdu_list);
    free(long_array);
    free(int_array);
    free(char_array);
