#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Task {
    int priority;
    char *title;
} Task;

Task* fetchTasks() {
    // Fetch tasks from remote server using RESTful API client
    Task *tasks = NULL;
    size_t num_tasks = 0;
    if (fetch_tasks(&tasks, &num_tasks)) {
        return NULL;
    }

    // Validate task titles to prevent buffer overflows
    for (size_t i = 0; i < num_tasks; i++) {
        size_t title_len = strlen(tasks[i].title);
        if (title_len > MAX_TITLE_LENGTH) {
            free(tasks[i].title);
            tasks[i].title = NULL;
        }
    }

    // Store tasks in local cache using a thread-safe mechanism
    pthread_mutex_lock(&cache_mutex);
    for (size_t i = 0; i < num_tasks; i++) {
        Task *task = malloc(sizeof(Task));
        task->priority = tasks[i].priority;
        task->title = strdup(tasks[i].title);
        cache_add(task);
    }
    pthread_mutex_unlock(&cache_mutex);

    // Free allocated memory to avoid memory leaks
    for (size_t i = 0; i < num_tasks; i++) {
        free(tasks[i].title);
    }
    free(tasks);

    return cache_get();
}
