#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <locale.h>
#include <iconv.h>

// Define the structure to hold the resource bundle
typedef struct {
    char **items;
    int num_items;
} ResourceBundle;

// Define the function to load the resource bundle from a file
int loadResourceBundle(const char *filepath, const char *format, ResourceBundle *bundle) {
    // Open the file for reading
    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    // Set the locale to UTF-8
    setlocale(LC_ALL, "en_US.UTF-8");

    // Create a new iconv converter for converting between UTF-8 and the file format
    iconv_t conv = iconv_open("UTF-8", format);
    if (conv == (iconv_t) -1) {
        perror("iconv_open");
        fclose(fp);
        return -1;
    }

    // Allocate memory for the resource bundle
    bundle->items = malloc(sizeof(char *) * 1024);
    if (bundle->items == NULL) {
        perror("malloc");
        fclose(fp);
        iconv_close(conv);
        return -1;
    }

    // Read the file line by line and parse each non-comment line
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Trim leading and trailing whitespace from the line
        char *trimmed = trim(line);

        // Ignore empty lines and comments
        if (strlen(trimmed) == 0 || trimmed[0] == '#') {
            continue;
        }

        // Convert the line to UTF-8 using iconv
        char *utf8 = convert(conv, trimmed);
        if (utf8 == NULL) {
            perror("convert");
            fclose(fp);
            free(line);
            iconv_close(conv);
            return -1;
        }

        // Count the number of unique items in the bundle ignoring case sensitivity
        int num_items = countUniqueItems(utf8, &bundle->items[bundle->num_items]);
        if (num_items == -1) {
            perror("countUniqueItems");
            fclose(fp);
            free(line);
            iconv_close(conv);
            return -1;
        }

        // Increment the number of items in the bundle
        bundle->num_items += num_items;
    }

    // Close the file and iconv converter
    fclose(fp);
    iconv_close(conv);

    // Return the number of items in the bundle
    return bundle->num_items;
}

// Define the function to trim leading and trailing whitespace from a string
char *trim(const char *str) {
    size_t len = strlen(str);
    size_t start = 0;
    while (isspace(str[start])) {
        start++;
    }
    size_t end = len - 1;
    while (isspace(str[end]) || str[end] == '\n') {
        end--;
    }
    return strndup(&str[start], end - start + 1);
}

// Define the function to convert a string from one encoding to another using iconv
char *convert(iconv_t conv, const char *str) {
    size_t len = strlen(str);
    size_t outlen = len * 4 + 1;
    char *outbuf = malloc(outlen);
    if (outbuf == NULL) {
        perror("malloc");
        return NULL;
    }
    size_t inlen = len;
    char *inbuf = strdup(str);
    iconv(conv, &inbuf, &inlen, &outbuf, &outlen);
    if (errno == E2BIG) {
        outlen += 1024;
        outbuf = realloc(outbuf, outlen);
        if (outbuf == NULL) {
            perror("realloc");
            return NULL;
        }
        iconv(conv, &inbuf, &inlen, &outbuf, &outlen);
    }
    if (errno != 0) {
        perror("iconv");
        free(outbuf);
        return NULL;
    }
    outbuf[outlen - 1] = '\0';
    return outbuf;
}

// Define the function to count the number of unique items in a string ignoring case sensitivity
int countUniqueItems(const char *str, char **items) {
    int num_items = 0;
    for (char *item = strtok((char *) str, "\n"); item != NULL; item = strtok(NULL, "\n")) {
        bool found = false;
        for (int i = 0; i < num_items; i++) {
            if (strcasecmp(item, items[i]) == 0) {
                found = true;
                break;
            }
        }
        if (!found) {
            items[num_items] = strdup(item);
            num_items++;
        }
    }
    return num_items;
}
