class VideoFrameQueue {
public:
    // Constructor
    VideoFrameQueue(int maxSize) : maxSize_(maxSize), frames_(), frameData_() {}

    // Destructor
    ~VideoFrameQueue() { clear(); }

    // Push a new frame to the queue
    void push(const FrameData& frame) {
        if (frames_.size() >= maxSize_) {
            frames_.pop_front();
        }
        frames_.push_back(frame);
        frameData_.push_back(frame.data());
    }

    // Pop the oldest frame from the queue
    FrameData pop() {
        if (frames_.empty()) {
            return {};
        }
        auto frame = frames_.front();
        frames_.pop_front();
        frameData_.pop_front();
        return frame;
    }

    // Clear the queue
    void clear() {
        frames_.clear();
        frameData_.clear();
    }

    // Get the size of the queue
    int size() const { return frames_.size(); }

private:
    // Maximum size of the queue
    int maxSize_;

    // Queue of frames
    std::deque<FrameData> frames_;

    // Queue of frame data pointers
    std::deque<void*> frameData_;
};
```
