// Custom mutex mechanism for thread-safe access and modification of the list
pthread_mutex_t lock;

// Structure to hold a list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T *data;
} List;

// Function to create a new list with the given initial capacity
List* createList(int capacity) {
    List *list = malloc(sizeof(List));
    if (list == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = capacity;
    list->data = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    return list;
}

// Function to add a new element to the list
void addElement(List *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&lock);
    if (list->size == list->capacity) {
        // Double the capacity of the list if it is full
        int newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newData == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        list->capacity = newCapacity;
        list->data = newData;
    }
    list->data[list->size++] = element;
    pthread_mutex_unlock(&lock);
}

// Function to remove an element from the list by its index
void removeElement(List *list, int index) {
    pthread_mutex_lock(&lock);
    if (index >= 0 && index < list->size) {
        // Shift all elements after the removed element to the left
        for (int i = index; i < list->size - 1; i++) {
            list->data[i] = list->data[i + 1];
        }
        list->size--;
    } else {
        fprintf(stderr, "Index out of bounds\n");
    }
    pthread_mutex_unlock(&lock);
}

// Function to get the size of the list
int getSize(List *list) {
    return list->size;
}

// Function to get an element from the list by its index
NFAPI_CRC_INDICATION_PDU_T getElement(List *list, int index) {
    if (index >= 0 && index < list->size) {
        return list->data[index];
    } else {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }
}

// Function to validate a JSON string against a predefined schema
bool validateJSON(const char *jsonString, const char *schema) {
    json_error_t error;
    json_t *root = json_loads(jsonString, 0, &error);
    if (!root) {
        fprintf(stderr, "Invalid JSON: %s\n", error.text);
        return false;
    }
    json_t *schemaRoot = json_loads(schema, 0, NULL);
    if (!schemaRoot) {
        fprintf(stderr, "Invalid schema\n");
        return false;
    }
    bool valid = json_validate(root, schemaRoot, &error);
    if (!valid) {
        fprintf(stderr, "JSON does not conform to schema: %s\n", error.text);
    }
    json_decref(root);
    json_decref(schemaRoot);
    return valid;
}

// Function to calculate the MD5 hash of a file
void calculateMD5(const char *filename, unsigned char *hash) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("fstat");
        close(fd);
        exit(EXIT_FAILURE);
    }
    unsigned char buffer[4096];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    while (st.st_size > 0) {
        int bytesRead = read(fd, buffer, sizeof(buffer));
        if (bytesRead == -1) {
            perror("read");
            close(fd);
            exit(EXIT_FAILURE);
        }
        MD5_Update(&ctx, buffer, bytesRead);
        st.st_size -= bytesRead;
    }
    MD5_Final(hash, &ctx);
    close(fd);
}

// Function to calculate the SHA-256 hash of a file
void calculateSHA256(const char *filename, unsigned char *hash) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("fstat");
        close(fd);
        exit(EXIT_FAILURE);
    }
    unsigned char buffer[4096];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    while (st.st_size > 0) {
        int bytesRead = read(fd, buffer, sizeof(buffer));
        if (bytesRead == -1) {
            perror("read");
            close(fd);
            exit(EXIT_FAILURE);
        }
        SHA256_Update(&ctx, buffer, bytesRead);
        st.st_size -= bytesRead;
    }
    SHA256_Final(hash, &ctx);
    close(fd);
}

