    NETWORK_PERFORMANCE_STATS_T *network_performance_stats = (NETWORK_PERFORMANCE_STATS_T *)malloc(sizeof(NETWORK_PERFORMANCE_STATS_T) * M);

    // Populate the dynamic array of user sessions and network performance metrics using random values
    for (int i = 0; i < M; i++) {
        user_session_log[i].UE_ID = rand() % 1000000 + 1;
        user_session_log[i].SESSION_TIMESTAMP = time(NULL);
        user_session_log[i].CONNECTIVITY_STATUS = "connected";
        user_session_log[i].DATA_USAGE_REPORT = rand() % 1000 + 1;

        network_performance_stats[i].NETWORK_NODE_ID = i + 1;
        network_performance_stats[i].TIMESTAMP = time(NULL);
