        EVP_EncryptUpdate(ctx, network_performance_stats[i].NETWORK_NODE_ID, sizeof(network_performance_stats[i].NETWORK_NODE_ID), &seed, sizeof(seed));
        EVP_EncryptFinal(ctx, NULL, NULL);
        EVP_CIPHER_CTX_free(ctx);
    }

    // Implement a strategy to function in degraded mode if necessary
    if (M > 100) {
        M = 100;
    }

    // Ensure all data structures balance between space and time complexity, supporting multiple types of input, including integers and floating-point numbers, and handle mixed data types appropriately
    for (int i = 0; i < M; i++) {
        user_session_log[i].UE_ID = rand() % 1000000 + 1;
        user_session_log[i].SESSION_TIMESTAMP = time(NULL);
