        network_performance_stats[i].NETWORK_NODE_ID = i + 1;
        network_performance_stats[i].TIMESTAMP = time(NULL);
        network_performance_stats[i].BANDWIDTH_UTILIZATION = rand() % 100 + 1;
        network_performance_stats[i].LATENCY_STATISTICS = rand() % 100 + 1;
        network_performance_stats[i].ERROR_RATES = rand() % 100 + 1;
    }

    // Implement robust logging mechanisms to record any failures during the population process
    for (int i = 0; i < M; i++) {
        if (user_session_log[i].UE_ID == -1) {
            printf("Error: Failed to populate user session log\n");
        } else if (network_performance_stats[i].NETWORK_NODE_ID == -1) {
            printf("Error: Failed to populate network performance stats\n");
