            return;
        }
    }

    // Initialize the custom memory pool for optimization
    MEMORY_POOL_T *memory_pool = (MEMORY_POOL_T *)malloc(sizeof(MEMORY_POOL_T));
    if (memory_pool == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for custom memory pool\n");
        return;
    }
    memory_pool->memory = malloc(10000 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (memory_pool->memory == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for custom memory pool\n");
        return;
    }
    memory_pool->size = 10000;

    // Dynamically allocate memory for the CRC indication PDUs
    for (int i = 0; i < *size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
