        NFAPI_CRC_INDICATION_PDU_T *pdu = (*array)[i];
        pthread_mutex_lock(&mutex);
        pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu->RNTI = rand() % 1000000000;
        pdu->CRCFLAG = rand() % 2;
        pthread_mutex_unlock(&mutex);
    }

    // Free the memory pool when it is no longer needed
    free(memory_pool->memory);
    free(memory_pool);
