    if (array->size == array->capacity) {
        // Double the capacity of the dynamic array if it's full
        size_t new_capacity = array->capacity * 2;
        struct NFAPIData* new_data = realloc(array->data, sizeof(struct NFAPIData) * new_capacity);
        if (new_data == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for NFAPI data\n");
            pthread_mutex_unlock(&array->mutex);
            return;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    // Insert the new element at the end of the dynamic array
    array->data[array->size++] = *data;
    pthread_mutex_unlock(&array->mutex);
}

// Function to remove an element from the dynamic array
void removeNFAPIData(struct NFAPIDataArray* array, size_t index) {
    if (index >= array->size) {
        fprintf(stderr, "Error: Index out of bounds\n");
        return;
    }
    pthread_mutex_lock(&array->mutex);
    // Shift all elements after the removed element to the left
    for (size_t i = index + 1; i < array->size; i++) {
        array->data[i - 1] = array->data[i];
    }
    // Decrement the size of the dynamic array
    array->size--;
    pthread_mutex_unlock(&array->mutex);
}

// Function to retrieve an element from the dynamic array
