void addChannelToList(struct Channel **head, int frequency, int bandwidth) {
    struct Channel *newChannel = malloc(sizeof(struct Channel));
    newChannel->frequency = frequency;
    newChannel->bandwidth = bandwidth;
    newChannel->next = NULL;

    if (*head == NULL) {
        *head = newChannel;
    } else {
        struct Channel *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newChannel;
    }
