    newContext->CI = CI;
    newContext->frequencyBand = frequencyBand;
    initChannelList(&newContext->downlinkChannels);

    if (vector->contexts == NULL) {
        vector->contexts = newContext;
        vector->numContexts++;
    } else {
        struct LTEPHYCONTEXT *current = vector->contexts;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newContext;
        vector->numContexts++;
    }
}

