        addLTEPHYContextToVector(vector, CI, frequencyBand);

        // Add a new RX_UE_INFORMATION_TAG structure to the LTEPHYCONTEXT structure
        struct LTEPHYCONTEXT *context = vector->contexts;
        while (context != NULL) {
            if (context->CI == CI) {
                break;
            }
            context = context->next;
        }
        if (context == NULL) {
            printf("Error: unable to find LTEPHYCONTEXT with CI %d\n", CI);
            return;
