        struct RX_UE_INFORMATION_TAG *newTag = malloc(sizeof(struct RX_UE_INFORMATION_TAG));
        newTag->RNTI = RNTI;
        newTag->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        context->downlinkChannels = addChannelToList(context->downlinkChannels, frequencyBand, bandwidth);
    }

    fclose(file);
}

