        int frequencyBand = atoi(strtok(NULL, ","));
        int RNTI = atoi(strtok(NULL, ","));
        int CRC_INDICATION_REL8_TAG = atoi(strtok(NULL, ","));

        // Add the last two fields to the total
        total += frequencyBand;
        total += CRC_INDICATION_REL8_TAG;

        lineCount++;
    }

    fclose(file);

    float average = total / (float)lineCount;
    printf("Average of last two fields: %f\n", average);
