        } else {
            Node* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = nodes[i];
        }
        pthread_mutex_unlock(&mutex);
    }

    // Free memory for linked list nodes
    free(nodes);

    return head;
}
