struct tiff_metadata {
    int bits_per_sample;
    int samples_per_pixel;
    int compression_type;
    int extra_samples;
};

int parse_tiff_metadata(const char* filename, struct tiff_metadata* metadata) {
    TIFF* tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error opening TIFF file: %s\n", filename);
        return 1;
    }

    // Validate the file header checksum for integrity verification
    if (TIFFCheckRead(tif, 0, -1) == 0) {
        fprintf(stderr, "Error validating TIFF file: %s\n", filename);
        return 2;
    }

    // Extract the image metadata
    uint32_t width = 0;
    uint32_t height = 0;
    uint16_t bits_per_sample = 0;
    uint16_t samples_per_pixel = 0;
    uint16_t compression_type = 0;
    uint16_t extra_samples = 0;
    TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width);
    TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height);
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bits_per_sample);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel);
    TIFFGetField(tif, TIFFTAG_COMPRESSION, &compression_type);
    TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extra_samples);

    // Validate the image metadata
    if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 && bits_per_sample != 8 && bits_per_sample != 16) {
        fprintf(stderr, "Error: unsupported bits per sample: %d\n", bits_per_sample);
        return 3;
    }
    if (samples_per_pixel > 4) {
        fprintf(stderr, "Error: unsupported samples per pixel: %d\n", samples_per_pixel);
        return 4;
    }

    // Fill in the metadata struct
    metadata->bits_per_sample = bits_per_sample;
    metadata->samples_per_pixel = samples_per_pixel;
    metadata->compression_type = compression_type;
    metadata->extra_samples = extra_samples;

    // Close the TIFF file
    TIFFClose(tif);

    return 0;
}
