struct jpeg_info {
    int color_space;
    int subsampling_factors[3];
    int compression_quality;
    bool has_metadata;
    char* metadata;
};

int process_jpeg(const char* filename, struct jpeg_info* info) {
    // Open the JPEG file and read its header
    FILE* f = fopen(filename, "rb");
    if (!f) {
        return -1;
    }
    unsigned char header[2];
    fread(header, 1, 2, f);
    fclose(f);

    // Check the JPEG format and extract information
    if (header[0] == 0xFF && header[1] == 0xD8) {
        // Baseline or progressive JPEG
        int color_space = -1;
        int subsampling_factors[3];
        for (int i = 0; i < 3; i++) {
            subsampling_factors[i] = -1;
        }
        int compression_quality = -1;
        bool has_metadata = false;
        char* metadata = NULL;

        // Read the JPEG header and extract information
        f = fopen(filename, "rb");
        if (!f) {
            return -1;
        }
        unsigned char segment[2];
        while (fread(segment, 1, 2, f)) {
            // Check for the start of a new segment
            if (segment[0] == 0xFF && segment[1] >= 0xC0 && segment[1] <= 0xCF) {
                // Extract information from the segment
                switch (segment[1]) {
                    case 0xC0:
                        color_space = segment[2];
                        break;
                    case 0xC4:
                        subsampling_factors[0] = segment[3];
                        subsampling_factors[1] = segment[5];
                        subsampling_factors[2] = segment[7];
                        break;
                    case 0xC8:
                        compression_quality = segment[2];
                        break;
                }
            } else if (segment[0] == 0xFF && segment[1] >= 0xD0 && segment[1] <= 0xDD) {
                // Check for the start of a new segment
                has_metadata = true;
                metadata = malloc(sizeof(char) * 256);
                fread(metadata, 1, 256, f);
            }
        }
        fclose(f);

        // Return the extracted information
        info->color_space = color_space;
        for (int i = 0; i < 3; i++) {
            info->subsampling_factors[i] = subsampling_factors[i];
        }
        info->compression_quality = compression_quality;
        info->has_metadata = has_metadata;
        info->metadata = metadata;
    } else {
        // Unrecognized JPEG format
        return -1;
    }

    // Check the image dimensions and return an error if necessary
    int width, height;
    f = fopen(filename, "rb");
    if (!f) {
        return -1;
    }
    unsigned char segment[2];
    while (fread(segment, 1, 2, f)) {
        // Check for the start of a new segment
        if (segment[0] == 0xFF && segment[1] >= 0xC0 && segment[1] <= 0xCF) {
            // Extract information from the segment
            width = segment[3];
            height = segment[5];
            break;
        }
    }
    fclose(f);
    if (width > 4096 || height > 4096) {
        return -1;
    }

    // Return the extracted information
    info->color_space = color_space;
    for (int i = 0; i < 3; i++) {
        info->subsampling_factors[i] = subsampling_factors[i];
    }
    info->compression_quality = compression_quality;
    info->has_metadata = has_metadata;
    info->metadata = metadata;
}
