#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jpeglib.h>
#include <setjmp.h>
#include <omp.h>

struct image_info {
    int width;
    int height;
    int color_space;
    int subsampling_factors[3];
    int compression_quality;
    char* metadata;
};

int process_jpeg(const char* filename, struct image_info* info) {
    // Open the JPEG file and read its header
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        return -1;
    }
    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    if (jpeg_create_decompress(&cinfo) != JPEG_OK) {
        fclose(fp);
        return -2;
    }
    if (jpeg_read_header(&cinfo, TRUE) != JPEG_OK) {
        jpeg_destroy_decompress(&cinfo);
        fclose(fp);
        return -3;
    }

    // Extract the image dimensions and color space
    info->width = cinfo.image_width;
    info->height = cinfo.image_height;
    info->color_space = cinfo.jpeg_color_space;

    // Extract the subsampling factors
    for (int i = 0; i < 3; ++i) {
        info->subsampling_factors[i] = cinfo.comp_info[i].h_samp_factor;
    }

    // Extract the compression quality
    info->compression_quality = cinfo.data_precision;

    // Extract any embedded metadata
    char* metadata = NULL;
    if (cinfo.marker_list != NULL) {
        for (struct jpeg_marker_struct* marker = cinfo.marker_list; marker != NULL; marker = marker->next_marker) {
            if (marker->marker == JPEG_APP0 + 14) {
                metadata = malloc(marker->data_length);
                memcpy(metadata, marker->data, marker->data_length);
                break;
            }
        }
    }
    info->metadata = metadata;

    // Close the JPEG file and clean up
    jpeg_destroy_decompress(&cinfo);
    fclose(fp);

    return 0;
}

int process_directory(const char* directory, struct image_info** infos) {
    // Get a list of all JPEG files in the directory
    int num_files = 0;
    struct dirent** entries = NULL;
    if (scandir(directory, &entries, NULL, alphasort) < 0) {
        return -1;
    }
    for (int i = 0; entries[i] != NULL; ++i) {
        if (strcmp(entries[i]->d_name + strlen(entries[i]->d_name) - 4, ".jpg") == 0 ||
            strcmp(entries[i]->d_name + strlen(entries[i]->d_name) - 5, ".jpeg") == 0) {
            ++num_files;
        }
    }

    // Allocate memory for the image information structs
    *infos = malloc(sizeof(struct image_info) * num_files);
    if (*infos == NULL) {
        return -2;
    }

    // Process each JPEG file in parallel using OpenMP
    #pragma omp parallel for schedule(dynamic, 10) shared(directory, infos)
    for (int i = 0; i < num_files; ++i) {
        char filename[PATH_MAX];
        snprintf(filename, PATH_MAX, "%s/%s", directory, entries[i]->d_name);
        if (process_jpeg(filename, &(*infos)[i]) != 0) {
            fprintf(stderr, "Error processing JPEG file %s\n", filename);
        }
    }

    // Clean up
    free(entries);

    return num_files;
}
```
This code uses the `jpeglib` library to read and decompress JPEG images. It extracts detailed information about each image's color space, subsampling factors, and compression quality, as well as any embedded metadata. The function also handles both single-threaded and multi-threaded execution scenarios using OpenMP.

The `process_jpeg` function takes a filename and a pointer to an `image_info` struct as input, and fills in the struct with information about the JPEG image. It returns 0 on success or a negative error code on failure.

The `process_directory` function takes a directory name and a pointer to a pointer to an array of `image_info` structs as input. It processes each JPEG file in the directory using `process_jpeg`, allocating memory for the image information structs if necessary, and returns the number of processed files on success or a negative error code on failure.

The function uses OpenMP to parallelize the processing of multiple JPEG files in the directory, with each thread handling a subset of the files. This allows the function to process large directories of images efficiently while minimizing memory usage and ensuring robustness against edge cases.']

