#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dicom.h>

struct image_info {
    int pixel_type;
    int width;
    int height;
    int compression;
};

int process_image(const char* filename) {
    // Open the DICOM file and read its header
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        return -1;
    }
    dicom_header header;
    int ret = dicom_read_header(fp, &header);
    if (ret != 0) {
        fclose(fp);
        return ret;
    }

    // Extract the image information from the header
    struct image_info info;
    info.pixel_type = dicom_get_pixel_type(&header);
    info.width = dicom_get_image_width(&header);
    info.height = dicom_get_image_height(&header);
    info.compression = dicom_get_compression_scheme(&header);

    // Close the file and return the extracted information
    fclose(fp);
    return 0;
}
