// Custom memory allocator for managing the list's storage
void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Custom memory deallocator for freeing list elements
void my_free(void* ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}

// Structure to represent a log record
typedef struct NFPAPI_LOG_RECORD {
    time_t timestamp;
    int level;
    char* source_id;
    char* message;
} NFPAPI_LOG_RECORD;

// Structure to represent the dynamic list of log records
typedef struct NFPAPI_LOG_LIST {
    size_t capacity;
    size_t count;
    NFPAPI_LOG_RECORD* elements;
} NFPAPI_LOG_LIST;

// Function to add a new log record to the list
void nfpapi_log_add(NFPAPI_LOG_LIST* list, time_t timestamp, int level, char* source_id, char* message) {
    // Validate input parameters
    if (list == NULL || timestamp < 0 || level < 0 || source_id == NULL || message == NULL) {
        fprintf(stderr, "Error: Invalid input parameters\n");
        return;
    }

    // Check if the list is full and needs to be resized
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFPAPI_LOG_RECORD* new_elements = my_malloc(new_capacity * sizeof(NFPAPI_LOG_RECORD));
        memcpy(new_elements, list->elements, list->count * sizeof(NFPAPI_LOG_RECORD));
        my_free(list->elements);
        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    // Add the new log record to the list
    NFPAPI_LOG_RECORD* element = &list->elements[list->count];
    element->timestamp = timestamp;
    element->level = level;
    element->source_id = source_id;
    element->message = message;
    list->count++;
}

// Function to retrieve log records by timestamp
void nfpapi_log_get(NFPAPI_LOG_LIST* list, time_t timestamp) {
    // Validate input parameters
    if (list == NULL || timestamp < 0) {
        fprintf(stderr, "Error: Invalid input parameters\n");
        return;
    }

    // Find the log record with the specified timestamp
    size_t index = 0;
    while (index < list->count && list->elements[index].timestamp != timestamp) {
        index++;
    }

    // Return the log record if found, otherwise return NULL
    if (index < list->count) {
        NFPAPI_LOG_RECORD* element = &list->elements[index];
        printf("Log record found: timestamp=%ld, level=%d, source_id=%s, message=%s\n", element->timestamp, element->level, element->source_id, element->message);
    } else {
        printf("Log record not found\n");
    }
}

// Function to remove log records older than a specified retention period
void nfpapi_log_remove(NFPAPI_LOG_LIST* list, time_t retention) {
    // Validate input parameters
    if (list == NULL || retention < 0) {
        fprintf(stderr, "Error: Invalid input parameters\n");
        return;
    }

    // Find the log record with the specified timestamp
    size_t index = 0;
    while (index < list->count && list->elements[index].timestamp >= retention) {
        index++;
    }

    // Remove the log records older than the specified retention period
    if (index > 0) {
        NFPAPI_LOG_RECORD* element = &list->elements[index];
        printf("Log record removed: timestamp=%ld, level=%d, source_id=%s, message=%s\n", element->timestamp, element->level, element->source_id, element->message);
    } else {
        printf("No log records found to remove\n");
    }
}

// Function to parse a TIFF image file for specific information
void tiff_parse(const char* filename) {
    // Open the TIFF image file
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open TIFF image file\n");
        return;
    }

    // Read the TIFF header and validate it
    char tiff_header[4];
    size_t bytes_read = fread(tiff_header, 1, sizeof(tiff_header), fp);
    if (bytes_read != sizeof(tiff_header) || memcmp(tiff_header, "MM\x00\x2a", 4)) {
        fprintf(stderr, "Error: Invalid TIFF header\n");
        fclose(fp);
        return;
    }

    // Read the image width and height from the TIFF file
    uint16_t width = 0;
    uint16_t height = 0;
    bytes_read = fread(&width, sizeof(uint16_t), 1, fp);
    if (bytes_read != sizeof(uint16_t)) {
        fprintf(stderr, "Error: Failed to read image width\n");
        fclose(fp);
        return;
    }
    bytes_read = fread(&height, sizeof(uint16_t), 1, fp);
    if (bytes_read != sizeof(uint16_t)) {
        fprintf(stderr, "Error: Failed to read image height\n");
        fclose(fp);
        return;
    }

    // Read the bits per sample from the TIFF file
    uint16_t bits_per_sample = 0;
    bytes_read = fread(&bits_per_sample, sizeof(uint16_t), 1, fp);
    if (bytes_read != sizeof(uint16_t)) {
        fprintf(stderr, "Error: Failed to read bits per sample\n");
        fclose(fp);
        return;
    }

    // Read the sample per pixel from the TIFF file
    uint16_t samples_per_pixel = 0;
    bytes_read = fread(&samples_per_pixel, sizeof(uint16_t), 1, fp);
    if (bytes_read != sizeof(uint16_t)) {
        fprintf(stderr, "Error: Failed to read samples per pixel\n");
        fclose(fp);
        return;
    }

    // Handle extra samples in the TIFF file
    uint16_t extra_samples = 0;
    if (bits_per_sample == 32) {
        extra_samples = samples_per_pixel - 4;
    } else if (bits_per_sample == 64) {
        extra_samples = samples_per_pixel - 8;
    }

    // Print the parsed information
    printf("TIFF image file: width=%d, height=%d, bits per sample=%d, samples per pixel=%d, extra samples=%d\n", width, height, bits_per_sample, samples_per_pixel, extra_samples);

    // Close the TIFF image file
    fclose(fp);
}
