```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <limits.h>

// Define a struct to store the extracted information
struct tiff_info {
    int bits_per_sample;
    int samples_per_pixel;
};

// Define a function to parse the TIFF image file and extract the information
int parse_tiff(const char* filename, struct tiff_info* info) {
    // Open the TIFF image file
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error: unable to open TIFF image file\n");
        return -1;
    }

    // Read the TIFF header and check for supported bits per sample
    char header[2];
    fread(header, 1, 2, fp);
    if (header[0] != 'M' || header[1] != 'M') {
        printf("Error: invalid TIFF image file\n");
        return -1;
    }
    int bits_per_sample = fgetc(fp);
    if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 && bits_per_sample != 8 && bits_per_sample != 16) {
        printf("Error: unsupported bits per sample\n");
        return -1;
    }

    // Read the TIFF image data and extract the information about samples per pixel
    int samples_per_pixel = 0;
    while (!feof(fp)) {
        char* line = fgets(fp);
        if (line == NULL) {
            break;
        }
        // Check for extra samples and extract the information about them
        if (strncmp(line, "ExtraSamples", 12) == 0) {
            int num_extra_samples = atoi(line + 13);
            char* extra_sample_info = fgets(fp);
            while (num_extra_samples-- > 0 && extra_sample_info != NULL) {
                // Extract the information about each extra sample and increment the count of samples per pixel
                int sample_type = atoi(extra_sample_info + 13);
                if (sample_type == 1 || sample_type == 2 || sample_type == 4) {
                    samples_per_pixel++;
                } else {
                    printf("Error: unsupported extra sample type\n");
                    return -1;
                }
                extra_sample_info = fgets(fp);
            }
        }
    }

    // Close the TIFF image file and return the extracted information
    fclose(fp);
    info->bits_per_sample = bits_per_sample;
    info->samples_per_pixel = samples_per_pixel;
    return 0;
}
