// Define a function to extract information from a DICOM file
int extract_image_info(const char* filename, struct image_info* info) {
    // Open the DICOM file using libdicom
    dicom_file* file = dicom_open(filename);
    if (!file) {
        return -1; // error opening file
    }

    // Get the pixel data type from the DICOM header
    int pixel_type = dicom_get_pixel_data_type(file);
    if (pixel_type < 0 || pixel_type > 3) {
        return -2; // unsupported pixel data type
    }

    // Get the dimensions of the image from the DICOM header
    int dimensions[3];
    dimensions[0] = dicom_get_image_width(file);
    dimensions[1] = dicom_get_image_height(file);
    dimensions[2] = dicom_get_image_depth(file);

    // Check if compression is applied to the image
    bool compression = false;
    if (dicom_is_compressed(file)) {
        compression = true;
    }

    // Close the DICOM file
    dicom_close(file);

    // Store the extracted information in the struct
    info->pixel_type = pixel_type;
    memcpy(info->dimensions, dimensions, sizeof(int) * 3);
    info->compression = compression;

    return 0; // success
}
