void manage_device_connections(int num_records, int seed_value, float quality_threshold, bool enable_logging) {
    // Initialize variables for managing device connections
    DEVICE_CONN_RECORD* records = (DEVICE_CONN_RECORD*)malloc(num_records * sizeof(DEVICE_CONN_RECORD));
    NFAPI_CRC_INDICATION_PDU_T* crc_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_records * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int num_active_connections = 0;
