// Function to add a new element to the list
void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST* list, RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti) {
    // Validate input parameters
    if (rx_ue_information == NULL || rnti == NULL) {
        return;
    }

    // Generate a random CRCFLAG value for the new element
    int crcflag = rand() % 2;

    // Allocate memory for the new element
    NFAPI_CRC_INDICATION_PDU_T* new_element = my_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_element == NULL) {
        return;
