    // Initialize the new element with the input parameters and the generated CRCFLAG value
    new_element->rx_ue_information = rx_ue_information;
    new_element->rnti = rnti;
    new_element->crc_indication_rel8.CRCFLAG = crcflag;

    // Add the new element to the list
    if (list->count < list->capacity) {
        list->data[list->count++] = *new_element;
    } else {
        // Handle full capacity limit by removing the oldest element from the list
        NFAPI_CRC_INDICATION_PDU_T* oldest_element = &list->data[0];
        for (size_t i = 1; i < list->count; i++) {
            if (list->data[i].rx_ue_information.timestamp > oldest_element->rx_ue_information.timestamp) {
                oldest_element = &list->data[i];
            }
        }
        *oldest_element = *new_element;
    }
