Here is an example implementation of the C function to manage a dynamic list of `NFPAPI_LOG_RECORD` structures:
```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdio.h>
#include <stdbool.h>

// Custom memory allocator to handle out-of-memory conditions gracefully
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Reduce the number of elements in the list until successful allocation is possible
        while (true) {
            size /= 2;
            ptr = realloc(NULL, size);
            if (ptr) break;
        }
    }
    return ptr;
}

// Struct to represent a log record
typedef struct NFPAPI_LOG_RECORD {
    time_t timestamp;
    int level;
    char* source_id;
    char* message;
} NFPAPI_LOG_RECORD;

// Function to add a new log record to the list
void add_log_record(NFPAPI_LOG_RECORD* record) {
    // Validate the log level and source ID
    if (record->level < 0 || record->level > 3) {
        printf("Invalid log level: %d\n", record->level);
        return;
    }
    if (!record->source_id) {
        printf("Invalid source ID: %s\n", record->source_id);
        return;
    }

    // Truncate the message to a maximum length of 1024 characters
    size_t msg_len = strlen(record->message);
    if (msg_len > 1024) {
        record->message[1023] = '\0';
    }

    // Add the log record to the list
    NFPAPI_LOG_RECORD* new_record = custom_malloc(sizeof(NFPAPI_LOG_RECORD));
    memcpy(new_record, record, sizeof(NFPAPI_LOG_RECORD));
    new_record->next = NULL;

    // Update the tail of the list
    if (tail) {
        tail->next = new_record;
    } else {
        head = new_record;
    }
    tail = new_record;
}

// Function to retrieve log records by timestamp
void get_log_records(time_t start, time_t end) {
    // Iterate through the list and print all records within the specified range
    NFPAPI_LOG_RECORD* current = head;
    while (current) {
        if (current->timestamp >= start && current->timestamp <= end) {
            printf("Log record: %s\n", current->message);
        }
        current = current->next;
    }
}

// Function to remove log records older than a specified retention period
void remove_old_records(time_t retention_period) {
    // Iterate through the list and remove all records older than the specified retention period
    NFPAPI_LOG_RECORD* current = head;
    while (current) {
        if (current->timestamp < time(NULL) - retention_period) {
            NFPAPI_LOG_RECORD* next = current->next;
            free(current);
            current = next;
        } else {
            current = current->next;
        }
    }
}

// Function to parse a TIFF image file for specific information
void parse_tiff_image(const char* filename) {
    // Open the TIFF image file
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        printf("Error opening TIFF image file: %s\n", strerror(errno));
        return;
    }

    // Read the TIFF header and check for validity
    char tiff_header[4];
    fread(tiff_header, 1, 4, fp);
    if (strncmp(tiff_header, "MM\x00\x2a", 4) != 0 && strncmp(tiff_header, "\x2a\x00MM", 4) != 0) {
        printf("Invalid TIFF header: %s\n", tiff_header);
        fclose(fp);
        return;
    }

    // Read the image width and height from the TIFF file
    uint16_t width, height;
    fread(&width, 2, 1, fp);
    fread(&height, 2, 1, fp);

    // Check for valid bits per sample values
    uint16_t bits_per_sample;
    fread(&bits_per_sample, 2, 1, fp);
    if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 && bits_per_sample != 8) {
        printf("Invalid bits per sample value: %d\n", bits_per_sample);
        fclose(fp);
        return;
    }

    // Read the number of extra samples from the TIFF file
    uint16_t num_extra_samples;
    fread(&num_extra_samples, 2, 1, fp);

    // Print details about the image's bits per sample and extra samples
    printf("Bits per sample: %d\n", bits_per_sample);
    if (num_extra_samples > 0) {
        printf("Extra samples: %d\n", num_extra_samples);
    }

    // Close the TIFF image file
    fclose(fp);
}
