// Define function to generate random string with given seed and length
char* generate_random_string(int seed, int length) {
    char* str = (char*)malloc(length * sizeof(char));
    for (int i = 0; i < length; i++) {
        str[i] = 'a' + (seed % 26);
        seed /= 26;
