// Define function to generate random number with given seed and range
int generate_random_number(int seed, int min, int max) {
    return min + (rand() % (max - min));
}

// Define function to generate random float with given seed and range
float generate_random_float(int seed, float min, float max) {
    return min + ((float)(rand() % 10000) / 100.0f);
}

