void nfpapi_add_log_record(time_t timestamp, int level, const char* source_id, const char* message) {
    // Validate the input parameters
    if (timestamp < 0 || level < 0 || source_id == NULL || message == NULL) {
        return;
    }

    // Acquire the mutex to ensure consistent access to the list by multiple threads
    pthread_mutex_lock(&mutex);

    // Check if the list is full and needs to be resized
    if (num_log_records >= MAX_NUM_LOG_RECORDS) {
        // Remove old log records that are older than the retention period
        time_t current_time = time(NULL);
        for (size_t i = 0; i < num_log_records; ++i) {
            if (log_records[i].timestamp + RETENTION_PERIOD <= current_time) {
                // Remove the log record and update the number of log records
                custom_free(log_records[i].message);
                memmove(&log_records[i], &log_records[i+1], (num_log_records - i - 1) * sizeof(NFPAPI_LOG_RECORD));
                --num_log_records;
            }
        }
    }

    // Add the new log record to the list
    NFPAPI_LOG_RECORD* new_record = custom_malloc(sizeof(NFPAPI_LOG_RECORD));
    if (new_record) {
        new_record->timestamp = timestamp;
        new_record->level = level;
        strncpy(new_record->source_id, source_id, 16);
        strncpy(new_record->message, message, 1024);
        log_records[num_log_records++] = new_record;
    } else {
        // Release the mutex and return if the allocation failed
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve log records by timestamp
void nfpapi_get_log_records(time_t start_timestamp, time_t end_timestamp) {
    // Acquire the mutex to ensure consistent access to the list by multiple threads
    pthread_mutex_lock(&mutex);

    // Iterate over the log records and print them if they are within the specified timestamp range
    for (size_t i = 0; i < num_log_records; ++i) {
        NFPAPI_LOG_RECORD* record = &log_records[i];
        if (record->timestamp >= start_timestamp && record->timestamp <= end_timestamp) {
            printf("Log record %zu: timestamp=%ld, level=%d, source_id=%s, message=%s\n", i, record->timestamp, record->level, record->source_id, record->message);
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to remove log records older than a specified retention period
void nfpapi_remove_old_log_records(int retention_period) {
    // Acquire the mutex to ensure consistent access to the list by multiple threads
    pthread_mutex_lock(&mutex);

    // Remove old log records that are older than the retention period
    time_t current_time = time(NULL);
    for (size_t i = 0; i < num_log_records; ++i) {
        if (log_records[i].timestamp + retention_period <= current_time) {
            // Remove the log record and update the number of log records
            custom_free(log_records[i].message);
            memmove(&log_records[i], &log_records[i+1], (num_log_records - i - 1) * sizeof(NFPAPI_LOG_RECORD));
            --num_log_records;
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to parse a TIFF image file for specific information
void nfpapi_parse_tiff_image(const char* filename) {
    // Open the TIFF image file
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        return;
    }

    // Read the TIFF header and check for errors
    uint16_t tiff_header[4];
    if (fread(tiff_header, sizeof(uint16_t), 4, fp) != 4 || memcmp(tiff_header, "MM\x00\x2a", 4)) {
        // Close the file and return if there was an error reading the header
        fclose(fp);
        return;
    }

    // Read the TIFF directory and check for errors
    uint16_t tiff_directory[3];
    if (fread(tiff_directory, sizeof(uint16_t), 3, fp) != 3 || memcmp(tiff_directory, "II\x2a\x00", 4)) {
        // Close the file and return if there was an error reading the directory
        fclose(fp);
        return;
    }

    // Read the TIFF image data and check for errors
    uint16_t tiff_image_data[3];
    if (fread(tiff_image_data, sizeof(uint16_t), 3, fp) != 3 || memcmp(tiff_image_data, "MM\x00\x2a", 4)) {
        // Close the file and return if there was an error reading the image data
        fclose(fp);
        return;
    }

    // Extract the bits per sample value from the TIFF header
    uint16_t bits_per_sample = tiff_header[0];

    // Extract the sample per pixel value from the TIFF directory
    uint16_t sample_per_pixel = tiff_directory[2];

    // Check if the image has extra samples and extract their details if necessary
    bool has_extra_samples = false;
    uint16_t extra_sample_count = 0;
    uint16_t* extra_samples = NULL;
    if (sample_per_pixel > 3) {
        has_extra_samples = true;
        extra_sample_count = sample_per_pixel - 3;
        extra_samples = malloc(extra_sample_count * sizeof(uint16_t));
        if (!extra_samples) {
            // Close the file and return if there was an error allocating memory for the extra samples
            fclose(fp);
            return;
        }
    }

    // Read the TIFF image data and check for errors
    uint16_t* tiff_image = malloc(sample_per_pixel * sizeof(uint16_t));
    if (!tiff_image) {
        // Close the file and return if there was an error allocating memory for the TIFF image data
        fclose(fp);
        free(extra_samples);
        return;
    }
    if (fread(tiff_image, sizeof(uint16_t), sample_per_pixel, fp) != sample_per_pixel) {
        // Close the file and return if there was an error reading the TIFF image data
        fclose(fp);
        free(extra_samples);
        free(tiff_image);
        return;
    }

    // Close the file and release resources
    fclose(fp);
    free(extra_samples);
    free(tiff_image);
}
```
