        printf("Error: unsupported pixel data type %d\n", info.pixelDataType);
        fclose(fp);
        return 1;
    }

    // Check for supported compression schemes
    if (info.compressionApplied && !dicom_check_compression(header)) {
        printf("Error: unsupported compression scheme\n");
        fclose(fp);
        return 1;
    }

    // Read the pixel data
    void* pixels = NULL;
    if (info.pixelDataType == DICOM_PIXEL_UINT8) {
        pixels = malloc(info.dimensions[0] * info.dimensions[1] * info.dimensions[2]);
        fread(pixels, 1, info.dimensions[0] * info.dimensions[1] * info.dimensions[2], fp);
    } else if (info.pixelDataType == DICOM_PIXEL_UINT16) {
        pixels = malloc(info.dimensions[0] * info.dimensions[1] * info.dimensions[2] * 2);
        fread(pixels, 2, info.dimensions[0] * info.dimensions[1] * info.dimensions[2], fp);
    } else if (info.pixelDataType == DICOM_PIXEL_SINT16) {
        pixels = malloc(info.dimensions[0] * info.dimensions[1] * info.dimensions[2] * 2);
        fread(pixels, 2, info.dimensions[0] * info.dimensions[1] * info.dimensions[2], fp);
    } else if (info.pixelDataType == DICOM_PIXEL_FLOAT32) {
        pixels = malloc(info.dimensions[0] * info.dimensions[1] * info.dimensions[2] * 4);
        fread(pixels, 4, info.dimensions[0] * info.dimensions[1] * info.dimensions[2], fp);
    }

    // Close the DICOM file
    fclose(fp);

    // Return the extracted information
    return info;
}
