#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <cmath>

struct Transaction {
    std::string type;
    double amount;
    bool encryption_applied;
};

struct EncryptionMethod {
    std::string name;
    int key_size;
};

std::vector<Transaction> process_transaction_log(const std::vector<Transaction>& transactions) {
    // Initialize a map to store the transaction volumes and average amounts
    std::map<std::string, double> volume_map;
    std::map<std::string, double> amount_map;

    // Iterate over each transaction in the log
    for (const Transaction& transaction : transactions) {
        // Check if the transaction type is supported
        if (transaction.type == "debit" || transaction.type == "credit" || transaction.type == "transfer") {
            // Update the volume and average amount maps
            volume_map[transaction.type]++;
            amount_map[transaction.type] += transaction.amount;
        } else {
            // Return an error code if a transaction type is not supported
            return std::vector<Transaction>{};
        }

        // Check if encryption is applied to the transaction
        if (transaction.encryption_applied) {
            // Update the encryption method map
            EncryptionMethod encryption_method = {transaction.type, transaction.key_size};
            std::map<EncryptionMethod, int> encryption_method_map;
            encryption_method_map[encryption_method]++;
        }
    }

    // Calculate the average transaction amounts and volumes
    for (const auto& volume : volume_map) {
        amount_map[volume.first] /= volume_map[volume.first];
    }

    // Return the extracted information in a structured format
    std::vector<Transaction> processed_transactions;
    for (const auto& transaction : transactions) {
        Transaction processed_transaction = {transaction.type, amount_map[transaction.type], encryption_method_map[EncryptionMethod{transaction.type, transaction.key_size}]};
        processed_transactions.push_back(processed_transaction);
    }
    return processed_transactions;
}
