// Custom memory allocator for optimal performance
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("custom_malloc");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Custom memory deallocator for optimal performance
void custom_free(void* ptr) {
    free(ptr);
}

// Structure to store log records
typedef struct NFPAPI_LOG_RECORD {
    time_t LOG_TIMESTAMP;
    int LOG_LEVEL;
    char SOURCE_ID[1024];
    char LOG_MESSAGE[1024];
} NFPAPI_LOG_RECORD;

// Structure to store user session logs
typedef struct LTE_USER_SESSION_LOG_T {
    int UE_ID;
    time_t SESSION_TIMESTAMP;
    int CONNECTIVITY_STATUS;
    long DATA_USAGE_REPORT;
} LTE_USER_SESSION_LOG_T;

// Structure to store network performance metrics
typedef struct NETWORK_PERFORMANCE_METRICS {
    int NODE_ID;
    time_t TIMESTAMP;
    float BANDWIDTH_UTILIZATION;
    float LATENCY_STATISTICS;
    float ERROR_RATES;
} NETWORK_PERFORMANCE_METRICS;

// Structure to store log records in a dynamic array
typedef struct LOG_RECORD_ARRAY {
    int size;
    int capacity;
    NFPAPI_LOG_RECORD* records;
} LOG_RECORD_ARRAY;

// Structure to store user session logs in a dynamic array
typedef struct USER_SESSION_LOG_ARRAY {
    int size;
    int capacity;
    LTE_USER_SESSION_LOG_T* records;
} USER_SESSION_LOG_ARRAY;

// Structure to store network performance metrics in a dynamic array
typedef struct NETWORK_PERFORMANCE_METRICS_ARRAY {
    int size;
    int capacity;
    NETWORK_PERFORMANCE_METRICS* records;
} NETWORK_PERFORMANCE_METRICS_ARRAY;

// Function to add a log record to the dynamic array
void add_log_record(LOG_RECORD_ARRAY* array, NFPAPI_LOG_RECORD record) {
    // Check if the array is full
    if (array->size == array->capacity) {
        // Double the capacity of the array
        int new_capacity = array->capacity * 2;
        NFPAPI_LOG_RECORD* new_records = custom_malloc(new_capacity * sizeof(NFPAPI_LOG_RECORD));
        memcpy(new_records, array->records, array->size * sizeof(NFPAPI_LOG_RECORD));
        custom_free(array->records);
        array->records = new_records;
        array->capacity = new_capacity;
    }
    // Add the log record to the end of the array
    array->records[array->size++] = record;
}

// Function to retrieve a log record from the dynamic array
NFPAPI_LOG_RECORD get_log_record(LOG_RECORD_ARRAY* array, int index) {
    // Check if the index is valid
    if (index < 0 || index >= array->size) {
        return NULL;
    }
    return array->records[index];
}

// Function to remove a log record from the dynamic array
void remove_log_record(LOG_RECORD_ARRAY* array, int index) {
    // Check if the index is valid
    if (index < 0 || index >= array->size) {
        return;
    }
    // Shift all records after the specified index to the left by one position
    for (int i = index + 1; i < array->size; ++i) {
        array->records[i - 1] = array->records[i];
    }
    --array->size;
}

