// Function to manage dynamic lists for both NFPAPI_LOG_RECORD and LTE_USER_SESSION_LOG_T structures
void manage_dynamic_lists(LOG_RECORD_ARRAY* log_records, USER_SESSION_LOG_ARRAY* user_session_logs, NETWORK_PERFORMANCE_METRICS_ARRAY* network_performance_metrics) {
    // Initialize semaphores for synchronizing access across multiple threads
    sem_t log_record_semaphore;
    sem_t user_session_log_semaphore;
    sem_t network_performance_metric_semaphore;
    sem_init(&log_record_semaphore, 0, 1);
    sem_init(&user_session_log_semaphore, 0, 1);
    sem_init(&network_performance_metric_semaphore, 0, 1);

    // Initialize mutexes for protecting the dynamic arrays from concurrent access
    pthread_mutex_t log_record_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_t user_session_log_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_t network_performance_metric_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize condition variables for signaling when a log record, user session log, or network performance metric is added or removed
    pthread_cond_t log_record_added_condition = PTHREAD_COND_INITIALIZER;
    pthread_cond_t user_session_log_added_condition = PTHREAD_COND_INITIALIZER;
    pthread_cond_t network_performance_metric_added_condition = PTHREAD_COND_INITIALIZER;
    pthread_cond_t log_record_removed_condition = PTHREAD_COND_INITIALIZER;
    pthread_cond_t user_session_log_removed_condition = PTHREAD_COND_INITIALIZER;
    pthread_cond_t network_performance_metric_removed_condition = PTHREAD_COND_INITIALIZER;

    // Initialize a thread pool for managing the dynamic lists
    int num_threads = 4;
    pthread_t* threads = (pthread_t*) malloc(num_threads * sizeof(pthread_t));
    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, manage_dynamic_lists_thread, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up semaphores and mutexes
    sem_destroy(&log_record_semaphore);
    sem_destroy(&user_session_log_semaphore);
    sem_destroy(&network_performance_metric_semaphore);
    pthread_mutex_destroy(&log_record_mutex);
    pthread_mutex_destroy(&user_session_log_mutex);
    pthread_mutex_destroy(&network_performance_metric_mutex);

    // Clean up condition variables
    pthread_cond_destroy(&log_record_added_condition);
    pthread_cond_destroy(&user_session_log_added_condition);
    pthread_cond_destroy(&network_performance_metric_added_condition);
    pthread_cond_destroy(&log_record_removed_condition);
    pthread_cond_destroy(&user_session_log_removed_condition);
