    int width;
    int height;
    int bit_depth;
    int color_space;
    int subsampling_factor;
    int compression_quality;
} image_info_t;

// Function to process a single JPEG image and extract information about it
int process_image(const char *filename) {
    // Open the JPEG file for reading
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return -1;
    }

    // Create a new JPEG decompression object
    jpeg_decompress_struct cinfo;
    jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    if (jpeg_create_decompress(&cinfo) != JPEG_OK) {
        printf("Error: unable to create decompression object\n");
        fclose(file);
        return -1;
    }

    // Set up the JPEG decompression parameters
    jpeg_read_header(&cinfo, TRUE);
    cinfo.out_color_space = JCS_RGB;
    cinfo.do_fancy_upsampling = FALSE;
    cinfo.dct_method = JDCT_ISLOW;

    // Start decompressing the JPEG image
    if (jpeg_start_decompress(&cinfo) != JPEG_OK) {
        printf("Error: unable to start decompression\n");
        jpeg_destroy_decompress(&cinfo);
        fclose(file);
        return -1;
    }

    // Get the image dimensions and bit depth
    int width = cinfo.image_width;
    int height = cinfo.image_height;
    int bit_depth = cinfo.data_precision;

    // Get the color space and subsampling factor
    int color_space = cinfo.out_color_components;
    int subsampling_factor = cinfo.comp_info[0].h_samp_factor * cinfo.comp_info[0].v_samp_factor;

    // Get the compression quality
    int compression_quality = cinfo.comp_info[0].quant_tbl->quality;

    // Close the JPEG file and destroy the decompression object
    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    fclose(file);

    // Log the image information in a structured data format
    image_info_t *image = malloc(sizeof(image_info_t));
    image->filename = strdup(filename);
    image->width = width;
    image->height = height;
    image->bit_depth = bit_depth;
    image->color_space = color_space;
    image->subsampling_factor = subsampling_factor;
    image->compression_quality = compression_quality;

    return 0;
}

// Function to process a directory of JPEG images and extract information about them
int process_directory(const char *directory) {
    // Open the directory for reading
    DIR *dir = opendir(directory);
    if (dir == NULL) {
        printf("Error: unable to open directory %s\n", directory);
        return -1;
    }

    // Loop through each file in the directory and process it
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char *filename = malloc(strlen(directory) + strlen(entry->d_name) + 2);
        sprintf(filename, "%s/%s", directory, entry->d_name);

        // Process the image and extract information about it
        int result = process_image(filename);
        if (result != 0) {
            printf("Error: unable to process image %s\n", filename);
            free(filename);
            continue;
        }

        // Log the image information in a structured data format
        image_info_t *image = malloc(sizeof(image_info_t));
        image->filename = strdup(filename);
        image->width = cinfo.image_width;
        image->height = cinfo.image_height;
        image->bit_depth = cinfo.data_precision;
        image->color_space = cinfo.out_color_components;
        image->subsampling_factor = cinfo.comp_info[0].h_samp_factor * cinfo.comp_info[0].v_samp_factor;
        image->compression_quality = cinfo.comp_info[0].quant_tbl->quality;

        // Free the filename and image information structures
        free(filename);
        free(image);
    }

    closedir(dir);

    return 0;
}
