#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>

// Custom memory allocator for optimal performance
void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Error: Out of memory\n");
        exit(1);
    }
    return ptr;
}

// Custom free function for the custom memory allocator
void my_free(void* ptr) {
    free(ptr);
}

// Thread-safe data structure for synchronizing access across multiple threads
typedef struct {
    pthread_mutex_t mutex;
    semaphore_t semaphore;
} thread_safe_data_structure;

// Initialize the thread-safe data structure
void init_thread_safe_data_structure(thread_safe_data_structure* ts) {
    pthread_mutex_init(&ts->mutex, NULL);
    semaphore_init(&ts->semaphore, 1);
}

// Lock the thread-safe data structure for exclusive access
void lock_thread_safe_data_structure(thread_safe_data_structure* ts) {
    pthread_mutex_lock(&ts->mutex);
}

// Unlock the thread-safe data structure after exclusive access
void unlock_thread_safe_data_structure(thread_safe_data_structure* ts) {
    pthread_mutex_unlock(&ts->mutex);
}

// Wait for a semaphore to be signaled before continuing
void wait_for_semaphore(semaphore_t* semaphore) {
    semaphore_wait(semaphore);
}

// Signal the semaphore to unblock waiting threads
void signal_semaphore(semaphore_t* semaphore) {
    semaphore_post(semaphore);
}

// Structure for storing log records
typedef struct {
    time_t timestamp;
    int level;
    char source_id[1024];
    char message[1024];
} log_record;

// Structure for storing user session logs
typedef struct {
    int ue_id;
    time_t session_timestamp;
    int connectivity_status;
    long data_usage_report;
} lte_user_session_log;

// Structure for storing network performance metrics
typedef struct {
    int node_id;
    time_t timestamp;
    float bandwidth_utilization;
    float latency_statistics;
    float error_rates;
} network_performance_metrics;

// Structure for storing the log list
typedef struct {
    thread_safe_data_structure ts;
    int count;
    log_record* records;
} log_list;

// Initialize the log list with a given capacity
void init_log_list(log_list* ll, int capacity) {
    ll->count = 0;
    ll->records = my_malloc(capacity * sizeof(log_record));
}

// Add a new log record to the log list
void add_log_record(log_list* ll, time_t timestamp, int level, char* source_id, char* message) {
    lock_thread_safe_data_structure(&ll->ts);
    if (ll->count < capacity) {
        ll->records[ll->count].timestamp = timestamp;
        ll->records[ll->count].level = level;
        strncpy(ll->records[ll->count].source_id, source_id, 1024);
        strncpy(ll->records[ll->count].message, message, 1024);
        ll->count++;
    } else {
        printf("Error: Log list is full\n");
    }
    unlock_thread_safe_data_structure(&ll->ts);
}

// Retrieve a log record from the log list based on timestamp
log_record* get_log_record(log_list* ll, time_t timestamp) {
    lock_thread_safe_data_structure(&ll->ts);
    for (int i = 0; i < ll->count; i++) {
        if (ll->records[i].timestamp == timestamp) {
            log_record* record = &ll->records[i];
            unlock_thread_safe_data_structure(&ll->ts);
            return record;
        }
    }
    unlock_thread_safe_data_structure(&ll->ts);
    return NULL;
}

// Remove a log record from the log list based on timestamp
void remove_log_record(log_list* ll, time_t timestamp) {
    lock_thread_safe_data_structure(&ll->ts);
    for (int i = 0; i < ll->count; i++) {
        if (ll->records[i].timestamp == timestamp) {
            ll->count--;
            memmove(&ll->records[i], &ll->records[i + 1], sizeof(log_record) * (ll->count - i));
            break;
        }
    }
    unlock_thread_safe_data_structure(&ll->ts);
}

// Structure for storing the user session log list
typedef struct {
    thread_safe_data_structure ts;
    int count;
    lte_user_session_log* logs;
} lte_user_session_log_list;

// Initialize the user session log list with a given capacity
void init_lte_user_session_log_list(lte_user_session_log_list* ll, int capacity) {
    ll->count = 0;
    ll->logs = my_malloc(capacity * sizeof(lte_user_session_log));
}

// Add a new user session log to the list
void add_lte_user_session_log(lte_user_session_log_list* ll, int ue_id, time_t session_timestamp, int connectivity_status, long data_usage_report) {
    lock_thread_safe_data_structure(&ll->ts);
    if (ll->count < capacity) {
        ll->logs[ll->count].ue_id = ue_id;
        ll->logs[ll->count].session_timestamp = session_timestamp;
        ll->logs[ll->count].connectivity_status = connectivity_status;
        ll->logs[ll->count].data_usage_report = data_usage_report;
        ll->count++;
    } else {
        printf("Error: User session log list is full\n");
    }
    unlock_thread_safe_data_structure(&ll->ts);
}

