// Custom memory allocator for dynamic list
void* custom_alloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // Handle out-of-memory condition gracefully by reducing the number of elements until successful allocation is possible
        while (size > 0) {
            size--;
            ptr = realloc(ptr, size);
            if (ptr != NULL) {
                break;
            }
        }
    }
    return ptr;
}

// Custom memory deallocator for dynamic list
