    TX_POWER_LEVEL tx_power;
    RECEIVED_SIGNAL_STRENGTH signal_strength;
    CHANNEL_ID channel_id;
    TIME_STAMP time_stamp;
} PHY_STATS_RECORD_T;

// Dynamic list to store PHY statistics records
typedef struct {
    size_t capacity; // Maximum number of elements in the list
    size_t count; // Current number of elements in the list
    PHY_STATS_RECORD_T* data; // Pointer to the array of PHY statistics records
} PHY_STATS_LIST_T;

// Initialize a new dynamic list with a specified capacity
void phy_stats_list_init(PHY_STATS_LIST_T* list, size_t capacity) {
    list->capacity = capacity;
    list->count = 0;
    list->data = custom_alloc(sizeof(PHY_STATS_RECORD_T) * capacity);
}

// Add a new element to the dynamic list
void phy_stats_list_add(PHY_STATS_LIST_T* list, TX_POWER_LEVEL tx_power, RECEIVED_SIGNAL_STRENGTH signal_strength, CHANNEL_ID channel_id, TIME_STAMP time_stamp) {
    // Validate input parameters
    if (tx_power < MIN_TX_POWER || tx_power > MAX_TX_POWER) {
        printf("Invalid TX power level: %d\n", tx_power);
        return;
    }
    if (signal_strength < MIN_SIGNAL_STRENGTH || signal_strength > MAX_SIGNAL_STRENGTH) {
        printf("Invalid received signal strength: %d\n", signal_strength);
        return;
    }

    // Acquire lock to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Check if the list is full
    if (list->count == list->capacity) {
        printf("List is full, cannot add new element\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Add new element to the list
    PHY_STATS_RECORD_T* record = &list->data[list->count];
    record->tx_power = tx_power;
    record->signal_strength = signal_strength;
    record->channel_id = channel_id;
    record->time_stamp = time_stamp;
    list->count++;

    // Release lock
    pthread_mutex_unlock(&list->mutex);
}

// Retrieve an element from the dynamic list by index
PHY_STATS_RECORD_T* phy_stats_list_get(PHY_STATS_LIST_T* list, size_t index) {
    // Validate input parameters
    if (index >= list->count) {
        printf("Index out of bounds: %zu\n", index);
        return NULL;
    }

    // Acquire lock to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Retrieve element from the list
    PHY_STATS_RECORD_T* record = &list->data[index];

    // Release lock
    pthread_mutex_unlock(&list->mutex);

    return record;
}

// Remove an element from the dynamic list by index
void phy_stats_list_remove(PHY_STATS_LIST_T* list, size_t index) {
    // Validate input parameters
    if (index >= list->count) {
        printf("Index out of bounds: %zu\n", index);
        return;
    }

    // Acquire lock to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Remove element from the list
    PHY_STATS_RECORD_T* record = &list->data[index];
    memmove(record, record + 1, (list->count - index - 1) * sizeof(PHY_STATS_RECORD_T));
    list->count--;

    // Release lock
    pthread_mutex_unlock(&list->mutex);
}

// Periodically clean up the dynamic list to maintain memory efficiency
void phy_stats_list_cleanup(PHY_STATS_LIST_T* list) {
    // Acquire lock to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Remove elements older than a specified time threshold
    size_t count = 0;
    for (size_t i = 0; i < list->count; i++) {
        PHY_STATS_RECORD_T* record = &list->data[i];
        if (record->time_stamp < TIME_THRESHOLD) {
            memmove(record, record + 1, (list->count - i - 1) * sizeof(PHY_STATS_RECORD_T));
            list->count--;
            count++;
        } else {
            break;
        }
    }

    // Release lock
    pthread_mutex_unlock(&list->mutex);

    printf("Removed %zu elements from the list\n", count);
}
