#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>
#include <jemalloc/jemalloc.h>

typedef struct LTE_UE_CONTEXT {
    int RRC_STATE;
    long TMSI;
    char* NAS_MESSAGE;
    int STATUS_CODE;
} LTE_UE_CONTEXT;

typedef struct record {
    int integer_field;
    double timestamp;
    float precision_indicator;
} record;

void populate_linked_list(LTE_UE_CONTEXT** head) {
    // Initialize arrays for offset values, keys, and precision values
    long* offset_values = malloc(sizeof(long) * 10);
    int* key_values = malloc(sizeof(int) * 10);
    float* precision_values = malloc(sizeof(float) * 10);

    // Initialize array of records
    record* records = malloc(sizeof(record) * 10);

    // Set the value of each record's integer field to a random value within a specified range
    for (int i = 0; i < 10; i++) {
        records[i].integer_field = rand() % 100;
        records[i].timestamp = time(NULL);
        records[i].precision_indicator = (float)rand() / RAND_MAX;
    }

    // Allocate memory for the linked list of LTE UE context structures
    *head = malloc(sizeof(LTE_UE_CONTEXT));

    // Initialize the head node with a valid RRC state, TMSI, and NAS message
    (*head)->RRC_STATE = 1;
    (*head)->TMSI = 1234567890;
    (*head)->NAS_MESSAGE = "Hello, world!";
    (*head)->STATUS_CODE = 0;

    // Add the records to the linked list
    for (int i = 0; i < 10; i++) {
        LTE_UE_CONTEXT* node = malloc(sizeof(LTE_UE_CONTEXT));
        node->RRC_STATE = (*head)->RRC_STATE;
        node->TMSI = (*head)->TMSI + offset_values[i];
        node->NAS_MESSAGE = records[i].integer_field;
        node->STATUS_CODE = 0;
        (*head)->next = node;
    }

    // Free memory for the arrays and linked list
    free(offset_values);
    free(key_values);
    free(precision_values);
    free(*head);
}
