#include <random>
#include <list>
#include <cstdint>

namespace NFAPI {
    class CRCIndicationPDU {
        public:
            struct RX_UE_INFORMATION_TAG {
                uint16_t rnti;
                uint8_t crcFlag;
            };

            struct CRC_INDICATION_REL8_TAG {
                uint8_t crcFlag;
            };

        private:
            static std::mt19937 mersenneTwister;

        public:
            static std::list<CRCIndicationPDU> createList(uint16_t n);
