```
#include "NFAPI/CRCIndicationPDU.h"

namespace NFAPI {
    std::mt19937 CRCIndicationPDU::mersenneTwister(std::random_device{}());

    std::list<CRCIndicationPDU> CRCIndicationPDU::createList(uint16_t n) {
        std::list<CRCIndicationPDU> list;
        for (uint16_t i = 0; i < n; ++i) {
            RX_UE_INFORMATION_TAG rxUETag;
            rxUETag.rnti = mersenneTwister() % 65536;
            rxUETag.crcFlag = mersenneTwister() % 2;

            CRC_INDICATION_REL8_TAG crcIndRel8Tag;
            crcIndRel8Tag.crcFlag = mersenneTwister() % 2;

            list.push_back(CRCIndicationPDU{rxUETag, crcIndRel8Tag});
        }
        return list;
    }
}
