#include <iostream>
#include <vector>
#include <random>
#include <ctime>

namespace Nfaapi {
    class NfarcrcGenerator {
        private:
            static std::mt19937 mt;

        public:
            static void generateCRCIndicationPDUs(const std::vector<RX_UE_INFORMATION_TAG>& rxUeInformationTags, const std::vector<RNTI>& rntis) {
                // Initialize the random number generator with a unique seed based on the current system time
                mt.seed(std::time(0));

                // Generate a list of NFAPI_CRC_INDICATION_PDU_T structures, each containing a valid RX_UE_INFORMATION_TAG and RNTI, along with a CRC_INDICATION_REL8_TAG
                std::vector<NFAPI_CRC_INDICATION_PDU_T> crcIndicationPDUs;
                for (const auto& rxUeInformationTag : rxUeInformationTags) {
                    for (const auto& rnti : rntis) {
                        NFAPI_CRC_INDICATION_PDU_T crcIndicationPdu;
                        crcIndicationPdu.rxUeInformationTag = rxUeInformationTag;
                        crcIndicationPdu.rnti = rnti;
                        crcIndicationPdu.crcIndicationRel8Tag = mt() % 2 == 0 ? CRC_INDICATION_REL8_TAG::CRC_INDICATION_REL8_TAG_TRUE : CRC_INDICATION_REL8_TAG::CRC_INDICATION_REL8_TAG_FALSE;
                        crcIndicationPDUs.push_back(crcIndicationPdu);
                    }
                }

                // Clear the generated structures when no longer needed to ensure proper memory management
                mt.clear();

                return crcIndicationPDUs;
            }
    };
