// Define the structure for a device connection record
typedef struct {
    char* device_id;
    int network_type;
    int connection_status;
    float quality_score;
    int flags;
    time_t last_update;
    int ref_count;
} DEVICE_CONN_RECORD;

// Define the structure for LTE cell information
typedef struct {
    int cell_id;
    int pci;
    float rsrp;
    int num_metrics;
    METRIC* metrics;
} LTE_CELL_INFO_T;

