    uint8_t payload[1500]; // MAC payload (up to 1500 bytes)
    uint32_t checksum; // Checksum of the frame
} MAC_FRAME_T;

// Function to dynamically generate and populate a list of MAC frames
MAC_FRAME_T* generateFrames(int numFrames, int payloadSize) {
    // Allocate memory for the list of frames
    MAC_FRAME_T* frames = (MAC_FRAME_T*)malloc(numFrames * sizeof(MAC_FRAME_T));
    if (!frames) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    // Initialize each frame with a valid MAC header, payload, and checksum
    for (int i = 0; i < numFrames; i++) {
        frames[i].header[0] = 0xAA; // Destination address
        frames[i].header[1] = 0xBB; // Source address
        frames[i].header[2] = 0xCC; // Frame control field
        frames[i].payload[0] = 0xDD; // Payload data
        frames[i].checksum = 0; // Initialize checksum to 0
    }

    // Calculate the checksum for each frame
    for (int i = 0; i < numFrames; i++) {
        uint32_t checksum = 0;
        for (int j = 0; j < payloadSize; j++) {
            checksum += frames[i].payload[j];
        }
        frames[i].checksum = checksum;
    }

    // Handle memory allocation failures by resetting the payload and reinitializing the checksum calculation
    if (frames == NULL) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    // Detect and mitigate packet duplication by checking for duplicate frames
    for (int i = 0; i < numFrames - 1; i++) {
        if (memcmp(frames[i].header, frames[i + 1].header, 14) == 0 && memcmp(frames[i].payload, frames[i + 1].payload, payloadSize) == 0) {
            printf("Duplicate frame detected\n");
            // Reset the payload and reinitialize the checksum calculation for the duplicate frame
            memset(frames[i].payload, 0, payloadSize);
            frames[i].checksum = 0;
        }
    }

    return frames;
}
