    time_t starttime;
    time_t endtime;
    char status;
    int refcount;
} OPERATION_LOG_ENTRY;

// Define function to generate random number within range
int rand_range(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Define function to create and populate file system operation records
void create_and_populate_file_system_operations(int num_ops, int seed, int concurrency_threshold, int logging_enabled) {
    // Initialize random number generator with seed value
    srand(seed);

    // Create array of file system operation records
    FILE_SYSTEM_OPERATION_RECORD *operations = (FILE_SYSTEM_OPERATION_RECORD *)malloc(num_ops * sizeof(FILE_SYSTEM_OPERATION_RECORD));

    // Populate array with random file system operation records
    for (int i = 0; i < num_ops; i++) {
        operations[i].id = i + 1;
        operations[i].type = 'R';
        operations[i].priority = rand_range(1, 5);
        operations[i].timestamp = time(NULL);
        operations[i].flags = 0;
        operations[i].refcount = 0;
    }

    // Sort array by priority level in descending order
    qsort(operations, num_ops, sizeof(FILE_SYSTEM_OPERATION_RECORD), compare_priority);

    // Create and populate operation log entries
    OPERATION_LOG_ENTRY *log = (OPERATION_LOG_ENTRY *)malloc(num_ops * sizeof(OPERATION_LOG_ENTRY));
    for (int i = 0; i < num_ops; i++) {
        log[i].loglevel = logging_enabled ? LOG_LEVEL_INFO : LOG_LEVEL_NONE;
        log[i].opid = operations[i].id;
        log[i].starttime = time(NULL);
        log[i].endtime = 0;
        log[i].status = 'S';
        log[i].refcount = 0;
    }

    // Dynamically adjust concurrency threshold based on external system load
    int current_load = get_system_load();
    if (current_load > concurrency_threshold) {
        concurrency_threshold = current_load + 1;
    }

    // Manage concurrent access to file system operations and log entries
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < num_ops; i++) {
        FILE_SYSTEM_OPERATION_RECORD *operation = &operations[i];
        OPERATION_LOG_ENTRY *log_entry = &log[i];

        // Check if operation priority meets or exceeds concurrency threshold
        if (operation->priority >= concurrency_threshold) {
            pthread_mutex_lock(&mutex);
            // Increment reference count for concurrent access to log entry
            log_entry->refcount++;
            // Update status of log entry to indicate in progress
            log_entry->status = 'I';
            pthread_mutex_unlock(&mutex);

            // Perform file system operation
            perform_file_system_operation(operation);

            pthread_mutex_lock(&mutex);
            // Decrement reference count for concurrent access to log entry
            log_entry->refcount--;
            // Update status of log entry to indicate completion
            log_entry->status = 'C';
            pthread_mutex_unlock(&mutex);
        } else {
            // Update status of log entry to indicate failure
            log_entry->status = 'F';
        }
    }

    // Free memory for file system operation records and log entries
    free(operations);
    free(log);
}

// Define function to perform file system operations
void perform_file_system_operation(FILE_SYSTEM_OPERATION_RECORD *operation) {
    // Perform file system operation based on operation type
