static record *hash_table = NULL;

// Function to dynamically populate a hash table of TCP connection states
record* populate_hash_table(int num_records, int ip_range, int port_protocol) {
    // Initialize the hash table with the specified number of records
    hash_table = (record*) malloc(num_records * sizeof(record));
    if (!hash_table) {
        printf("Error: Failed to allocate memory for hash table\n");
        return NULL;
    }

    // Initialize the socket IDs, packet sizes, and latency measurements arrays
    unsigned long *socket_ids = (unsigned long*) malloc(num_records * sizeof(unsigned long));
    int *packet_sizes = (int*) malloc(num_records * sizeof(int));
    float *latency_measurements = (float*) malloc(num_records * sizeof(float));
    if (!socket_ids || !packet_sizes || !latency_measurements) {
        printf("Error: Failed to allocate memory for arrays\n");
        free(hash_table);
        return NULL;
    }

    // Set the value of each record's integer field to a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        hash_table[i].integer_field = rand() % ip_range + 1;
    }

    // Populate the timestamp with the current time and initialize the latency field based on predefined criteria
    for (int i = 0; i < num_records; i++) {
        hash_table[i].timestamp = time(NULL);
        if (hash_table[i].integer_field % 2 == 0) {
            hash_table[i].latency = 1.0f;
        } else {
            hash_table[i].latency = 0.5f;
        }
    }

    // Track the total memory usage of all allocated structures and ensure that memory is freed upon function exit
    size_t total_memory_usage = num_records * sizeof(record) + num_records * sizeof(unsigned long) + num_records * sizeof(int) + num_records * sizeof(float);
    printf("Total memory usage: %lu bytes\n", total_memory_usage);
    free(socket_ids);
    free(packet_sizes);
    free(latency_measurements);

    // Handle concurrent access to shared resources safely using thread-safe mechanisms
    pthread_mutex_lock(&mutex);
    return hash_table;
}

// Function to handle memory exhaustion scenarios by implementing a retry mechanism with exponential backoff
void handle_memory_exhaustion(record* hash_table, int num_records) {
