                    new_data[j] = images[i].data[(x + y * images[i].width) * 2];
                }
                free(images[i].data);
                images[i].data = new_data;
            }
        }

        // Convert the image to a standard 8-bit RGB format for consistent processing
        if (cinfo.jpeg_color_space != JCS_RGB) {
