            memcpy(images[i].data, cinfo2.mem->mem, cinfo2.mem->size);
        }

        // Log the results in a structured data format
        printf("Image %d: %s\n", i + 1, images[i].filename);
        printf("\tWidth: %d\n", images[i].width);
        printf("\tHeight: %d\n", images[i].height);
        printf("\tColor Space: %d\n", images[i].color_space);
        printf("\tSubsampling Factors: %d, %d, %d\n", images[i].subsampling_factors[0], images[i].subsampling_factors[1], images[i].subsampling_factors[2]);
        printf("\tCompression Quality: %d\n", images[i].compression_quality);
        if (images[i].data != NULL) {
            printf("\tEmbedded Metadata: %s\n", images[i].data);
        } else {
            printf("\tNo Embedded Metadata\n");
        }

        // Close the JPEG file and free any allocated memory
        jpeg_destroy_decompress(&cinfo2);
        fclose(file);
    }
