#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>

// Struct to store extracted information about a TIFF image
struct tiff_info {
    int bits_per_sample;
    int samples_per_pixel;
    int compression_method;
    float resolution[2];
    int color_space;
    int extra_samples;
};

// Function to parse a TIFF image file and extract detailed information about its structure
struct tiff_info parse_tiff(const char* filename) {
    struct tiff_info info = {0};
    TIFF *tif = TIFFOpen(filename, "r");
    if (tif == NULL) {
        fprintf(stderr, "Error opening TIFF file: %s\n", filename);
        return info;
    }

    // Get the image width and height
    uint32 width, height;
    TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width);
    TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height);

    // Get the bits per sample and samples per pixel
    uint16 bps;
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bps);
    info.bits_per_sample = bps;
    uint16 spp;
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &spp);
    info.samples_per_pixel = spp;

    // Get the compression method and resolution
    uint16 cm;
    TIFFGetField(tif, TIFFTAG_COMPRESSION, &cm);
    info.compression_method = cm;
    float res[2];
    TIFFGetField(tif, TIFFTAG_XRESOLUTION, &res[0]);
    TIFFGetField(tif, TIFFTAG_YRESOLUTION, &res[1]);
    info.resolution[0] = res[0];
    info.resolution[1] = res[1];

    // Get the color space and extra samples
    uint16 cs;
    TIFFGetField(tif, TIFFTAG_PHOTOMETRIC, &cs);
    info.color_space = cs;
    uint16 es;
    TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &es);
    info.extra_samples = es;

    // Validate the consistency of metadata and warn if there are discrepancies between image dimensions and number of samples
    uint32 npixels = width * height;
    if (npixels != spp * npixels) {
        fprintf(stderr, "Warning: inconsistent metadata in TIFF file %s\n", filename);
    }

    // Close the TIFF file and return the extracted information
    TIFFClose(tif);
    return info;
}
```
