// Define function to create device connection list with user management
void createDeviceConnectionListWithUserManagement(int N, int seed, int quality_threshold, bool enable_logging) {
    // Initialize variables
    srand(seed);
    DEVICE_CONN_RECORD* device_conn_list = (DEVICE_CONN_RECORD*)malloc(sizeof(DEVICE_CONN_RECORD) * N);
    int num_devices = 0;
    bool throttling_enabled = false;
    int throttling_rate = 10; // default throttling rate of 10 new connections per second

    // Loop through input parameters to populate device connection list
    for (int i = 0; i < N; i++) {
        // Generate random device identifier and network type
        char* device_id = generateRandomDeviceId();
        int network_type = generateRandomNetworkType();

        // Check if device is connected and has a quality score greater than or equal to threshold
        bool connected = checkConnectionStatus(device_id, network_type);
        int quality_score = getQualityScore(device_id, network_type);
        if (quality_score >= quality_threshold) {
            // Add device connection record to list
            device_conn_list[num_devices].device_id = device_id;
            device_conn_list[num_devices].network_type = network_type;
            device_conn_list[num_devices].connected = connected;
            device_conn_list[num_devices].quality_score = quality_score;
            device_conn_list[num_devices].flags = 0;
            device_conn_list[num_devices].last_update = time(NULL);
            num_devices++;
        } else {
            // Free memory for device identifier and network type
            free(device_id);
            device_id = NULL;
            free(network_type);
            network_type = NULL;
        }
    }

    // Check if throttling is enabled and adjust throttling rate based on current load
    if (throttling_enabled) {
        int current_load = getCurrentLoad();
        if (current_load > 0.8) {
            throttling_rate = 5; // adjust throttling rate to 5 new connections per second
        } else if (current_load > 0.6) {
            throttling_rate = 10; // adjust throttling rate to 10 new connections per second
        } else {
            throttling_rate = 20; // adjust throttling rate to 20 new connections per second
        }
    }

    // Loop through device connection list and add new devices at a maximum rate of throttling_rate
    for (int i = 0; i < num_devices; i++) {
        if (throttling_enabled && i % throttling_rate == 0) {
            continue; // skip adding new device if throttling is enabled and maximum rate has been reached
        }
        char* device_id = generateRandomDeviceId();
        int network_type = generateRandomNetworkType();
        bool connected = checkConnectionStatus(device_id, network_type);
        int quality_score = getQualityScore(device_id, network_type);
        if (quality_score >= quality_threshold) {
            device_conn_list[num_devices].device_id = device_id;
            device_conn_list[num_devices].network_type = network_type;
            device_conn_list[num_devices].connected = connected;
            device_conn_list[num_devices].quality_score = quality_score;
            device_conn_list[num_devices].flags = 0;
            device_conn_list[num_devices].last_update = time(NULL);
            num_devices++;
        } else {
            free(device_id);
            device_id = NULL;
            free(network_type);
            network_type = NULL;
        }
    }

    // Free memory for device connection list and return
    free(device_conn_list);
    device_conn_list = NULL;
}

