#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int connection_id;
    time_t timestamp;
    bool status;
} network_connection_report;

network_connection_report* reports = NULL;
size_t num_reports = 0;
pthread_mutex_t report_lock = PTHREAD_MUTEX_INITIALIZER;

void add_report(int connection_id, time_t timestamp, bool status) {
    network_connection_report* new_report = malloc(sizeof(network_connection_report));
    new_report->connection_id = connection_id;
    new_report->timestamp = timestamp;
    new_report->status = status;

    pthread_mutex_lock(&report_lock);
    reports = realloc(reports, (num_reports + 1) * sizeof(network_connection_report));
    reports[num_reports++] = new_report;
    pthread_mutex_unlock(&report_lock);
}

void update_report(int connection_id, time_t timestamp, bool status) {
    network_connection_report* report = NULL;

    pthread_mutex_lock(&report_lock);
    for (size_t i = 0; i < num_reports; i++) {
        if (reports[i]->connection_id == connection_id) {
            report = reports[i];
            break;
        }
    }
    pthread_mutex_unlock(&report_lock);

    if (report != NULL) {
        report->timestamp = timestamp;
        report->status = status;
    }
}

network_connection_report* get_active_report() {
    network_connection_report* active_report = NULL;

    pthread_mutex_lock(&report_lock);
    for (size_t i = 0; i < num_reports; i++) {
        if (reports[i]->status) {
            active_report = reports[i];
            break;
        }
    }
    pthread_mutex_unlock(&report_lock);

    return active_report;
}
