typedef struct {
    int RRC_STATE;
    long TMSI;
    char* NAS_MESSAGE;
    int STATUS_CODE;
} UEContext;

typedef struct {
    int frequencyBand;
    int cellID;
} NetworkConfig;

// Define a linked list for storing UE contexts
typedef struct {
    UEContext* ueContext;
    struct Node* next;
} UELinkedList;

// Define a cache for frequently accessed UE contexts
