    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is full and needs to be resized
    if (cache->capacity == 0 || cache->size >= cache->capacity) {
        cache->capacity *= 2;
        setting_t *new_settings = (setting_t *)realloc(cache->settings, cache->capacity * sizeof(setting_t));
