    if (!sessions) {
        printf("Error: Failed to allocate memory for %d sessions\n", n);
        free(list);
        return NULL;
    }

    // Initialize each session in the list
    for (int i = 0; i < n; i++) {
        Session* session = (Session*)malloc(sizeof(Session));
        if (!session) {
            printf("Error: Failed to allocate memory for session %d\n", i);
            free(sessions);
            free(list);
            return NULL;
