        // Set the ID, username, last active timestamp, status, priority level, and duration of the session
        session->id = i + 1;
        session->username = "user";
        session->last_active = time(NULL);
        session->status = 0;
        session->priority = 1;
        session->duration = 30;

        // Add the session to the list
        sessions[i] = session;
    }

    // Set the sessions pointer in the list
    list->sessions = sessions;

    return list;
}

