    if (!list) {
        printf("Error: Failed to create session list\n");
        return;
    }

    // Initialize the number of active sessions
    int num_active_sessions = 0;

    // Loop through each session in the list and update its status based on the priority threshold
    for (int i = 0; i < n; i++) {
        Session* session = list->sessions[i];
        if (session->priority >= priority_threshold) {
            num_active_sessions++;
            session->status = 1;
        } else {
            session->status = 0;
        }
    }

    // Print the number of active sessions and the longest session duration
