    int longest_duration = 0;
    for (int i = 0; i < n; i++) {
        Session* session = list->sessions[i];
        if (session->status == 1 && session->duration > longest_duration) {
            longest_duration = session->duration;
        }
    }
    printf("Longest session duration: %d\n", longest_duration);

    // Free the memory for the list of sessions
