network_element_config *network_element_configs = NULL;
lte_ue_context_record *lte_ue_context_records = NULL;

// Define the function to manage dynamic collections of network element configurations and LTE UE Context Information Records
void manage_collections(int N, int seed, bool degraded) {
    // Initialize the collections with the given number of elements
    network_element_configs = (network_element_config *)malloc(N * sizeof(network_element_config));
    lte_ue_context_records = (lte_ue_context_record *)malloc(N * sizeof(lte_ue_context_record));

    // Populate the collections with random data
    srand(seed);
    for (int i = 0; i < N; i++) {
