    ue_context_info_record* ue_context_records = (ue_context_info_record*)malloc(n * sizeof(ue_context_info_record));
    if (!ue_context_records) {
        printf("Error: Failed to allocate memory for UE context information records\n");
        free(configurations);
        return;
    }

    // Initialize array of update and delete indications
    update_indication* update_indications = (update_indication*)malloc(n * sizeof(update_indication));
    if (!update_indications) {
        printf("Error: Failed to allocate memory for update indications\n");
        free(configurations);
        free(ue_context_records);
        return;
    }

    delete_indication* delete_indications = (delete_indication*)malloc(n * sizeof(delete_indication));
    if (!delete_indications) {
        printf("Error: Failed to allocate memory for delete indications\n");
        free(configurations);
        free(ue_context_records);
        free(update_indications);
        return;
    }

    // Initialize random number generator with seed value
    srand(seed);

    // Populate network element configurations and UE context information records
    for (int i = 0; i < n; i++) {
        configurations[i].id = i + 1;
        configurations[i].ip_address = "192.168.1.1";
        configurations[i].port = 8080;
        configurations[i].connected = true;
        ue_context_records[i].ue_id = i + 1;
        ue_context_records[i].serving_cell = "Cell 1";
        ue_context_records[i].mobility_status = false;
        ue_context_records[i].last_update_time = time(NULL);
    }

    // Initialize update and delete indications with random or user-specified values
    for (int i = 0; i < n; i++) {
        update_indications[i].resource_identifier = rand() % n + 1;
        update_indications[i].request_body = "{\"ue_id\":\"1\", \"serving_cell\":\"Cell 2\", \"mobility_status\":true}";
        update_indications[i].action_type_tag = 'U';
        delete_indications[i].resource_identifier = rand() % n + 1;
    }

    // Implement thread-safe operations and efficient memory allocation under high-load conditions
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Manage network element configurations and UE context information records
    for (int i = 0; i < n; i++) {
        pthread_mutex_lock(&mutex);
        if (update_indications[i].action_type_tag == 'U') {
            // Update network element configuration
            configurations[update_indications[i].resource_identifier - 1].ip_address = update_indications[i].request_body;
