#include <string.h>
#include <pthread.h>

// Define a structure to represent a record
typedef struct {
    int key;
    long offset;
} Record;

// Define a pool of memory for the records
static const size_t POOL_SIZE = 1024 * 1024; // 1 MB
static char pool[POOL_SIZE];

// Define a mutex to protect concurrent access to the pool
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate a new record from the pool
Record* alloc_record(int key, long offset) {
    // Acquire the mutex to prevent concurrent access to the pool
    pthread_mutex_lock(&pool_mutex);

    // Find the first available memory block in the pool
    char* mem = NULL;
    for (size_t i = 0; i < POOL_SIZE; i++) {
        if (pool[i] == '\0') {
            mem = &pool[i];
            break;
        }
    }

    // If no memory block is available, return NULL
    if (mem == NULL) {
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }

    // Initialize the record structure and set its key and offset values
    Record* rec = (Record*) mem;
    rec->key = key;
    rec->offset = offset;

    // Mark the memory block as used in the pool
    *mem = '1';

    // Release the mutex to allow other threads to access the pool
    pthread_mutex_unlock(&pool_mutex);

    return rec;
}

// Function to free a record from the pool
void free_record(Record* rec) {
    // Acquire the mutex to prevent concurrent access to the pool
    pthread_mutex_lock(&pool_mutex);

    // Find the memory block corresponding to the record
    char* mem = (char*) rec;

    // Mark the memory block as available in the pool
    *mem = '\0';

    // Release the mutex to allow other threads to access the pool
    pthread_mutex_unlock(&pool_mutex);
}

// Function to update a record's key and offset values
void update_record(Record* rec, int new_key, long new_offset) {
    // Acquire the mutex to prevent concurrent access to the pool
    pthread_mutex_lock(&pool_mutex);

    // Update the record structure's key and offset values
    rec->key = new_key;
    rec->offset = new_offset;

    // Release the mutex to allow other threads to access the pool
    pthread_mutex_unlock(&pool_mutex);
}

// Function to retrieve a record from the pool based on its key value
Record* get_record(int key) {
    // Acquire the mutex to prevent concurrent access to the pool
    pthread_mutex_lock(&pool_mutex);

    // Iterate over the records in the pool and find the one with the matching key
    for (size_t i = 0; i < POOL_SIZE; i++) {
        char* mem = &pool[i];
        if (*mem == '1' && ((Record*) mem)->key == key) {
            // Return a pointer to the record structure
            Record* rec = (Record*) mem;
            pthread_mutex_unlock(&pool_mutex);
            return rec;
        }
    }

    // If no matching record is found, return NULL
    pthread_mutex_unlock(&pool_mutex);
    return NULL;
}
