#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Structure to represent a user authentication session
typedef struct {
    int session_id;
    time_t expiration_time;
    char* config_settings;
    bool is_active;
} Session;

// Linked list node for storing sessions
typedef struct Node {
    Session* data;
    struct Node* next;
} Node;

// Global variable to store the head of the linked list
Node* head = NULL;

// Function to add a new session to the linked list
void add_session(int session_id, time_t expiration_time, char* config_settings) {
    // Create a new node for the session
    Node* new_node = malloc(sizeof(Node));
    new_node->data = malloc(sizeof(Session));
    new_node->data->session_id = session_id;
    new_node->data->expiration_time = expiration_time;
    new_node->data->config_settings = config_settings;
    new_node->data->is_active = true;

    // Add the node to the linked list
    if (head == NULL) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to update the configuration settings of a session
void update_session(int session_id, char* config_settings) {
    // Find the node with the matching session ID
    Node* current = head;
    while (current != NULL && current->data->session_id != session_id) {
        current = current->next;
    }

    // Update the configuration settings if the node is found
    if (current != NULL) {
        free(current->data->config_settings);
        current->data->config_settings = config_settings;
    }
}

// Function to extend the expiration time of a session
void extend_session(int session_id, time_t new_expiration_time) {
    // Find the node with the matching session ID
    Node* current = head;
    while (current != NULL && current->data->session_id != session_id) {
        current = current->next;
    }

    // Extend the expiration time if the node is found
    if (current != NULL) {
        current->data->expiration_time = new_expiration_time;
    }
}

// Function to retrieve the longest-lasting active session for a given user
Session* get_longest_session(int user_id) {
    // Find the node with the matching user ID
    Node* current = head;
    while (current != NULL && current->data->user_id != user_id) {
        current = current->next;
    }

    // Return the longest-lasting active session if the node is found
    if (current != NULL) {
        Session* longest_session = current->data;
        Node* next = current->next;
        while (next != NULL) {
            if (longest_session->expiration_time < next->data->expiration_time && next->data->is_active) {
                longest_session = next->data;
            }
            next = next->next;
        }
        return longest_session;
    } else {
        return NULL;
    }
}

// Function to revoke a session under certain conditions
void revoke_session(int session_id) {
    // Find the node with the matching session ID
    Node* current = head;
    while (current != NULL && current->data->session_id != session_id) {
        current = current->next;
    }

    // Revoke the session if the node is found
    if (current != NULL) {
        current->data->is_active = false;
    }
}
