    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize the unique key array with random values within the specified range
    srand(seed);
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % max_mem_limit;
    }

    // Allocate memory for the record array
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
