// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Define the memory pool structure
typedef struct {
    size_t capacity; // Total number of records in the pool
    size_t used; // Number of records currently in use
    size_t free; // Number of free records available for allocation
    Record* records; // Array of record structures
} MemoryPool;

// Define the custom memory allocator function
void* my_alloc(size_t size) {
    // Allocate memory from the pool
    MemoryPool* pool = get_memory_pool();
    if (pool->free == 0) {
        // No free records available, expand the pool
        pool->capacity += 10;
        pool->records = realloc(pool->records, pool->capacity * sizeof(Record));
        memset(pool->records + pool->used, 0, pool->free * sizeof(Record));
    }
    Record* record = &pool->records[pool->used++];
    pool->free--;
    return record;
}

// Define the custom memory deallocator function
void my_dealloc(void* ptr) {
    // Deallocate memory from the pool
    MemoryPool* pool = get_memory_pool();
    Record* record = (Record*)ptr;
    if (record < pool->records || record >= pool->records + pool->used) {
        return;
    }
    pool->free++;
}

// Define the function to manage a collection of records
void manage_records(int num_records, int key_range) {
    // Initialize the memory pool
    MemoryPool* pool = get_memory_pool();
    pool->capacity = 10;
    pool->used = 0;
    pool->free = 0;
    pool->records = malloc(pool->capacity * sizeof(Record));
    memset(pool->records, 0, pool->capacity * sizeof(Record));

    // Initialize the records with random values within the specified range
