    if (idle_sockets == NULL) {
        free(sockets);
        sockets = NULL;
    }

    // Loop over the file generation tasks and generate files concurrently
    while (1) {
        // Get an idle socket descriptor from the pool
        int* idle_socket = getIdleSocket(idle_sockets, num_connections);

        if (idle_socket == NULL) {
            break;
        }

        // Create a new file generation task
