        if (new_sockets == NULL) {
            free(sockets);
            sockets = NULL;
            break;
        }
        sockets = new_sockets;
        sockets[num_sockets++] = createSocket();
    }

    // Close the socket descriptors and free memory
    for (int i = 0; i < num_connections; i++) {
        close(sockets[i]);
    }
    free(sockets);
    sockets = NULL;

    for (int i = 0; i < num_connections; i++) {
        free(connections[i].data);
