// Custom memory allocator for the list
void* my_malloc(size_t size) {
  void* ptr = malloc(size);
  if (!ptr) {
    printf("Memory allocation failed\n");
    return NULL;
  }
  return ptr;
}

// Custom memory deallocator for the list
void my_free(void* ptr) {
  free(ptr);
}

// Structure to represent a single element in the list
typedef struct NFAPI_CRC_INDICATION_PDU_T {
  RX_UE_INFORMATION_TAG rx_ue_information_tag;
  RNTI rnti;
  CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Structure to represent the list of elements
typedef struct NFAPI_CRC_INDICATION_LIST {
  size_t capacity; // Maximum number of elements in the list
  size_t count; // Current number of elements in the list
  NFAPI_CRC_INDICATION_PDU_T* elements; // Array of elements
} NFAPI_CRC_INDICATION_LIST;

// Function to create a new empty list
NFAPI_CRC_INDICATION_LIST* nfapi_crc_indication_list_create() {
  NFAPI_CRC_INDICATION_LIST* list = my_malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
  if (!list) {
    return NULL;
  }
  list->capacity = 10000; // Default capacity of the list
  list->count = 0; // Initially empty list
  list->elements = my_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
  if (!list->elements) {
    my_free(list);
    return NULL;
  }
  return list;
}

// Function to add a new element to the list
int nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST* list, RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
  if (!list || !rx_ue_information_tag || !rnti || !crc_indication_rel8_tag) {
    return -1; // Invalid input parameters
  }
  if (list->count == list->capacity) {
    // List is full, need to resize it
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_elements = my_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_elements) {
      return -1; // Memory allocation failed
    }
    memcpy(new_elements, list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->count);
    my_free(list->elements);
    list->elements = new_elements;
    list->capacity = new_capacity;
  }
  NFAPI_CRC_INDICATION_PDU_T* element = &list->elements[list->count];
  element->rx_ue_information_tag = rx_ue_information_tag;
  element->rnti = rnti;
  element->crc_indication_rel8_tag = crc_indication_rel8_tag;
  list->count++;
  return 0; // Success
}

// Function to retrieve an element from the list by index
NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_list_get(NFAPI_CRC_INDICATION_LIST* list, size_t index) {
  if (!list || index >= list->count) {
    return NULL; // Invalid input parameters or out of range
  }
  return &list->elements[index];
}

// Function to remove an element from the list by index
int nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST* list, size_t index) {
  if (!list || index >= list->count) {
    return -1; // Invalid input parameters or out of range
  }
  memmove(&list->elements[index], &list->elements[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count - index - 1));
  list->count--;
  return 0; // Success
}

// Function to validate the input parameters before adding an element to the list
int nfapi_crc_indication_validate(RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti) {
  if (!rx_ue_information_tag || !rnti) {
    return -1; // Invalid input parameters
  }
  return 0; // Success
}

// Function to handle out-of-memory conditions by reducing the number of elements until successful allocation is possible
void nfapi_crc_indication_handle_oom(NFAPI_CRC_INDICATION_LIST* list) {
  while (list->count > 0 && !my_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
    nfapi_crc_indication_remove(list, list->count - 1);
  }
}

// Function to handle concurrent access to the list by multiple threads without data corruption
void nfapi_crc_indication_lock(NFAPI_CRC_INDICATION_LIST* list) {
  pthread_mutex_lock(&list->mutex);
}

void nfapi_crc_indication_unlock(NFAPI_CRC_INDICATION_LIST* list) {
  pthread_mutex_unlock(&list->mutex);
}
