    int sorting_criteria;
    int transformation_rules;
    int filtering_conditions;
} ConfigData;

// Define the structure for storing the array data
typedef struct {
    int *data;
    int size;
} ArrayData;

// Define the function to read the configuration file and initialize the config data
ConfigData* init_config(char* filename) {
    ConfigData* config = (ConfigData*)malloc(sizeof(ConfigData));
    // Read the configuration file and populate the config data structure
    return config;
}

// Define the function to read the array data from standard input
ArrayData* init_array() {
    ArrayData* array = (ArrayData*)malloc(sizeof(ArrayData));
    // Read the array data from standard input and populate the array data structure
    return array;
}

// Define the function to process the array data according to the configuration file
void process_array(ConfigData* config, ArrayData* array) {
    // Initialize the statistics variables
    int max = -1;
    double mean = 0.0;
    double median = 0.0;
    int mode = -1;
    int count[config->max_array_size] = {0};

    // Sort the array data according to the sorting criteria
    if (config->sorting_criteria == 1) {
        // Bubble sort
        for (int i = 0; i < array->size - 1; i++) {
            for (int j = 0; j < array->size - i - 1; j++) {
                if (array->data[j] > array->data[j + 1]) {
                    int temp = array->data[j];
                    array->data[j] = array->data[j + 1];
                    array->data[j + 1] = temp;
                }
            }
        }
    } else if (config->sorting_criteria == 2) {
        // Quick sort
        quickSort(array->data, 0, array->size - 1);
    }

    // Transform the array data according to the transformation rules
    if (config->transformation_rules & 1) {
        // Add 1 to each element
        for (int i = 0; i < array->size; i++) {
            array->data[i] += 1;
        }
    } else if (config->transformation_rules & 2) {
        // Multiply each element by 2
        for (int i = 0; i < array->size; i++) {
            array->data[i] *= 2;
        }
    }

    // Filter the array data according to the filtering conditions
    if (config->filtering_conditions & 1) {
        // Remove elements less than or equal to 0
        int new_size = 0;
        for (int i = 0; i < array->size; i++) {
            if (array->data[i] > 0) {
                array->data[new_size++] = array->data[i];
            }
        }
        array->size = new_size;
    } else if (config->filtering_conditions & 2) {
        // Remove elements greater than or equal to the maximum value
        int max = -1;
        for (int i = 0; i < array->size; i++) {
            if (array->data[i] > max) {
                max = array->data[i];
            }
        }
        int new_size = 0;
        for (int i = 0; i < array->size; i++) {
            if (array->data[i] < max) {
                array->data[new_size++] = array->data[i];
            }
        }
        array->size = new_size;
    }

    // Calculate the statistics of the filtered array data
    for (int i = 0; i < array->size; i++) {
        count[array->data[i]]++;
    }
    mean = calculate_mean(count, array->size);
    median = calculate_median(count, array->size);
    mode = calculate_mode(count, array->size);

    // Print the statistics of the filtered array data
    printf("Maximum value: %d\n", max);
    printf("Mean: %.2f\n", mean);
    printf("Median: %.2f\n", median);
    printf("Mode: %d\n", mode);
}

// Define the function to calculate the mean of an array
double calculate_mean(int* count, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += count[i];
    }
    return sum / size;
}

// Define the function to calculate the median of an array
double calculate_median(int* count, int size) {
    // Sort the array data according to the sorting criteria
    if (config->sorting_criteria == 1) {
        // Bubble sort
        for (int i = 0; i < size - 1; i++) {
            for (int j = 0; j < size - i - 1; j++) {
                if (array->data[j] > array->data[j + 1]) {
                    int temp = array->data[j];
                    array->data[j] = array->data[j + 1];
                    array->data[j + 1] = temp;
                }
            }
        }
    } else if (config->sorting_criteria == 2) {
        // Quick sort
        quickSort(array->data, 0, size - 1);
    }

    // Calculate the median of the sorted array data
    if (size % 2 == 0) {
        return (double)(array->data[size / 2] + array->data[size / 2 - 1]) / 2;
    } else {
        return (double)array->data[size / 2];
    }
}

// Define the function to calculate the mode of an array
int calculate_mode(int* count, int size) {
    // Find the maximum value in the array data
    int max = -1;
    for (int i = 0; i < size; i++) {
        if (count[i] > max) {
            max = count[i];
        }
    }

    // Find the index of the maximum value in the array data
    int max_index = -1;
    for (int i = 0; i < size; i++) {
        if (count[i] == max) {
            max_index = i;
            break;
        }
    }

    // Return the mode of the array data
    return array->data[max_index];
}

// Define the function to sort an array using quicksort algorithm
void quickSort(int* arr, int low, int high) {
    if (low < high) {
        // Partition the array into two subarrays
        int pivot = partition(arr, low, high);

        // Recursively sort the left and right subarrays
        quickSort(arr, low, pivot - 1);
        quickSort(arr, pivot + 1, high);
    }
}

// Define the function to partition an array using quicksort algorithm
int partition(int* arr, int low, int high) {
    // Select a pivot element from the array
    int pivot = arr[low];

    // Divide the array into two subarrays based on the pivot element
    int i = low + 1;
    for (int j = low + 1; j <= high; j++) {
        if (arr[j] < pivot) {
            swap(arr, i++, j);
        }
    }

    // Swap the pivot element with the middle element of the left subarray
    swap(arr, low, --i);

    // Return the index of the pivot element
    return i;
}

// Define the function to swap two elements in an array
void swap(int* arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}
```
