        Random random = new Random(seedValue);
        for (int i = 0; i < numRecords; i++) {
            USER_SESSION_RECORD userSessionRecord = new USER_SESSION_RECORD();
            userSessionRecord.userId = random.nextInt(1000);
            userSessionRecord.serviceType = "UMTS";
            userSessionRecord.connectionStatus = true;
            userSessionRecord.bandwidthAllocation = random.nextInt(1000) + 1;
            userSessionRecord.lastUpdateTimestamp = System.currentTimeMillis();
            userSessionRecord.flags = 0;
            if (userSessionRecord.bandwidthAllocation >= bandwidthThreshold) {
                userSessionRecords.add(userSessionRecord);
            } else {
                LOGGER.info("Skipping user session record with bandwidth allocation " + userSessionRecord.bandwidthAllocation);
            }
        }
    }

    public List<UMTS_PDU> generateUmtsPdus() {
        List<UMTS_PDU> umtsPdus = new ArrayList<>();
        for (USER_SESSION_RECORD userSessionRecord : userSessionRecords) {
