            umtsPdu.userInfoTag = new UMTS_USER_INFO_TAG(umtsPdu.userSessionRecord.userId, umtsPdu.userSessionRecord.serviceType);
            umtsPdu.rnti = new UMTS_RNTI(random.nextInt(1000));
            umtsPdu.pduDataTag = new UMTS_PDU_DATA_TAG(true);
            umtsPdu.timestamp = System.currentTimeMillis();
            umtsPdu.flags = 0;
            umtsPdus.add(umtsPdu);
        }
        return umtsPdus;
    }

