// Define the maximum size of the array
#define MAX_ARRAY_SIZE 1024

// Define the structure for a MAC PDU
typedef struct {
    int type;
    int sequence_number;
    char* payload;
} MAC_PDU;

// Function to dynamically allocate memory for an array of MAC PDUs
MAC_PDU** alloc_mac_pdu_array(int size) {
    // Check if the requested size exceeds the maximum allowed size
    if (size > MAX_ARRAY_SIZE) {
        fprintf(stderr, "Error: Requested array size exceeds maximum allowed size\n");
        return NULL;
    }

    // Allocate memory for the array of MAC PDUs
    MAC_PDU** mac_pdu_array = (MAC_PDU**)malloc(size * sizeof(MAC_PDU*));
    if (!mac_pdu_array) {
        fprintf(stderr, "Error: Failed to allocate memory for the array of MAC PDUs\n");
        return NULL;
    }

    // Initialize each element in the array with a valid MAC PDU structure
    for (int i = 0; i < size; i++) {
        mac_pdu_array[i] = (MAC_PDU*)malloc(sizeof(MAC_PDU));
        if (!mac_pdu_array[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for MAC PDU %d\n", i);
            return NULL;
        }
        mac_pdu_array[i]->type = 0;
        mac_pdu_array[i]->sequence_number = 0;
        mac_pdu_array[i]->payload = NULL;
    }

    // Return the allocated array of MAC PDUs
    return mac_pdu_array;
}

// Function to free memory for an array of MAC PDUs
void free_mac_pdu_array(MAC_PDU** mac_pdu_array, int size) {
    // Free each element in the array
    for (int i = 0; i < size; i++) {
        if (mac_pdu_array[i]) {
            free(mac_pdu_array[i]);
        }
    }

    // Free the memory allocated for the array itself
    free(mac_pdu_array);
}
