COLLECTION* create_collection(int size) {
    // Allocate memory for the collection
    COLLECTION* collection = (COLLECTION*)malloc(sizeof(COLLECTION));
    if (!collection) {
        printf("Error: Failed to allocate memory for collection\n");
        return NULL;
    }

    // Initialize the size and capacity of the collection
    collection->size = 0;
    collection->capacity = size;

    // Allocate memory for the records in the collection
    collection->records = (FILE_SYSTEM_OPERATION_RECORD*)malloc(sizeof(FILE_SYSTEM_OPERATION_RECORD) * size);
    if (!collection->records) {
        printf("Error: Failed to allocate memory for records in collection\n");
        free(collection);
        return NULL;
    }

    // Initialize the flags and refcount fields of each record
    for (int i = 0; i < size; i++) {
        collection->records[i].flags = 0;
        collection->records[i].refcount = 0;
    }

    return collection;
}

// Define the function to add a new file system operation record to the collection
