    // Check if the collection is empty
    if (collection->size == 0) {
        printf("Error: Collection is empty\n");
        return -1;
    }

    // Find the record with the specified ID and remove it from the collection
    for (int i = 0; i < collection->size; i++) {
        if (collection->records[i].id == id) {
            collection->size--;
            memmove(&collection->records[i], &collection->records[i + 1], sizeof(FILE_SYSTEM_OPERATION_RECORD) * (collection->size - i));
            return 0;
