using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace DynamicValueManager
{
    public class DynamicValueManager
    {
        private List<Range> ranges = new List<Range>();

        public void AddRange(int min, int max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

            ranges.Add(new Range(min, max));
        }

        public void RemoveRange(int index)
        {
            if (index < 0 || index >= ranges.Count)
                throw new ArgumentOutOfRangeException("Index must be within the range of existing ranges.");

            ranges.RemoveAt(index);
        }

        public int GetRandomValue(int index)
        {
            if (index < 0 || index >= ranges.Count)
                throw new ArgumentOutOfRangeException("Index must be within the range of existing ranges.");

            return ranges[index].GetRandomValue();
        }

        public void ShiftRanges(int offset)
        {
            foreach (var range in ranges)
            {
                range.Min += offset;
                range.Max += offset;
            }
        }

        public void ScaleRanges(float factor)
        {
            foreach (var range in ranges)
            {
                range.Min = (int)(range.Min * factor);
                range.Max = (int)(range.Max * factor);
            }
        }

        public void MergeRanges(int index1, int index2)
        {
            if (index1 < 0 || index1 >= ranges.Count)
                throw new ArgumentOutOfRangeException("Index1 must be within the range of existing ranges.");

            if (index2 < 0 || index2 >= ranges.Count)
                throw new ArgumentOutOfRangeException("Index2 must be within the range of existing ranges.");

            var range1 = ranges[index1];
            var range2 = ranges[index2];

            if (!range1.Overlaps(range2))
                return;

            ranges.RemoveAt(index2);
            ranges.Insert(index1, new Range(Math.Min(range1.Min, range2.Min), Math.Max(range1.Max, range2.Max)));
        }

        public override string ToString()
        {
            var sb = new StringBuilder();

            foreach (var range in ranges)
            {
                sb.AppendLine($"Range: [{range.Min}, {range.Max}]");
            }

            return sb.ToString();
        }

        public string Serialize()
        {
            var json = JsonConvert.SerializeObject(ranges);
            return json;
        }

        public void Deserialize(string json)
        {
            ranges = JsonConvert.DeserializeObject<List<Range>>(json);
        }

        public float GetMean()
        {
            var sum = 0f;
            foreach (var range in ranges)
            {
                sum += range.GetMean();
            }

            return sum / ranges.Count;
        }

        public float GetStandardDeviation()
        {
            var mean = GetMean();
            var variance = 0f;
            foreach (var range in ranges)
            {
                variance += Math.Pow(range.GetMean() - mean, 2);
            }

            return (float)Math.Sqrt(variance / ranges.Count);
        }

        public int GetSmallestValue()
        {
            var smallest = int.MaxValue;
            foreach (var range in ranges)
            {
                smallest = Math.Min(smallest, range.GetSmallestValue());
            }

            return smallest;
        }

        public int GetLargestValue()
        {
            var largest = int.MinValue;
            foreach (var range in ranges)
            {
                largest = Math.Max(largest, range.GetLargestValue());
            }

            return largest;
        }

        public float GetRandomValue(float weight1, float weight2)
        {
            var totalWeight = weight1 + weight2;
            var randomValue = Random.NextDouble() * totalWeight;

            if (randomValue < weight1)
                return ranges[0].GetRandomValue();
            else
                return ranges[1].GetRandomValue();
        }

        public void ValidateValues(int[] values, int[] constraints)
        {
            foreach (var value in values)
            {
                if (!IsValidValue(value, constraints))
                    throw new ArgumentException("Invalid value detected.");
            }
        }

        private bool IsValidValue(int value, int[] constraints)
