#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdbool.h>

// Define the structure for the NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the configuration parameters for the function
#define MAX_BUFFER_SIZE 1024 // Maximum buffer size for file reading
#define MAX_NUM_STRUCTURES 100 // Maximum number of structures to allocate memory for
#define BUFFER_SIZE_MULTIPLIER 2 // Buffer size multiplier for asynchronous operations
#define ERROR_LOG_FILE "error.log" // File name for error log file

// Define the function that loads the resource bundle from a file and returns the number of unique items
int loadResourceBundleFromFile(const char* filename, int numStructures) {
    // Initialize variables
    int bufferSize = MAX_BUFFER_SIZE;
    int numItems = 0;
    bool isBufferFull = false;
    bool isCancelled = false;
    sem_t *semaphore = NULL;
    pthread_t threadId = 0;
    NFAPI_CRC_INDICATION_PDU_T* structures = NULL;

    // Allocate memory for the structures array
    structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        perror("Failed to allocate memory for structures");
        return -1;
    }

    // Create a semaphore for synchronizing asynchronous operations
    semaphore = sem_open("/semaphore", O_CREAT, 0644, 0);
    if (!semaphore) {
        perror("Failed to create semaphore");
        return -1;
    }

    // Create a thread for reading the file asynchronously
    pthread_create(&threadId, NULL, readFileAsync, (void*)filename);

    // Loop until the buffer is full or cancellation is requested
    while (!isBufferFull || !isCancelled) {
        // Wait on the semaphore to be signaled by the thread
        if (sem_wait(semaphore)) {
            perror("Failed to wait on semaphore");
            return -1;
        }

        // Check if cancellation was requested
        isCancelled = checkCancellation();
        if (isCancelled) {
            break;
        }

        // Read the next line from the file and parse it
        char* line = readNextLine(filename);
        if (!line) {
            continue;
        }

        // Ignore comments and whitespace in the line
        char* nonCommentLine = ignoreCommentsAndWhitespace(line);
        free(line);
        if (!nonCommentLine) {
            continue;
        }

        // Parse the line into a structure
        NFAPI_CRC_INDICATION_PDU_T* structure = parseStructure(nonCommentLine);
        free(nonCommentLine);
        if (!structure) {
            continue;
        }

        // Add the structure to the array of structures
        structures[numItems++] = *structure;

        // Check if the buffer is full
        if (numItems == numStructures) {
            isBufferFull = true;
        }
    }

    // Clean up resources
    sem_close(semaphore);
    pthread_join(threadId, NULL);
    free(structures);

    return numItems;
}

// Define the function that reads a file asynchronously and signals the semaphore when done
void* readFileAsync(void* filename) {
    // Open the file for reading
    int fd = open((const char*)filename, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return NULL;
    }

    // Read the file line by line and signal the semaphore when done
    while (!feof(fd)) {
        char* line = readNextLine(filename);
        if (!line) {
            break;
        }
        free(line);
    }

    // Close the file
    close(fd);

    // Signal the semaphore to indicate that the file has been read
    sem_post(semaphore);

    return NULL;
}

// Define the function that reads the next line from a file
char* readNextLine(const char* filename) {
    // Open the file for reading
    int fd = open((const char*)filename, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return NULL;
    }

    // Read the next line from the file
    char* line = malloc(MAX_BUFFER_SIZE * sizeof(char));
    if (!line) {
        perror("Failed to allocate memory for line buffer");
        close(fd);
        return NULL;
    }
    int bytesRead = read(fd, line, MAX_BUFFER_SIZE - 1);
    if (bytesRead == -1) {
        perror("Failed to read from file");
        free(line);
        close(fd);
        return NULL;
    }
    line[bytesRead] = '\0';

    // Close the file
    close(fd);

    return line;
}

// Define the function that ignores comments and whitespace in a line
char* ignoreCommentsAndWhitespace(const char* line) {
    // Ignore any leading whitespace
    while (isspace(*line)) {
        line++;
    }

    // Check if the line is empty or starts with a comment symbol
    if (*line == '\0' || *line == '#') {
        return NULL;
    }

    // Ignore any trailing whitespace
    int length = strlen(line);
    while (isspace(line[length - 1])) {
        line[length - 1] = '\0';
        length--;
    }

    return line;
}

// Define the function that parses a structure from a line
NFAPI_CRC_INDICATION_PDU_T* parseStructure(const char* line) {
    // Initialize variables
    NFAPI_CRC_INDICATION_PDU_T* structure = NULL;
    int numItems = 0;

    // Parse the line into a structure
    char* token = strtok((char*)line, " ");
    while (token) {
        switch (numItems++) {
            case 0:
                structure->RX_UE_INFORMATION_TAG = atoi(token);
                break;
            case 1:
                structure->RNTI = atoi(token);
                break;
            case 2:
                structure->CRCFLAG = atoi(token);
                break;
            case 3:
                structure->CRC_INDICATION_REL8_TAG = atoi(token);
                break;
        }
        token = strtok(NULL, " ");
    }

    return structure;
}

// Define the function that checks if cancellation was requested
bool checkCancellation() {
    // Check if the cancel flag is set
    if (cancelFlag) {
        return true;
    }

    // Check if the semaphore has been signaled
    if (sem_trywait(semaphore)) {
        perror("Failed to check for cancellation");
        return false;
    }

    return false;
