        event_log[i] = (NETWORK_EVENT_T*)malloc(sizeof(NETWORK_EVENT_T));
        if (!event_log[i]) {
            // Handle memory allocation failure gracefully
            return NULL;
        }

        // Initialize random seed for successFlag
