        event_log[i]->successFlag = (rand() % 2 == 0);

        // Randomly set other fields in NETWORK_EVENT_T
        // Assume these functions are available: initializeEVENT_TYPE_TAG(), setTime_STAMP_TAG(), initializeNETWORK_ENTITY_TAG(), initializeSTATUS_CODE_TAG()
        initializeEVENT_TYPE_TAG(&event_log[i]->eventType);
