    // Introduce a new requirement: the network events must be logged only if the network is healthy
    if (isNetworkHealthy()) {
        // Validate network health before processing events
        if (validateNetworkHealth()) {
            // Return the pointer to the first element of the populated log
            return event_log[0];
        }
    }

    // Free memory before returning if network health validation fails
    free(event_log);
    return NULL;
}

