void populate_device_config_list(int N, int seed, double priority_threshold) {
    // Initialize the list of network device configurations
    device_config_list_t* config_list = (device_config_list_t*)malloc(sizeof(device_config_list_t));
    config_list->num_configs = 0;
    config_list->configs = NULL;

    // Generate random numbers for the device IDs, MAC addresses, and IP addresses
    srand(seed);
    int* device_ids = (int*)malloc(N * sizeof(int));
    char** mac_addrs = (char**)malloc(N * sizeof(char*));
    char** ip_addrs = (char**)malloc(N * sizeof(char*));
    for (int i = 0; i < N; i++) {
        device_ids[i] = rand() % 1000000;
        mac_addrs[i] = generate_mac_addr();
        ip_addrs[i] = generate_ip_addr();
    }

    // Populate the list of network device configurations with random data
    for (int i = 0; i < N; i++) {
        device_config_t* config = (device_config_t*)malloc(sizeof(device_config_t));
        config->id = malloc(16);
        sprintf(config->id, "%d", device_ids[i]);
        config->mac_addr = mac_addrs[i];
        config->ip_addr = ip_addrs[i];
        config->version = rand() % 10;
        config->operational_status = rand() % 2;
        config->last_updated = time(NULL);
        // Add additional attributes, including various data types such as strings, integers, and floating-point numbers
        config_list->num_configs++;
        config_list->configs = realloc(config_list->configs, config_list->num_configs * sizeof(device_config_t));
        memcpy(&config_list->configs[i], config, sizeof(device_config_t));
    }

    // Free memory for the random numbers and MAC addresses
    free(device_ids);
    free(mac_addrs);
    free(ip_addrs);
}

