// Define the function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(size_t num_elements) {
    // Check if the input is valid
    if (num_elements == 0) {
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);
    if (pdu == NULL) {
        // Log an error message if memory allocation fails
        printf("Error: Failed to allocate memory for CRC indication PDU\n");
        return NULL;
    }

    // Initialize each structure in the array with a unique RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (size_t i = 0; i < num_elements; i++) {
        pdu[i].RX_UE_INFORMATION_TAG = i + 1;
        pdu[i].RNTI = rand() % 65536;
        pdu[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    // Validate that all structures have been properly initialized
    for (size_t i = 0; i < num_elements; i++) {
        if (pdu[i].RX_UE_INFORMATION_TAG == 0 || pdu[i].RNTI == 0 || pdu[i].CRC_INDICATION_REL8_TAG == 0) {
            // Log an error message if any structure is not properly initialized
            printf("Error: Failed to initialize CRC indication PDU\n");
            free(pdu);
            return NULL;
        }
    }

    // Return the allocated array of structures
    return pdu;
}
