    NetworkElementConfig* configs = (NetworkElementConfig*)malloc(N * sizeof(NetworkElementConfig));

    // Populate the array of network element configurations
    for (int i = 0; i < N; i++) {
        // Generate a random ID, IP address, port number, and connection status
        int id = rand() % 10000;
        char* ip_address = "192.168.1." + (rand() % 256);
        int port = rand() % 65536;
        bool connected = (rand() % 2) == 0;

        // Initialize the network element configuration
        configs[i].id = id;
        configs[i].ip_address = ip_address;
        configs[i].port = port;
        configs[i].connected = connected;
    }

    // Allocate memory for the array of records
    Record* records = (Record*)malloc(N * sizeof(Record));

    // Populate the array of records with random values within a specified range
    for (int i = 0; i < N; i++) {
        int value = rand() % 10000;
        records[i].value = value;
    }

    // Allocate memory for the arrays of long and int keys
    long* long_keys = (long*)malloc(N * sizeof(long));
    int* int_keys = (int*)malloc(N * sizeof(int));

    // Populate the arrays of long and int keys with random values within a specified range
    for (int i = 0; i < N; i++) {
        long long_key = rand() % 10000;
        int int_key = rand() % 10000;
        long_keys[i] = long_key;
        int_keys[i] = int_key;
    }

    // Find and print the largest integer along with its corresponding string from the populated records
    int max_value = -1;
    char* max_string = NULL;
    for (int i = 0; i < N; i++) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
            max_string = configs[i].ip_address;
        }
    }
    printf("The largest integer is %d with corresponding string: %s\n", max_value, max_string);

    // Free the memory for the arrays of network element configurations and records
    free(configs);
    free(records);

    // Free the memory for the arrays of long and int keys
    free(long_keys);
    free(int_keys);
}

