        sessions[i]->id = i + 1;
        sessions[i]->username = "user" + std::to_string(i);
        sessions[i]->email = "user" + std::to_string(i) + "@example.com";
        sessions[i]->last_activity = time(NULL);
        sessions[i]->role = "admin";
    }

    // Allocate memory for the timestamp array
    time_t* timeouts = (time_t*)malloc(n * sizeof(time_t));

    // Initialize the timestamp array with random values
    srand(seed);
    for (int i = 0; i < n; i++) {
        timeouts[i] = time(NULL) + rand() % 3600;
    }

    // Allocate memory for the user role array
    char** roles = (char**)malloc(n * sizeof(char*));

    // Initialize the user role array with random values
    srand(seed);
    for (int i = 0; i < n; i++) {
        roles[i] = "admin";
    }

    // Print the oldest session along with its user role and credentials
    printf("Oldest session: %d\n", sessions[0]->id);
    printf("User role: %s\n", sessions[0]->role);
    printf("Credentials: %s, %s\n", sessions[0]->username, sessions[0]->email);

    // Free the memory allocated for the session array and timestamp array
    free(sessions);
    free(timeouts);
}

int main() {
    int n = 10; // Number of sessions
    int seed = 42; // Seed value for random number generation

    populate_sessions(n, seed);

    dynamic_switching(n, seed);

    return 0;
}
