// Define a struct to represent a traffic flow with attributes such as ID, timestamp, activity level, and status
typedef struct TrafficMonitorConfig {
    int flow_id;
    time_t timestamp;
    int activity_level;
    bool is_active;
} TrafficMonitorConfig;

// Define a linked list to store the traffic flows
struct TrafficFlowList {
    TrafficMonitorConfig *head;
    TrafficMonitorConfig *tail;
};

// Function to initialize the traffic monitoring system
void initializeTrafficMonitoring(struct TrafficFlowList *flow_list) {
    // Initialize the linked list of flows
    flow_list->head = NULL;
    flow_list->tail = NULL;
}

// Function to add a new flow to the traffic monitoring system
void addTrafficFlow(struct TrafficFlowList *flow_list, int flow_id) {
    // Create a new node for the flow
    TrafficMonitorConfig *new_node = (TrafficMonitorConfig *)malloc(sizeof(TrafficMonitorConfig));
    new_node->flow_id = flow_id;
    new_node->timestamp = time(NULL);
    new_node->activity_level = 0;
    new_node->is_active = true;

    // Add the node to the linked list
    if (flow_list->head == NULL) {
        flow_list->head = new_node;
        flow_list->tail = new_node;
    } else {
        flow_list->tail->next = new_node;
        flow_list->tail = new_node;
    }
}

// Function to update an existing flow in the traffic monitoring system
void updateTrafficFlow(struct TrafficFlowList *flow_list, int flow_id) {
    // Find the node for the specified flow ID
    TrafficMonitorConfig *current = flow_list->head;
    while (current != NULL && current->flow_id != flow_id) {
        current = current->next;
    }

    // If the flow was found, update its activity level and timestamp
    if (current != NULL) {
        current->activity_level++;
        current->timestamp = time(NULL);
    }
}

// Function to remove an inactive flow from the traffic monitoring system
void removeInactiveFlow(struct TrafficFlowList *flow_list, int flow_id) {
    // Find the node for the specified flow ID
    TrafficMonitorConfig *current = flow_list->head;
    while (current != NULL && current->flow_id != flow_id) {
        current = current->next;
    }

    // If the flow was found, remove it from the linked list
    if (current != NULL) {
        TrafficMonitorConfig *previous = current->prev;
        TrafficMonitorConfig *next = current->next;
        previous->next = next;
        next->prev = previous;
        free(current);
    }
}

// Function to periodically check and update the activity level of each flow based on real-time network conditions
void updateFlowActivityLevels(struct TrafficFlowList *flow_list) {
    // Iterate through the linked list of flows and update their activity levels
    TrafficMonitorConfig *current = flow_list->head;
    while (current != NULL) {
        current->activity_level++;
        current = current->next;
    }
}

// Function to periodically prune the list of flows that have been inactive for a specified duration
void pruneInactiveFlows(struct TrafficFlowList *flow_list, int inactive_duration) {
    // Iterate through the linked list of flows and remove any that have been inactive for the specified duration
    TrafficMonitorConfig *current = flow_list->head;
    while (current != NULL) {
        if (current->is_active == false && current->timestamp < time(NULL) - inactive_duration) {
            removeInactiveFlow(flow_list, current->flow_id);
        } else {
            current = current->next;
        }
    }
}
