struct image_info {
    int bits_per_sample;
    int samples_per_pixel;
    int compression_method;
    int resolution[2];
    int color_space;
};

void process_tiff(const char* filepath) {
    // Initialize TIFF parser and logging system
    TIFF *tif = TIFFOpen(filepath, "r");
    if (tif == NULL) {
        LOG_ERROR("Failed to open TIFF file: %s", filepath);
        return;
    }

    // Initialize memory pool and caching strategies
    struct image_info info;
    memset(&info, 0, sizeof(struct image_info));
    int num_samples = 0;
    int sample_size = 0;
    int compression_method = 0;
    int color_space = 0;
    int resolution[2] = {0};

    // Parse TIFF header and extract image information
    while (TIFFReadDirectory(tif)) {
        TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &info.bits_per_sample);
        TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &info.samples_per_pixel);
        TIFFGetField(tif, TIFFTAG_COMPRESSION, &compression_method);
        TIFFGetField(tif, TIFFTAG_RESOLUTIONUNIT, &resolution[0]);
        TIFFGetField(tif, TIFFTAG_XRESOLUTION, &resolution[1]);
        TIFFGetField(tif, TIFFTAG_COLORSPACE, &color_space);

        // Handle unsupported compression methods and color spaces
        if (compression_method != COMPRESSION_NONE && compression_method != COMPRESSION_LZW) {
            LOG_WARNING("Unsupported compression method: %d", compression_method);
            continue;
        }
        if (color_space != PHOTOMETRIC_RGB && color_space != PHOTOMETRIC_YCBCR) {
            LOG_WARNING("Unsupported color space: %d", color_space);
            continue;
        }

        // Validate image dimensions and number of samples
        int width = 0, height = 0;
        TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width);
        TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &height);
        num_samples = info.samples_per_pixel * width * height;
        sample_size = info.bits_per_sample / 8;
        if (num_samples > MAX_SAMPLES || sample_size > MAX_SAMPLE_SIZE) {
            LOG_WARNING("Image dimensions or number of samples exceeds limits");
            continue;
        }

        // Parse image data and extract primary and extra samples
        uint8_t* buffer = malloc(num_samples * sample_size);
        if (buffer == NULL) {
            LOG_ERROR("Failed to allocate memory for image data");
            break;
        }
        TIFFReadRGBAImage(tif, width, height, buffer, 0);
        int primary_samples = info.samples_per_pixel * width * height;
        int extra_samples = num_samples - primary_samples;
        if (extra_samples > 0) {
            // Handle extra samples by copying them to a separate buffer
            uint8_t* extra_buffer = malloc(extra_samples * sample_size);
            if (extra_buffer == NULL) {
                LOG_ERROR("Failed to allocate memory for extra image data");
                break;
            }
            memcpy(extra_buffer, buffer + primary_samples * sample_size, extra_samples * sample_size);
        }

        // Validate metadata and log warnings if necessary
        int expected_metadata = 2 * width * height * info.bits_per_sample / 8;
        if (TIFFGetSize(tif) != expected_metadata) {
            LOG_WARNING("Image metadata inconsistent with image dimensions");
        }

        // Integrate processed image information into data pipeline
        struct image_info* new_info = malloc(sizeof(struct image_info));
        if (new_info == NULL) {
            LOG_ERROR("Failed to allocate memory for image info");
            break;
        }
        memcpy(new_info, &info, sizeof(struct image_info));
        new_info->extra_samples = extra_samples;
        data_pipeline_push(new_info);
    }

    // Clean up resources and return
    TIFFClose(tif);
    free(buffer);
    if (extra_buffer != NULL) {
        free(extra_buffer);
    }
}
