// structure to hold information about each TCP connection
typedef struct {
    int id; // unique ID for the connection
    char* ip; // IP address of the remote server
    int port; // port number of the remote server
    vector<packet> transmitted_packets; // vector of transmitted packets
} TCPConnection;

// function to process a TIFF image file and initialize and configure a dynamic array of TCPConnection contexts
void process_tiff_image(char* filename) {
    // open the TIFF image file
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error: unable to open TIFF image file %s\n", filename);
        return;
    }

    // read the header of the TIFF image file
    char* header = malloc(12);
    fread(header, 1, 12, fp);

    // extract detailed information about the image's structure
    int bits_per_sample = *((int*)header + 0);
    int samples_per_pixel = *((int*)header + 1);
    int compression_method = *((int*)header + 2);
    int resolution = *((int*)header + 3);
    int color_space = *((int*)header + 4);

    // validate the consistency of metadata and log warnings if there are discrepancies between the image dimensions and the number of samples
    if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 && bits_per_sample != 8 && bits_per_sample != 16) {
        printf("Warning: unsupported bits per sample value %d\n", bits_per_sample);
    }
    if (samples_per_pixel != 1 && samples_per_pixel != 2 && samples_per_pixel != 4 && samples_per_pixel != 8) {
        printf("Warning: unsupported samples per pixel value %d\n", samples_per_pixel);
    }
    if (compression_method != 1 && compression_method != 2 && compression_method != 3) {
        printf("Warning: unsupported compression method value %d\n", compression_method);
    }
    if (resolution < 0 || resolution > 10000) {
        printf("Warning: invalid resolution value %d\n", resolution);
    }
    if (color_space != 1 && color_space != 2 && color_space != 3) {
        printf("Warning: unsupported color space value %d\n", color_space);
    }

    // initialize and configure a dynamic array of TCPConnection contexts
    TCPConnection* connections = malloc(sizeof(TCPConnection) * MAX_CONNECTIONS);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connections[i].id = i + 1;
        connections[i].ip = NULL;
        connections[i].port = -1;
        connections[i].transmitted_packets = vector<packet>();
    }

    // process images efficiently to handle up to 10,000 images per minute, with each image potentially being several gigabytes in size
    while (true) {
