        char* buffer = malloc(BUFFER_SIZE);
        int bytes_read = fread(buffer, 1, BUFFER_SIZE, fp);
        if (bytes_read == 0) {
            break;
        }

        // process the packet and add it to the appropriate TCPConnection context
        for (int i = 0; i < MAX_CONNECTIONS; i++) {
            if (connections[i].ip != NULL && connections[i].port > 0) {
                int bytes_sent = send(connections[i].id, buffer, bytes_read, 0);
                if (bytes_sent == -1) {
                    printf("Error: unable to send packet to connection %d\n", connections[i].id);
                } else {
                    // add the sent packet to the vector of transmitted packets for this TCPConnection context
                    packet p;
                    p.sequence_number = connections[i].transmitted_packets.size() + 1;
                    p.timestamp = time(NULL);
                    p.data = malloc(bytes_sent);
                    memcpy(p.data, buffer, bytes_sent);
                    connections[i].transmitted_packets.push_back(p);
