    // Log warnings for any discrepancies between the image dimensions and the number of samples
    logWarnings(loggingSystem, imageInfo);

    // Free the memory allocated for the image information
    freeImageInfo(imageInfo);

    // Close the TIFF image file
    closeTiffImage(tiffImage);

    // Destroy the memory pool and logging system
    destroyMemoryPool(memoryPool);
    destroyLoggingSystem(loggingSystem);
}

// Define the function to extract detailed information about an image's structure
ImageInfo* extractImageInfo(TiffImage* tiffImage, MemoryPool* memoryPool) {
    // Initialize the image information structure
    ImageInfo* imageInfo = allocateMemory(sizeof(ImageInfo), memoryPool);

    // Check if the image information structure was allocated successfully
    if (imageInfo == NULL) {
        return NULL;
    }

    // Extract the bits per sample from the TIFF image file
