        return NULL;
    }

    // Extract the samples per pixel from the TIFF image file
    int samplesPerPixel = getSamplesPerPixel(tiffImage);

    // Check if the samples per pixel was extracted successfully
    if (samplesPerPixel == -1) {
        return NULL;
    }

    // Extract the compression method from the TIFF image file
    int compressionMethod = getCompressionMethod(tiffImage);

    // Check if the compression method was extracted successfully
    if (compressionMethod == -1) {
        return NULL;
    }

    // Extract the color space from the TIFF image file
    int colorSpace = getColorSpace(tiffImage);

    // Check if the color space was extracted successfully
    if (colorSpace == -1) {
        return NULL;
    }

    // Extract the resolution from the TIFF image file
    int resolution = getResolution(tiffImage);

    // Check if the resolution was extracted successfully
    if (resolution == -1) {
        return NULL;
    }

    // Set the bits per sample, samples per pixel, compression method, color space, and resolution in the image information structure
    imageInfo->bitsPerSample = bitsPerSample;
    imageInfo->samplesPerPixel = samplesPerPixel;
    imageInfo->compressionMethod = compressionMethod;
    imageInfo->colorSpace = colorSpace;
    imageInfo->resolution = resolution;

    // Return the image information structure
    return imageInfo;
}

// Define the function to validate the consistency of metadata
void validateMetadata(ImageInfo* imageInfo, LoggingSystem* loggingSystem) {
    // Check if the image dimensions and number of samples are consistent
    if (imageInfo->bitsPerSample > MAX_BITS_PER_SAMPLE || imageInfo->samplesPerPixel > MAX_SAMPLES_PER_PIXEL) {
        logError(loggingSystem, "Invalid metadata: bits per sample or samples per pixel exceeds maximum value");
    }
}

// Define the function to log warnings for any discrepancies between the image dimensions and the number of samples
void logWarnings(LoggingSystem* loggingSystem, ImageInfo* imageInfo) {
    // Check if there are any discrepancies between the image dimensions and the number of samples
    if (imageInfo->bitsPerSample != 1 && imageInfo->samplesPerPixel != 1) {
        logWarning(loggingSystem, "Discrepancy between image dimensions and number of samples: %d bits per sample, %d samples per pixel", imageInfo->bitsPerSample, imageInfo->samplesPerPixel);
    }
}

// Define the function to free the memory allocated for the image information structure
void freeImageInfo(ImageInfo* imageInfo) {
    // Free the memory allocated for the image information structure
    freeMemory(imageInfo);
}
