    time_t timestamp;
    int level;
    char source_id[16];
    char message[1024];
} NFPAPI_LOG_RECORD;

// Structure to represent the list of log records
typedef struct NFP_LOG_LIST {
    size_t count;
    NFPAPI_LOG_RECORD* records;
} NFP_LOG_LIST;

// Function to add a new log record to the list
void nfp_log_add(NFP_LOG_LIST* list, time_t timestamp, int level, const char* source_id, const char* message) {
    // Validate the input parameters
    assert(list != NULL);
    assert(timestamp > 0);
    assert(level >= 0 && level <= 3);
    assert(source_id != NULL);
    assert(message != NULL);

    // Allocate memory for the new log record
    NFPAPI_LOG_RECORD* new_record = (NFPAPI_LOG_RECORD*) my_malloc(sizeof(NFPAPI_LOG_RECORD));
    if (new_record == NULL) {
        // Handle out-of-memory condition gracefully by reducing the number of elements until successful allocation is possible
        return;
    }

    // Initialize the new log record
    new_record->timestamp = timestamp;
    new_record->level = level;
    strncpy(new_record->source_id, source_id, 16);
    strncpy(new_record->message, message, 1024);

    // Add the new log record to the list
    list->records[list->count++] = new_record;
}

// Function to retrieve a log record by timestamp
NFPAPI_LOG_RECORD* nfp_log_get(NFP_LOG_LIST* list, time_t timestamp) {
    // Validate the input parameters
    assert(list != NULL);
    assert(timestamp > 0);

    // Search for the log record with the specified timestamp
    for (size_t i = 0; i < list->count; i++) {
        if (list->records[i]->timestamp == timestamp) {
            return list->records[i];
        }
    }

    // Return NULL if no log record with the specified timestamp is found
    return NULL;
}

// Function to remove log records older than a specified retention period
void nfp_log_remove(NFP_LOG_LIST* list, time_t retention_period) {
    // Validate the input parameters
    assert(list != NULL);
    assert(retention_period > 0);

    // Remove log records that are older than the specified retention period
    for (size_t i = 0; i < list->count; i++) {
        if (list->records[i]->timestamp <= retention_period) {
            my_free(list->records[i]);
            list->count--;
            memmove(&list->records[i], &list->records[i + 1], sizeof(NFPAPI_LOG_RECORD*) * (list->count - i));
        }
    }
}

// Function to parse a TIFF image file for specific information
int nfp_tiff_parse(const char* filename, int* bits_per_sample, int* sample_per_pixel, int* extra_samples) {
    // Open the TIFF image file
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        return -1;
    }

    // Read the TIFF header and validate it
    char tiff_header[4];
    size_t bytes_read = fread(tiff_header, 1, sizeof(tiff_header), fp);
    if (bytes_read != sizeof(tiff_header) || memcmp(tiff_header, "MM\x00\x2a", 4)) {
        fclose(fp);
        return -1;
    }

    // Read the TIFF directory and validate it
    char tiff_directory[8];
    bytes_read = fread(tiff_directory, 1, sizeof(tiff_directory), fp);
    if (bytes_read != sizeof(tiff_directory) || memcmp(tiff_directory, "II\x2a\x00", 4)) {
        fclose(fp);
        return -1;
    }

    // Read the TIFF image width and height
    int width = 0;
    int height = 0;
    bytes_read = fread(&width, sizeof(int), 1, fp);
    if (bytes_read != sizeof(int)) {
        fclose(fp);
        return -1;
    }
    bytes_read = fread(&height, sizeof(int), 1, fp);
    if (bytes_read != sizeof(int)) {
        fclose(fp);
        return -1;
    }

    // Read the TIFF bits per sample and sample per pixel values
    bytes_read = fread(bits_per_sample, sizeof(int), 1, fp);
    if (bytes_read != sizeof(int)) {
        fclose(fp);
        return -1;
    }
    bytes_read = fread(sample_per_pixel, sizeof(int), 1, fp);
    if (bytes_read != sizeof(int)) {
        fclose(fp);
        return -1;
    }

    // Read the TIFF extra samples information
    bytes_read = fread(extra_samples, sizeof(int), 1, fp);
    if (bytes_read != sizeof(int)) {
        fclose(fp);
        return -1;
    }

    // Close the TIFF image file
    fclose(fp);

    // Return the number of extra samples and their details
    return *extra_samples;
}
