#include <semaphore.h>

// Define the SESSION_INFO structure to store session information
typedef struct {
    int id;
    char* user;
    time_t expiration;
    char* resources[10]; // Maximum number of recently accessed resources is 10
} SESSION_INFO;

// Define the SESSION_COLLECTION structure to store a collection of sessions
typedef struct {
    int size;
    SESSION_INFO** sessions;
} SESSION_COLLECTION;

// Initialize the session collection with the given number of sessions and seed value for random number generation
void init_session_collection(SESSION_COLLECTION* collection, int n, unsigned int seed) {
    // Allocate memory for the session collection
    collection->sessions = (SESSION_INFO**)malloc(n * sizeof(SESSION_INFO*));
    if (!collection->sessions) {
        fprintf(stderr, "Failed to allocate memory for session collection\n");
        return;
    }

    // Initialize the session information for each session
    for (int i = 0; i < n; i++) {
        SESSION_INFO* session = (SESSION_INFO*)malloc(sizeof(SESSION_INFO));
        if (!session) {
            fprintf(stderr, "Failed to allocate memory for session %d\n", i);
            return;
        }

        // Generate a unique session identifier using the seed value and the current time
        session->id = (seed * 1000 + time(NULL)) % INT_MAX;

        // Initialize the user authentication state to "not authenticated"
        session->user = NULL;

        // Set the expiration time for the session to a random value between 30 and 60 seconds in the future
        session->expiration = time(NULL) + (rand_r(&seed) % 30) + 30;

        // Initialize the list of recently accessed resources to empty
        memset(session->resources, 0, sizeof(char*) * 10);

        collection->sessions[i] = session;
    }

    collection->size = n;
}

// Add a new session to the collection and return its index
int add_session(SESSION_COLLECTION* collection) {
    // Allocate memory for the new session
    SESSION_INFO* session = (SESSION_INFO*)malloc(sizeof(SESSION_INFO));
    if (!session) {
        fprintf(stderr, "Failed to allocate memory for new session\n");
        return -1;
    }

    // Generate a unique session identifier using the current time and a random value
    session->id = (time(NULL) * 1000 + rand_r(&seed) % INT_MAX);

    // Initialize the user authentication state to "not authenticated"
    session->user = NULL;

    // Set the expiration time for the session to a random value between 30 and 60 seconds in the future
    session->expiration = time(NULL) + (rand_r(&seed) % 30) + 30;

    // Initialize the list of recently accessed resources to empty
    memset(session->resources, 0, sizeof(char*) * 10);

    // Add the new session to the collection
    collection->sessions[collection->size++] = session;

    return collection->size - 1;
}

// Remove a session from the collection and free its memory
void remove_session(SESSION_COLLECTION* collection, int index) {
    // Check if the index is valid
    if (index < 0 || index >= collection->size) {
        fprintf(stderr, "Invalid session index\n");
        return;
    }

    // Free the memory for the session
    free(collection->sessions[index]);

    // Shift all subsequent sessions to fill the gap
    for (int i = index + 1; i < collection->size; i++) {
        collection->sessions[i - 1] = collection->sessions[i];
    }

    // Decrement the size of the collection
    collection->size--;
}

// Update the expiration time for a session in the collection
void update_session(SESSION_COLLECTION* collection, int index, time_t new_expiration) {
    // Check if the index is valid
    if (index < 0 || index >= collection->size) {
        fprintf(stderr, "Invalid session index\n");
        return;
    }

    // Update the expiration time for the session
    collection->sessions[index]->expiration = new_expiration;
}

// Check if a session has expired and remove it from the collection if necessary
void check_session(SESSION_COLLECTION* collection, int index) {
    // Check if the index is valid
    if (index < 0 || index >= collection->size) {
        fprintf(stderr, "Invalid session index\n");
        return;
    }

    // Get the current time and compare it to the expiration time for the session
    time_t now = time(NULL);
    if (collection->sessions[index]->expiration <= now) {
        // Remove the session from the collection
        remove_session(collection, index);
    }
}

// Add a resource to the list of recently accessed resources for a session in the collection
void add_resource(SESSION_COLLECTION* collection, int index, char* resource) {
    // Check if the index is valid
    if (index < 0 || index >= collection->size) {
        fprintf(stderr, "Invalid session index\n");
        return;
    }

    // Add the resource to the list of recently accessed resources for the session
    strcpy(collection->sessions[index]->resources[collection->sessions[index]->num_resources++], resource);
}

// Remove a resource from the list of recently accessed resources for a session in the collection
void remove_resource(SESSION_COLLECTION* collection, int index, char* resource) {
    // Check if the index is valid
    if (index < 0 || index >= collection->size) {
        fprintf(stderr, "Invalid session index\n");
        return;
    }

    // Remove the resource from the list of recently accessed resources for the session
    int i = 0;
    while (i < collection->sessions[index]->num_resources) {
        if (!strcmp(collection->sessions[index]->resources[i], resource)) {
            break;
        }
        i++;
    }
    if (i == collection->sessions[index]->num_resources) {
        fprintf(stderr, "Resource not found in session\n");
        return;
    }
    for (int j = i; j < collection->sessions[index]->num_resources - 1; j++) {
        strcpy(collection->sessions[index]->resources[j], collection->sessions[index]->resources[j + 1]);
    }
    collection->sessions[index]->num_resources--;
}

// Print the session information for a given index in the collection
void print_session(SESSION_COLLECTION* collection, int index) {
    // Check if the index is valid
    if (index < 0 || index >= collection->size) {
        fprintf(stderr, "Invalid session index\n");
        return;
    }

    // Print the session information for the given index
    printf("Session %d:\n", index);
    printf("\tID: %d\n", collection->sessions[index]->id);
    if (collection->sessions[index]->user) {
        printf("\tUser: %s\n", collection->sessions[index]->user);
    } else {
        printf("\tUser: Not authenticated\n");
    }
    printf("\tExpiration time: %ld\n", collection->sessions[index]->expiration);
    for (int i = 0; i < collection->sessions[index]->num_resources; i++) {
        printf("\tRecently accessed resource %d: %s\n", i + 1, collection->sessions[index]->resources[i]);
    }
}

// Print the session information for all sessions in the collection
void print_all_sessions(SESSION_COLLECTION* collection) {
    // Iterate over each session in the collection and print its information
    for (int i = 0; i < collection->size; i++) {
        printf("Session %d:\n", i);
        printf("\tID: %d\n", collection->sessions[i]->id);
        if (collection->sessions[i]->user) {
            printf("\tUser: %s\n", collection->sessions[i]->user);
        } else {
            printf("\tUser: Not authenticated\n");
        }
        printf("\tExpiration time: %ld\n", collection->sessions[i]->expiration);
        for (int j = 0; j < collection->sessions[i]->num_resources; j++) {
            printf("\tRecently accessed resource %d: %s\n", j + 1, collection->sessions[i]->resources[j]);
        }
    }
}
