        if (settings->sockets[i]->socket == socket) {
            // Close the socket and free the memory associated with it
            close(settings->sockets[i]->socket);
            free(settings->sockets[i]);

            // Shift all subsequent socket handles to fill the gap
            for (int j = i; j < settings->num_settings - 1; j++) {
                settings->sockets[j] = settings->sockets[j + 1];
            }

            // Decrement the number of settings in the collection
