// Define the function for initializing the packet collection
void initPacketCollection(int N, long seed_value, int packet_size, char* payload_content_type, long timestamp_granularity) {
    // Allocate memory for the packet collection
    struct PacketCollection* collection = malloc(sizeof(struct PacketCollection));
    if (collection == NULL) {
        printf("Error: Failed to allocate memory for packet collection\n");
        return;
    }

    // Initialize the size and capacity of the packet collection
    collection->size = 0;
    collection->capacity = N;

    // Allocate memory for the packets in the collection
    collection->packets = malloc(sizeof(Packet*) * N);
    if (collection->packets == NULL) {
        printf("Error: Failed to allocate memory for packets\n");
        free(collection);
        return;
    }

    // Initialize the random number generator with the seed value
