    // Print a message indicating that the collection has been initialized
    printf("Packet collection initialized with %d packets\n", N);
}

// Define the function for adding a new packet to the collection
void addPacketToCollection(struct PacketCollection* collection, int sequence_number, long timestamp, int packet_length, char* payload_data) {
    // Check if the collection is full
    if (collection->size == collection->capacity) {
        // Dynamically resize the collection to accommodate more packets
        collection->capacity *= 2;
        collection->packets = realloc(collection->packets, sizeof(Packet*) * collection->capacity);
        if (collection->packets == NULL) {
            printf("Error: Failed to resize packet collection\n");
            return;
        }
    }

    // Allocate memory for the new packet
    Packet* packet = malloc(sizeof(Packet));
    if (packet == NULL) {
        printf("Error: Failed to allocate memory for packet\n");
        return;
    }

    // Initialize the fields of the new packet
    packet->sequence_number = sequence_number;
    packet->timestamp = timestamp;
    packet->packet_length = packet_length;
    packet->payload_data = malloc(sizeof(char) * packet_length);
    if (packet->payload_data == NULL) {
        printf("Error: Failed to allocate memory for payload data\n");
        free(packet);
        return;
    }

    // Copy the payload data into the new packet
    memcpy(packet->payload_data, payload_data, packet_length);

    // Add the new packet to the collection
    collection->packets[collection->size] = packet;
    collection->size++;
}

// Define the function for removing a packet from the collection
void removePacketFromCollection(struct PacketCollection* collection, int sequence_number) {
    // Find the index of the packet to be removed
    int index = -1;
    for (int i = 0; i < collection->size; i++) {
        if (collection->packets[i]->sequence_number == sequence_number) {
            index = i;
            break;
        }
    }

    // Check if the packet was found
    if (index == -1) {
        printf("Error: Packet with sequence number %d not found in collection\n", sequence_number);
        return;
    }

    // Remove the packet from the collection
    free(collection->packets[index]->payload_data);
    free(collection->packets[index]);
    for (int i = index; i < collection->size - 1; i++) {
        collection->packets[i] = collection->packets[i + 1];
    }
    collection->size--;
}

// Define the function for converting a packet to JSON format
void convertPacketToJSON(struct PacketCollection* collection, int sequence_number) {
    // Find the index of the packet to be converted
    int index = -1;
    for (int i = 0; i < collection->size; i++) {
        if (collection->packets[i]->sequence_number == sequence_number) {
            index = i;
            break;
        }
    }

    // Check if the packet was found
    if (index == -1) {
        printf("Error: Packet with sequence number %d not found in collection\n", sequence_number);
        return;
    }

    // Convert the packet to JSON format
    json_object* json = json_object_new_object();
    json_object_object_add(json, "sequenceNumber", json_object_new_int(collection->packets[index]->sequence_number));
    json_object_object_add(json, "timestamp", json_object_new_int64(collection->packets[index]->timestamp));
    json_object_object_add(json, "packetLength", json_object_new_int(collection->packets[index]->packet_length));
    json_object_object_add(json, "payloadData", json_object_new_string(collection->packets[index]->payload_data));

    // Print the JSON object to stdout
    printf("%s\n", json_object_to_json_string_ext(json, JSON_C_TO_STRING_PRETTY));
}

// Define the function for creating a new instance of a subclass using a factory function
void* createNewInstanceOfSubclass(int ID) {
    // Check if the ID is valid
    if (ID < 0 || ID >= NUM_SUBCLASSES) {
        printf("Error: Invalid ID %d\n", ID);
        return NULL;
    }

    // Create a new instance of the subclass using the factory function associated with the ID
    void* instance = (*factoryFunctions[ID])();
    if (instance == NULL) {
        printf("Error: Failed to create new instance of subclass %d\n", ID);
        return NULL;
    }

    // Return the new instance
    return instance;
}

// Define the function for adding a new factory function to the registry
void addFactoryFunctionToRegistry(int ID, void* (*factoryFunction)()) {
    // Check if the ID is valid
    if (ID < 0 || ID >= NUM_SUBCLASSES) {
        printf("Error: Invalid ID %d\n", ID);
        return;
    }

    // Add the factory function to the registry
    factoryFunctions[ID] = factoryFunction;
}
