// Define the function to generate a list of CRC indications
void generate_crc_indications(int n, int seed) {
    // Allocate memory for the list of CRC indications
    NFAPI_CRC_INDICATION_PDU_T *crc_indications = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the timestamp for each CRC indication
    time_t current_timestamp = time(NULL);

    // Generate a random RX UE information tag, RNTI, and CRCFLAG for each CRC indication
    for (int i = 0; i < n; i++) {
        crc_indications[i].rx_ue_information_tag = rand() % 65536;
        crc_indications[i].rnti = rand() % 4294967296;
        crc_indications[i].crc_indication_rel8_tag = rand() % 256;
        crc_indications[i].crcflag = (rand() % 2) == 0;
        crc_indications[i].timestamp = current_timestamp + i * 1000; // Add 1 second for each CRC indication
