    MD5_CTX ctx;
    MD5Init(&ctx);
    MD5Update(&ctx, (unsigned char *)crc_indications, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    MD5Final(md5_hash, &ctx);

