// Define the structure for UE context information record
typedef struct {
    int ue_id;
    char serving_cell[10];
    bool mobility_status;
    time_t last_update_time;
} UE_CONTEXT_INFO_RECORD;

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for the dynamic collection of UE context information records
typedef struct {
    UE_CONTEXT_INFO_RECORD *records;
    int num_records;
} UE_CONTEXT_COLLECTION;

// Define the function to populate the UE context collection
void populate_ue_context_collection(int N, int seed, bool degraded) {
    // Initialize the UE context collection with the given number of records
    UE_CONTEXT_COLLECTION *collection = (UE_CONTEXT_COLLECTION *)malloc(sizeof(UE_CONTEXT_COLLECTION));
    collection->num_records = N;
    collection->records = (UE_CONTEXT_INFO_RECORD *)malloc(N * sizeof(UE_CONTEXT_INFO_RECORD));

    // Initialize the random number generator with the given seed value
    srand(seed);

    // Populate the UE context information records in the collection
    for (int i = 0; i < N; i++) {
        collection->records[i].ue_id = rand() % 1000000;
        strcpy(collection->records[i].serving_cell, "Cell-1");
        collection->records[i].mobility_status = (rand() % 2 == 0) ? true : false;
        collection->records[i].last_update_time = time(NULL);
    }

    // If the function is operating in degraded mode, log a warning message and return
    if (degraded) {
        printf("WARNING: Degraded mode enabled. Unable to read external configuration file.\n");
        return;
    }

    // Read the external configuration file and update the UE context information records accordingly
    FILE *config_file = fopen("config.txt", "r");
    if (config_file == NULL) {
        printf("ERROR: Unable to open external configuration file.\n");
        return;
    }

    // Read the number of records from the configuration file and update the collection accordingly
    int num_records = 0;
    fscanf(config_file, "%d", &num_records);
    if (num_records > N) {
        printf("WARNING: Number of records in external configuration file exceeds maximum allowed.\n");
        num_records = N;
    }
    collection->num_records = num_records;

    // Read the UE context information records from the configuration file and update the collection accordingly
    for (int i = 0; i < num_records; i++) {
        fscanf(config_file, "%d %s %d", &collection->records[i].ue_id, collection->records[i].serving_cell, &collection->records[i].mobility_status);
    }

    // Close the configuration file and return the populated UE context collection
    fclose(config_file);
    return collection;
}

