void add_long_element(long **array, int *size, long value) {
    // If the array is full, double its size and reallocate memory for it
    if (*size == 0 || *size % 2 == 0) {
        *array = (long *)realloc(*array, (*size + 1) * sizeof(long));
    }

    // Add the new element to the end of the array
    (*array)[*size] = value;
    (*size)++;
}

