    // If the index is out of bounds, return
    if (index < 0 || index >= *size) {
        return;
    }

    // Shift all elements after the specified index to the left by one position
    for (int i = index + 1; i < *size; i++) {
        (*array)[i - 1] = (*array)[i];
    }

    // Decrement the size of the array and reallocate memory for it if necessary
    (*size)--;
    if (*size > 0 && *size % 2 == 1) {
        *array = (long *)realloc(*array, (*size + 1) * sizeof(long));
    }
}

