// Define the function to calculate the MD5 hash of a large file
void md5_hash_file(char *path) {
    // Open the file for reading in binary mode
    FILE *file = fopen(path, "rb");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", path);
        return;
    }

    // Create a buffer for reading the file in chunks
    char buffer[1024];

    // Initialize the MD5 hash context
    MD5_CTX ctx;
    MD5_Init(&ctx);

    // Read the file in chunks and update the MD5 hash with each chunk
    while (fread(buffer, 1, sizeof(buffer), file) > 0) {
        MD5_Update(&ctx, buffer, sizeof(buffer));
    }

    // Close the file
    fclose(file);

    // Finalize the MD5 hash and print it to the console
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &ctx);
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", digest[i]);
    }
}
