// Define the configuration structure
typedef struct {
    char ip_address[16];
    char subnet_mask[16];
    char gateway[16];
    char dns_servers[3][16];
    int qos;
} network_config_t;

// Define the function to initialize the network configuration
int initialize_network_config(network_config_t *config, size_t num_configs, unsigned long seed) {
    // Check if the input parameters are valid
    if (config == NULL || num_configs <= 0) {
        return -1;
    }

    // Initialize the random number generator with the provided seed
    srand(seed);

    // Iterate over each configuration and initialize it
    for (size_t i = 0; i < num_configs; ++i) {
        network_config_t *current_config = &config[i];

        // Generate a random IP address, subnet mask, gateway, and DNS servers
        char ip_address[16], subnet_mask[16], gateway[16], dns_servers[3][16];
        for (int j = 0; j < 4; ++j) {
            snprintf(ip_address, sizeof(ip_address), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
            snprintf(subnet_mask, sizeof(subnet_mask), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
            snprintf(gateway, sizeof(gateway), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
            for (int k = 0; k < 3; ++k) {
                snprintf(dns_servers[k], sizeof(dns_servers[k]), "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
            }
        }

        // Set the IP address, subnet mask, gateway, and DNS servers for the current configuration
        strcpy(current_config->ip_address, ip_address);
        strcpy(current_config->subnet_mask, subnet_mask);
        strcpy(current_config->gateway, gateway);
        memcpy(current_config->dns_servers, dns_servers, sizeof(dns_servers));

        // Set the QoS settings for the current configuration
        current_config->qos = rand() % 10;
    }

    return 0;
}
