            ueContextCache->tail = NULL;
        }
    }

    // Populate the NFAPI_CRC_INDICATION_PDU_T structures with UE contexts
    for (int i = 0; i < numComponents; i++) {
        struct LTE_UE_CONTEXT *ueContext = ueContextList[rand() % numUEs].next;
