void initMemoryPool(struct MemoryPool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->buffer = malloc(pool->capacity * sizeof(char));
}

// Function to allocate memory from the memory pool
void* allocFromPool(struct MemoryPool* pool, size_t size) {
    if (size > pool->capacity) {
        return NULL;
    }
    void* ptr = pool->buffer + pool->capacity - size;
    pool->capacity -= size;
    return ptr;
}

// Function to release memory back to the memory pool
