// Function to initialize a new memory pool with a given capacity
struct MemoryPool* initMemoryPool(size_t capacity) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        return NULL;
    }
    pool->capacity = capacity;
    pool->used = 0;
    pool->buffer = malloc(capacity);
    if (!pool->buffer) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Function to allocate memory from the memory pool
void* allocMemory(struct MemoryPool* pool, size_t size) {
    if (size > pool->capacity - pool->used) {
        // Not enough space in the pool, try to expand it
        size_t newCapacity = pool->capacity * 2;
        char* newBuffer = realloc(pool->buffer, newCapacity);
        if (!newBuffer) {
            return NULL;
        }
        pool->buffer = newBuffer;
        pool->capacity = newCapacity;
    }
    void* memory = pool->buffer + pool->used;
    pool->used += size;
    return memory;
}

