        pthread_mutex_lock(&mutex);
        if (queue->size == 0) {
            pthread_cond_signal(&cond);
            break;
        }
        struct Record record = queue[0];
        queue->pop();
        pthread_mutex_unlock(&mutex);

        // Process the record
        process_record(record);
    }
}

