#include <pthread.h>

// Define the data structures for storing complex numbers and doubles
typedef struct {
    double real;
    double imag;
} ComplexNumber;

typedef struct {
    ComplexNumber *numbers;
    size_t count;
} ComplexNumberArray;

typedef struct {
    double *doubles;
    size_t count;
} DoubleArray;

// Define the function pointers for mathematical operations on complex numbers
typedef void (*ComplexOperation)(ComplexNumber *, ComplexNumber *);

void add(ComplexNumber *a, ComplexNumber *b) {
    a->real += b->real;
    a->imag += b->imag;
}

void subtract(ComplexNumber *a, ComplexNumber *b) {
    a->real -= b->real;
    a->imag -= b->imag;
}

void multiply(ComplexNumber *a, ComplexNumber *b) {
    double real = a->real * b->real - a->imag * b->imag;
    double imag = a->real * b->imag + a->imag * b->real;
    a->real = real;
    a->imag = imag;
}

void exponent(ComplexNumber *a, ComplexNumber *b) {
    double real = pow(a->real, b->real);
    double imag = pow(a->imag, b->imag);
    a->real = real;
    a->imag = imag;
}

void logarithm(ComplexNumber *a, ComplexNumber *b) {
    double real = log(a->real);
    double imag = log(a->imag);
    a->real = real;
    a->imag = imag;
}

void sine(ComplexNumber *a, ComplexNumber *b) {
    double real = sin(a->real);
    double imag = sin(a->imag);
    a->real = real;
    a->imag = imag;
}

// Define the function to perform arithmetic operations on complex numbers concurrently from multiple threads
void performOperation(ComplexNumber *a, ComplexNumber *b, ComplexOperation op) {
    pthread_mutex_lock(&mutex);
    op(a, b);
    pthread_mutex_unlock(&mutex);
}

// Define the function to serialize the current state of the complex numbers into a binary file
void serializeComplexNumbers(ComplexNumberArray *numbers) {
    FILE *file = fopen("complex_numbers.bin", "wb");
    if (file == NULL) {
        printf("Error: unable to open file for writing\n");
        return;
    }
    size_t count = numbers->count;
    fwrite(&count, sizeof(size_t), 1, file);
    ComplexNumber *numbers = numbers->numbers;
    for (size_t i = 0; i < count; i++) {
        ComplexNumber number = numbers[i];
        fwrite(&number.real, sizeof(double), 1, file);
        fwrite(&number.imag, sizeof(double), 1, file);
    }
    fclose(file);
}

// Define the function to deserialize the current state of the complex numbers from a binary file
void deserializeComplexNumbers(ComplexNumberArray *numbers) {
    FILE *file = fopen("complex_numbers.bin", "rb");
    if (file == NULL) {
