void init_hash_table(struct hash_table* table, int size) {
    table->records = (struct device_status_record**)malloc(sizeof(struct device_status_record*) * size);
    memset(table->records, 0, sizeof(struct device_status_record*) * size);
    table->size = size;
    table->count = 0;
}

void insert_device_status_record(struct hash_table* table, struct device_status_record record) {
    int index = record.id % table->size;
    while (table->records[index] != NULL && table->records[index]->id != record.id) {
        index++;
        if (index == table->size) {
            index = 0;
        }
    }
    if (table->records[index] == NULL) {
        table->count++;
    }
    table->records[index] = (struct device_status_record*)malloc(sizeof(struct device_status_record));
    memcpy(table->records[index], &record, sizeof(struct device_status_record));
}

void delete_device_status_record(struct hash_table* table, int id) {
    int index = id % table->size;
    while (table->records[index] != NULL && table->records[index]->id != id) {
        index++;
        if (index == table->size) {
            index = 0;
        }
    }
    if (table->records[index] != NULL) {
        free(table->records[index]);
        table->count--;
    }
}

