// Function to insert a temperature reading into the hash table
void insert_temperature_reading(TemperatureHashTable *ht, TemperatureReading *reading) {
    if (ht->size == ht->capacity) {
        // Resize the hash table if it is full
        int new_capacity = ht->capacity * 2;
        TemperatureReading *new_readings = (TemperatureReading *)malloc(new_capacity * sizeof(TemperatureReading));
        for (int i = 0; i < ht->size; i++) {
            new_readings[i] = ht->readings[i];
