    }

    // Initialize the caching layer with a fixed number of structures
    cached_elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(CACHE_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!cached_elements) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize the sliding window mechanism with a fixed number of structures
    num_elements = WINDOW_SIZE;
}

// Define the function for dynamically resizing the array of NFAPI_CRC_INDICATION_PDU_T structures based on system load and resource availability
void resize(int new_size) {
    // Check if the new size is within the allowed range
    if (new_size < MIN_WINDOW_SIZE || new_size > MAX_WINDOW_SIZE) {
        return;
    }

    // Reallocate memory for the array of structures
    elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(elements, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!elements) {
        printf("Error: Memory allocation failed\n");
        return;
