        elements[i].rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        elements[i].rnti = rand();
        elements[i].crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
        elements[i].crc_indication_rel8.crcflag = rand() % 2;
    }

    // Update the number of elements in the array
    num_elements = new_size;
}

// Define the function for caching the most recently accessed structures
void cache(int index) {
    // Check if the index is within the bounds of the array
    if (index < 0 || index >= num_elements) {
        return;
    }

    // Copy the structure at the specified index to the caching layer
    cached_elements[num_cached_elements] = elements[index];
    num_cached_elements++;

    // Check if the caching layer is full and needs to be resized
    if (num_cached_elements == CACHE_SIZE) {
        resize(num_cached_elements * 2);
    }
}

// Define the function for retrieving a structure from the caching layer
NFAPI_CRC_INDICATION_PDU_T* retrieve(int index) {
    // Check if the index is within the bounds of the caching layer
    if (index < 0 || index >= num_cached_elements) {
        return NULL;
    }

    // Return the structure at the specified index from the caching layer
    return &cached_elements[index];
}

// Define the function for tracking and logging performance metrics
void track_metrics() {
    // Increment the number of elements in the array
    metrics[current_metric].num_elements = num_elements;

    // Increment the number of cached elements in the caching layer
    metrics[current_metric].num_cached_elements = num_cached_elements;

    // Increment the cache hits and misses based on the number of accesses to the caching layer
    if (num_cached_elements > 0) {
        metrics[current_metric].cache_hits = num_cached_elements - cached_elements[0].rx_ue_information.tag;
        metrics[current_metric].cache_misses = cached_elements[0].rx_ue_information.tag;
