    hist->histogram = (int *)malloc(num_sessions * sizeof(int));
    if (hist->histogram == NULL) {
        printf("Error: Failed to allocate memory for histogram array\n");
        return 1;
    }
    hist->size = num_sessions;
    for (int i = 0; i < num_sessions; i++) {
        double total_duration = 0.0;
        for (int j = 0; j < 10; j++) {
            total_duration += (*sessions)[i].events[j].timestamp - seed + i * 1000 + j;
        }
        hist->histogram[i] = (int)total_duration;
    }

    // Print the largest integer along with the corresponding string
    int max_index = 0;
    for (int i = 1; i < num_sessions; i++) {
        if (hist->histogram[i] > hist->histogram[max_index]) {
            max_index = i;
        }
    }
    printf("Largest integer: %d\n", hist->histogram[max_index]);
    printf("Corresponding string: %s\n", (*sessions)[max_index].session_id);

    // Clean up memory
    for (int i = 0; i < num_sessions; i++) {
        free((*sessions)[i].events[j].payload);
        free((*sessions)[i].events);
        free((*sessions)[i].session_id);
    }
    free(hist->histogram);
    free(hist);
    free(*sessions);

    return 0;
}

// Define the function to populate the UE context information records
