// Define the DNS server priorities and retry logic
#define DNS_SERVERS {"8.8.8.8", "8.8.4.4"}
#define DNS_RETRY_COUNT 3
#define DNS_RETRY_DELAY 1000 // in milliseconds

// Define the rate limiting mechanism for the function
#define RATE_LIMITING_ENABLED true
#define MAX_REQUESTS_PER_SECOND 5

// Define the memory management mechanism for the function
