// Define the structure for storing sensor data points
typedef struct {
    char device_id[16];
    double timestamp;
    int sensor_type;
    double measurement;
    char metadata[256];
} data_point;

// Define the structure for storing a collection of data streams
typedef struct {
    char device_id[16];
    linked_list *data_points;
    double total_measurement_sum;
} data_stream;

// Define the structure for storing IoT Device Status Records
typedef struct {
    char device_id[16];
    int current_state;
    double last_online_timestamp;
    linked_list *recent_anomalies;
} device_status_record;

// Define the function for managing sensor data streams
int manage_data_streams(int num_devices, int num_records, int seed) {
    // Initialize variables
    int i, j, k;
    double total_measurement_sum = 0.0;
    linked_list *data_points = NULL;
    device_status_record *device_statuses = NULL;

    // Allocate memory for the data streams and device status records
    data_stream **data_streams = (data_stream**)malloc(num_devices * sizeof(data_stream*));
    if (!data_streams) {
        printf("Error: Failed to allocate memory for data streams\n");
        return 1;
    }
    device_status_record **device_statuses = (device_status_record**)malloc(num_devices * sizeof(device_status_record*));
    if (!device_statuses) {
        printf("Error: Failed to allocate memory for device status records\n");
        return 1;
    }

    // Populate the data streams and device status records
    for (i = 0; i < num_devices; i++) {
        data_streams[i] = (data_stream*)malloc(sizeof(data_stream));
        if (!data_streams[i]) {
            printf("Error: Failed to allocate memory for data stream %d\n", i);
            return 1;
        }
        device_statuses[i] = (device_status_record*)malloc(sizeof(device_status_record));
        if (!device_statuses[i]) {
            printf("Error: Failed to allocate memory for device status record %d\n", i);
            return 1;
        }
    }

    // Populate the data points and total measurement sum
    for (i = 0; i < num_devices; i++) {
        data_streams[i]->device_id = "Device ID";
        data_streams[i]->data_points = NULL;
        data_streams[i]->total_measurement_sum = 0.0;
    }
    for (j = 0; j < num_records; j++) {
        // Generate a random device ID and sensor type
        char device_id[16];
        int sensor_type = rand() % 3 + 1;
        sprintf(device_id, "Device ID %d", i);

        // Allocate memory for the data point
        data_point *data_point = (data_point*)malloc(sizeof(data_point));
        if (!data_point) {
            printf("Error: Failed to allocate memory for data point\n");
            return 1;
        }

        // Populate the data point fields
        data_point->device_id = device_id;
        data_point->timestamp = time(NULL);
        data_point->sensor_type = sensor_type;
        data_point->measurement = rand() % 100 + 1;
        sprintf(data_point->metadata, "Metadata for device ID %d", i);

        // Add the data point to the linked list of data points
        if (data_streams[i]->data_points == NULL) {
            data_streams[i]->data_points = (linked_list*)malloc(sizeof(linked_list));
            if (!data_streams[i]->data_points) {
                printf("Error: Failed to allocate memory for linked list\n");
                return 1;
            }
        }
        data_streams[i]->data_points->push_back(data_point);

        // Update the total measurement sum
        total_measurement_sum += data_point->measurement;
    }

    // Compute the average measurements for each device and store them in a histogram
    for (i = 0; i < num_devices; i++) {
        double average_measurement = total_measurement_sum / data_streams[i]->data_points->size();
        printf("Average measurement for device ID %d: %.2f\n", i, average_measurement);
    }

    // Detect and report duplicate IDs
    for (i = 0; i < num_devices; i++) {
        if (data_streams[i]->device_id == data_streams[i+1]->device_id) {
            printf("Duplicate device ID detected: %s\n", data_streams[i]->device_id);
        }
    }

    // Release memory for the data streams and device status records
    for (i = 0; i < num_devices; i++) {
        free(data_streams[i]);
        free(device_statuses[i]);
    }
