// Configuration options
#define MAX_DNS_QUERIES_PER_SEC 10 // Maximum number of DNS queries per second
#define LOGGING_ENABLED true       // Enable or disable logging
#define LOG_FILE_PATH "./logs/dns.log" // Log file path

// Struct to hold the resolved IPv4 address and error message
typedef struct {
    u_char ip[4];
    char* error;
} ResolvedIP;

// Function to resolve a hostname to an IPv4 address
ResolvedIP resolve_hostname(const char* hostname) {
    // Initialize the resolved IP and error message
    ResolvedIP resolved_ip = {0};
    char* error = NULL;

    // Check if the hostname is valid
    if (!hostname || strlen(hostname) == 0) {
        error = "Invalid hostname";
        goto cleanup;
    }

    // Get the current time in seconds
    time_t now = time(NULL);

    // Check if we have reached the maximum number of DNS queries per second
    if (now - last_dns_query < 1) {
        error = "Maximum number of DNS queries per second exceeded";
        goto cleanup;
    }

    // Resolve the hostname to an IPv4 address
    struct addrinfo* result = NULL;
    int rc = getaddrinfo(hostname, NULL, NULL, &result);
    if (rc != 0) {
        error = "Failed to resolve hostname";
        goto cleanup;
    }

    // Get the IPv4 address from the result
    struct sockaddr_in* addr = (struct sockaddr_in*)result->ai_addr;
    memcpy(resolved_ip.ip, &addr->sin_addr.s_addr, 4);

    // Clean up the result
    freeaddrinfo(result);

cleanup:
    // Log relevant information if logging is enabled
    if (LOGGING_ENABLED) {
        char* log_message = NULL;
        asprintf(&log_message, "Resolved hostname %s to IPv4 address %u.%u.%u.%u", hostname, resolved_ip.ip[0], resolved_ip.ip[1], resolved_ip.ip[2], resolved_ip.ip[3]);
        if (error) {
            log_message = strcat(log_message, " with error: ");
            log_message = strcat(log_message, error);
        }
        write_to_file(LOG_FILE_PATH, log_message);
    }

    // Return the resolved IP and error message
    return resolved_ip;
}

// Function to write a string to a file
void write_to_file(const char* path, const char* str) {
    FILE* fp = fopen(path, "a");
    if (fp == NULL) {
        perror("fopen");
        return;
    }
    fprintf(fp, "%s\n", str);
    fclose(fp);
}
```
