    // Initialize the log entry array with a default capacity of 1024 entries
    entries->capacity = 1024;
    entries->size = 0;
    entries->entries = (log_entry*)malloc(sizeof(log_entry) * entries->capacity);
}

void add_log_entry(struct log_entry_array* entries, time_t timestamp, double measurement, char* description) {
    // Check if the array is full and needs to be resized
    if (entries->size == entries->capacity) {
        // Resize the array by a factor of 2
        entries->capacity *= 2;
        entries->entries = (log_entry*)realloc(entries->entries, sizeof(log_entry) * entries->capacity);
    }

    // Add the new log entry to the end of the array
    entries->entries[entries->size].timestamp = timestamp;
    entries->entries[entries->size].measurement = measurement;
    entries->entries[entries->size].description = description;
    entries->size++;
