    }

    // Populate the timestamp with the current time
    struct tm* now = localtime(&now);
    for (int i = 0; i < n; i++) {
        entries[i].timestamp = *now;
    }

    // Initialize the priority based on predefined criteria
    for (int i = 0; i < n; i++) {
        if (entries[i].value > 50) {
            entries[i].priority = 1.0f;
        } else if (entries[i].value > 25) {
            entries[i].priority = 0.75f;
        } else if (entries[i].value > 10) {
            entries[i].priority = 0.5f;
        } else {
            entries[i].priority = 0.25f;
        }
    }

    // Return the allocated array of config_entry structures
    return entries;
}

// Define the function to dynamically allocate memory for a single config_entry structure
config_entry* alloc_config_entry(void) {
    // Allocate memory for the config_entry structure
    config_entry* entry = malloc(sizeof(config_entry));
