        return -1;
    }

    // Serialize the array of config_entry structures to a JSON file
    json_t* root = json_object();
    for (int i = 0; i < n; i++) {
        json_object_set(root, entries[i].key, json_integer(entries[i].value));
    }
    char* json_string = json_dumps(root, JSON_COMPACT);

    // Deserialize the JSON file to an array of config_entry structures
    json_error_t error;
    json_t* root2 = json_loads(json_string, 0, &error);
    if (!root2) {
        fprintf(stderr, "Error: %s\n", error.text);
        return -1;
    }
    config_entry* entries2 = malloc(sizeof(config_entry) * n);
    for (int i = 0; i < n; i++) {
