void process_file(struct file_info *file_info) {
    // Check if input file is valid
    struct stat file_stat;
    if (fstat(file_info->fd, &file_stat) == -1) {
        log_error("Failed to get file statistics");
        return;
    }
    if (file_stat.st_size > MAX_FILE_SIZE) {
        log_error("File size exceeds maximum limit");
        return;
    }

    // Initialize variables
    char *line = malloc(MAX_LINE_LENGTH);
    int line_count = 0;
    double start_time = clock();

    // Process file in chunks
    while (1) {
        // Read next chunk of data from file
        ssize_t bytes_read = read(file_info->fd, line, MAX_LINE_LENGTH);
        if (bytes_read == 0) {
            break;
        } else if (bytes_read == -1) {
            log_error("Failed to read from file");
            return;
        }

        // Process chunk of data
        for (int i = 0; i < bytes_read; i++) {
            if (line[i] != ' ') {
                line_count++;
            } else {
                line_count = 0;
            }
        }
    }

    // Calculate processing time and throughput
    double end_time = clock();
    average_processing_time += (end_time - start_time) / CLOCKS_PER_SEC;
    overall_throughput += line_count / ((end_time - start_time) / CLOCKS_PER_SEC);
}

void* thread_func(void *thread_data) {
    struct thread_data *data = (struct thread_data *)thread_data;
    sem_wait(data->semaphore);
    process_file(data->file_info);
    sem_post(data->semaphore);
    pthread_exit(NULL);
}

void handle_signal(int signal) {
    // Handle SIGINT and SIGTERM signals
    if (signal == SIGINT || signal == SIGTERM) {
        log_error("Processing interrupted");
        exit(1);
    }
}

void log_error(char *message) {
    // Log error message to stderr
    fprintf(stderr, "%s\n", message);
}

void log_processing_details() {
    // Log processing details and send notification if necessary
    printf("Processing completed successfully\n");
    printf("Total lines processed: %d\n", total_lines);
    printf("Average processing time per line: %.2f seconds\n", average_processing_time / thread_count);
    printf("Overall throughput: %.2f lines/second\n", overall_throughput);
    if (!notification_sent) {
        send_notification("Processing completed successfully");
    }
}

void log_resource_usage() {
    // Log resource usage to stderr
    fprintf(stderr, "Resource usage: CPU %d%%, memory %d%%\n", 0, 0);
}

void send_notification(char *message) {
    // Send notification to external system using specified mechanism
    if (strcmp(NOTIFICATION_SYSTEM, "slack") == 0) {
        // Slack notification example
        printf("Sending Slack notification: %s\n", message);
    } else {
        log_error("Unsupported notification system");
    }
}
