char *compact_line(char *line) {
    char *compacted_line = malloc(strlen(line));
    if (!compacted_line) {
        printf("Error: unable to allocate memory for compacted line.\n");
        return NULL;
    }

    int i = 0;
    while (*line != '\0') {
        if (*line == ' ' || *line == '\t' || *line == '\r' || *line == '\n') {
            line++;
            continue;
        }
        compacted_line[i++] = *line++;
    }
    compacted_line[i] = '\0';

    return compacted_line;
}

char *add_timestamp(char *compacted_line) {
    char *timestamped_line = malloc(strlen(compacted_line) + 20);
    if (!timestamped_line) {
        printf("Error: unable to allocate memory for timestamped line.\n");
        return NULL;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(timestamped_line, 20, "%Y-%m-%d %H:%M:%S", tm);
    sprintf(timestamped_line + strlen(timestamped_line), " %s\n", compacted_line);

    return timestamped_line;
}
