        System.out.println("Options:");
        System.out.println("  -i <filename>   Specifies the input log file to be processed.");
        System.out.println("  --help          Displays comprehensive usage instructions and examples.");
        System.out.println("  -v <verbosity>  Sets the verbosity level of output, ranging from 1 to 5, where higher values increase the amount of detail in the output.");
        System.out.println("  -o <output_file> Redirects the output to a specified file instead of printing to the console.");
        System.out.println("  -t <tag>        Filters events by a specific tag, allowing for focused analysis of relevant events.");
    }
}
