    if (!records) {
        printf("Error: Failed to allocate memory for %d records\n", num_records);
        return NULL;
    }

    // Initialize the array of records with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand() % 1000;
        records[i].key = rand() % 1000;
        records[i].precision_indicator = (float)rand() / RAND_MAX;
        records[i].value = rand() % 1000;
        records[i].timestamp = time(NULL);
        records[i].precision_indicator2 = (float)rand() / RAND_MAX;
    }

    return records;
}

// Define the function to free memory allocated for an array of records
void free_records(record* records, int num_records) {
    // Free the memory allocated for the array of records
    free(records);
}

// Define the function to compute the MD5 hash of a string in Java
char* md5_hash(const char* str) {
    // Compute the MD5 hash of the input string
    unsigned char* digest = (unsigned char*)malloc(16 * sizeof(unsigned char));
    if (!digest) {
        printf("Error: Failed to allocate memory for MD5 hash\n");
        return NULL;
    }
    MD5_CTX ctx;
    MD5Init(&ctx);
    MD5Update(&ctx, (unsigned char*)str, strlen(str));
    MD5Final(digest, &ctx);

    // Convert the digest to a hexadecimal string
    char* hash = (char*)malloc((16 * 2) + 1);
    if (!hash) {
        printf("Error: Failed to allocate memory for MD5 hash string\n");
        return NULL;
    }
    for (int i = 0; i < 16; i++) {
        sprintf(hash + (i * 2), "%02x", digest[i]);
    }

    // Free the memory allocated for the MD5 hash and return the hexadecimal string
    free(digest);
    return hash;
}
