    // Process the chunk and generate HTML files for each line
    foreach ($chunk as $row) {
        $data = array_map(function ($value) use ($config) {
            return $config->get('currency') === 'USD' ? $value : convertCurrency($value, $config->get('currency'));
        }, $row);
        $html->write($data);
    }
}

