#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Define a structure to represent a cell context
typedef struct {
    int cell_id;
    char frequency_band[10];
    int rx_ue_information_tag;
    int rnti;
} NFAPI_CELL_CONTEXT_T;

// Define a dynamic memory pool for the cell contexts
static NFAPI_CELL_CONTEXT_T *cell_context_pool = NULL;
static size_t cell_context_pool_size = 0;
static pthread_mutex_t cell_context_pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Define a function to populate the collection of cell contexts
int populate_cell_contexts(int N, int seed) {
    // Validate input parameters
    if (N <= 0 || seed < 0) {
        return -1;
    }

    // Initialize the dynamic memory pool for the cell contexts
    if (!cell_context_pool) {
        cell_context_pool = malloc(sizeof(NFAPI_CELL_CONTEXT_T) * N);
        if (!cell_context_pool) {
            return -1;
        }
        cell_context_pool_size = N;
    }

    // Populate the collection of cell contexts with random values
    for (int i = 0; i < N; i++) {
        int cell_id = seed + i;
        char frequency_band[10];
        sprintf(frequency_band, "5G");
