        // Validate the cell ID and frequency band before including them in the collection
        if (cell_id < 0 || strcmp(frequency_band, "5G") != 0) {
            continue;
        }

        // Lock the mutex to ensure thread safety when accessing shared resources
        pthread_mutex_lock(&cell_context_pool_lock);

        // Add the cell context to the collection
        cell_context_pool[i].cell_id = cell_id;
        strcpy(cell_context_pool[i].frequency_band, frequency_band);
        cell_context_pool[i].rx_ue_information_tag = rx_ue_information_tag;
        cell_context_pool[i].rnti = rnti;

        // Unlock the mutex to release shared resources
        pthread_mutex_unlock(&cell_context_pool_lock);
    }

    return 0;
}

// Define a function to clean up temporary resources in case of early termination due to errors or timeouts
void cleanup_cell_contexts() {
    // Lock the mutex to ensure thread safety when accessing shared resources
    pthread_mutex_lock(&cell_context_pool_lock);

    // Free the dynamic memory pool for the cell contexts
    free(cell_context_pool);
    cell_context_pool = NULL;
    cell_context_pool_size = 0;

    // Unlock the mutex to release shared resources
    pthread_mutex_unlock(&cell_context_pool_lock);
}
