    int num_file_system_operations;
    IO_SENSOR_READING *iot_sensor_readings;
    int num_iot_sensor_readings;
} COLLECTION;

// Define the function to create a new collection
COLLECTION* create_collection(int size) {
    // Allocate memory for the collection
    COLLECTION *collection = (COLLECTION*) malloc(sizeof(COLLECTION));
    if (!collection) {
        fprintf(stderr, "Error: Failed to allocate memory for collection\n");
        return NULL;
    }

    // Initialize the collection
    collection->file_system_operations = (FILE_SYSTEM_OPERATION_RECORD*) malloc(size * sizeof(FILE_SYSTEM_OPERATION_RECORD));
    if (!collection->file_system_operations) {
        fprintf(stderr, "Error: Failed to allocate memory for file system operations\n");
        free(collection);
        return NULL;
    }
    collection->num_file_system_operations = 0;
    collection->iot_sensor_readings = (IO_SENSOR_READING*) malloc(size * sizeof(IO_SENSOR_READING));
    if (!collection->iot_sensor_readings) {
        fprintf(stderr, "Error: Failed to allocate memory for IoT sensor readings\n");
        free(collection->file_system_operations);
        free(collection);
        return NULL;
    }
    collection->num_iot_sensor_readings = 0;

    // Initialize the concurrency threshold and priority level for file system operations
    collection->concurrency_threshold = CONCURRENCY_THRESHOLD;
    collection->file_system_operation_priority = FILE_SYSTEM_OPERATION_PRIORITY;

    // Initialize the priority level for IoT sensor readings
    collection->iot_sensor_reading_priority = IO_SENSOR_READING_PRIORITY;

    return collection;
}

// Define the function to add a new file system operation to the collection
int add_file_system_operation(COLLECTION *collection, int id, char *type, int priority) {
    // Check if the collection is full
    if (collection->num_file_system_operations >= MAX_COLLECTION_SIZE) {
        fprintf(stderr, "Error: Collection is full\n");
        return -1;
    }

    // Allocate memory for the new file system operation record
    FILE_SYSTEM_OPERATION_RECORD *new_record = (FILE_SYSTEM_OPERATION_RECORD*) malloc(sizeof(FILE_SYSTEM_OPERATION_RECORD));
    if (!new_record) {
        fprintf(stderr, "Error: Failed to allocate memory for new file system operation record\n");
        return -1;
    }

    // Initialize the new file system operation record
    new_record->id = id;
    strcpy(new_record->type, type);
    new_record->priority = priority;
    new_record->timestamp = time(NULL);
    new_record->flags = 0;
    new_record->refcount = 1;

    // Add the new file system operation record to the collection
    collection->file_system_operations[collection->num_file_system_operations++] = *new_record;

    return 0;
}

// Define the function to add a new IoT sensor reading to the collection
int add_iot_sensor_reading(COLLECTION *collection, int sensor_id, float temperature, float humidity, float battery_level) {
    // Check if the collection is full
    if (collection->num_iot_sensor_readings >= MAX_COLLECTION_SIZE) {
        fprintf(stderr, "Error: Collection is full\n");
        return -1;
    }

    // Allocate memory for the new IoT sensor reading record
    IO_SENSOR_READING *new_record = (IO_SENSOR_READING*) malloc(sizeof(IO_SENSOR_READING));
    if (!new_record) {
        fprintf(stderr, "Error: Failed to allocate memory for new IoT sensor reading record\n");
        return -1;
    }

    // Initialize the new IoT sensor reading record
    new_record->timestamp = time(NULL);
    new_record->sensor_id = sensor_id;
    new_record->temperature = temperature;
    new_record->humidity = humidity;
    new_record->battery_level = battery_level;

    // Add the new IoT sensor reading record to the collection
    collection->iot_sensor_readings[collection->num_iot_sensor_readings++] = *new_record;

    return 0;
}

// Define the function to remove a file system operation from the collection
int remove_file_system_operation(COLLECTION *collection, int id) {
    // Find the index of the file system operation record with the specified ID
    int i = 0;
    for (i = 0; i < collection->num_file_system_operations; i++) {
        if (collection->file_system_operations[i].id == id) {
            break;
        }
    }

    // Check if the file system operation record was found
    if (i >= collection->num_file_system_operations) {
        fprintf(stderr, "Error: File system operation with ID %d not found\n", id);
        return -1;
    }

    // Decrement the reference count of the file system operation record
    collection->file_system_operations[i].refcount--;

    // Remove the file system operation record from the collection
    if (collection->file_system_operations[i].refcount == 0) {
        memmove(&collection->file_system_operations[i], &collection->file_system_operations[i + 1], sizeof(FILE_SYSTEM_OPERATION_RECORD) * (collection->num_file_system_operations - i - 1));
        collection->num_file_system_operations--;
    }

    return 0;
}

