    if (config->port_number < 0) {
        config->port_number = rand() % 10000;
    }
}

// Define the function to implement a retry mechanism with exponential backoff for failed API calls
void retryAPICall(NetworkElementConfig* config, int attempt) {
    // Check if the API call has failed
    if (config->connection_status == false) {
        printf("API call failed: %d\n", config->id);
        return;
    }

    // Sleep for a random amount of time between 0 and 1 second before retrying the API call
    int sleep_time = rand() % 1000 + 1;
    usleep(sleep_time * 1000);

    // Increment the attempt number and retry the API call
    attempt++;
    if (attempt > 5) {
        printf("Maximum number of attempts reached: %d\n", config->id);
        return;
    }
    retryAPICall(config, attempt);
}

