// Define the function to support concurrent updates to the configuration collection from multiple threads, implementing fine-grained locking mechanisms to minimize contention and ensure data integrity
void updateConfigCollection(NetworkElementConfig* config) {
    // Lock the configuration collection for writing
    pthread_mutex_lock(&config_lock);

    // Check if the configuration already exists in the collection
    bool found = false;
    for (int i = 0; i < num_configs; i++) {
        if (configs[i].id == config->id) {
            found = true;
            break;
        }
    }

    // If the configuration already exists, update it in the collection
    if (found) {
        for (int i = 0; i < num_configs; i++) {
            if (configs[i].id == config->id) {
                configs[i] = *config;
                break;
            }
        }
    } else {
        // If the configuration does not exist, add it to the collection
        NetworkElementConfig* new_config = (NetworkElementConfig*)malloc(sizeof(NetworkElementConfig));
        if (!new_config) {
            printf("Failed to allocate memory for network element configuration\n");
            pthread_mutex_unlock(&config_lock);
            return;
        }
        *new_config = *config;
        configs[num_configs] = new_config;
        num_configs++;
    }

    // Unlock the configuration collection for writing
    pthread_mutex_unlock(&config_lock);
}

// Define the function to dynamically resize the collection of network element configurations as configurations are added or removed, doing so efficiently to avoid frequent memory allocations and deallocations
void resizeConfigCollection(int new_size) {
    // Check if the new size is greater than the current size
    if (new_size > num_configs) {
        // Allocate memory for the additional configurations
        NetworkElementConfig* new_configs = (NetworkElementConfig*)malloc((new_size - num_configs) * sizeof(NetworkElementConfig));
        if (!new_configs) {
            printf("Failed to allocate memory for network element configurations\n");
            return;
        }

        // Copy the additional configurations from the old collection to the new one
        for (int i = num_configs; i < new_size; i++) {
            new_configs[i] = configs[i];
        }

        // Free the memory allocated for the old collection
        free(configs);

        // Update the pointer to the new collection and the size of the collection
        configs = new_configs;
        num_configs = new_size;
    } else {
        // Check if the new size is less than the current size
        if (new_size < num_configs) {
            // Free the memory allocated for the additional configurations
            NetworkElementConfig* new_configs = (NetworkElementConfig*)malloc((num_configs - new_size) * sizeof(NetworkElementConfig));
            if (!new_configs) {
                printf("Failed to allocate memory for network element configurations\n");
                return;
            }

            // Copy the additional configurations from the old collection to the new one
            for (int i = num_configs - 1; i >= new_size; i--) {
                new_configs[i] = configs[i];
            }

            // Free the memory allocated for the old collection
            free(configs);

            // Update the pointer to the new collection and the size of the collection
            configs = new_configs;
            num_configs = new_size;
        } else {
            // If the new size is equal to the current size, do nothing
        }
    }
}

