}

// Define the function to handle DNS resolution for a given hostname
int resolve_dns(const char *hostname, u_char **ip) {
    // Check if the hostname is valid
    if (hostname == NULL || strlen(hostname) == 0) {
        return ERROR_DNS_RESOLUTION;
    }

    // Initialize the DNS resolution parameters
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    // Resolve the DNS server list and get the first available server
    struct addrinfo *dns_server = NULL;
    if (getaddrinfo(DNS_SERVERS, NULL, &hints, &dns_server) != 0) {
        return ERROR_DNS_RESOLUTION;
    }

    // Create a socket and connect to the DNS server
    int sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (sock < 0) {
        return ERROR_DNS_RESOLUTION;
    }
    if (connect(sock, dns_server->ai_addr, dns_server->ai_addrlen) != 0) {
        close(sock);
        return ERROR_DNS_RESOLUTION;
    }

    // Send the DNS query and receive the response
    char *query = "QUERY";
    send(sock, query, strlen(query), 0);
    char buffer[1024];
    recv(sock, buffer, sizeof(buffer), 0);

    // Close the socket and return the IP address
    close(sock);
    *ip = malloc(sizeof(u_char) * 4);
    if (*ip == NULL) {
        return ERROR_MEMORY_ALLOCATION;
    }
    memcpy(*ip, buffer, sizeof(buffer));
    return 0;
}

