// Define the function to initialize a dynamic configuration structure for a network interface
int initialize_network_config(network_config_t *config, size_t num_configs, unsigned long seed) {
    // Check if the input parameters are valid
    if (config == NULL || num_configs <= 0) {
        return -1;
    }

    // Initialize the configuration structure with default values
    for (size_t i = 0; i < num_configs; i++) {
        config[i].ip_address[0] = '\0';
        config[i].subnet_mask[0] = '\0';
        config[i].gateway[0] = '\0';
        for (int j = 0; j < 3; j++) {
            config[i].dns_servers[j][0] = '\0';
        }
        config[i].qos_settings = 0;
    }

    // Generate random IP addresses, subnet masks, and DNS servers if a seed is provided
    if (seed != 0) {
        srand(seed);
        for (size_t i = 0; i < num_configs; i++) {
            generate_random_ip(&config[i].ip_address);
            generate_random_ip(&config[i].subnet_mask);
            generate_random_dns(&config[i].dns_servers);
        }
    }

    // Log the initialization process and return success
    printf("Initialized %lu network configurations\n", num_configs);
    return 0;
}

// Generate a random IP address with the specified format
void generate_random_ip(char *ip) {
    // Check if the input parameter is valid
    if (ip == NULL) {
        return;
    }

    // Generate a random integer between 0 and 255 for each octet of the IP address
    int octets[4];
    for (int i = 0; i < 4; i++) {
        octets[i] = rand() % 256;
    }

    // Format the random IP address in the specified format
    sprintf(ip, "%d.%d.%d.%d", octets[0], octets[1], octets[2], octets[3]);
}

// Generate a random DNS server with the specified format
void generate_random_dns(char *dns) {
    // Check if the input parameter is valid
    if (dns == NULL) {
        return;
    }

    // Generate a random integer between 0 and 255 for each octet of the DNS server
    int octets[4];
    for (int i = 0; i < 4; i++) {
        octets[i] = rand() % 256;
    }

    // Format the random DNS server in the specified format
    sprintf(dns, "%d.%d.%d.%d", octets[0], octets[1], octets[2], octets[3]);
}
