// Function to add a new LTE PHY context to the dynamic array
void add_ltephycontext(LTEPHYCONTEXT **ltephycontexts, int *num_ltephycontexts, int ci, int frequency_band) {
    // Check if the maximum number of LTE PHY contexts has been reached
    if (*num_ltephycontexts == 10) {
        printf("Error: Maximum number of LTE PHY contexts has been reached\n");
        return;
    }

    // Allocate memory for the new LTE PHY context
    LTEPHYCONTEXT *new_ltephycontext = (LTEPHYCONTEXT *)malloc(sizeof(LTEPHYCONTEXT));
    if (new_ltephycontext == NULL) {
