}

// Function to read a potentially large text file line by line, dynamically allocating memory for each line and printing its contents in a comma-separated format
void read_file(char *filename) {
    // Open the file for reading
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: Failed to open the file %s\n", filename);
        return;
    }

    // Allocate memory for the buffer to read the file line by line
    char *buffer = (char *)malloc(sizeof(char) * 1024);
    if (buffer == NULL) {
        printf("Error: Failed to allocate memory for the buffer\n");
        fclose(fp);
        return;
    }

    // Read the file line by line and dynamically allocate memory for each line
    while (fgets(buffer, 1024, fp) != NULL) {
        // Split the line into fields using a comma as the delimiter
        char *token = strtok(buffer, ",");
        int num_fields = 0;
        while (token != NULL) {
            // Allocate memory for each field and store its contents in the dynamic array of strings
            char **strings = (char **)realloc(strings, sizeof(char *) * (num_fields + 1));
            if (strings == NULL) {
                printf("Error: Failed to allocate memory for the dynamic array of strings\n");
                fclose(fp);
                free(buffer);
                return;
            }
            strings[num_fields] = token;
            num_fields++;
            token = strtok(NULL, ",");
        }

        // Print the contents of each line in a comma-separated format
        for (int i = 0; i < num_fields - 1; i++) {
            printf("%s,", strings[i]);
        }
        printf("%s\n", strings[num_fields - 1]);

        // Free the memory allocated for each field
        for (int i = 0; i < num_fields; i++) {
            free(strings[i]);
        }
        free(strings);
    }

    // Free the memory allocated for the buffer
    free(buffer);

    // Close the file
    fclose(fp);
}

// Function to calculate the average of the last two fields of each line in a potentially large text file
void calculate_average(char *filename) {
    // Open the file for reading
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: Failed to open the file %s\n", filename);
        return;
    }

