    char *buffer = (char *)malloc(sizeof(char) * 1024);
    if (buffer == NULL) {
        printf("Error: Failed to allocate memory for the buffer\n");
        fclose(fp);
        return;
    }

    // Read the file line by line and calculate the average of the last two fields of each line
    while (fgets(buffer, 1024, fp) != NULL) {
        // Split the line into fields using a comma as the delimiter
        char *token = strtok(buffer, ",");
        int num_fields = 0;
        while (token != NULL) {
            // Allocate memory for each field and store its contents in the dynamic array of strings
            char **strings = (char **)realloc(strings, sizeof(char *) * (num_fields + 1));
            if (strings == NULL) {
                printf("Error: Failed to allocate memory for the dynamic array of strings\n");
                fclose(fp);
                free(buffer);
                return;
            }
            strings[num_fields] = token;
            num_fields++;
            token = strtok(NULL, ",");
        }

        // Calculate the average of the last two fields of each line
        int field1 = atoi(strings[num_fields - 2]);
        int field2 = atoi(strings[num_fields - 1]);
        float average = (field1 + field2) / 2.0;
        printf("%s,%.2f\n", strings[num_fields - 2], average);

        // Free the memory allocated for each field
        for (int i = 0; i < num_fields; i++) {
            free(strings[i]);
        }
        free(strings);
    }

    // Free the memory allocated for the buffer
    free(buffer);

    // Close the file
