// Function to initialize and configure a dynamic array of LTEPHYCONTEXT structures
void init_ltephycontexts(int num_contexts, ltephycontext_t** contexts) {
    // Allocate memory for the array of LTEPHYCONTEXT structures
    *contexts = (ltephycontext_t*)malloc(num_contexts * sizeof(ltephycontext_t));
    if (*contexts == NULL) {
        fprintf(stderr, "Failed to allocate memory for LTEPHYCONTEXT array\n");
        exit(1);
    }

    // Initialize each structure in the array with default values
    for (int i = 0; i < num_contexts; i++) {
        (*contexts)[i].ci = -1;
        (*contexts)[i].frequency_band = -1;
        memset((*contexts)[i].downlink_channels, '\0', sizeof((*contexts)[i].downlink_channels));
    }
}

// Function to add a new channel to the dynamic array of LTEPHYCONTEXT structures
void add_channel(ltephycontext_t** contexts, int num_contexts, int ci, int frequency_band, char* downlink_channel) {
    // Check if the new channel is already in the array
    for (int i = 0; i < num_contexts; i++) {
        if ((*contexts)[i].ci == ci && (*contexts)[i].frequency_band == frequency_band && strcmp((*contexts)[i].downlink_channels, downlink_channel) == 0) {
            return;
        }
    }

    // If the new channel is not in the array, add it to the end of the array
    (*contexts)[num_contexts - 1].ci = ci;
    (*contexts)[num_contexts - 1].frequency_band = frequency_band;
    strcpy((*contexts)[num_contexts - 1].downlink_channels, downlink_channel);
}

// Function to read data from a remote HTTP API endpoint and process it in batches
void read_api_data(ltephycontext_t** contexts, int num_contexts) {
