        fprintf(stderr, "Failed to initialize CURL handle\n");
        exit(1);
    }

    // Set the URL for the API endpoint and the HTTP method
    char url[256];
    sprintf(url, "https://api.example.com/users?limit=100");
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_HTTPGET, 1L);

    // Set the JSON parser for parsing the API response
    json_t* root = NULL;
    json_error_t error;

    // Make the HTTP request and parse the JSON response
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to perform HTTP request: %s\n", curl_easy_strerror(res));
        exit(1);
    }
    root = json_loads(curl_easy_getinfo(curl, CURLINFO_RESPONSE_BODY), 0, &error);
    if (root == NULL) {
        fprintf(stderr, "Failed to parse JSON response: %s\n", error.text);
        exit(1);
    }

    // Iterate over the JSON array and process each object in batches
    json_t* users = json_object_get(root, "users");
    if (users == NULL) {
        fprintf(stderr, "Failed to find 'users' field in JSON response\n");
        exit(1);
    }
    int num_users = json_array_size(users);
    for (int i = 0; i < num_users; i += 10) {
        // Process a batch of 10 users at a time
        json_t* user_batch = json_array_get(users, i, i + 9);
        if (user_batch == NULL) {
            fprintf(stderr, "Failed to get user batch from JSON response\n");
            exit(1);
