            int frequency_band = json_object_get_int(user, "frequency_band");
            char* downlink_channel = json_string_value(json_object_get(user, "downlink_channel"));
            add_channel(contexts, num_contexts, ci, frequency_band, downlink_channel);
        }
    }

    // Clean up the CURL handle and JSON parser
    curl_easy_cleanup(curl);
    json_decref(root);
}

