    float humidity_threshold;
    char* environment_settings;
} EnvironmentSettings;

// Define the function to process sensor data and update settings
void process_sensor_data_and_update_settings(int N, int seed, int max_size, EnvironmentSettings* env_settings) {
    // Initialize a dynamic list of sensor readings
    SensorReading* readings = (SensorReading*)malloc(sizeof(SensorReading) * max_size);
    if (!readings) {
        printf("Error: Failed to allocate memory for sensor readings\n");
        return;
    }

    // Initialize a mutex for synchronizing access to the list of readings
    pthread_mutex_t readings_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Populate the list of sensor readings based on input parameters
    for (int i = 0; i < N; i++) {
        SensorReading reading = {i, time(NULL), "Unknown", 0.0f, 0.0f, true};
        pthread_mutex_lock(&readings_mutex);
        readings[i] = reading;
        pthread_mutex_unlock(&readings_mutex);
    }

    // Calculate the average temperature and humidity across all readings
    float avg_temperature = 0.0f;
    float avg_humidity = 0.0f;
    for (int i = 0; i < N; i++) {
        avg_temperature += readings[i].temperature;
        avg_humidity += readings[i].humidity;
    }
    avg_temperature /= N;
    avg_humidity /= N;

    // Categorize the data into predefined ranges based on specified thresholds
    int num_ranges = 0;
    for (int i = 0; i < N; i++) {
        if (readings[i].temperature > env_settings->temperature_threshold) {
            readings[i].operational = false;
        } else if (readings[i].humidity > env_settings->humidity_threshold) {
            readings[i].operational = false;
        }
    }

    // Update the environmental settings based on the categorized data
    for (int i = 0; i < N; i++) {
        if (!readings[i].operational) {
            env_settings->environment_settings = "Malfunctioning";
            break;
        }
    }

    // Attempt to update the environmental control parameters in a remote server via HTTP POST requests
    bool success = true;
    if (success) {
        printf("Success: Updated environmental settings\n");
    } else {
        printf("Error: Failed to update environmental settings\n");
    }

    // Clean up the memory allocated for the list of readings and mutex
    free(readings);
    pthread_mutex_destroy(&readings_mutex);

    return;
}
