void populateTCPHeaderArray(int N, int seed) {
    struct TCP_HEADER *tcpArray = malloc(N * sizeof(struct TCP_HEADER));
    if (tcpArray == NULL) {
        fprintf(stderr, "Failed to allocate memory for TCP header array\n");
        return;
    }

    srand(seed); // Initialize random number generator with seed value

    for (int i = 0; i < N; i++) {
        tcpArray[i].SOURCE_PORT = rand() % 65536; // Generate random source port
        tcpArray[i].DESTINATION_PORT = rand() % 65536; // Generate random destination port
