        perror("Failed to allocate memory for TCP session pool");
        exit(1);
    }

    // Initialize the metadata for each TCP connection object
    for (int i = 0; i < MAX_NUM_CONNECTIONS; i++) {
        tcp_sessions[i].session_id = -1;
        tcp_sessions[i].state = INIT;
    }
}

// Add a new TCP connection object to the pool
void add_tcp_connection(int session_id, char *client_ip, char *server_ip) {
    // Acquire the mutex for protecting concurrent access to the pool
    pthread_mutex_lock(&tcp_session_pool_mutex);

    // Find an available slot in the pool for the new TCP connection object
    int i;
    for (i = 0; i < MAX_NUM_CONNECTIONS; i++) {
        if (tcp_sessions[i].state == INIT) {
            break;
        }
    }

    // If no available slot is found, return an error
    if (i >= MAX_NUM_CONNECTIONS) {
        perror("Failed to add TCP connection object: pool is full");
        pthread_mutex_unlock(&tcp_session_pool_mutex);
        return;
    }

    // Initialize the metadata for the new TCP connection object
    tcp_sessions[i].session_id = session_id;
    strcpy(tcp_sessions[i].client_ip, client_ip);
    strcpy(tcp_sessions[i].server_ip, server_ip);
    tcp_sessions[i].state = ESTABLISHED;

    // Increment the number of active connections in the pool
    num_active_connections++;

    // Release the mutex for protecting concurrent access to the pool
    pthread_mutex_unlock(&tcp_session_pool_mutex);
}

// Remove a TCP connection object from the pool
void remove_tcp_connection(int session_id) {
    // Acquire the mutex for protecting concurrent access to the pool
    pthread_mutex_lock(&tcp_session_pool_mutex);

    // Find the slot in the pool corresponding to the specified session ID
    int i;
    for (i = 0; i < MAX_NUM_CONNECTIONS; i++) {
        if (tcp_sessions[i].session_id == session_id) {
            break;
        }
    }

    // If the specified session ID is not found, return an error
    if (i >= MAX_NUM_CONNECTIONS) {
        perror("Failed to remove TCP connection object: session ID not found");
        pthread_mutex_unlock(&tcp_session_pool_mutex);
        return;
    }

    // Set the state of the TCP connection object to CLOSED
    tcp_sessions[i].state = CLOSED;

    // Decrement the number of active connections in the pool
    num_active_connections--;

    // Release the mutex for protecting concurrent access to the pool
    pthread_mutex_unlock(&tcp_session_pool_mutex);
}

// Get the metadata for a TCP connection object from the pool
TCP_SESSION_PDU_T *get_tcp_connection(int session_id) {
    // Acquire the mutex for protecting concurrent access to the pool
    pthread_mutex_lock(&tcp_session_pool_mutex);

    // Find the slot in the pool corresponding to the specified session ID
    int i;
    for (i = 0; i < MAX_NUM_CONNECTIONS; i++) {
        if (tcp_sessions[i].session_id == session_id) {
            break;
        }
    }

    // If the specified session ID is not found, return NULL
    if (i >= MAX_NUM_CONNECTIONS) {
        perror("Failed to get TCP connection object: session ID not found");
        pthread_mutex_unlock(&tcp_session_pool_mutex);
        return NULL;
    }

    // Return a pointer to the metadata for the specified TCP connection object
    TCP_SESSION_PDU_T *pdu = &tcp_sessions[i];

    // Release the mutex for protecting concurrent access to the pool
    pthread_mutex_unlock(&tcp_session_pool_mutex);

    return pdu;
}

// Handle a potential network failure by closing the TCP connection object and removing it from the pool
void handle_network_failure(int session_id) {
    // Acquire the mutex for protecting concurrent access to the pool
    pthread_mutex_lock(&tcp_session_pool_mutex);

    // Find the slot in the pool corresponding to the specified session ID
    int i;
    for (i = 0; i < MAX_NUM_CONNECTIONS; i++) {
        if (tcp_sessions[i].session_id == session_id) {
            break;
        }
    }

    // If the specified session ID is not found, return an error
    if (i >= MAX_NUM_CONNECTIONS) {
        perror("Failed to handle network failure: session ID not found");
        pthread_mutex_unlock(&tcp_session_pool_mutex);
        return;
    }

    // Close the TCP connection object and set its state to CLOSED
    close(tcp_sessions[i].fd);
    tcp_sessions[i].state = CLOSED;

    // Decrement the number of active connections in the pool
    num_active_connections--;

    // Release the mutex for protecting concurrent access to the pool
    pthread_mutex_unlock(&tcp_session_pool_mutex);
}
