// Define the function to initialize the pool of TCP connections
void init_tcp_connection_pool(TCP_SESSION_POOL_T *pool) {
    // Initialize the number of sessions in the pool to 0
    pool->num_sessions = 0;

    // Allocate memory for the list of sessions
    pool->sessions = (TCP_SESSION_PDU_T *)malloc(sizeof(TCP_SESSION_PDU_T) * MAX_NUM_SESSIONS);

    // Initialize each session in the pool to an empty state
    for (int i = 0; i < MAX_NUM_SESSIONS; i++) {
        pool->sessions[i].session_id = -1;
        pool->sessions[i].state = TCP_SESSION_STATE_INIT;
    }
}

// Define the function to allocate a new session in the pool
int alloc_tcp_connection(TCP_SESSION_POOL_T *pool) {
    // If there are no available sessions, return -1
    if (pool->num_sessions == MAX_NUM_SESSIONS) {
        return -1;
    }

    // Find the first available session in the pool and allocate it to a new connection
    for (int i = 0; i < MAX_NUM_SESSIONS; i++) {
        if (pool->sessions[i].session_id == -1) {
            pool->num_sessions++;
            return i;
        }
    }

    // If no available sessions were found, return -1
    return -1;
}

// Define the function to release a session in the pool
void free_tcp_connection(TCP_SESSION_POOL_T *pool, int session_id) {
    // If the session ID is invalid or there are no available sessions, do nothing
    if (session_id < 0 || pool->num_sessions == 0) {
        return;
    }

    // Find the session in the pool and mark it as free
    for (int i = 0; i < MAX_NUM_SESSIONS; i++) {
        if (pool->sessions[i].session_id == session_id) {
            pool->num_sessions--;
            pool->sessions[i].session_id = -1;
            return;
        }
    }
}

