void handle_new_connection(TCP_SESSION_POOL_T *pool, int client_fd) {
    // Allocate a new session in the pool for the new connection
    int session_id = alloc_tcp_connection(pool);

    // If there are no available sessions, close the connection and return
    if (session_id < 0) {
