#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>

// Define the maximum number of identifiers that can be stored in the pool
#define MAX_IDENTIFIERS 50000

// Define the maximum size of each identifier string
#define IDENTIFIER_SIZE 256

// Define the maximum number of transactions that can be stored in the pool
#define MAX_TRANSACTIONS 100000

// Define the maximum amount of memory that can be used by the pool
#define MAX_MEMORY 2097152

// Define the frequency and threshold for garbage collection
#define GC_FREQUENCY 60 // seconds
#define GC_THRESHOLD 0.1 // percentage of unused identifiers

// Define the structure to store a transaction record
typedef struct {
    int id;
    long timestamp;
    char account[IDENTIFIER_SIZE];
    double amount;
    bool status;
} transaction_record;

// Define the structure to store an identifier in the pool
typedef struct {
    char identifier[IDENTIFIER_SIZE];
    int count; // number of transactions using this identifier
} identifier_record;

// Define the global variables for the pool
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static bool initialized = false;
static int num_identifiers = 0;
static int num_transactions = 0;
static identifier_record *identifiers = NULL;
static transaction_record *transactions = NULL;

// Define the function to initialize the pool
void init_pool() {
    // Allocate memory for the identifiers and transactions arrays
    identifiers = (identifier_record *)malloc(MAX_IDENTIFIERS * sizeof(identifier_record));
    transactions = (transaction_record *)malloc(MAX_TRANSACTIONS * sizeof(transaction_record));

    // Initialize the identifiers array with empty strings and a count of 0
    for (int i = 0; i < MAX_IDENTIFIERS; i++) {
        strcpy(identifiers[i].identifier, "");
        identifiers[i].count = 0;
    }

    // Initialize the transactions array with empty records and a status of false
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        transactions[i].id = -1;
        transactions[i].timestamp = 0;
        strcpy(transactions[i].account, "");
        transactions[i].amount = 0.0;
        transactions[i].status = false;
    }

    // Set the number of identifiers and transactions to 0
    num_identifiers = 0;
    num_transactions = 0;

    // Set the initialized flag to true
    initialized = true;
}

// Define the function to add a transaction to the pool
void add_transaction(int id, long timestamp, char *account, double amount, bool status) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&lock);

    // Check if the pool is initialized
    if (!initialized) {
        init_pool();
    }

    // Check if the transaction is already in the pool
    for (int i = 0; i < num_transactions; i++) {
        if (transactions[i].id == id) {
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // Check if the transaction is valid
    if (id < 0 || timestamp <= 0 || account == NULL || amount <= 0.0) {
        pthread_mutex_unlock(&lock);
        return;
    }

    // Add the transaction to the pool
    transactions[num_transactions].id = id;
    transactions[num_transactions].timestamp = timestamp;
    strcpy(transactions[num_transactions].account, account);
    transactions[num_transactions].amount = amount;
    transactions[num_transactions].status = status;
    num_transactions++;

    // Update the identifier count for the transaction's account
    for (int i = 0; i < num_identifiers; i++) {
        if (strcmp(identifiers[i].identifier, account) == 0) {
            identifiers[i].count++;
            break;
        }
    }

    // Release the lock on the pool
    pthread_mutex_unlock(&lock);
}

// Define the function to remove a transaction from the pool
void remove_transaction(int id) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&lock);

    // Check if the pool is initialized
    if (!initialized) {
        init_pool();
    }

    // Find the transaction in the pool and remove it
    for (int i = 0; i < num_transactions; i++) {
        if (transactions[i].id == id) {
            // Remove the transaction from the pool
            transactions[i] = transactions[num_transactions - 1];
            num_transactions--;

            // Update the identifier count for the transaction's account
            for (int j = 0; j < num_identifiers; j++) {
                if (strcmp(identifiers[j].identifier, transactions[i].account) == 0) {
                    identifiers[j].count--;
                    break;
                }
            }
        }
    }

    // Release the lock on the pool
    pthread_mutex_unlock(&lock);
}

// Define the function to get a transaction from the pool by ID
transaction_record *get_transaction(int id) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&lock);

    // Check if the pool is initialized
    if (!initialized) {
        init_pool();
    }

    // Find the transaction in the pool and return it
    for (int i = 0; i < num_transactions; i++) {
        if (transactions[i].id == id) {
            pthread_mutex_unlock(&lock);
            return &transactions[i];
        }
    }

    // Release the lock on the pool
    pthread_mutex_unlock(&lock);

    // Return NULL if the transaction is not found
    return NULL;
}

// Define the function to get a list of transactions from the pool by account ID
transaction_record **get_transactions(char *account) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&lock);

    // Check if the pool is initialized
    if (!initialized) {
        init_pool();
    }

    // Find the account in the pool and return its transactions
    for (int i = 0; i < num_identifiers; i++) {
        if (strcmp(identifiers[i].identifier, account) == 0) {
            transaction_record **transactions = malloc(identifiers[i].count * sizeof(transaction_record));
            int count = 0;
            for (int j = 0; j < num_transactions; j++) {
                if (strcmp(transactions[j].account, account) == 0) {
                    transactions[count] = &transactions[j];
                    count++;
                }
            }
            pthread_mutex_unlock(&lock);
            return transactions;
        }
    }

    // Release the lock on the pool
    pthread_mutex_unlock(&lock);

    // Return NULL if the account is not found
    return NULL;
}

// Define the function to update an identifier in the pool
void update_identifier(char *old_identifier, char *new_identifier) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&lock);

    // Check if the pool is initialized
    if (!initialized) {
        init_pool();
    }

    // Find the old identifier in the pool and update it
    for (int i = 0; i < num_identifiers; i++) {
        if (strcmp(identifiers[i].identifier, old_identifier) == 0) {
            strcpy(identifiers[i].identifier, new_identifier);
            break;
        }
    }

    // Release the lock on the pool
    pthread_mutex_unlock(&lock);
}

// Define the function to remove an identifier from the pool
void remove_identifier(char *identifier) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&lock);

    // Check if the pool is initialized
    if (!initialized) {
        init_pool();
    }

    // Find the identifier in the pool and remove it
    for (int i = 0; i < num_identifiers; i++) {
        if (strcmp(identifiers[i].identifier, identifier) == 0) {
            identifiers[i] = identifiers[num_identifiers - 1];
            num_identifiers--;
            break;
        }
    }

    // Release the lock on the pool
    pthread_mutex_unlock(&lock);
}

// Define the function to add an identifier to the pool
void add_identifier(char *identifier) {
    // Acquire the lock on the pool
    pthread_mutex_lock(&lock);

    // Check if the pool is initialized
    if (!initialized) {
        init_pool();
    }

    // Check if the identifier is already in the pool
    for (int i = 0; i < num_identifiers; i++) {
        if (strcmp(identifiers[i].identifier, identifier) == 0) {
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // Add the identifier to the pool
    strcpy(identifiers[num_identifiers].identifier, identifier);
    num_identifiers++;

    // Release the lock on the pool
    pthread_mutex_unlock(&lock);
}

// Define the function to garbage collect unused identifiers in the pool
void gc_identifiers() {
    // Acquire the lock on the pool
    pthread_mutex_lock(&lock);

    // Check if the pool is initialized
    if (!initialized) {
        init_pool();
    }

    // Calculate the number of unused identifiers
    int num_unused = 0;
    for (int i = 0; i < num_identifiers; i++) {
        if (identifiers[i].count == 0) {
            num_unused++;
        }
    }

    // Check if the number of unused identifiers exceeds the threshold
    if (num_unused / num_identifiers >= GC_THRESHOLD) {
        // Sort the identifiers by count in descending order
        qsort(identifiers, num_identifiers, sizeof(identifier_record), compare_count);

        // Remove the unused identifiers from the pool
        for (int i = 0; i < num_unused; i++) {
            remove_identifier(identifiers[i].identifier);
        }
    }

    // Release the lock on the pool
    pthread_mutex_unlock(&lock);
}

// Define the function to compare two identifier records by count
int compare_count(const void *a, const void *b) {
    return ((identifier_record *)a)->count - ((identifier_record *)b)->count;
}

// Define the function to periodically garbage collect unused identifiers in the pool
void gc_thread() {
    while (true) {
        // Sleep for a specified amount of time before garbage collecting
        sleep(GC_FREQUENCY);

        // Garbage collect the identifiers in the pool
        gc_identifiers();
    }
}
