    checksum_info.current_hash_algorithm = MD5;

    // Initialize the logging information
    LOGGING_INFO_T logging_info;
    logging_info.log_file_path = "file_io_log.txt";
    logging_info.log_verbosity_level = 2;

    // Add file I/O tasks to the pool and process them
    FILE_IO_TASK_T task1, task2, task3;
    task1.task_id = 1;
    task1.file_path = "example_file1.txt";
    task1.read_mode = true;
    add_file_io_task(&task1, &pool);
    task2.task_id = 2;
    task2.file_path = "example_file2.txt";
    task2.read_mode = false;
    add_file_io_task(&task2, &pool);
    task3.task_id = 3;
    task3.file_path = "example_file3.txt";
    task3.read_mode = true;
    add_file_io_task(&task3, &pool);
    process_file_io_tasks(&pool);

    // Generate the checksum for the file and log the event
    generate_checksum(&checksum_info);
    log_file_io_event(&logging_info, &task1, EVENT_TYPE_CHECKSUM_GENERATED);

    // Destroy the worker thread pool and I/O scheduling policy
    destroy_worker_thread_pool(&pool);
    return 0;
}

// Define the function to initialize the worker thread pool
void initialize_worker_thread_pool(WORKER_THREAD_POOL_T* pool) {
    // Allocate memory for the thread pool and task queue
    pool->num_threads = 4;
    pool->task_queue_size = 10;
    pool->thread_pool = (pthread_t*) malloc(sizeof(pthread_t) * pool->num_threads);
    pool->task_queue = (FILE_IO_TASK_T*) malloc(sizeof(FILE_IO_TASK_T) * pool->task_queue_size);

    // Initialize the task queue and thread pool
    for (int i = 0; i < pool->num_threads; i++) {
        pthread_create(&pool->thread_pool[i], NULL, process_file_io_tasks, pool);
    }
}

// Define the function to destroy the worker thread pool
void destroy_worker_thread_pool(WORKER_THREAD_POOL_T* pool) {
    // Join all threads in the thread pool and free memory
    for (int i = 0; i < pool->num_threads; i++) {
        pthread_join(pool->thread_pool[i], NULL);
    }
    free(pool->task_queue);
    free(pool->thread_pool);
}

// Define the function to add a file I/O task to the pool
void add_file_io_task(FILE_IO_TASK_T* task, WORKER_THREAD_POOL_T* pool) {
    // Check if the task queue is full and resize it if necessary
    if (pool->task_queue_size == pool->num_tasks) {
        pool->task_queue_size *= 2;
        pool->task_queue = (FILE_IO_TASK_T*) realloc(pool->task_queue, sizeof(FILE_IO_TASK_T) * pool->task_queue_size);
    }

    // Add the task to the queue and update the number of tasks
    pool->task_queue[pool->num_tasks++] = *task;
}

// Define the function to remove a file I/O task from the pool
void remove_file_io_task(int task_id, WORKER_THREAD_POOL_T* pool) {
    // Find the index of the task in the queue and remove it
    for (int i = 0; i < pool->num_tasks; i++) {
        if (pool->task_queue[i].task_id == task_id) {
            pool->num_tasks--;
            memmove(&pool->task_queue[i], &pool->task_queue[i + 1], sizeof(FILE_IO_TASK_T) * (pool->num_tasks - i));
            break;
        }
    }
}

// Define the function to process file I/O tasks in the pool
void* process_file_io_tasks(WORKER_THREAD_POOL_T* pool) {
    // Loop until all tasks are completed or the thread is interrupted
    while (true) {
        // Check if there are any pending tasks and process them
        for (int i = 0; i < pool->num_tasks; i++) {
            FILE_IO_TASK_T* task = &pool->task_queue[i];
            switch (task->current_state) {
                case INIT:
                    // Open the file and update the state
                    int fd = open(task->file_path, task->read_mode ? O_RDONLY : O_WRONLY);
                    if (fd == -1) {
                        handle_file_io_error(errno, task, pool);
                        break;
                    }
                    update_task_state(task, RUNNING);
                case RUNNING:
                    // Read or write the file and update the state
                    if (task->read_mode) {
                        char buffer[1024];
                        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
                        if (bytes_read == -1) {
                            handle_file_io_error(errno, task, pool);
                            break;
                        }
                    } else {
                        char buffer[1024];
                        ssize_t bytes_written = write(fd, buffer, sizeof(buffer));
                        if (bytes_written == -1) {
                            handle_file_io_error(errno, task, pool);
                            break;
                        }
                    }
                    update_task_state(task, COMPLETE);
                case COMPLETE:
                    // Close the file and remove the task from the queue
                    close(fd);
                    remove_file_io_task(task->task_id, pool);
            }
        }

        // Sleep for a short period of time to avoid busy-waiting
        usleep(1000);
    }
}

// Define the function to handle file I/O errors
void handle_file_io_error(int error_code, FILE_IO_TASK_T* task, WORKER_THREAD_POOL_T* pool) {
    // Log the error and update the state of the task
    log_file_io_event(&logging_info, task, EVENT_TYPE_FILE_IO_ERROR);
    update_task_state(task, INIT);
}

// Define the function to update the state of a file I/O task
void update_task_state(FILE_IO_TASK_T* task, enum state new_state) {
    // Update the state of the task and log the event
    task->current_state = new_state;
    log_file_io_event(&logging_info, task, EVENT_TYPE_STATE_UPDATED);
}

// Define the function to generate a checksum for a file
void generate_checksum(CHECKSUM_GENERATION_INFO_T* info) {
    // Open the file and read its contents
    int fd = open(info->file_path, O_RDONLY);
    if (fd == -1) {
        handle_file_io_error(errno, task, pool);
        return;
    }
    char buffer[1024];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
    if (bytes_read == -1) {
        handle_file_io_error(errno, task, pool);
        return;
    }

    // Generate the checksum using the specified hash algorithm
    switch (info->current_hash_algorithm) {
        case MD5:
            unsigned char md5[MD5_DIGEST_LENGTH];
            MD5(buffer, bytes_read, md5);
            printf("Checksum for %s is %s\n", info->file_path, md5);
            break;
        case SHA256:
            unsigned char sha256[SHA256_DIGEST_LENGTH];
            SHA256(buffer, bytes_read, sha256);
            printf("Checksum for %s is %s\n", info->file_path, sha256);
            break;
        case SHA384:
            unsigned char sha384[SHA384_DIGEST_LENGTH];
            SHA384(buffer, bytes_read, sha384);
            printf("Checksum for %s is %s\n", info->file_path, sha384);
            break;
        case SHA512:
            unsigned char sha512[SHA512_DIGEST_LENGTH];
            SHA512(buffer, bytes_read, sha512);
            printf("Checksum for %s is %s\n", info->file_path, sha512);
            break;
    }

    // Close the file and return
    close(fd);
}

// Define the function to log a file I/O event
void log_file_io_event(LOGGING_INFO_T* logging_info, FILE_IO_TASK_T* task, enum event_type event_type) {
    // Open the log file and write the event information
    int fd = open(logging_info->log_file_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        printf("Error opening log file: %s\n", strerror(errno));
        return;
    }
    char* event_string = NULL;
    switch (event_type) {
        case EVENT_TYPE_FILE_IO_ERROR:
            asprintf(&event_string, "File I/O error for task %d: %s\n", task->task_id, strerror(errno));
            break;
        case EVENT_TYPE_STATE_UPDATED:
            asprintf(&event_string, "Task %d state updated to %s\n", task->task_id, get_state_string(task->current_state));
            break;
    }
    write(fd, event_string, strlen(event_string));
    close(fd);
}

// Define the function to get a string representation of a file I/O task state
char* get_state_string(enum state state) {
    switch (state) {
        case INIT: return "INIT";
        case RUNNING: return "RUNNING";
        case COMPLETE: return "COMPLETE";
    }
