    task->current_state = RUNNING;
    pthread_create(&pool->threads[thread_id], NULL, &run_file_io_task, task);
}

// Function to release resources for a completed task
void release_resources(RESOURCE_POOL_T* pool, FILE_IO_TASK_T* task) {
    // Find the thread that is running the task and set its state to DONE
