void crc_indication_list_init(CRC_INDICATION_LIST *list) {
    list->count = 0;
    list->elements = NULL;
}

void crc_indication_list_add(CRC_INDICATION_LIST *list, uint16_t RX_UE_INFORMATION_TAG, uint32_t RNTI, uint8_t CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (element == NULL) {
        // handle memory allocation failure
        return;
    }
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    element->CRCFLAG = CRCFLAG;
    list->elements = realloc(list->elements, (list->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->elements == NULL) {
        // handle memory allocation failure
        free(element);
        return;
    }
    list->elements[list->count++] = *element;
}

void crc_indication_list_remove(CRC_INDICATION_LIST *list, uint32_t RNTI) {
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (list->elements[i].RNTI == RNTI) {
            break;
        }
    }
    if (i == list->count) {
        // element not found
        return;
    }
    memmove(&list->elements[i], &list->elements[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count--;
}

void crc_indication_list_get(CRC_INDICATION_LIST *list, size_t index, NFAPI_CRC_INDICATION_PDU_T **element) {
    if (index >= list->count) {
        // element not found
        return;
    }
    *element = &list->elements[index];
}

void crc_indication_list_destroy(CRC_INDICATION_LIST *list) {
    free(list->elements);
    list->count = 0;
    list->elements = NULL;
}
