    struct node *next;
} lte_ue_context_list_t;

// Function to add a new context to the list
void add_context(lte_ue_context_list_t **head, uint64_t ue_identity, uint32_t s_tmsi) {
    lte_ue_context_t *new_context = malloc(sizeof(lte_ue_context_t));
    if (new_context == NULL) {
        // Handle memory allocation failure
        return;
    }
    new_context->ue_identity = ue_identity;
    new_context->s_tmsi = s_tmsi;
    new_context->rrc_connection_state = false;
    pthread_mutex_init(&new_context->mutex, NULL);
    // Add the new context to the list
    lte_ue_context_list_t *node = malloc(sizeof(lte_ue_context_list_t));
    if (node == NULL) {
        free(new_context);
        // Handle memory allocation failure
        return;
    }
    node->context = new_context;
    node->next = *head;
    *head = node;
}

// Function to remove a context from the list by S-TMSI
void remove_context(lte_ue_context_list_t **head, uint32_t s_tmsi) {
    lte_ue_context_list_t *node = *head;
    while (node != NULL && node->context->s_tmsi != s_tmsi) {
        node = node->next;
    }
    if (node == NULL) {
        // Handle context not found
        return;
    }
    lte_ue_context_list_t *prev = NULL;
    while (node != NULL && node->context->s_tmsi == s_tmsi) {
        prev = node;
        node = node->next;
    }
    if (prev == NULL) {
        // Handle context not found
        return;
    }
    pthread_mutex_destroy(&node->context->mutex);
    free(node->context);
    prev->next = node->next;
}

// Function to update the PDN connections of a context
void update_pdns(lte_ue_context_list_t *head, uint64_t ue_identity, struct {
        char *apn;
        char *ip_address;
    } active_pdns[MAX_PDNS]) {
    lte_ue_context_list_t *node = head;
    while (node != NULL && node->context->ue_identity != ue_identity) {
        node = node->next;
    }
    if (node == NULL) {
        // Handle context not found
        return;
    }
    for (int i = 0; i < MAX_PDNS; i++) {
        if (active_pdns[i].apn != NULL && active_pdns[i].ip_address != NULL) {
            node->context->active_pdns[i].apn = strdup(active_pdns[i].apn);
            node->context->active_pdns[i].ip_address = strdup(active_pdns[i].ip_address);
        } else {
            break;
        }
    }
}

// Function to retrieve a context from the list by index or UE Identity
lte_ue_context_t *get_context(lte_ue_context_list_t *head, uint64_t ue_identity) {
    lte_ue_context_list_t *node = head;
    while (node != NULL && node->context->ue_identity != ue_identity) {
        node = node->next;
    }
    if (node == NULL) {
        // Handle context not found
        return NULL;
    }
    return node->context;
}
