// Define a struct to represent a TCP connection record
typedef struct {
    int conn_id;
    char remote_ip[16];
    char local_ip[16];
    enum tcp_state_enum state;
} tcp_connection_record_t;

// Define an array to store the TCP connection records
static tcp_connection_record_t *tcp_connections = NULL;

// Define a mutex to protect the array from concurrent access
static pthread_mutex_t tcp_connections_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new TCP connection record
int add_tcp_connection(const char *remote_ip, const char *local_ip) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&tcp_connections_mutex);

    // Allocate memory for a new TCP connection record
    tcp_connection_record_t *new_conn = malloc(sizeof(tcp_connection_record_t));
    if (!new_conn) {
        pthread_mutex_unlock(&tcp_connections_mutex);
        return -1; // Error: memory allocation failed
    }

    // Initialize the new TCP connection record
    new_conn->conn_id = 0;
    strcpy(new_conn->remote_ip, remote_ip);
    strcpy(new_conn->local_ip, local_ip);
    new_conn->state = SYN_RECEIVED; // Randomly set the SYN_RECEIVED flag

    // Add the new TCP connection record to the array
    tcp_connections = realloc(tcp_connections, (num_conns + 1) * sizeof(tcp_connection_record_t));
    if (!tcp_connections) {
        pthread_mutex_unlock(&tcp_connections_mutex);
        return -1; // Error: memory allocation failed
    }
    tcp_connections[num_conns++] = new_conn;

    // Release the mutex and return success
    pthread_mutex_unlock(&tcp_connections_mutex);
    return 0;
}

// Function to close a TCP connection by connection ID
int close_tcp_connection(int conn_id) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&tcp_connections_mutex);

    // Find the index of the TCP connection record with the given connection ID
    int i;
    for (i = 0; i < num_conns; i++) {
        if (tcp_connections[i]->conn_id == conn_id) {
            break;
        }
    }

    // If the TCP connection record was not found, return an error
    if (i == num_conns) {
        pthread_mutex_unlock(&tcp_connections_mutex);
        return -1; // Error: connection ID not found
    }

    // Free the memory allocated for the TCP connection record
    free(tcp_connections[i]);

    // Shift all subsequent TCP connection records down one index
    for (int j = i; j < num_conns - 1; j++) {
        tcp_connections[j] = tcp_connections[j + 1];
    }

    // Decrement the number of TCP connections and release the mutex
    num_conns--;
    pthread_mutex_unlock(&tcp_connections_mutex);
    return 0;
}

// Function to retrieve a TCP connection by index
int get_tcp_connection(int index) {
    // Acquire the mutex to prevent concurrent access
    pthread_mutex_lock(&tcp_connections_mutex);

    // If the index is out of range, return an error
    if (index < 0 || index >= num_conns) {
        pthread_mutex_unlock(&tcp_connections_mutex);
        return -1; // Error: index out of range
    }

    // Return the TCP connection record at the given index
    tcp_connection_record_t *conn = tcp_connections[index];
    pthread_mutex_unlock(&tcp_connections_mutex);
    return conn;
}
```
