    fwrite(&state->direction, sizeof(double), 1, file);
}

void deserialize_vector_states(FILE* file, vector_state_t* state) {
    fread(&state->magnitude, sizeof(double), 1, file);
    fread(&state->direction, sizeof(double), 1, file);
}

