// Define the function to calculate the MD5 hash of a large file given its path
void calculate_md5(char* file_path) {
    // Open the file for reading
    FILE* file = fopen(file_path, "r");
    if (file == NULL) {
        perror("Error opening file");
        exit(1);
    }

    // Allocate memory for the buffer and read the file in chunks
    size_t buffer_size = 4096;
    char* buffer = (char*) allocate_memory(buffer_size);
    while (!feof(file)) {
        fread(buffer, sizeof(char), buffer_size, file);
        // Calculate the MD5 hash of the buffer and print it to stdout
        printf("%s\n", md5(buffer));
    }

    // Clean up resources
    free_memory(buffer);
    fclose(file);
}

// Define the function to monitor and report CPU and memory usage during execution
void monitor_usage() {
    // Get the current time in milliseconds
    long current_time = (long) time(NULL) * 1000;

    // Calculate the elapsed time since the last update
    long elapsed_time = current_time - previous_time;

    // Print the CPU and memory usage to stdout
    printf("CPU Usage: %.2f%%\n", (float) cpu_usage / 100);
    printf("Memory Usage: %d MB\n", (int) memory_usage / 1024);

    // Update the previous time and reset the CPU and memory usage counters
    previous_time = current_time;
    cpu_usage = 0;
