#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdio.h>

// Define a structure to represent a network device instance
typedef struct {
    char mac_address[18]; // MAC address of the device
    char ip_address[16]; // IP address of the device
    char subnet_mask[16]; // Subnet mask of the device
    char default_gateway[16]; // Default gateway of the device
    int num_interfaces; // Number of interfaces associated with the device
    struct interface *interfaces; // Array of interfaces associated with the device
} network_device;

// Define a structure to represent an interface instance
typedef struct {
    char name[16]; // Name of the interface
    int index; // Index of the interface
    int priority; // Priority level of the interface (lower values indicate higher priority)
} interface;

// Define a linked list data structure to store network device instances
typedef struct node {
    network_device *data;
    struct node *next;
} node;

// Define a hash table to map MAC addresses to network device instances
typedef struct {
    int size; // Size of the hash table
    node **buckets; // Array of buckets in the hash table
} mac_table;

// Define a linked list data structure to store interface instances
typedef struct {
    interface *data;
    struct node *next;
} interface_list;

// Define a hash table to map interface names to interface instances
typedef struct {
    int size; // Size of the hash table
    interface_list **buckets; // Array of buckets in the hash table
} interface_table;

// Define a structure to represent the device manager state
typedef struct {
    mac_table *mac_table; // Hash table mapping MAC addresses to network device instances
    interface_table *interface_table; // Hash table mapping interface names to interface instances
    int num_devices; // Number of active devices in the system
    pthread_mutex_t lock; // Mutex for protecting concurrent access to the device manager state
} device_manager;

// Define a function to add a new network device instance to the device manager
void add_device(network_device *device) {
    // Acquire the lock on the device manager state
    pthread_mutex_lock(&device_manager.lock);

    // Check if the MAC address of the device is already in use
    mac_table_entry = hash_lookup(device_manager.mac_table, device->mac_address);
    if (mac_table_entry != NULL) {
        // If the MAC address is already in use, update the existing network device instance
        network_device *existing_device = mac_table_entry->data;
        strcpy(existing_device->ip_address, device->ip_address);
        strcpy(existing_device->subnet_mask, device->subnet_mask);
        strcpy(existing_device->default_gateway, device->default_gateway);
        existing_device->num_interfaces = device->num_interfaces;
        for (int i = 0; i < existing_device->num_interfaces; i++) {
            interface *interface = &existing_device->interfaces[i];
            strcpy(interface->name, device->interfaces[i].name);
            interface->index = device->interfaces[i].index;
            interface->priority = device->interfaces[i].priority;
        }
    } else {
        // If the MAC address is not in use, add a new network device instance to the hash table
        mac_table_entry = hash_insert(device_manager.mac_table, device->mac_address);
        mac_table_entry->data = device;
    }

    // Release the lock on the device manager state
    pthread_mutex_unlock(&device_manager.lock);
}

// Define a function to remove a network device instance from the device manager by MAC address
void remove_device(char *mac_address) {
    // Acquire the lock on the device manager state
    pthread_mutex_lock(&device_manager.lock);

    // Look up the network device instance in the hash table using the MAC address
    mac_table_entry = hash_lookup(device_manager.mac_table, mac_address);
    if (mac_table_entry != NULL) {
        // If the network device instance is found, remove it from the hash table and decrement the number of active devices
        hash_remove(device_manager.mac_table, mac_table_entry);
        device_manager.num_devices--;
    }

    // Release the lock on the device manager state
    pthread_mutex_unlock(&device_manager.lock);
}

// Define a function to update the network interface configurations of a network device instance
void update_interfaces(network_device *device) {
    // Acquire the lock on the device manager state
    pthread_mutex_lock(&device_manager.lock);

    // Look up the network device instance in the hash table using the MAC address
    mac_table_entry = hash_lookup(device_manager.mac_table, device->mac_address);
    if (mac_table_entry != NULL) {
        // If the network device instance is found, update its interface configurations
        network_device *existing_device = mac_table_entry->data;
        existing_device->num_interfaces = device->num_interfaces;
        for (int i = 0; i < existing_device->num_interfaces; i++) {
            interface *interface = &existing_device->interfaces[i];
            strcpy(interface->name, device->interfaces[i].name);
            interface->index = device->interfaces[i].index;
            interface->priority = device->interfaces[i].priority;
        }
    }

    // Release the lock on the device manager state
    pthread_mutex_unlock(&device_manager.lock);
}

// Define a function to retrieve a network device instance by index or MAC address
network_device *get_device(int index, char *mac_address) {
    // Acquire the lock on the device manager state
    pthread_mutex_lock(&device_manager.lock);

    // Look up the network device instance in the hash table using the MAC address or index
    if (mac_address != NULL) {
        mac_table_entry = hash_lookup(device_manager.mac_table, mac_address);
        if (mac_table_entry != NULL) {
            // If the network device instance is found, return it
            network_device *device = mac_table_entry->data;
            pthread_mutex_unlock(&device_manager.lock);
            return device;
        }
    } else if (index >= 0 && index < device_manager.num_devices) {
        // If the MAC address is not specified, look up the network device instance by index
        node *current = device_manager.mac_table->buckets[index];
        while (current != NULL) {
            if (current->data->index == index) {
                // If the network device instance is found, return it
                network_device *device = current->data;
                pthread_mutex_unlock(&device_manager.lock);
                return device;
            }
            current = current->next;
        }
    }

    // If the network device instance is not found, return NULL
    pthread_mutex_unlock(&device_manager.lock);
    return NULL;
}

// Define a function to periodically clean up unused devices in the device manager
void cleanup_devices() {
    // Acquire the lock on the device manager state
    pthread_mutex_lock(&device_manager.lock);

    // Iterate over all network device instances in the hash table and remove any that are not marked as active
    for (int i = 0; i < device_manager.mac_table->size; i++) {
        node *current = device_manager.mac_table->buckets[i];
        while (current != NULL) {
            network_device *device = current->data;
            if (!device->active) {
                // If the network device instance is not marked as active, remove it from the hash table and decrement the number of active devices
                hash_remove(device_manager.mac_table, current);
                device_manager.num_devices--;
            }
            current = current->next;
        }
    }

    // Release the lock on the device manager state
    pthread_mutex_unlock(&device_manager.lock);
}

// Define a function to query the number of active devices by access technology
int get_num_active_devices(int access_technology) {
    // Acquire the lock on the device manager state
    pthread_mutex_lock(&device_manager.lock);

    // Iterate over all network device instances in the hash table and count the number of active devices by access technology
    int num_active_devices = 0;
    for (int i = 0; i < device_manager.mac_table->size; i++) {
        node *current = device_manager.mac_table->buckets[i];
        while (current != NULL) {
            network_device *device = current->data;
            if (device->active && device->access_technology == access_technology) {
                num_active_devices++;
            }
            current = current->next;
        }
    }

    // Release the lock on the device manager state
    pthread_mutex_unlock(&device_manager.lock);
    return num_active_devices;
}
