#define MAX_DNS_QUERIES 100 // maximum number of DNS queries per minute
#define QUERY_INTERVAL 60 // query interval in seconds

// structure to hold DNS query information
struct dns_query {
    char *hostname;
    struct sockaddr_in addr;
};

// function to perform DNS resolution
int dns_resolve(char *hostname, u_char *ip) {
    // create a new DNS query structure
    struct dns_query *query = malloc(sizeof(struct dns_query));
    if (!query) {
        return -1;
    }

    // initialize the DNS query structure
    query->hostname = hostname;
    memset(&query->addr, 0, sizeof(struct sockaddr_in));

    // perform DNS resolution using the standard library functions
    int status = getaddrinfo(hostname, NULL, NULL, &query->addr);
    if (status != 0) {
        free(query);
        return -1;
    }

    // convert the IP address to a string and store it in the output parameter
    char ip_str[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &query->addr.sin_addr, ip_str, INET_ADDRSTRLEN);
    strcpy((char *)ip, ip_str);

    // free the DNS query structure
    free(query);

    return 0;
}

// function to limit the capabilities of the process
void limit_capabilities() {
    // set the maximum number of DNS queries per minute
    struct rlimit rlim = { MAX_DNS_QUERIES, QUERY_INTERVAL };
    setrlimit(RLIMIT_NPROC, &rlim);
}

// function to handle errors and return an appropriate error code
int handle_error() {
    // log the error message for debugging and audit purposes
    perror("Error: ");

    // return an appropriate error code
    return -1;
}

// function to perform DNS resolution asynchronously
void *dns_resolve_async(void *args) {
    struct dns_query *query = (struct dns_query *)args;

    // perform DNS resolution using the standard library functions
    int status = getaddrinfo(query->hostname, NULL, NULL, &query->addr);
    if (status != 0) {
        handle_error();
    }

    // convert the IP address to a string and store it in the output parameter
    char ip_str[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &query->addr.sin_addr, ip_str, INET_ADDRSTRLEN);
    strcpy((char *)ip, ip_str);

    // free the DNS query structure
    free(query);

    return NULL;
}

// function to perform DNS resolution and log all attempts and results
void dns_resolve_log(char *hostname, u_char *ip) {
    // create a new DNS query structure
    struct dns_query *query = malloc(sizeof(struct dns_query));
    if (!query) {
        handle_error();
    }

    // initialize the DNS query structure
    query->hostname = hostname;
    memset(&query->addr, 0, sizeof(struct sockaddr_in));

    // perform DNS resolution using the standard library functions
    int status = getaddrinfo(hostname, NULL, NULL, &query->addr);
    if (status != 0) {
        handle_error();
    }

    // convert the IP address to a string and store it in the output parameter
    char ip_str[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &query->addr.sin_addr, ip_str, INET_ADDRSTRLEN);
    strcpy((char *)ip, ip_str);

    // log the DNS query attempt and result for debugging and audit purposes
    printf("DNS Query: %s\n", hostname);
    printf("DNS Result: %s\n", ip_str);

    // free the DNS query structure
    free(query);
}

// function to perform DNS resolution asynchronously and log all attempts and results
void *dns_resolve_async_log(void *args) {
    struct dns_query *query = (struct dns_query *)args;

    // perform DNS resolution using the standard library functions
    int status = getaddrinfo(query->hostname, NULL, NULL, &query->addr);
