void print_usage(char *progname) {
    printf("Usage: %s [options] <input files>\n", progname);
    printf("\t-i <filename>: Specify the input file.\n");
    printf("\t-o <filename>: Redirect the output to a specified file.\n");
    printf("\t-s: Print statistics about the input file, including the number of lines, words, and characters.\n");
    printf("\t-c: Print a condensed version of the file content with one line per word.\n");
    printf("\t--manpage: Display detailed usage information.\n");
    printf("\t-h: Display brief usage information.\n");
}

void print_statistics(struct input_file *input_file) {
    int lines = 0, words = 0, chars = 0;
    char c;
    while ((c = fgetc(input_file->fd)) != EOF) {
        if (c == '\n') {
            lines++;
        } else if (c != ' ') {
            words++;
        }
        chars++;
    }
    printf("File: %s\n", input_file->filename);
    printf("\tLines: %d\n", lines);
    printf("\tWords: %d\n", words);
    printf("\tCharacters: %d\n", chars);
}

void print_condensed(struct input_file *input_file, struct output_file *output_file) {
    char c;
    while ((c = fgetc(input_file->fd)) != EOF) {
        if (c == ' ') {
            continue;
        } else if (c == '\n') {
            fputc('\n', output_file->fd);
        } else {
            fputc(c, output_file->fd);
        }
    }
}

void *thread_func(void *data) {
    struct thread_data *td = (struct thread_data *)data;
    struct input_file *input_file = td->input_file;
    struct output_file *output_file = td->output_file;
    int thread_id = td->thread_id;
    char c;
    while ((c = fgetc(input_file->fd)) != EOF) {
        if (c == ' ') {
            continue;
        } else if (c == '\n') {
            fputc('\n', output_file->fd);
        } else {
            fputc(c, output_file->fd);
        }
    }
}

int main(int argc, char *argv[]) {
    struct input_file input_files[MAX_INPUT_FILES];
    struct output_file output_files[MAX_OUTPUT_FILES];
    int num_input_files = 0;
    int num_output_files = 0;
    int i, j;
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-i") == 0) {
            if (num_input_files >= MAX_INPUT_FILES) {
                printf("Too many input files specified\n");
                return 1;
            }
            input_files[num_input_files].filename = argv[++i];
            input_files[num_input_files].fd = open(argv[i], O_RDONLY);
            if (input_files[num_input_files].fd == -1) {
                printf("Error opening file %s\n", argv[i]);
                return 1;
            }
            num_input_files++;
        } else if (strcmp(argv[i], "-o") == 0) {
            if (num_output_files >= MAX_OUTPUT_FILES) {
                printf("Too many output files specified\n");
                return 1;
            }
            output_files[num_output_files].filename = argv[++i];
            output_files[num_output_files].fd = open(argv[i], O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
            if (output_files[num_output_files].fd == -1) {
                printf("Error opening file %s\n", argv[i]);
                return 1;
            }
            num_output_files++;
