        } else if (strcmp(argv[i], "-c") == 0) {
            for (j = 0; j < num_input_files; j++) {
                print_condensed(&input_files[j], &output_files[num_output_files - 1]);
            }
        } else if (strcmp(argv[i], "--manpage") == 0) {
            printf("Usage: %s [options] <input files>\n", argv[0]);
            printf("\t-i <filename>: Specify the input file.\n");
            printf("\t-o <filename>: Redirect the output to a specified file.\n");
            printf("\t-s: Print statistics about the input file, including the number of lines, words, and characters.\n");
            printf("\t-c: Print a condensed version of the file content with one line per word.\n");
            printf("\t--manpage: Display detailed usage information.\n");
            printf("\t-h: Display brief usage information.\n");
        } else if (strcmp(argv[i], "-h") == 0) {
            print_usage(argv[0]);
        } else {
            printf("Invalid option %s\n", argv[i]);
            return 1;
        }
    }
    if (num_input_files == 0) {
        print_usage(argv[0]);
        return 1;
