        td[i].input_file = &input_files[i];
        td[i].output_file = &output_files[num_output_files - 1];
        td[i].thread_id = i;
        pthread_create(&threads[i], NULL, thread_func, (void *)&td[i]);
    }
    for (i = 0; i < num_input_files; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
