// Define a structure to represent a network device instance
typedef struct {
    char mac_address[18]; // MAC address of the device
    char ip_address[16]; // IP address of the device
    char subnet_mask[16]; // Subnet mask of the device
    char default_gateway[16]; // Default gateway of the device
    int num_interfaces; // Number of interfaces associated with the device
    struct interface *interfaces; // Array of interfaces associated with the device
} network_device;

// Define a structure to represent an interface instance
typedef struct {
    char name[16]; // Name of the interface
    int index; // Index of the interface
    int type; // Type of the interface (e.g., Ethernet, Wi-Fi, Cellular)
} interface;

// Define a linked list data structure to store network device instances
typedef struct node {
    network_device *data;
    struct node *next;
} node;

// Global variables
node *head = NULL; // Head of the linked list
int num_devices = 0; // Number of devices in the linked list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety

// Function to add a new network device instance to the linked list
void add_device(network_device *dev) {
    pthread_mutex_lock(&mutex);
    node *new_node = malloc(sizeof(node));
    new_node->data = dev;
    new_node->next = head;
    head = new_node;
    num_devices++;
    pthread_mutex_unlock(&mutex);
}

// Function to remove a network device instance from the linked list by MAC address
void remove_device(char *mac_address) {
    pthread_mutex_lock(&mutex);
    node *curr = head;
    while (curr != NULL && strcmp(curr->data->mac_address, mac_address) != 0) {
        curr = curr->next;
    }
    if (curr == NULL) {
        pthread_mutex_unlock(&mutex);
        return; // Device not found
    }
    node *prev = head;
    while (prev->next != curr) {
        prev = prev->next;
    }
    prev->next = curr->next;
    free(curr);
    num_devices--;
    pthread_mutex_unlock(&mutex);
}

// Function to update the network interface configurations of a device instance
void update_device(char *mac_address, char *ip_address, char *subnet_mask, char *default_gateway) {
    pthread_mutex_lock(&mutex);
    node *curr = head;
    while (curr != NULL && strcmp(curr->data->mac_address, mac_address) != 0) {
        curr = curr->next;
    }
    if (curr == NULL) {
        pthread_mutex_unlock(&mutex);
        return; // Device not found
    }
    strcpy(curr->data->ip_address, ip_address);
    strcpy(curr->data->subnet_mask, subnet_mask);
    strcpy(curr->data->default_gateway, default_gateway);
    pthread_mutex_unlock(&mutex);
}

