    if (curr == NULL) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Device not found
    }
    network_device *dev = malloc(sizeof(network_device));
    memcpy(dev, curr->data, sizeof(network_device));
    pthread_mutex_unlock(&mutex);
