#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <pthread.h>
#include <errno.h>

#define MAX_HOSTNAME_LEN 256
#define MAX_IP_ADDR_LEN 16
#define DNS_PORT 53
#define DNS_TIMEOUT 5000 // in milliseconds
#define DNS_RETRY_COUNT 3
#define DNS_BACKOFF_STRATEGY "exponential"
#define DNS_CONNECTION_POOL_SIZE 10

typedef struct {
    char hostname[MAX_HOSTNAME_LEN];
    u_char ip_addr[MAX_IP_ADDR_LEN];
} dns_query;

typedef enum {
    DNS_SUCCESS,
    DNS_FAILURE,
    DNS_TIMEOUT,
    DNS_RETRY_LIMIT_EXCEEDED
} dns_result_status;

void *dns_resolver(void *args) {
    dns_query *query = (dns_query *) args;
    struct sockaddr_in server_addr;
    int socket_fd, bytes_received;
    char buffer[MAX_IP_ADDR_LEN];
    struct timeval timeout;
    fd_set read_fds;
    int retry_count = 0;

    // Initialize the DNS server address
    memset(&server_addr, 0, sizeof(struct sockaddr_in));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(DNS_PORT);
    inet_pton(AF_INET, "8.8.8.8", &server_addr.sin_addr);

    // Initialize the socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        perror("Failed to create socket");
        return NULL;
    }

    // Set the timeout for DNS queries
    timeout.tv_sec = DNS_TIMEOUT / 1000;
    timeout.tv_usec = (DNS_TIMEOUT % 1000) * 1000;

    // Initialize the connection pool
    pthread_mutex_t conn_pool_lock;
    pthread_cond_t conn_pool_cv;
    int conn_pool[DNS_CONNECTION_POOL_SIZE];
    for (int i = 0; i < DNS_CONNECTION_POOL_SIZE; i++) {
        conn_pool[i] = -1;
    }

    // Loop until the query is resolved or a retry limit is exceeded
    while (retry_count < DNS_RETRY_COUNT) {
        // Acquire a connection from the pool
        pthread_mutex_lock(&conn_pool_lock);
        while (conn_pool[0] == -1) {
            pthread_cond_wait(&conn_pool_cv, &conn_pool_lock);
        }
        int conn_fd = conn_pool[0];
        for (int i = 0; i < DNS_CONNECTION_POOL_SIZE - 1; i++) {
            conn_pool[i] = conn_pool[i + 1];
        }
        conn_pool[DNS_CONNECTION_POOL_SIZE - 1] = -1;
        pthread_mutex_unlock(&conn_pool_lock);

        // Send the DNS query over the socket
        sendto(socket_fd, query->hostname, strlen(query->hostname), 0, (struct sockaddr *) &server_addr, sizeof(struct sockaddr));

        // Receive the response from the server
        FD_ZERO(&read_fds);
        FD_SET(socket_fd, &read_fds);
        bytes_received = select(socket_fd + 1, &read_fds, NULL, NULL, &timeout);
        if (bytes_received > 0) {
            recvfrom(socket_fd, buffer, MAX_IP_ADDR_LEN, 0, NULL, NULL);
            break;
        } else if (bytes_received == 0) {
            // Timeout occurred
            retry_count++;
            pthread_mutex_lock(&conn_pool_lock);
            conn_pool[DNS_CONNECTION_POOL_SIZE - 1] = socket_fd;
            pthread_cond_signal(&conn_pool_cv);
            pthread_mutex_unlock(&conn_pool_lock);
            continue;
        } else {
            // Error occurred
            perror("Failed to receive DNS response");
            retry_count++;
            pthread_mutex_lock(&conn_pool_lock);
            conn_pool[DNS_CONNECTION_POOL_SIZE - 1] = socket_fd;
            pthread_cond_signal(&conn_pool_cv);
            pthread_mutex_unlock(&conn_pool_lock);
            continue;
        }
    }

    // Check if the query was resolved successfully
    if (retry_count >= DNS_RETRY_COUNT) {
        return NULL;
    } else {
        memcpy(query->ip_addr, buffer, MAX_IP_ADDR_LEN);
        return query->ip_addr;
    }
}

void dns_resolver_cleanup() {
    // Release the connection pool
    pthread_mutex_lock(&conn_pool_lock);
    for (int i = 0; i < DNS_CONNECTION_POOL_SIZE; i++) {
        if (conn_pool[i] != -1) {
            close(conn_pool[i]);
        }
    }
    pthread_mutex_unlock(&conn_pool_lock);
}
