#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <pthread.h>
#include <errno.h>
#include <time.h>
#include <syslog.h>

#define MAX_CONCURRENCY 100
#define RETRY_INTERVAL 5 // seconds
#define BACKOFF_STRATEGY "exponential"
#define LOG_LEVEL "INFO"

typedef struct {
    char *hostname;
    u_char *ipaddr;
} query_t;

void *dns_resolver(void *arg) {
    query_t *query = (query_t *)arg;
    int sockfd, retval;
    struct sockaddr_in serv_addr;
    char buf[1024];
    size_t len;
    ssize_t nread;
    time_t start_time, end_time;
    u_char *ipaddr = NULL;
    int error = 0;

    // create a socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "socket creation failed: %s", strerror(errno));
        return NULL;
    }

    // set up the server address
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(53);
    if (inet_pton(AF_INET, "8.8.8.8", &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "invalid IP address: %s", strerror(errno));
        return NULL;
    }

    // send the DNS query
    start_time = time(NULL);
    len = snprintf(buf, sizeof(buf), "%s\r\n", query->hostname);
    retval = sendto(sockfd, buf, len, 0, (struct sockaddr *)&serv_addr, sizeof(serv_addr));
    if (retval < 0) {
        syslog(LOG_ERR, "sendto failed: %s", strerror(errno));
        return NULL;
    }

    // receive the DNS response
    nread = recvfrom(sockfd, buf, sizeof(buf), 0, NULL, NULL);
    if (nread < 0) {
        syslog(LOG_ERR, "recvfrom failed: %s", strerror(errno));
        return NULL;
    }

    // parse the DNS response
    ipaddr = malloc(sizeof(u_char) * 4);
    if (ipaddr == NULL) {
        syslog(LOG_ERR, "malloc failed: %s", strerror(errno));
        return NULL;
    }
    memcpy(ipaddr, buf + 12, 4);

    // close the socket
    close(sockfd);

    // log the query and its result
    end_time = time(NULL);
    syslog(LOG_INFO, "query %s: start=%ld, end=%ld, result=%s", query->hostname, start_time, end_time, inet_ntoa(*(struct in_addr *)ipaddr));

    // return the IP address
    return ipaddr;
}

u_char *dns_resolve(const char *hostname) {
    pthread_t thread;
    query_t query = {.hostname = hostname};
    void *retval;

    // create a new thread for the DNS resolution
    if (pthread_create(&thread, NULL, dns_resolver, &query) != 0) {
        syslog(LOG_ERR, "pthread_create failed: %s", strerror(errno));
        return NULL;
    }

    // wait for the thread to finish and retrieve its result
    if (pthread_join(thread, &retval) != 0) {
        syslog(LOG_ERR, "pthread_join failed: %s", strerror(errno));
        return NULL;
    }

    // return the IP address
    return retval;
}
