        freeaddrinfo(res);
        return NULL;
    }

    // Send the DNS query and receive the response
    if (sendto(sockfd, "QUERY", 4, 0, res->ai_addr, res->ai_addrlen) == -1) {
        perror("sendto");
        close(sockfd);
        freeaddrinfo(res);
        return NULL;
    }

