        perror("recvfrom");
        close(sockfd);
        freeaddrinfo(res);
        return NULL;
    }

    // Close the socket and release resources
    close(sockfd);
    freeaddrinfo(res);

    // Log the query and response
    if (LOGGING_LEVEL >= 3) {
