pthread_mutex_t context_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new LTE UE Context to the linked list
void add_lte_ue_context(char *ue_identity, int s_tmsi, int rrc_connection_state) {
    lte_ue_context_t *new_context = (lte_ue_context_t *)malloc(sizeof(lte_ue_context_t));
    new_context->ue_identity = ue_identity;
    new_context->s_tmsi = s_tmsi;
    new_context->rrc_connection_state = rrc_connection_state;
    new_context->num_active_pdns = 0;
    new_context->active_pdns = NULL;

    // Acquire the lock to protect the linked list from concurrent access
    pthread_mutex_lock(&context_list_lock);

    // Add the new context to the end of the linked list
    if (context_list.tail == NULL) {
        context_list.head = new_context;
    } else {
        context_list.tail->next = new_context;
    }
    context_list.tail = new_context;

    // Release the lock to allow other threads to access the linked list
    pthread_mutex_unlock(&context_list_lock);
}

// Function to remove an LTE UE Context from the linked list by S-TMSI
void remove_lte_ue_context(int s_tmsi) {
    // Acquire the lock to protect the linked list from concurrent access
    pthread_mutex_lock(&context_list_lock);

    // Find the context with the matching S-TMSI and remove it from the linked list
    lte_ue_context_t *current = context_list.head;
    while (current != NULL) {
        if (current->s_tmsi == s_tmsi) {
            // Remove the context from the linked list
            if (current == context_list.head) {
                context_list.head = current->next;
            } else {
                current->prev->next = current->next;
            }
            if (current == context_list.tail) {
                context_list.tail = current->prev;
            } else {
                current->next->prev = current->prev;
            }

            // Release the lock to allow other threads to access the linked list
            pthread_mutex_unlock(&context_list_lock);

            // Free the memory allocated for the context
            free(current);

            return;
        }
        current = current->next;
    }

    // Release the lock to allow other threads to access the linked list
    pthread_mutex_unlock(&context_list_lock);
}

// Function to update an LTE UE Context's PDN connections by S-TMSI
void update_lte_ue_pdn_connections(int s_tmsi, char *apn, char *ip_address) {
    // Acquire the lock to protect the linked list from concurrent access
    pthread_mutex_lock(&context_list_lock);

    // Find the context with the matching S-TMSI and update its PDN connections
    lte_ue_context_t *current = context_list.head;
    while (current != NULL) {
        if (current->s_tmsi == s_tmsi) {
            // Add a new active PDN connection to the list if it doesn't already exist
            int found = 0;
            for (int i = 0; i < current->num_active_pdns; i++) {
                if (!strcmp(current->active_pdns[i].apn, apn) && !strcmp(current->active_pdns[i].ip_address, ip_address)) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                current->num_active_pdns++;
                active_pdn_t *new_pdn = (active_pdn_t *)malloc(sizeof(active_pdn_t));
                new_pdn->apn = apn;
                new_pdn->ip_address = ip_address;
                current->active_pdns = realloc(current->active_pdns, sizeof(active_pdn_t) * current->num_active_pdns);
                current->active_pdns[current->num_active_pdns - 1] = *new_pdn;
            }

            // Release the lock to allow other threads to access the linked list
            pthread_mutex_unlock(&context_list_lock);

            return;
        }
        current = current->next;
    }

    // Release the lock to allow other threads to access the linked list
    pthread_mutex_unlock(&context_list_lock);
}

// Function to retrieve an LTE UE Context by index
lte_ue_context_t *get_lte_ue_context(int index) {
    // Acquire the lock to protect the linked list from concurrent access
    pthread_mutex_lock(&context_list_lock);

    // Find the context at the specified index and return it
    lte_ue_context_t *current = context_list.head;
    for (int i = 0; i < index; i++) {
        current = current->next;
    }

    // Release the lock to allow other threads to access the linked list
    pthread_mutex_unlock(&context_list_lock);

    return current;
}

// Function to retrieve an LTE UE Context by UE Identity
lte_ue_context_t *get_lte_ue_context_by_identity(char *ue_identity) {
    // Acquire the lock to protect the linked list from concurrent access
    pthread_mutex_lock(&context_list_lock);

    // Find the context with the matching UE Identity and return it
    lte_ue_context_t *current = context_list.head;
    while (current != NULL) {
        if (!strcmp(current->ue_identity, ue_identity)) {
            break;
        }
        current = current->next;
    }

    // Release the lock to allow other threads to access the linked list
    pthread_mutex_unlock(&context_list_lock);

    return current;
}
