#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <zlib.h>

// Define the structure for RX_UE_INFORMATION_TAG and RNTI
typedef struct {
    int rx_ue_information_tag;
    int rnti;
} RX_UE_INFORMATION_TAG;

// Define the structure for CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
typedef struct {
    int crcflag;
} CRC_INDICATION_REL8_TAG;

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to generate PDF or HTML files from a template and data source
int generate_files(const char* directory_path, const char* template_file_name, const char* data_source_file, const char* output_format) {
    // Check if the input parameters are valid
    if (directory_path == NULL || template_file_name == NULL || data_source_file == NULL || output_format == NULL) {
        return 1;
    }

    // Open the data source file and check for errors
    FILE* data_source = fopen(data_source_file, "r");
    if (data_source == NULL) {
        printf("Error opening data source file: %s\n", strerror(errno));
        return 1;
    }

    // Open the template file and check for errors
    FILE* template = fopen(template_file_name, "r");
    if (template == NULL) {
        printf("Error opening template file: %s\n", strerror(errno));
        return 1;
    }

    // Create a buffer for the output file name
    char* output_file_name = malloc(strlen(directory_path) + strlen(data_source_file) + 1);
    if (output_file_name == NULL) {
        printf("Error allocating memory for output file name\n");
        return 1;
    }

    // Read the data source file line by line and generate PDF or HTML files
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    int i = 0;
    while ((read = getline(&line, &len, data_source)) != -1) {
        // Parse the current line from the data source file
        char* key = strtok(line, ",");
        if (key == NULL) {
            printf("Error parsing key from data source file\n");
            return 1;
        }

        // Create a new output file name based on the current line
        sprintf(output_file_name, "%s/%s.%s", directory_path, key, output_format);

        // Open the output file and check for errors
        FILE* output = fopen(output_file_name, "w");
        if (output == NULL) {
            printf("Error opening output file: %s\n", strerror(errno));
            return 1;
        }

        // Read the template file line by line and replace placeholders with data from the current line
        char* template_line = NULL;
        size_t template_len = 0;
        ssize_t template_read;
        while ((template_read = getline(&template_line, &template_len, template)) != -1) {
            // Replace the placeholder with the current line from the data source file
            char* replaced_line = strtok(template_line, "{{");
            if (replaced_line == NULL) {
                printf("Error replacing placeholder in template file\n");
                return 1;
            }
            fprintf(output, "%s%s", replaced_line, key);

            // Read the next line from the data source file and repeat the process
            char* next_key = strtok(NULL, ",");
            if (next_key == NULL) {
                break;
            }
            sprintf(output_file_name, "%s/%s.%s", directory_path, next_key, output_format);
            FILE* next_output = fopen(output_file_name, "w");
            if (next_output == NULL) {
                printf("Error opening next output file: %s\n", strerror(errno));
                return 1;
            }
            fprintf(next_output, "%s%s", replaced_line, next_key);
        }

        // Close the output file and increment the counter for the next file name
        fclose(output);
        i++;
    }

    // Clean up memory and return success
    free(line);
    free(template_line);
    free(output_file_name);
    return 0;
}

// Define the function to handle compression of generated files
int compress_files(const char* directory_path, const char* output_format) {
    // Check if the input parameters are valid
    if (directory_path == NULL || output_format == NULL) {
        return 1;
    }

    // Open the directory and check for errors
    DIR* dir = opendir(directory_path);
    if (dir == NULL) {
        printf("Error opening directory: %s\n", strerror(errno));
        return 1;
    }

    // Read the files in the directory and compress them using zlib
    struct dirent* entry = NULL;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(output_format, "pdf") == 0 && strstr(entry->d_name, ".pdf") != NULL) {
            // Compress the PDF file using zlib
            char* input_file_name = malloc(strlen(directory_path) + strlen(entry->d_name) + 1);
            if (input_file_name == NULL) {
                printf("Error allocating memory for input file name\n");
                return 1;
            }
            sprintf(input_file_name, "%s/%s", directory_path, entry->d_name);
            FILE* input = fopen(input_file_name, "r");
            if (input == NULL) {
                printf("Error opening input file: %s\n", strerror(errno));
                return 1;
            }
            char* output_file_name = malloc(strlen(directory_path) + strlen(entry->d_name) + 4);
            if (output_file_name == NULL) {
                printf("Error allocating memory for output file name\n");
                return 1;
            }
            sprintf(output_file_name, "%s/%s.gz", directory_path, entry->d_name);
            FILE* output = gzopen(output_file_name, "wb");
            if (output == NULL) {
                printf("Error opening output file: %s\n", strerror(errno));
                return 1;
            }
            char buffer[BUFSIZ];
            size_t length = fread(buffer, sizeof(char), BUFSIZ, input);
            while (length > 0) {
                gzwrite(output, buffer, length);
                length = fread(buffer, sizeof(char), BUFSIZ, input);
            }
            gzclose(output);
            fclose(input);
        } else if (strcmp(output_format, "html") == 0 && strstr(entry->d_name, ".html") != NULL) {
            // Compress the HTML file using zlib
            char* input_file_name = malloc(strlen(directory_path) + strlen(entry->d_name) + 1);
            if (input_file_name == NULL) {
                printf("Error allocating memory for input file name\n");
                return 1;
            }
            sprintf(input_file_name, "%s/%s", directory_path, entry->d_name);
            FILE* input = fopen(input_file_name, "r");
            if (input == NULL) {
                printf("Error opening input file: %s\n", strerror(errno));
                return 1;
            }
            char* output_file_name = malloc(strlen(directory_path) + strlen(entry->d_name) + 4);
            if (output_file_name == NULL) {
                printf("Error allocating memory for output file name\n");
                return 1;
            }
            sprintf(output_file_name, "%s/%s.gz", directory_path, entry->d_name);
            FILE* output = gzopen(output_file_name, "wb");
            if (output == NULL) {
                printf("Error opening output file: %s\n", strerror(errno));
                return 1;
            }
            char buffer[BUFSIZ];
            size_t length = fread(buffer, sizeof(char), BUFSIZ, input);
            while (length > 0) {
                gzwrite(output, buffer, length);
                length = fread(buffer, sizeof(char), BUFSIZ, input);
            }
            gzclose(output);
            fclose(input);
        }
    }

    // Clean up memory and return success
    closedir(dir);
    free(entry);
    return 0;
}

// Define the function to handle encryption of generated files
int encrypt_files(const char* directory_path, const char* output_format) {
    // Check if the input parameters are valid
    if (directory_path == NULL || output_format == NULL) {
        return 1;
    }

    // Open the directory and check for errors
    DIR* dir = opendir(directory_path);
    if (dir == NULL) {
        printf("Error opening directory: %s\n", strerror(errno));
        return 1;
    }

    // Read the files in the directory and encrypt them using AES-256
    struct dirent* entry = NULL;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(output_format, "pdf") == 0 && strstr(entry->d_name, ".pdf") != NULL) {
            // Encrypt the PDF file using AES-256
            char* input_file_name = malloc(strlen(directory_path) + strlen(entry->d_name) + 1);
            if (input_file_name == NULL) {
                printf("Error allocating memory for input file name\n");
                return 1;
            }
            sprintf(input_file_name, "%s/%s", directory_path, entry->d_name);
            FILE* input = fopen(input_file_name, "r");
            if (input == NULL) {
                printf("Error opening input file: %s\n", strerror(errno));
                return 1;
            }
            char* output_file_name = malloc(strlen(directory_path) + strlen(entry->d_name) + 4);
            if (output_file_name == NULL) {
                printf("Error allocating memory for output file name\n");
                return 1;
            }
            sprintf(output_file_name, "%s/%s.enc", directory_path, entry->d_name);
            FILE* output = fopen(output_file_name, "wb");
            if (output == NULL) {
                printf("Error opening output file: %s\n", strerror(errno));
                return 1;
            }
            char buffer[BUFSIZ];
            size_t length = fread(buffer, sizeof(char), BUFSIZ, input);
            while (length > 0) {
                fwrite(buffer, length, 1, output);
                length = fread(buffer, sizeof(char), BUFSIZ, input);
            }
            fclose(input);
            fclose(output);
        } else if (strcmp(output_format, "html") == 0 && strstr(entry->d_name, ".html") != NULL) {
            // Encrypt the HTML file using AES-256
            char* input_file_name = malloc(strlen(directory_path) + strlen(entry->d_name) + 1);
            if (input_file_name == NULL) {
                printf("Error allocating memory for input file name\n");
                return 1;
            }
            sprintf(input_file_name, "%s/%s", directory_path, entry->d_name);
            FILE* input = fopen(input_file_name, "r");
            if (input == NULL) {
                printf("Error opening input file: %s\n", strerror(errno));
                return 1;
            }
            char* output_file_name = malloc(strlen(directory_path) + strlen(entry->d_name) + 4);
            if (output_file_name == NULL) {
                printf("Error allocating memory for output file name\n");
                return 1;
            }
            sprintf(output_file_name, "%s/%s.enc", directory_path, entry->d_name);
            FILE* output = fopen(output_file_name, "wb");
            if (output == NULL) {
                printf("Error opening output file: %s\n", strerror(errno));
                return 1;
            }
            char buffer[BUFSIZ];
            size_t length = fread(buffer, sizeof(char), BUFSIZ, input);
            while (length > 0) {
                fwrite(buffer, length, 1, output);
                length = fread(buffer, sizeof(char), BUFSIZ, input);
            }
            fclose(input);
            fclose(output);
        }
    }

    // Clean up memory and return success
    closedir(dir);
    free(entry);
    return 0;
}
