static uint32_t *destination_ip_packet_counts = NULL;

// Define the minimum and maximum UDP ports
#define MIN_PORT 1024
#define MAX_PORT 65535

// Define the function to populate the list of UDP_PACKET structures
void populate_udp_packets(size_t m, uint32_t source_ip, uint32_t destination_ip) {
    // Initialize the list of UDP_PACKET structures if necessary
    if (udp_packets == NULL) {
        udp_packets = malloc(sizeof(UDP_PACKET) * m);
        memset(udp_packets, 0, sizeof(UDP_PACKET) * m);
    }

    // Initialize the pool of pre-allocated UDP_PACKET structures if necessary
    if (preallocated_udp_packets == NULL) {
        preallocated_udp_packets = malloc(sizeof(UDP_PACKET) * PREALLOCATED_UDP_PACKETS);
        memset(preallocated_udp_packets, 0, sizeof(UDP_PACKET) * PREALLOCATED_UDP_PACKETS);
    }

    // Initialize the mutex and condition variable for synchronizing access to the list of UDP_PACKET structures
    pthread_mutex_init(&udp_packet_mutex, NULL);
    pthread_cond_init(&udp_packet_populated, NULL);

    // Initialize the callback function and total number of packets sent to each unique DESTINATION_IP
    populate_callback_func = NULL;
    destination_ip_packet_counts = malloc(sizeof(uint32_t) * m);
    memset(destination_ip_packet_counts, 0, sizeof(uint32_t) * m);

    // Generate the UDP_PACKET structures and track the total memory usage
    size_t total_memory = 0;
    for (size_t i = 0; i < m; i++) {
        // Allocate a new UDP_PACKET structure from the pool if necessary
        UDP_PACKET *udp_packet = NULL;
        if (i < PREALLOCATED_UDP_PACKETS) {
            udp_packet = &preallocated_udp_packets[i];
        } else {
            udp_packet = malloc(sizeof(UDP_PACKET));
            total_memory += sizeof(UDP_PACKET);
        }

        // Initialize the UDP_PACKET structure with a random UDP port and sequence number
        udp_packet->source_ip = source_ip;
        udp_packet->destination_ip = destination_ip;
        udp_packet->udp_port = (uint16_t)rand() % (MAX_PORT - MIN_PORT + 1) + MIN_PORT;

        // Add the UDP_PACKET structure to the list of UDP_PACKET structures
        udp_packets[i] = *udp_packet;

        // Increment the total number of packets sent to each unique DESTINATION_IP
        destination_ip_packet_counts[i]++;
    }

    // Log the total memory usage and free any unused UDP_PACKET structures in the pool
    printf("Total memory usage: %zu bytes\n", total_memory);
    for (size_t i = m; i < PREALLOCATED_UDP_PACKETS; i++) {
        free(preallocated_udp_packets[i]);
    }

    // Signal the condition variable to notify any waiting threads that the list is populated
    pthread_cond_signal(&udp_packet_populated);
}

// Define the function to retrieve a UDP_PACKET structure from the list
UDP_PACKET *get_udp_packet(size_t index) {
    // Acquire the mutex for synchronizing access to the list of UDP_PACKET structures
    pthread_mutex_lock(&udp_packet_mutex);

    // Return the UDP_PACKET structure at the specified index
    UDP_PACKET *udp_packet = &udp_packets[index];

    // Release the mutex for synchronizing access to the list of UDP_PACKET structures
    pthread_mutex_unlock(&udp_packet_mutex);

    return udp_packet;
}

// Define the function to set the callback function for notifying when the list is populated
void set_populate_callback(populate_callback populate_callback) {
    // Acquire the mutex for synchronizing access to the list of UDP_PACKET structures
    pthread_mutex_lock(&udp_packet_mutex);

    // Set the callback function and signal the condition variable to notify any waiting threads that the list is populated
    populate_callback_func = populate_callback;
    pthread_cond_signal(&udp_packet_populated);

    // Release the mutex for synchronizing access to the list of UDP_PACKET structures
    pthread_mutex_unlock(&udp_packet_mutex);
}

// Define the function to retrieve the total number of packets sent to each unique DESTINATION_IP
uint32_t *get_destination_ip_packet_counts() {
    // Acquire the mutex for synchronizing access to the list of UDP_PACKET structures
    pthread_mutex_lock(&udp_packet_mutex);

    // Return a copy of the total number of packets sent to each unique DESTINATION_IP
    uint32_t *destination_ip_packet_counts_copy = malloc(sizeof(uint32_t) * m);
    memcpy(destination_ip_packet_counts_copy, destination_ip_packet_counts, sizeof(uint32_t) * m);

    // Release the mutex for synchronizing access to the list of UDP_PACKET structures
    pthread_mutex_unlock(&udp_packet_mutex);

    return destination_ip_packet_counts_copy;
}
