import hashlib
import os

def calculate_file_md5(filepath, chunk_size=1024):
    # Open the file and create a hash object
    with open(filepath, 'rb') as f:
        md5 = hashlib.md5()

        # Read the file in chunks and update the hash
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            md5.update(chunk)

    # Return the hexdigest of the hash and a boolean indicating successful processing
    return md5.hexdigest(), True
