    int rand_num = (rand() % (max - min + 1)) + min;

    // Check if the generated session ID is already in use
    for (int i = 0; i < cache->size; i++) {
        if (cache->cache[i]->session_id == rand_num) {
            return generate_session_id(min, max);
        }
    }

    // Return the generated session ID
    return rand_num;
}

// Function to populate the cache with N elements
void populate_cache(int n) {
