// Initialize the packet pool with random packets
void init_packet_pool(int size) {
    srand(DEFAULT_SEED);
    for (int i = 0; i < size; i++) {
        packets[i].payload = malloc(MAX_PAYLOAD_SIZE);
        if (!packets[i].payload) {
            printf("Error: Failed to allocate memory for packet %d\n", i);
            return -1;
        }
        packets[i].payload_size = rand() % MAX_PAYLOAD_SIZE + 1;
    }
}

// Populate the packet pool with random messages
void populate_packet_pool() {
    for (int i = 0; i < MAX_PACKETS; i++) {
        // Generate source and destination IP addresses
        struct in_addr src_ip, dst_ip;
        src_ip.s_addr = htonl(rand() % DEFAULT_MAX_SIZE + 1);
        dst_ip.s_addr = htonl(rand() % DEFAULT_MAX_SIZE + 1);

        // Generate source and destination port numbers
        int src_port = rand() % DEFAULT_PORT + 1;
        int dst_port = rand() % DEFAULT_PORT + 1;

        // Generate protocol type
        int protocol_type = DEFAULT_PROTOCOL_TYPE;

        // Fill in the packet header
        packets[i].header.source_ip = src_ip;
        packets[i].header.destination_ip = dst_ip;
        packets[i].header.port_numbers = htons(src_port, dst_port);
        packets[i].header.protocol_type = protocol_type;
    }
}

// Send packets on a given interface
void send_packets(int interface, int count) {
    for (int i = 0; i < count; i++) {
        // Fill in the socket address structure
        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_port = htons(interfaces[interface]->address.sin_port);
        addr.sin_addr = interfaces[interface]->address.sin_addr;

        // Send the packet
        sendto(interfaces[interface]->socket, packets[i].payload, packets[i].payload_size, 0, (struct sockaddr *)&addr, sizeof(addr));
    }
}

// Receive packets on a given interface
void receive_packets(int interface) {
    // Fill in the socket address structure
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(interfaces[interface]->address.sin_port);
    addr.sin_addr = interfaces[interface]->address.sin_addr;

    // Receive the packet
    int recv_size = recvfrom(interfaces[interface]->socket, packets[i].payload, MAX_PAYLOAD_SIZE, 0, (struct sockaddr *)&addr, sizeof(addr));
    if (recv_size < 0) {
        printf("Error: Failed to receive packet on interface %d\n", interface);
        return -1;
    }
}

// Handle a received packet
void handle_packet(packet_t *packet) {
    // Check if the packet is valid
    if (packet->header.source_ip == 0 || packet->header.destination_ip == 0) {
        printf("Error: Received invalid packet\n");
        return -1;
    }

    // Update delivery attempts and success rate
    update_delivery_attempts(1);
    update_success_rate((float) packet_count / MAX_PACKETS);

    // Log debug information
    log_debug_info();
}

// Update the number of delivery attempts
void update_delivery_attempts(int count) {
    pthread_mutex_lock(&mutex);
    delivery_attempts += count;
    pthread_mutex_unlock(&mutex);
}

// Update the success rate
void update_success_rate(float rate) {
    pthread_mutex_lock(&mutex);
    success_rate = rate;
    pthread_mutex_unlock(&mutex);
}

// Update the error code
void update_error_code(int code) {
    pthread_mutex_lock(&mutex);
    error_code = code;
    pthread_mutex_unlock(&mutex);
}

// Log debug information
void log_debug_info() {
    printf("Delivery attempts: %d\n", delivery_attempts);
    printf("Success rate: %.2f%%\n", success_rate * 100.0f);
    printf("Error code: %d\n", error_code);
}

// Clean up resources
void cleanup() {
    for (int i = 0; i < MAX_PACKETS; i++) {
        free(packets[i].payload);
    }
    for (int i = 0; i < MAX_INTERFACES; i++) {
        close(interfaces[i]->socket);
        free(interfaces[i]);
    }
}
