// structure to represent a UDP packet
struct udp_packet {
    struct sockaddr_in source; // source IP and port number
    struct sockaddr_in destination; // destination IP and port number
    char protocol[4]; // protocol type (e.g., "UDP")
    unsigned short sequence_number; // sequence number of the packet
    time_t timestamp; // timestamp of the packet
    char payload[MAX_PAYLOAD_SIZE]; // payload data
};

// structure to represent an NFAPI_RRC_MESSAGE_PDU_T
struct nfapi_rrc_message_pdu {
    unsigned short message_type; // type of the RRC message (e.g., 0x1234)
    unsigned short sequence_number; // sequence number of the message
    time_t timestamp; // timestamp of the message
};

// structure to represent a rule for parsing input files
struct rule {
    char *name; // name of the rule (e.g., "rule1")
    char *pattern; // pattern to match in the input file (e.g., ".*(abc|def).*")
    char *replacement; // replacement string for the matched pattern (e.g., "XYZ")
};

// function to generate a random seed for reproducibility
unsigned int get_random_seed() {
    return DEFAULT_SEED;
}

// function to initialize a UDP packet with randomly generated header and payload data
void init_udp_packet(struct udp_packet *packet) {
    // generate random source and destination IP addresses and port numbers
    packet->source.sin_addr.s_addr = htonl(rand() % 256);
    packet->destination.sin_addr.s_addr = htonl(rand() % 256);
    packet->source.sin_port = htons(rand() % 65536);
    packet->destination.sin_port = htons(rand() % 65536);

    // generate random protocol type (e.g., "UDP")
    strcpy(packet->protocol, "UDP");

    // generate random sequence number and timestamp
    packet->sequence_number = rand() % 1000;
    packet->timestamp = time(NULL);

    // generate random payload data
    for (int i = 0; i < MAX_PAYLOAD_SIZE; i++) {
        packet->payload[i] = rand() % 256;
    }
}

// function to parse an input file based on a set of rules provided via command-line arguments
void parse_input_file(char *input_file, char *output_file, char *packet_file, char *rules) {
    // initialize variables for parsing the input file
    FILE *fp = fopen(input_file, "r");
    FILE *op = fopen(output_file, "w");
    struct udp_packet packet;
    int rule_index = 0;
    char *rule_name = NULL;
    char *rule_pattern = NULL;
    char *rule_replacement = NULL;

    // loop through each line in the input file
    while (fgets(line, sizeof(line), fp) != NULL) {
        // check if the current line matches any of the rules provided via command-line arguments
        for (int i = 0; i < MAX_RULES; i++) {
            rule_name = strtok(rules[i], " ");
            rule_pattern = strtok(NULL, " ");
            rule_replacement = strtok(NULL, " ");
            if (rule_name != NULL && rule_pattern != NULL && rule_replacement != NULL) {
                // check if the current line matches the pattern of the current rule
                if (strstr(line, rule_pattern) != NULL) {
                    // replace the matched pattern with the replacement string
                    char *new_line = strreplace(line, rule_pattern, rule_replacement);
                    fprintf(op, "%s", new_line);
                    free(new_line);
                    break;
                }
            }
        }
    }

    // close the input and output files
    fclose(fp);
    fclose(op);
}

// function to generate a list of NFAPI_RRC_MESSAGE_PDU_T structures based on input parameters for the number of structures (`N`) and the seed value for random generation
void generate_nfapi_rrc_message_pdu(int N, unsigned int seed) {
    // initialize variables for generating the list of NFAPI_RRC_MESSAGE_PDU_T structures
    struct nfapi_rrc_message_pdu *list = malloc(N * sizeof(struct nfapi_rrc_message_pdu));
    int i;

    // loop through each structure in the list and initialize it with randomly generated message type, sequence number, and timestamp
    for (i = 0; i < N; i++) {
        list[i].message_type = rand() % 1000;
        list[i].sequence_number = rand() % 1000;
        list[i].timestamp = time(NULL);
    }
}

// function to track the total number of packet delivery attempts and report the success rate along with the error code upon completion
void track_packet_delivery(int N, int success) {
    // initialize variables for tracking the total number of packet delivery attempts and success rate
    int total = 0;
    int success_rate = 0;

    // loop through each structure in the list and increment the total number of packet delivery attempts
    for (int i = 0; i < N; i++) {
        total++;
        if (success) {
            success_rate++;
        }
    }

    // report the success rate along with the error code upon completion
    printf("Total number of packet delivery attempts: %d\n", total);
    printf("Success rate: %.2f%%\n", (float)success_rate / total * 100);
}

// function to generate a checksum for the integrity check of the generated messages, comparing it against a predefined expected value
void generate_checksum(char *input_file, char *output_file) {
    // initialize variables for generating the checksum and comparing it against the expected value
    FILE *fp = fopen(input_file, "r");
    FILE *op = fopen(output_file, "w");
    int checksum = 0;
    char line[MAX_LINE_LENGTH];

    // loop through each line in the input file and calculate the checksum
    while (fgets(line, sizeof(line), fp) != NULL) {
        checksum += strlen(line);
    }

    // close the input and output files
    fclose(fp);
    fclose(op);

    // compare the generated checksum against the expected value
    if (checksum == EXPECTED_CHECKSUM) {
        printf("Checksum matches the expected value\n");
    } else {
        printf("Checksum does not match the expected value\n");
    }
}

// function to record the total memory usage, any errors encountered during execution, and detailed statistics about the distribution of message types and timestamps across the dataset
void log_statistics(int N) {
    // initialize variables for recording the total memory usage, any errors encountered during execution, and detailed statistics about the distribution of message types and timestamps across the dataset
    int total_memory = 0;
    char *error_message = NULL;
    struct nfapi_rrc_message_pdu *list = malloc(N * sizeof(struct nfapi_rrc_message_pdu));
    int message_type[100]; // array to store the distribution of message types across the dataset
    time_t timestamp[100]; // array to store the distribution of timestamps across the dataset

    // loop through each structure in the list and record the total memory usage, any errors encountered during execution, and detailed statistics about the distribution of message types and timestamps across the dataset
    for (int i = 0; i < N; i++) {
        total_memory += sizeof(struct nfapi_rrc_message_pdu);
        if (error_message != NULL) {
            printf("Error encountered during execution: %s\n", error_message);
        } else {
            message_type[list[i].message_type]++; // record the distribution of message types across the dataset
            timestamp[list[i].timestamp]++; // record the distribution of timestamps across the dataset
