#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_PACKETS 1000000 // maximum number of packets in the pool
#define MAX_RULES 100 // maximum number of rules to be applied
#define MAX_MESSAGE_TYPE 100 // maximum message type supported
#define MAX_SEED 1000000 // maximum seed value for random generation
#define DEFAULT_THEME_DIR "/path/to/default/theme/dir" // default theme directory
#define DEFAULT_THEME "default.jpg" // default theme file name

// structure to represent a UDP packet
struct udp_packet {
    struct sockaddr_in source; // source IP and port number
    struct sockaddr_in destination; // destination IP and port number
    int protocol; // protocol type (e.g., TCP, UDP)
    char payload[MAX_PAYLOAD]; // payload data
};

// structure to represent an NFAPI_RRC_MESSAGE_PDU_T
struct nfapi_rrc_message_pdu {
    int message_type; // RRC message type (e.g., RRCConnectionSetup)
    int sequence_number; // sequence number of the message
    long timestamp; // timestamp of the message
};

// structure to represent a packet pool
struct packet_pool {
    struct udp_packet packets[MAX_PACKETS]; // array of UDP packets
    int num_packets; // number of packets in the pool
    int max_size; // maximum size of the pool
};

// structure to represent a rule set
struct rule_set {
    char rules[MAX_RULES][MAX_RULE_LENGTH]; // array of rules
    int num_rules; // number of rules in the set
};

// function to generate a random seed value
int generate_seed() {
    return rand() % MAX_SEED + 1;
}

// function to initialize a packet pool
void init_packet_pool(struct packet_pool *pool) {
    pool->num_packets = 0;
    pool->max_size = MAX_PACKETS;
}

// function to add a new UDP packet to the pool
void add_packet(struct packet_pool *pool, struct udp_packet packet) {
    if (pool->num_packets < pool->max_size) {
        pool->packets[pool->num_packets++] = packet;
    } else {
        printf("Packet pool is full. Cannot add more packets.\n");
    }
}

// function to parse a binary input file and populate the packet pool
void parse_input_file(struct packet_pool *pool, char *filename) {
    // open the input file in binary mode
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error: unable to open input file %s\n", filename);
        return;
    }

    // read the contents of the file and populate the packet pool
    while (!feof(fp)) {
        struct udp_packet packet;
        fread(&packet, sizeof(struct udp_packet), 1, fp);
        add_packet(pool, packet);
    }

    // close the input file
    fclose(fp);
}

// function to apply a set of rules to the packet pool
void apply_rules(struct packet_pool *pool, struct rule_set *rule_set) {
    for (int i = 0; i < rule_set->num_rules; i++) {
        char *rule = rule_set->rules[i];
        // parse the rule and apply it to each packet in the pool
        for (int j = 0; j < pool->num_packets; j++) {
            struct udp_packet *packet = &pool->packets[j];
            // check if the current packet matches the rule
            if (match_rule(packet, rule)) {
                // apply the rule to the packet
                apply_rule(packet, rule);
            }
        }
    }
}

// function to match a rule against a UDP packet
int match_rule(struct udp_packet *packet, char *rule) {
    // parse the rule and extract the necessary fields
    int source_ip = atoi(strtok(rule, " "));
    int destination_ip = atoi(strtok(NULL, " "));
    int port = atoi(strtok(NULL, " "));
    int protocol = atoi(strtok(NULL, " "));

    // check if the current packet matches the rule
    return (packet->source.sin_addr.s_addr == source_ip &&
            packet->destination.sin_addr.s_addr == destination_ip &&
            packet->source.sin_port == port &&
            packet->protocol == protocol);
}

// function to apply a rule to a UDP packet
void apply_rule(struct udp_packet *packet, char *rule) {
    // parse the rule and extract the necessary fields
    int source_ip = atoi(strtok(rule, " "));
    int destination_ip = atoi(strtok(NULL, " "));
    int port = atoi(strtok(NULL, " "));
    int protocol = atoi(strtok(NULL, " "));

    // update the source and destination IP addresses and ports
    packet->source.sin_addr.s_addr = source_ip;
    packet->destination.sin_addr.s_addr = destination_ip;
    packet->source.sin_port = port;
    packet->protocol = protocol;
}

// function to generate a checksum for the integrity of the generated messages
int generate_checksum(struct packet_pool *pool) {
    int checksum = 0;
    // iterate over each packet in the pool and calculate the checksum
    for (int i = 0; i < pool->num_packets; i++) {
        struct udp_packet *packet = &pool->packets[i];
        checksum += packet->source.sin_addr.s_addr + packet->destination.sin_addr.s_addr + packet->source.sin_port + packet->protocol;
    }
    return checksum;
}

// function to track the total number of packet delivery attempts and report the success rate along with the error code upon completion
void track_packet_delivery(struct packet_pool *pool, int num_delivered, int num_failed) {
    // calculate the success rate and error code based on the number of delivered and failed packets
    float success_rate = (float)num_delivered / (num_delivered + num_failed);
    int error_code = 0;
    if (success_rate < 0.5) {
        error_code = 1; // error code for packet loss
    }
    printf("Packet delivery: %d delivered, %d failed. Success rate: %.2f%%. Error code: %d\n", num_delivered, num_failed, success_rate * 100, error_code);
}

// function to generate an output file based on the transformed contents of the input file according to the specified rules
void generate_output_file(struct packet_pool *pool, char *filename) {
    // open the output file in binary mode
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        printf("Error: unable to open output file %s\n", filename);
        return;
    }

    // write each packet in the pool to the output file
    for (int i = 0; i < pool->num_packets; i++) {
        struct udp_packet *packet = &pool->packets[i];
        fwrite(packet, sizeof(struct udp_packet), 1, fp);
    }

    // close the output file
    fclose(fp);
}

// function to create and populate a list of NFAPI_RRC_MESSAGE_PDU_T structures based on input parameters for the number of structures (`N`) and the seed value for random generation
void generate_nfapi_rrc_message_pdu(int N, int seed) {
    // initialize a list of NFAPI_RRC_MESSAGE_PDU_T structures
    struct nfapi_rrc_message_pdu *list = malloc(N * sizeof(struct nfapi_rrc_message_pdu));
    if (list == NULL) {
        printf("Error: unable to allocate memory for NFAPI_RRC_MESSAGE_PDU_T list\n");
        return;
    }

    // populate the list with randomly generated message headers and payloads based on the seed value
    srand(seed);
    for (int i = 0; i < N; i++) {
        struct nfapi_rrc_message_pdu *pdu = &list[i];
        pdu->message_type = rand() % MAX_MESSAGE_TYPE + 1; // random message type
        pdu->sequence_number = rand() % 1000000 + 1; // random sequence number
        pdu->timestamp = time(NULL); // current timestamp
    }
}

// function to track the total memory usage and any errors encountered during execution
void track_memory_usage(struct packet_pool *pool) {
    // calculate the total memory usage of the pool
    int total_memory_usage = 0;
    for (int i = 0; i < pool->num_packets; i++) {
        struct udp_packet *packet = &pool->packets[i];
        total_memory_usage += sizeof(struct udp_packet);
    }
    printf("Total memory usage: %d bytes\n", total_memory_usage);
}

// function to record detailed statistics about the distribution of message types and timestamps across the dataset
void track_message_type_and_timestamp(struct packet_pool *pool) {
    // initialize a map to store the distribution of message types and timestamps
    struct message_type_map {
        int message_type;
        int count;
    };
    struct message_type_map *message_type_map = malloc(MAX_MESSAGE_TYPE * sizeof(struct message_type_map));
    if (message_type_map == NULL) {
        printf("Error: unable to allocate memory for message type map\n");
        return;
    }

    // populate the map with the distribution of message types and timestamps in the pool
    for (int i = 0; i < pool->num_packets; i++) {
        struct udp_packet *packet = &pool->packets[i];
        int message_type = packet->protocol;
        if (message_type > MAX_MESSAGE_TYPE) {
            continue; // skip packets with invalid message types
        }
        struct message_type_map *entry = &message_type_map[message_type - 1];
        entry->count++;
    }

    // print the distribution of message types and timestamps in the map
    for (int i = 0; i < MAX_MESSAGE_TYPE; i++) {
        struct message_type_map *entry = &message_type_map[i];
        if (entry->count > 0) {
            printf("Message type %d: %d\n", entry->message_type, entry->count);
        }
    }
}

// function to handle packet loss by retransmitting missing packets and simulate a scenario where the function processes a large number of packets in a streaming fashion
