#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the structure of a UE context
typedef struct {
    int RRC_STATE;
    long TMSI;
    char* NAS_MESSAGE;
    int STATUS_CODE;
} UEContext;

// Define the linked list data structure for storing UE contexts
typedef struct {
    UEContext* head;
    UEContext* tail;
    size_t size;
    pthread_mutex_t mutex;
} LinkedList;

// Define the function to dynamically populate a linked list of UE contexts
void populateUEContexts(LinkedList* list, int numUEs) {
    // Initialize the linked list with an empty head and tail
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Iterate over the number of UE contexts to be populated
    for (int i = 0; i < numUEs; i++) {
        // Allocate memory for a new UE context structure
        UEContext* ueContext = malloc(sizeof(UEContext));

        // Set the RRC state, TMSI, NAS message, and status code randomly
        ueContext->RRC_STATE = rand() % 10;
        ueContext->TMSI = rand();
        ueContext->NAS_MESSAGE = "Hello, world!";
        ueContext->STATUS_CODE = rand() % 10;

        // Add the new UE context to the linked list
        if (list->head == NULL) {
            list->head = ueContext;
            list->tail = ueContext;
        } else {
            list->tail->next = ueContext;
            list->tail = ueContext;
        }

        // Increment the size of the linked list
        list->size++;
    }

    // Unlock the mutex to allow concurrent access
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to handle dynamic cache resizing for the UE contexts
void resizeUEContextCache(LinkedList* list, int newSize) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // If the new size is smaller than the current size, evict the least recently used UE contexts
    if (newSize < list->size) {
        // Iterate over the linked list from the tail to the head
        for (int i = 0; i < list->size - newSize; i++) {
            // Remove the least recently used UE context from the linked list
            UEContext* ueContext = list->tail;
            list->tail = list->tail->prev;
            free(ueContext);
        }
    } else if (newSize > list->size) {
        // If the new size is larger than the current size, allocate new memory for the new UE contexts
        for (int i = 0; i < newSize - list->size; i++) {
            // Allocate memory for a new UE context structure
            UEContext* ueContext = malloc(sizeof(UEContext));

            // Set the RRC state, TMSI, NAS message, and status code randomly
            ueContext->RRC_STATE = rand() % 10;
            ueContext->TMSI = rand();
            ueContext->NAS_MESSAGE = "Hello, world!";
            ueContext->STATUS_CODE = rand() % 10;

            // Add the new UE context to the linked list
            if (list->head == NULL) {
                list->head = ueContext;
                list->tail = ueContext;
            } else {
                list->tail->next = ueContext;
                list->tail = ueContext;
            }

            // Increment the size of the linked list
            list->size++;
        }
    }

    // Unlock the mutex to allow concurrent access
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to handle dynamic reconfiguration of network settings for the UE contexts
void reconfigureNetworkSettings(LinkedList* list, int newFrequencyBand, int newCellID) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Iterate over the linked list from the head to the tail
    for (UEContext* ueContext = list->head; ueContext != NULL; ueContext = ueContext->next) {
        // Check if the UE context matches the new network configuration parameters
        if (ueContext->RRC_STATE == newFrequencyBand && ueContext->TMSI == newCellID) {
            // Invalidate the existing UE context and rebuild the linked list accordingly
            free(ueContext);
            list->size--;
            break;
        }
    }

    // Resize the cache to accommodate the new number of UE contexts
    resizeUEContextCache(list, list->size);

    // Unlock the mutex to allow concurrent access
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to handle real-time updates of network configuration parameters for the UE contexts
void updateNetworkConfiguration(LinkedList* list, int newFrequencyBand, int newCellID) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Iterate over the linked list from the head to the tail
    for (UEContext* ueContext = list->head; ueContext != NULL; ueContext = ueContext->next) {
        // Check if the UE context matches the new network configuration parameters
        if (ueContext->RRC_STATE == newFrequencyBand && ueContext->TMSI == newCellID) {
            // Update the UE context with the new network configuration parameters
            ueContext->RRC_STATE = newFrequencyBand;
            ueContext->TMSI = newCellID;
        }
    }

    // Unlock the mutex to allow concurrent access
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to handle logging of critical events for the UE contexts
void logCriticalEvents(LinkedList* list, int severityLevel) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Iterate over the linked list from the head to the tail
    for (UEContext* ueContext = list->head; ueContext != NULL; ueContext = ueContext->next) {
        // Check if the UE context matches the new network configuration parameters
        if (ueContext->RRC_STATE == severityLevel) {
            // Log the critical event with the corresponding severity level and time range
            printf("Critical event: UE %d, RRC state %d\n", ueContext->TMSI, ueContext->RRC_STATE);
        }
    }

    // Unlock the mutex to allow concurrent access
    pthread_mutex_unlock(&list->mutex);
}
