        record.network_type = rand() % 2 + 1;
        record.connected = rand() % 2 == 0 ? true : false;
        record.quality_score = rand() % quality_threshold + 1;
        record.timestamp = time(NULL);
        record.flags = rand();

        // Add the record to the collection if its quality score is greater than or equal to the specified threshold
        if (record.quality_score >= quality_threshold) {
            pthread_mutex_lock(&collection_mutex);
