        memset(offset_array, 0, sizeof(long) * OFFSET_ARRAY_SIZE);
    }
}

// Define the function for managing an array of int keys for filtering out duplicates and handling missing values
void manage_key_array(int n) {
    // Loop through each key value and check if it is a duplicate or missing
    for (int i = 0; i < n; i++) {
        // Check if the key value is a duplicate
        bool duplicate = false;
        for (int j = 0; j < i; j++) {
            if (key_array[i] == key_array[j]) {
                duplicate = true;
                break;
            }
        }

        // If the key value is a duplicate, remove it from the array
        if (duplicate) {
            memmove(key_array + i, key_array + i + 1, sizeof(int) * (n - i));
            n--;
            i--;
        }
    }
}

