            record_count++;
        }
    }

    // Ensure thread-safe operations to prevent race conditions or deadlocks
    pthread_mutex_lock(&mutex);

    // Implement synchronization mechanisms using atomic operations and mutexes for safe concurrent access
    int *atomic_record_count = (int *)malloc(sizeof(int));
    if (!atomic_record_count) {
        printf("Error: Failed to allocate memory for atomic record count\n");
        free(offset_array);
        free(key_array);
        free(record_array);
        free(crc_indication_pdu_array);
        pthread_mutex_unlock(&mutex);
        return;
    }
    atomic_record_count = 0;

    // Log and monitor memory usage for debugging purposes
    logging_message.timestamp = time(NULL);
    logging_message.message = "Memory usage updated";
    log_message(&logging_message);

    // Ensure thread-safe operations to prevent race conditions or deadlocks
    pthread_mutex_unlock(&mutex);

    // Implement secure cleanup functions to disable the cipher and release resources properly
    EVP_CIPHER_CTX_free(cipher);
    EVP_CIPHER_CTX_free(decryptor);
    free(key);
    free(atomic_record_count);
    free(offset_array);
    free(key_array);
    free(record_array);
    free(crc_indication_pdu_array);
}
