['```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace NetworkDeviceConnectionManager
{
    public class DeviceConnectionManager
    {
        private readonly object _lock = new object();
        private readonly List<DEVICE_CONN_RECORD> _deviceConnections;
        private readonly List<UE_CONTEXT_INFO_RECORD> _ueContextInfoRecords;
        private readonly Random _random;
        private readonly int _qualityThreshold;
        private readonly int _maxOffsetValue;
        private readonly int _maxKeyValue;
        private readonly int _seed;

        public DeviceConnectionManager(int qualityThreshold, int maxOffsetValue, int maxKeyValue, int seed)
        {
            _deviceConnections = new List<DEVICE_CONN_RECORD>();
            _ueContextInfoRecords = new List<UE_CONTEXT_INFO_RECORD>();
            _random = new Random(seed);
            _qualityThreshold = qualityThreshold;
            _maxOffsetValue = maxOffsetValue;
            _maxKeyValue = maxKeyValue;
        }

        public void AddDeviceConnection(DEVICE_CONN_RECORD deviceConnection)
        {
            lock (_lock)
            {
                _deviceConnections.Add(deviceConnection);
            }
        }

        public void AddUeContextInfoRecord(UE_CONTEXT_INFO_RECORD ueContextInfoRecord)
        {
            lock (_lock)
            {
                _ueContextInfoRecords.Add(ueContextInfoRecord);
            }
        }

        public List<DEVICE_CONN_RECORD> GetDeviceConnections()
        {
            lock (_lock)
            {
                return new List<DEVICE_CONN_RECORD>(_deviceConnections);
            }
        }

        public List<UE_CONTEXT_INFO_RECORD> GetUeContextInfoRecords()
        {
            lock (_lock)
            {
                return new List<UE_CONTEXT_INFO_RECORD>(_ueContextInfoRecords);
            }
        }

        public void PopulateDeviceConnections(int n, int m, int seed)
        {
            lock (_lock)
            {
                _deviceConnections.Clear();
                _random = new Random(seed);

                for (int i = 0; i < n; i++)
                {
                    var deviceConnection = new DEVICE_CONN_RECORD()
                    {
                        DeviceId = i,
                        NetworkType = "LTE",
                        ConnectionStatus = _random.Next(2) == 0 ? "Connected" : "Disconnected",
                        QualityScore = _random.Next(100),
                        Timestamp = DateTime.Now,
                        Flags = (DeviceConnectionFlags)_random.Next(32)
                    };

                    if (deviceConnection.QualityScore >= _qualityThreshold)
                    {
                        _deviceConnections.Add(deviceConnection);
                    }
                }
            }
        }

        public void PopulateUeContextInfoRecords(int n, int m, int seed)
        {
            lock (_lock)
            {
                _ueContextInfoRecords.Clear();
                _random = new Random(seed);

                for (int i = 0; i < n; i++)
                {
                    var ueContextInfoRecord = new UE_CONTEXT_INFO_RECORD()
                    {
                        UeId = i,
                        ServingCellInformation = _random.Next(10),
                        MobilityStatus = _random.Next(2) == 0 ? "Stationary" : "Mobile",
                        Timestamp = DateTime.Now
                    };

                    if (ueContextInfoRecord.MobilityStatus == "Mobile")
                    {
                        ueContextInfoRecord.LastUpdateTime = DateTime.Now;
                    }

                    _ueContextInfoRecords.Add(ueContextInfoRecord);
                }
            }
        }

        public List<NFAPI_CRC_INDICATION_PDU_T> GetCrcIndicationPdus()
        {
            lock (_lock)
            {
                var crcIndicationPdus = new List<NFAPI_CRC_INDICATION_PDU_T>();

                foreach (var deviceConnection in _deviceConnections)
                {
                    if (deviceConnection.QualityScore >= _qualityThreshold)
                    {
                        var crcIndicationPdu = new NFAPI_CRC_INDICATION_PDU_T()
                        {
                            RxUeInformationTag = deviceConnection.DeviceId,
                            Rnti = deviceConnection.DeviceId,
                            CrcIndicationRel8Tag = new CRC_INDICATION_REL8_TAG()
                            {
                                CrcFlag = _random.Next(2) == 0 ? true : false
                            },
                            Timestamp = DateTime.Now
                        };

                        crcIndicationPdus.Add(crcIndicationPdu);
                    }
                }

                return crcIndicationPdus;
            }
        }

        public void Dispose()
        {
            lock (_lock)
            {
                _deviceConnections.Clear();
                _ueContextInfoRecords.Clear();
            }
        }
    }
}
