#include <stdbool.h>

// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
    uint64_t timestamp;
    uint32_t UID;
    uint32_t checksum;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the memory pool for allocating and deallocating structures
#define MEMORY_POOL_SIZE 1024 // Size of the memory pool in bytes
static uint8_t memory_pool[MEMORY_POOL_SIZE];
static size_t memory_pool_index = 0; // Index for allocating and deallocating structures from the memory pool

// Define the function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void create_and_populate_crc_indication_list(size_t N, uint32_t seed) {
    // Initialize the memory pool for allocating and deallocating structures
    memset(memory_pool, 0, MEMORY_POOL_SIZE);
    memory_pool_index = 0;

    // Loop over each structure in the list
    for (size_t i = 0; i < N; i++) {
        // Allocate a new structure from the memory pool
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)memory_pool + memory_pool_index;
        memory_pool_index += sizeof(NFAPI_CRC_INDICATION_PDU_T);

        // Set the RX_UE_INFORMATION_TAG and RNTI for the structure
        pdu->RX_UE_INFORMATION_TAG = i;
        pdu->RNTI = seed + i;

        // Generate a random CRCFLAG value for the structure
        pdu->CRCFLAG = rand() % 256;

        // Set the timestamp for the structure
        pdu->timestamp = time(NULL);

        // Compute the UID and checksum for the structure
        pdu->UID = i;
        pdu->checksum = compute_checksum(pdu);
    }
}

// Define a function to compute the checksum over the fields of an NFAPI_CRC_INDICATION_PDU_T structure
uint32_t compute_checksum(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    uint32_t checksum = 0;
    checksum += pdu->RX_UE_INFORMATION_TAG;
    checksum += pdu->RNTI;
    checksum += pdu->CRCFLAG;
    checksum += pdu->timestamp;
    return checksum;
}

// Define a function to handle memory allocation and deallocation for the list of NFAPI_CRC_INDICATION_PDU_T structures
void *allocate_memory(size_t size) {
    // Check if there is enough space in the memory pool for the requested size
    if (memory_pool_index + size > MEMORY_POOL_SIZE) {
        return NULL;
    }

    // Allocate a new block of memory from the memory pool
    void *ptr = memory_pool + memory_pool_index;
    memory_pool_index += size;

    // Return the pointer to the allocated memory
    return ptr;
}

void deallocate_memory(void *ptr) {
    // Check if the pointer is within the memory pool
    if (ptr < memory_pool || ptr >= memory_pool + MEMORY_POOL_SIZE) {
        return;
    }

    // Deallocate the block of memory from the memory pool
    size_t size = (char *)ptr - (char *)memory_pool;
    memory_pool_index -= size;
}
