#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint32_t uid; // Unique identifier (UID) generated based on the structure's index
    uint16_t rx_ue_information_tag; // RX_UE_INFORMATION_TAG
    uint16_t rnti; // RNTI
    uint8_t crc_indication_rel8_tag; // CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
    uint32_t timestamp; // Timestamp representing the time at which the CRC indication was processed
} NFAPI_CRC_INDICATION_PDU_T;

// Define memory pool for NFAPI_CRC_INDICATION_PDU_T structures
#define MEMORY_POOL_SIZE 1024 // Size of the memory pool in bytes
static uint8_t memory_pool[MEMORY_POOL_SIZE]; // Memory pool buffer
static size_t memory_pool_used = 0; // Used memory in the pool

// Define synchronization variables for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for protecting shared resources
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER; // Condition variable for signaling changes in the pool

// Define function to allocate memory from the pool
void* allocate_memory(size_t size) {
    void* ptr = NULL;
    pthread_mutex_lock(&mutex);
    if (memory_pool_used + size <= MEMORY_POOL_SIZE) {
        ptr = &memory_pool[memory_pool_used];
        memory_pool_used += size;
    }
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
    return ptr;
}

// Define function to free memory from the pool
void free_memory(void* ptr) {
    pthread_mutex_lock(&mutex);
    size_t size = MEMORY_POOL_SIZE - (size_t)(&memory_pool[0] - (uint8_t*)ptr);
    memory_pool_used -= size;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
}

// Define function to populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void populate_list(size_t n, uint32_t seed) {
    // Initialize the list with NULL pointers
    NFAPI_CRC_INDICATION_PDU_T* list[n];
    for (size_t i = 0; i < n; i++) {
        list[i] = NULL;
    }

    // Populate the list with structures
    for (size_t i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_memory(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            // Handle memory allocation failure
            continue;
        }
        memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->uid = i + 1;
        pdu->rx_ue_information_tag = (uint16_t)(i % 256);
        pdu->rnti = (uint16_t)(i % 65536);
        pdu->crc_indication_rel8_tag = (uint8_t)((seed + i) % 256);
        pdu->timestamp = time(NULL);
        list[i] = pdu;
    }

    // Handle dynamic reconfiguration requests
    if (n > 0) {
        size_t new_size = n * sizeof(NFAPI_CRC_INDICATION_PDU_T*);
        NFAPI_CRC_INDICATION_PDU_T** new_list = allocate_memory(new_size);
        if (!new_list) {
            // Handle memory allocation failure
            return;
        }
        memcpy(new_list, list, n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        free_memory(list);
        list = new_list;
    }
}

