    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list structure for storing the populated NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
} LINKED_LIST_T;

// Function to dynamically populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures with random CRCFLAG values
LINKED_LIST_T* populateLinkedList(int numElements) {
    // Allocate memory for the linked list structure
    LINKED_LIST_T *list = malloc(sizeof(LINKED_LIST_T));
    if (list == NULL) {
        printf("Error: Failed to allocate memory for linked list\n");
        return NULL;
    }

    // Initialize the head of the linked list to NULL
    list->head = NULL;

    // Loop through each element in the linked list and populate it with a random CRCFLAG value
    for (int i = 0; i < numElements; i++) {
        NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (element == NULL) {
            printf("Error: Failed to allocate memory for linked list element\n");
            return NULL;
        }

        // Set the CRCFLAG value to a random boolean value
        bool crcFlag = rand() % 2;
        element->CRCFLAG = crcFlag;

        // Add the element to the linked list
        if (list->head == NULL) {
            list->head = element;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *current = list->head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = element;
        }
    }

    return list;
}

